# v3.2fix: 可选依赖自动安装 (from Pro v2.3)
# ═══════════════════════════════════════════════════════════
def _check_and_install_dependencies():
    """检查可选依赖，缺失时尝试自动安装"""
    import subprocess
    missing = []
    for pkg_mod, pkg_name in [('scipy', 'scipy'), ('chardet', 'chardet'),
                                ('chinese_calendar', 'chinese_calendar'), ('psutil', 'psutil')]:
        try:
            __import__(pkg_mod)
        except ImportError:
            missing.append(pkg_name)
    if not missing:
        return
    if not sys.stdin.isatty():
        return
    msg = '检测到以下可选依赖未安装:\n' + '\n'.join(f'  - {p}' for p in missing)
    msg += '\n\n是否尝试自动安装？(y/N): '
    try:
        user_input = input(msg).strip().lower()
    except EOFError:
        return
    if user_input.startswith('y'):
        for pkg in missing:
            try:
                subprocess.check_call([sys.executable, '-m', 'pip', 'install', pkg],
                                      stdout=subprocess.DEVNULL, stderr=subprocess.STDOUT)
            except Exception:
                pass

