# v3.1: 工程化基础设施 (crash边界/MILP超时/结果缓存)
# ═══════════════════════════════════════════════════════════
import hashlib, functools, threading

# ── MILP 结果缓存 ──
_milp_cache: dict = {}     # {data_fingerprint: MilpResult}
MILP_CACHE_MAX = 32        # 最多缓存32个结果
MILP_TIMEOUT_S = 60        # MILP 默认超时(秒)

# ── v3.2: 统一计算缓存层(跨按钮复用) ──
_compute_cache: dict = {}   # {work_hash: {stage: result}}
COMPUTE_CACHE_MAX = 64      # 最多缓存64个计算结果


def _compute_cache_key(load_array: np.ndarray) -> str:
    """计算负荷数据的轻量哈希键, 用于缓存查询."""
    h = hashlib.sha256()
    h.update(str(load_array.shape).encode())
    flat = load_array.flatten()
    h.update(f'{float(np.mean(flat)):.1f},{float(np.std(flat)):.1f},{float(np.min(flat)):.1f},{float(np.max(flat)):.1f}'.encode())
    return h.hexdigest()[:12]


def _get_or_compute(cache_key: str, stage: str, compute_fn, force: bool = False):
    """统一调度: 有缓存直接返回, 无缓存计算并存入."""
    if not force and cache_key in _compute_cache and stage in _compute_cache[cache_key]:
        return _compute_cache[cache_key][stage]
    result = compute_fn()
    if cache_key not in _compute_cache:
        if len(_compute_cache) >= COMPUTE_CACHE_MAX:
            _compute_cache.pop(next(iter(_compute_cache)))
        _compute_cache[cache_key] = {}
    _compute_cache[cache_key][stage] = result
    return result


def _invalidate_compute_cache():
    """清空计算缓存(数据变更时调用)."""
    _compute_cache.clear()

# ═══════════════════════════════════════════════════════════
# v3.2: 文件指纹记忆系统 (自动恢复映射+参数配置)
# ═══════════════════════════════════════════════════════════
import json as _json

class FileMemory:
    """文件指纹→配置快照 记忆库."""
    _instance = None
    MEMORY_FILE = 'file_memory.json'
    MAX_ENTRIES = 200

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._loaded = False
        return cls._instance

    def __init__(self):
        if self._loaded:
            return
        self._memory: dict = {}
        self._load()
        self._loaded = True

    def _load(self):
        """从磁盘加载记忆库."""
        try:
            path = os.path.join(os.path.dirname(os.path.abspath(__file__)), self.MEMORY_FILE)
            if os.path.exists(path):
                with open(path, 'r', encoding='utf-8') as f:
                    self._memory = _json.load(f)
        except Exception:
            self._memory = {}

    def _save(self):
        """持久化到磁盘."""
        try:
            if len(self._memory) > self.MAX_ENTRIES:
                # LRU淘汰: 保留最近200条
                sorted_items = sorted(self._memory.items(),
                    key=lambda x: x[1].get('last_used', ''), reverse=True)
                self._memory = dict(sorted_items[:self.MAX_ENTRIES])
            path = os.path.join(os.path.dirname(os.path.abspath(__file__)), self.MEMORY_FILE)
            with open(path, 'w', encoding='utf-8') as f:
                _json.dump(self._memory, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    @staticmethod
    def hash_file(filepath: str) -> str:
        """文件指纹: 路径+大小+修改时间 → SHA256前16位."""
        try:
            stat = os.stat(filepath)
            raw = f'{filepath}|{stat.st_size}|{stat.st_mtime}'
            return hashlib.sha256(raw.encode()).hexdigest()[:16]
        except Exception:
            return ''

    def get(self, filepath: str) -> dict:
        """查询记忆: 返回 {mapping, settings} 或 None."""
        key = self.hash_file(filepath)
        if key and key in self._memory:
            entry = self._memory[key]
            # 验证文件未变(大小+mtime一致)
            try:
                stat = os.stat(filepath)
                if entry.get('size') == stat.st_size and entry.get('mtime') == stat.st_mtime:
                    import datetime
                    entry['last_used'] = datetime.datetime.now().isoformat()
                    self._save()
                    return {'mapping': entry.get('mapping', {}),
                            'settings': entry.get('settings', {})}
            except Exception:
                pass
        return None

    def set(self, filepath: str, mapping: dict = None, settings: dict = None):
        """保存记忆: 合并更新, 不覆盖已有字段."""
        key = self.hash_file(filepath)
        if not key:
            return
        if key not in self._memory:
            self._memory[key] = {}
        entry = self._memory[key]
        if mapping is not None:
            entry['mapping'] = mapping
        if settings is not None:
            existing = entry.get('settings', {})
            existing.update(settings)
            entry['settings'] = existing
        try:
            stat = os.stat(filepath)
            entry['size'] = stat.st_size
            entry['mtime'] = stat.st_mtime
        except Exception:
            pass
        import datetime
        entry['last_used'] = datetime.datetime.now().isoformat()
        self._save()

    def forget(self, filepath: str = None, key: str = None):
        """清除记忆."""
        if filepath:
            key = self.hash_file(filepath)
        if key and key in self._memory:
            del self._memory[key]
            self._save()


def _data_fingerprint(df: 'pd.DataFrame', config: 'MilpConfig' = None) -> str:
    """计算数据指纹: 基于shape+统计量+关键config参数的轻量哈希."""
    h = hashlib.sha256()
    h.update(str(df.shape).encode())
    h.update(','.join(sorted(df.columns)).encode())
    for col in ['consume', 'produce']:
        if col in df.columns:
            s = df[col]
            h.update(f'{s.mean():.1f},{s.std():.1f},{s.min():.1f},{s.max():.1f}'.encode())
    if config is not None:
        h.update(f'dr{config.discount_rate}'.encode())
        h.update(f'dl{config.demand_limit}'.encode())
        h.update(f'lc{config.lifecycle}'.encode())
        if config.devices:
            for d in config.devices:
                h.update(f'dv{d.capacity:.0f},{d.max_c_rate:.2f},{d.price:.0f}'.encode())
    return h.hexdigest()[:16]


def _run_milp_with_timeout(df, config, timeout_s=MILP_TIMEOUT_S) -> 'MilpResult':
    """带超时的MILP求解: 子线程求解, 主线程等待, 超时返回timeout状态."""
    result_holder = []
    exception_holder = []

    def _solve():
        try:
            result_holder.append(solve_milp_capacity(df, config))
        except Exception as e:
            exception_holder.append(e)

    t = threading.Thread(target=_solve, daemon=True)
    t.start()
    t.join(timeout=timeout_s)
    if t.is_alive():
        # 超时——线程仍运行, 但不等待了(damon线程会在进程退出时清理)
        return MilpResult(status='timeout', solve_time_s=timeout_s)
    if exception_holder:
        raise exception_holder[0]
    return result_holder[0] if result_holder else MilpResult(status='error')


def _cached_milp_solve(df, config) -> 'MilpResult':
    """带缓存的MILP求解: 相同数据指纹直接返回缓存结果."""
    fp = _data_fingerprint(df, config)
    if fp in _milp_cache:
        cached = _milp_cache[fp]
        cached.solve_time_s = 0.0  # 缓存命中, 耗时标记为0
        return cached
    # LRU淘汰
    if len(_milp_cache) >= MILP_CACHE_MAX:
        _milp_cache.pop(next(iter(_milp_cache)))
    result = _run_milp_with_timeout(df, config)
    if result.status in ('optimal', 'feasible'):
        _milp_cache[fp] = result
    return result


def safe_ui_op(func):
    """装饰器: UI回调crash边界——异常时弹窗而非静默崩溃."""
    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            return func(self, *args, **kwargs)
        except Exception as e:
            import traceback
            tb = traceback.format_exc()
            log.error(f"UI操作异常 [{func.__name__}]: {e}\n{tb[-500:]}")
            # 尝试弹窗(可能在非GUI线程, 用invokeMethod安全调用)
            try:
                from PySide6.QtWidgets import QMessageBox
                QMessageBox.critical(self if hasattr(self, 'isWidgetType') else None,
                                     "操作异常", f"{func.__name__}: {e}")
            except Exception:
                try:
                    from PyQt5.QtWidgets import QMessageBox  # fallback
                    QMessageBox.critical(None, "操作异常", f"{func.__name__}: {e}")
                except Exception:
                    pass
    return wrapper

# v2.23: matplotlib安全上下文管理器------确保figure在任何退出路径都被关闭
from contextlib import contextmanager, suppress
@contextmanager
def _safe_plt_figure(*args, **kwargs):
    """安全的plt.subplots上下文管理器.
    用法: with _safe_plt_figure(figsize=(16,8)) as (fig, ax):
    保证fig在退出时(含异常)被正确关闭,防止长时间运行内存泄漏.
    注意: 不支持num参数(指定figure编号),使用num可能导致plt.close行为异常.
    v2.29fix: 加_plt None守卫,matplotlib初始化失败时安全降级."""
    _init_matplotlib()
    if _plt is None:
        raise RuntimeError("matplotlib 初始化失败,无法创建图形")
    fig, ax = _plt.subplots(*args, **kwargs)
    try:
        yield fig, ax
    finally:
        if _plt is not None:
            _plt.close(fig)

