def _check_dependencies(lazy=True):
    """检查可选依赖.lazy=True 时仅报告已缓存结果(后台线程已检查),否则同步检查.
    v2.29fix: lazy模式回退到已缓存结果,而非直接返回空."""
    if lazy:
        global MISSING_DEPENDENCIES, _background_dep_check_done
        if not _background_dep_check_done:
            return []  # 后台检查未完成,不阻塞启动
        return MISSING_DEPENDENCIES
    missing = []
    for pkg, import_path in [
        ('scipy', 'scipy.interpolate'),
        ('chardet', 'chardet'),
        ('chinese_calendar', 'chinese_calendar'),
        ('psutil', 'psutil'),
    ]:
        try:
            __import__(import_path)
        except ImportError:
            missing.append(pkg)
    if missing:
        logging.getLogger(__name__).warning(f"可选依赖缺失: {', '.join(missing)}.相应功能将降级或不可用.")
    return missing

MISSING_DEPENDENCIES = []
# v2.23: 启动时后台检测依赖,供后续功能使用
_background_dep_check_done = False
def _background_dep_check():
    global MISSING_DEPENDENCIES, _background_dep_check_done
    try:
        MISSING_DEPENDENCIES = _check_dependencies(lazy=False)
    except Exception as _e:
        log.warning(f"后台依赖检测失败: {_e}")
        MISSING_DEPENDENCIES = []
    _background_dep_check_done = True
_dep_thread = threading.Thread(target=_background_dep_check, daemon=True, name='dep-check')
_dep_thread.start()

log_formatter = logging.Formatter('%(asctime)s - %(threadName)s - %(levelname)s - %(message)s')

_LOG_DIR = "logs"
_log_root_handler = None

def _get_log_dir():
    return _LOG_DIR

def _set_log_dir(path):
    global _LOG_DIR, _log_root_handler
    if not path:
        path = "logs"
    path = os.path.abspath(path)
    if path != _LOG_DIR:
        _LOG_DIR = path
        os.makedirs(_LOG_DIR, exist_ok=True)
        root_logger = logging.getLogger()  # v2.23: 统一使用根logger
        if _log_root_handler:
            root_logger.removeHandler(_log_root_handler)
            _log_root_handler.close()
        _log_root_handler = _create_file_handler()
        if _log_root_handler:
            root_logger.addHandler(_log_root_handler)

def _create_file_handler():
    try:
        os.makedirs(_LOG_DIR, exist_ok=True)
        handler = logging.handlers.RotatingFileHandler(
            os.path.join(_LOG_DIR, "app.log"), maxBytes=5*1024*1024, backupCount=5, encoding='utf-8'
        )
        handler.setFormatter(log_formatter)
        return handler
    except Exception as _e:
        import sys as _sys
        print(f"[WARNING] 日志文件处理器创建失败: {_e}", file=_sys.stderr)
        return None

