# v2.28: CJK字体智能回退检测链
# ═══════════════════════════════════════════════════════════
_CJK_FONT_CANDIDATES = [
    "Microsoft YaHei",        # Windows首选
    "HarmonyOS Sans SC",       # 用户已安装的鸿蒙字体
    "Noto Sans CJK SC",        # Google开源CJK
    "Source Han Sans SC",      # Adobe思源黑体
    "SimHei",                  # Windows黑体fallback
    "WenQuanYi Micro Hei",     # Linux常见
    "PingFang SC",             # macOS
    "Hiragino Sans GB",        # macOS旧版
]
_CJK_FONT_DETECTED = None
_CJK_FONT_LOCK = threading.Lock()

def _detect_cjk_font():
    """检测系统可用的最佳CJK字体,结果缓存.
    优先级: Microsoft YaHei > HarmonyOS Sans SC > Noto Sans CJK SC > ... > 系统默认
    v2.29fix: 加QApplication实例守卫,CLI/测试/启动早期安全回退."""
    global _CJK_FONT_DETECTED
    if _CJK_FONT_DETECTED is not None:
        return _CJK_FONT_DETECTED
    app = QApplication.instance()
    if app is None:
        _CJK_FONT_DETECTED = "Microsoft YaHei"
        return _CJK_FONT_DETECTED
    with _CJK_FONT_LOCK:
        if _CJK_FONT_DETECTED is not None:
            return _CJK_FONT_DETECTED
        for candidate in _CJK_FONT_CANDIDATES:
            if QFontDatabase.hasFamily(candidate):
                _CJK_FONT_DETECTED = candidate
                log.debug(f"CJK字体检测: 选用 {candidate}")
                return candidate
        # 最终回退:系统默认
        default_family = QFont().family() or "sans-serif"
        _CJK_FONT_DETECTED = default_family
        log.warning(f"CJK字体检测: 未找到任何已知CJK字体,回退至系统默认 {default_family}")
        return default_family

_EMBEDDED_FONT_FAMILY = None  # v2.28: 延迟检测,首次调用 _detect_cjk_font() 时确定

def _get_embedded_font_family():
    """获取当前嵌入字体族名(延迟检测+缓存)"""
    global _EMBEDDED_FONT_FAMILY
    if _EMBEDDED_FONT_FAMILY is None:
        _EMBEDDED_FONT_FAMILY = _detect_cjk_font()
    return _EMBEDDED_FONT_FAMILY

def _get_emoji_font_path():
    """v3.0fix: 获取内置emoji字体路径,兼容源码运行和PyInstaller打包."""
    import sys as _sys
    # PyInstaller 打包后的临时目录
    if hasattr(_sys, '_MEIPASS'):
        base = _sys._MEIPASS
    else:
        base = os.path.dirname(os.path.abspath(__file__))
    path = os.path.join(base, 'NotoColorEmoji.ttf')
    if os.path.exists(path):
        return path
    return None

def _load_emoji_fonts():
    """v3.0fix: 加载内置Noto Color Emoji字体 + 系统emoji回退."""
    emoji_families = []
    emoji_path = _get_emoji_font_path()
    if emoji_path:
        fid = QFontDatabase.addApplicationFont(emoji_path)
        if fid >= 0:
            families = QFontDatabase.applicationFontFamilies(fid)
            emoji_families.extend(families)
    for ef in ('Segoe UI Emoji', 'Segoe UI Symbol'):
        if QFontDatabase.hasFamily(ef) and ef not in emoji_families:
            emoji_families.append(ef)
    return emoji_families

_EMOJI_FAMILIES = None  # 延迟加载,需QApplication实例

def get_default_font(point_size=12, bold=True):
    global _EMOJI_FAMILIES
    if _EMOJI_FAMILIES is None:
        _EMOJI_FAMILIES = _load_emoji_fonts()
    font = QFont()
    font.setFamilies([_get_embedded_font_family()] + _EMOJI_FAMILIES + ['sans-serif'])
    font.setPointSize(point_size)
    font.setBold(bold)
    return font

def apply_global_font(app: QApplication):
    global _EMOJI_FAMILIES
    if _EMOJI_FAMILIES is None:
        _EMOJI_FAMILIES = _load_emoji_fonts()
    family = _get_embedded_font_family()
    font = QFont()
    font.setFamilies([family] + _EMOJI_FAMILIES + ['sans-serif'])
    font.setPointSize(9)
    font.setBold(False)
    font.setStyleStrategy(QFont.PreferAntialias)
    app.setFont(font)
    # v2.23: 通知DesignTokens更新base_size缓存(字体变化后QSS需重新生成)
    invalidate_qss_cache()

def get_font_metrics(app: QApplication = None):
    if app is None:
        app = QApplication.instance()
    if app:
        return QFontMetrics(app.font())
    return QFontMetrics(QFont())

def base_size(app: QApplication = None):
    fm = get_font_metrics(app)
    return max(fm.height() * 1.5, 24)  # 舒适统一的基础尺寸

def set_global_theme(theme: str):
    global _current_theme
    with _theme_lock:
        _current_theme = theme

def get_global_theme():
    with _theme_lock:
        return _current_theme

_theme_lock = threading.Lock()  # v2.23: 主题变量线程安全锁
_current_theme = 'light'


