class RippleButton(QPushButton):
    """手绘按钮:渐变主按钮/普通波纹按钮,带hover光效+点击波纹."""
    def __init__(self, text='', parent=None, primary=True):
        super().__init__(text, parent)
        self._ripple = 0.0
        self._ripple_x = 0
        self._ripple_y = 0
        self._hover = 0.0
        self._primary = primary  # True=渐变蓝, False=白底边框
        self._danger = False     # True=红色警告按钮
        self._timer = QTimer(self)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self._tick)
        self.setCursor(Qt.PointingHandCursor)

    def setDanger(self, v=True):
        self._danger = v
        self.update()

    def _tick(self):
        changed = False
        if self._ripple > 0.01:
            self._ripple *= 0.85
            changed = True
        if self.underMouse() and self._hover < 1.0:
            self._hover = min(1.0, self._hover + 0.12)
            changed = True
        elif not self.underMouse() and self._hover > 0.0:
            self._hover = max(0.0, self._hover - 0.08)
            changed = True
        if not changed:
            self._timer.stop()
        self.update()

    def enterEvent(self, e): self._timer.start(); super().enterEvent(e)
    def leaveEvent(self, e): self._timer.start(); super().leaveEvent(e)

    def mousePressEvent(self, e):
        self._ripple = 1.0
        pt = e.position().toPoint()
        self._ripple_x = pt.x(); self._ripple_y = pt.y()
        self._timer.start()
        super().mousePressEvent(e)

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        w, h = self.width(), self.height()
        r = min(10, h // 3)
        tk = DesignTokens.current_tokens()
        if not self.isEnabled():
            p.setPen(Qt.NoPen); p.setBrush(tk['BG_ACTIVITY'])
            p.drawRoundedRect(0, 0, w, h, r, r)
            p.setPen(tk['TEXT_DISABLED'])
            p.setFont(get_default_font(12, False))
            p.drawText(self.rect(), Qt.AlignCenter, self.text())
            return
        if self._primary or self._danger:
            # 渐变按钮
            grad = QLinearGradient(0, 0, w, 0)
            if self._danger:
                grad.setColorAt(0, tk['DANGER_COLOR'])
                grad.setColorAt(1, tk['DANGER_GRADIENT_END'])
            else:
                grad.setColorAt(0, tk['ACCENT'])
                grad.setColorAt(1, tk['ACCENT_GRADIENT_END'])
            p.setPen(Qt.NoPen); p.setBrush(grad)
            p.drawRoundedRect(0, 0, w, h, r, r)
        else:
            # 次要按钮(主题感知边框+背景)
            p.setPen(QPen(tk['BORDER'], 1.5))
            bg = tk['BTN_BG_HOVER'] if self._hover >= 0.5 else tk['BTN_BG']
            p.setBrush(bg)
            p.drawRoundedRect(0, 0, w, h, r, r)
        # hover光效
        if self._hover > 0.01:
            alpha = int(self._hover * 25)
            p.setPen(Qt.NoPen)
            p.setBrush(QColor(255, 255, 255, alpha) if (self._primary or self._danger) else QColor(0, 0, 0, alpha))
            p.drawRoundedRect(0, 0, w, h, r, r)
        # 点击波纹
        if self._ripple > 0.01:
            ripple_r = max(w, h) * self._ripple
            rg = QRadialGradient(self._ripple_x, self._ripple_y, ripple_r)
            ca = 60 if (self._primary or self._danger) else 40
            rg.setColorAt(0, QColor(255, 255, 255, int(ca * self._ripple)))
            rg.setColorAt(1, QColor(255, 255, 255, 0))
            p.setPen(Qt.NoPen); p.setBrush(rg)
            p.drawRoundedRect(0, 0, w, h, r, r)
        # 文字
        if self._danger or self._primary:
            tc = QColor(255, 255, 255)
        else:
            tc = tk['TEXT_PRIMARY']
        p.setPen(tc)
        p.setFont(get_default_font(12, True))
        p.drawText(self.rect(), Qt.AlignCenter, self.text())


class GlowProgressBar(QProgressBar):
    """手绘进度条:HSL彩虹流光+圆角."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self._glow_offset = 0.0
        HslAnimator().phase_changed.connect(self._update_glow)

    def _update_glow(self):
        self._glow_offset = (self._glow_offset + 0.02) % 1.0
        if self.value() > 0:
            self.update()

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        w, h = self.width(), self.height()
        r = h // 2
        tk = DesignTokens.current_tokens()
        # 背景轨道
        p.setPen(Qt.NoPen); p.setBrush(tk['PROGRESS_TRACK'])
        p.drawRoundedRect(0, 0, w, h, r, r)
        # 填充进度——HSL彩虹渐变
        if self.maximum() > 0:
            ratio = self.value() / self.maximum()
            fill_w = int(w * ratio)
            if fill_w > r:
                grad = QLinearGradient(0, 0, w, 0)
                c0 = HslAnimator.hsl_color(0.58, 0.7, 0.55)  # 蓝
                c1 = HslAnimator.hsl_color(0.70, 0.7, 0.55)  # 青
                c2 = HslAnimator.hsl_color(0.82, 0.7, 0.50)  # 绿
                grad.setColorAt(0, c0)
                grad.setColorAt(0.5, c1)
                grad.setColorAt(1, c2)
                p.setBrush(grad)
                p.drawRoundedRect(0, 0, fill_w, h, r, r)
                # 流动光条
                glow_x = int(w * self._glow_offset * 1.5) - 30
                glow_grad = QLinearGradient(glow_x, 0, glow_x + 60, 0)
                glow_grad.setColorAt(0, QColor(255, 255, 255, 0))
                glow_grad.setColorAt(0.5, QColor(255, 255, 255, 70))
                glow_grad.setColorAt(1, QColor(255, 255, 255, 0))
                p.setBrush(glow_grad)
                p.drawRoundedRect(0, 0, fill_w, h, r, r)
        # 文字
        if self.value() > 0:
            if ratio > 0.3:
                p.setPen(QColor(255, 255, 255))
            else:
                p.setPen(tk['TEXT_SECONDARY'])
            p.setFont(get_default_font(10, True))
            p.drawText(self.rect(), Qt.AlignCenter, self.text() or f'{self.value()}%')


