    @classmethod
    def current_tokens(cls):
        return cls.DARK if get_global_theme() == 'dark' else cls.LIGHT

    @classmethod
    def generate_qss(cls, app: QApplication = None):
        # QSS 缓存:同一主题避免重复生成(v2.23: 加锁防竞态)
        cache_key = (get_global_theme(), app.objectName() if app and app.objectName() else (id(app) if app else None))
        with cls._qss_lock:
            if hasattr(cls, '_qss_cache') and cls._qss_cache_key == cache_key:
                return cls._qss_cache
        tokens = cls.current_tokens()
        bsize = base_size(app)
