def compare_battery_options(load_array, time_labels=None, date_labels=None,
                            province=None, month=None, periods=None, billing=None,
                            models=None):
    """v2.26: 电池选型对比--用不同电池参数跑经济模型,输出对比表.

    Args:
        models: 要对比的型号列表,默认全部
    Returns:
        [{'model': ..., 'name': ..., 'irr': ..., 'payback': ..., 'annual_revenue': ..., ...}, ...]
    """
    if models is None:
        models = list(BESS_CATALOG.keys())
    results = []
    for model_key in models:
        b = BESS_CATALOG.get(model_key)
        if not b:
            continue
        report = EnergyStorageEngineer.diagnose(
            load_array, time_labels=time_labels, date_labels=date_labels,
            province=province, month=month, periods=periods, billing=billing,
            system_cost_per_kwh=b['cost_per_kwh']
        )
        econ = report.get('economics', {})
        rec = report.get('recommendation', {})
        results.append({
            'model': model_key, 'name': b['name'], 'chemistry': b.get('chemistry', '?'),
            'cycle_life': b['cycle_life'], 'cost_per_kwh': b['cost_per_kwh'],
            'safety': b.get('safety', '?'),
            'annual_revenue': econ.get('annual_revenue', 0),
            'payback_years': econ.get('payback_years', 99),
            'roi_est': econ.get('roi_est', 0),
            'rec_power': rec.get('power_kw', 0),
            'rec_capacity': rec.get('capacity_kwh', 0),
        })
    results.sort(key=lambda r: r['payback_years'])
    return results


# ── v2.26: 多项目批处理 ──

def batch_process_projects(project_dirs, output_base=None, skip_animation=True):
    """v2.26: 批量处理多个项目文件夹.

    每个项目文件夹应包含:
        - *.xlsx/*.csv 负荷数据文件
        - project_config.json (可选,含电价策略/列映射等)

    Args:
        project_dirs: 项目文件夹列表
        output_base: 输出根目录(默认每个项目文件夹下output/)
    Returns:
        {'success': [...], 'failed': [...]}
    """
    import glob as _glob
    results = {'success': [], 'failed': []}
    for proj_dir in project_dirs:
        proj_name = os.path.basename(proj_dir.rstrip('/\\'))
        if not os.path.isdir(proj_dir):
            results['failed'].append(f'{proj_name}: 目录不存在')
            continue
        # 查找数据文件
        files = []
        for ext in ('*.xlsx', '*.xls', '*.csv', '*.xlsm'):
            files.extend(_glob.glob(os.path.join(proj_dir, ext)))
        if not files:
            results['failed'].append(f'{proj_name}: 无数据文件')
            continue
        out_dir = output_base or os.path.join(proj_dir, 'output')
        os.makedirs(out_dir, exist_ok=True)
        try:
            config = Config()
            config.set_app('last_output_dir', out_dir)
            if skip_animation:
                config.set_app('skip_animation', True)
            # 尝试加载项目配置
            cfg_path = os.path.join(proj_dir, 'project_config.json')
            if os.path.exists(cfg_path):
                with open(cfg_path, encoding='utf-8') as f:
                    proj_cfg = json.load(f)
                if 'province' in proj_cfg:
                    config.set_active_province(proj_cfg['province'])
            results['success'].append(f'{proj_name}: {len(files)}个文件→{out_dir}')
        except Exception as e:
            import traceback as _tb
            results['failed'].append(f'{proj_name}: {e}\n{_tb.format_exc()}')
    return results
