ANALYSIS_ENGINE_MODE = 'basic'  # 默认基础模式;可选 'professional'
_ENGINE_MODE_LOCK = threading.RLock()  # v2.27: 线程安全保护

def is_warning_muted(warning_type: str, config=None) -> bool:
    """v2.17: 检查告警是否已被用户静默"""
    if config is None:
        return False
    try:
        return warning_type in config.app_set('muted_warnings', [])
    except Exception:
        return False

def mute_warning(warning_type: str, config):
    """v2.17: 静默指定类型的告警"""
    try:
        muted = list(config.app_set('muted_warnings', []))
        if warning_type not in muted:
            muted.append(warning_type)
            config.set_app('muted_warnings', muted)
    except Exception:
        pass

