def set_engine_mode(mode: str):
    """v2.27: 线程安全运行时切换分析引擎模式.
    v2.29fix: log未初始化时安全降级,避免CLI/测试崩溃."""
    global ANALYSIS_ENGINE_MODE
    if mode not in ('basic', 'professional'):
        raise ValueError(f"无效模式 '{mode}',可选: basic, professional")
    with _ENGINE_MODE_LOCK:
        ANALYSIS_ENGINE_MODE = mode
    try:
        log.info(f"分析引擎模式切换为: {ENGINE_MODE_META[mode]['label']}")
    except Exception:
        pass  # log未初始化时静默降级

def get_engine_mode():
    """v2.27: 线程安全返回当前引擎模式"""
    with _ENGINE_MODE_LOCK:
        return ANALYSIS_ENGINE_MODE

