TARIFF_DB_LAST_UPDATED = "2026-06-17"  # v2.28: 初始化默认值,启动时如果加载了外部 price_strategies.json(含 _metadata.updated)则自动覆盖
TARIFF_DB_UPDATE_INTERVAL_DAYS = 90  # 建议更新间隔(软警告)
TARIFF_DB_STALE_DAYS = 180           # v2.24: 硬门禁阈值,超期电价DB结果不可信

def check_tariff_db_freshness():
    """v2.24: 检查电价DB是否过期.
    过期>90天返回软警告, >180天返回硬门禁(is_stale=True).
    """
    try:
        updated = datetime.strptime(TARIFF_DB_LAST_UPDATED, "%Y-%m-%d")
        age = (datetime.now() - updated).days
        if age > TARIFF_DB_STALE_DAYS:
            return True, True, f"电价数据库已 {age} 天未更新(建议每{TARIFF_DB_UPDATE_INTERVAL_DAYS}天更新),\n部分省份电价政策可能已变更,计算结果仅供参考."
        if age > TARIFF_DB_UPDATE_INTERVAL_DAYS:
            return True, False, f"电价数据库已 {age} 天未更新(>90天),建议核实最新电价政策."
        return False, False, ""
    except Exception:
        return False, False, ""

# v2.28fix: 全局电价数据库线程安全锁
_tariff_db_lock = threading.RLock()

def _safe_get_tariff_db():
    """线程安全读取电价数据库的浅拷贝."""
    with _tariff_db_lock:
        return dict(PROVINCE_TARIFF_DB)

def _safe_update_tariff_db(entries: dict):
    """线程安全更新电价数据库."""
    with _tariff_db_lock:
        PROVINCE_TARIFF_DB.update(entries)

def _safe_get_tariff_province(province: str):
    """线程安全获取单省电价数据."""
    with _tariff_db_lock:
        return PROVINCE_TARIFF_DB.get(province, {}).copy()
