# v2.17: 外部电价策略加载 - 优先读取 price_strategies.json,存在则覆盖内置数据
# 允许在不修改源码的情况下更新电价策略,适配行政电价取消潮下的快速变化
def _validate_tariff_periods(periods) -> bool:
    """v2.28fix: 校验电价时段格式一致性.
    合法格式: (1) [(start, end, type), ...] 平铺 (2) [((months_tuple), [(s,e,t),...]), ...] 分层
    非法: 混合两种格式 或 空列表."""
    if not periods or not isinstance(periods, list):
        return False
    first = periods[0]
    if isinstance(first, (tuple, list)) and len(first) >= 2:
        # 分层格式: 每个元素是 (months_tuple, periods_list)
        if isinstance(first[0], (tuple, list)) and isinstance(first[1], list):
            # v2.28fix: 递归验证内层时段列表
            return all(
                isinstance(p, (tuple, list)) and len(p) >= 2
                and isinstance(p[0], (tuple, list))
                and isinstance(p[1], list)
                and all(isinstance(ip, (tuple, list)) and len(ip) >= 2 for ip in p[1])
                for p in periods
            )
    # 平铺格式: 每个元素是 (start, end, type)
    return all(isinstance(p, (tuple, list)) and len(p) >= 2 for p in periods)


def _load_external_tariff_db():
    """尝试从外部文件加载电价策略.成功则更新 PROVINCE_TARIFF_DB 和 TARIFF_DB_LAST_UPDATED.
    v2.28: 支持从外部文件的 _metadata.updated 字段同步更新日期."""
    import json as _json
    global TARIFF_DB_LAST_UPDATED
    search_paths = [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), 'price_strategies.json'),
        os.path.join(os.getcwd(), 'price_strategies.json'),
        os.path.join(os.path.expanduser('~'), '.powercurve', 'price_strategies.json'),
    ]
    for path in search_paths:
        if os.path.isfile(path):
            try:
                with open(path, encoding='utf-8') as f:
                    external_db = _json.load(f)
                if isinstance(external_db, dict) and len(external_db) > 0:
                    # v2.28: 提取元数据中的更新日期
                    metadata = external_db.pop('_metadata', None)
                    if isinstance(metadata, dict) and 'updated' in metadata:
                        try:
                            updated_str = str(metadata['updated'])
                            datetime.strptime(updated_str, "%Y-%m-%d")  # 校验格式
                            TARIFF_DB_LAST_UPDATED = updated_str
                        except (ValueError, TypeError):
                            pass
                    tariff_entries = {k: v for k, v in external_db.items() if not k.startswith('_')}
                    # v2.28fix: 校验每个省份的时段格式
                    for pname, pdata in tariff_entries.items():
                        if isinstance(pdata, dict) and 'periods' in pdata:
                            if not _validate_tariff_periods(pdata['periods']):
                                logging.getLogger(__name__).warning(
                                    f"省份 '{pname}' 时段格式无效,跳过.请检查 periods 格式."
                                )
                                tariff_entries.pop(pname)
                    if tariff_entries:
                        _safe_update_tariff_db(tariff_entries)  # v2.28fix: 线程安全更新
                    logging.getLogger(__name__).info(
                        f"已加载外部电价策略: {path} ({len(tariff_entries)}个省份)"
                    )
                    return True
            except Exception as e:
                logging.getLogger(__name__).warning(f"外部电价策略加载失败 {path}: {e}")
    return False

# v2.23: 异步加载外部电价(移出模块导入路径,避免大文件阻塞启动)
_background_tariff_loaded = False
def _async_load_external_tariff():
    global _background_tariff_loaded
    try:
        _load_external_tariff_db()
    except Exception as e:
        logging.getLogger(__name__).warning(f"异步加载外部电价失败: {e}")
    _background_tariff_loaded = True
_ext_tariff_thread = threading.Thread(target=_async_load_external_tariff, daemon=True, name='ext-tariff')
_ext_tariff_thread.start()

def import_market_prices(filepath: str) -> dict:
    """v2.18: 导入市场化电价曲线(CSV/JSON格式).
    v2.23: 导入前深拷贝保护--校验失败自动回滚,防止外部文件污染内置数据库.
    """
    # v2.23: 导入前深拷贝保护
    import copy as _copy
    _backup = _copy.deepcopy(PROVINCE_TARIFF_DB)
    try:
        return _import_market_prices_inner(filepath)
    except Exception:
        # 校验失败或解析异常:回滚所有修改
        with _tariff_db_lock:
            PROVINCE_TARIFF_DB.clear()
            PROVINCE_TARIFF_DB.update(_backup)
        logging.getLogger(__name__).exception(f"市场化电价导入失败,已回滚内置数据: {filepath}")
        return {'error': '导入失败,内置电价数据已回滚.请检查文件格式是否正确.'}

def _import_market_prices_inner(filepath: str) -> dict:
    """
    CSV格式: province,peak,valley,flat,periods_json,mode,note 或
              hour,price(96点价格曲线,自动推导峰谷时段)
    JSON格式: {"province":"xx","peak":1.0,"valley":0.3,"flat":0.6,"periods":[...],"mode":"两充两放"}

    Returns: {'province': str, 'data': dict, 'format': 'csv'|'json'}
    """
    import json as _json
    ext = os.path.splitext(filepath)[1].lower()
    result = None

    if ext == '.json':
        with open(filepath, encoding='utf-8') as f:
            data = _json.load(f)
        if isinstance(data, list):
            # 多省份列表
            imported = {}
            for entry in data:
                prov = entry.get('province', '')
                if prov:
                    PROVINCE_TARIFF_DB[prov] = {k: v for k, v in entry.items() if k != 'province'}
                    imported[prov] = entry
            result = {'count': len(imported), 'provinces': list(imported.keys()), 'format': 'json'}
        elif isinstance(data, dict) and 'province' in data:
            prov = data.pop('province')
            PROVINCE_TARIFF_DB[prov] = data
            result = {'province': prov, 'data': data, 'format': 'json'}

    elif ext == '.csv':
        pd_lib = _get_pd()
        df = pd_lib.read_csv(filepath, encoding='utf-8')
        cols = [c.lower() for c in df.columns]
        # 检测格式:省份汇总 or 96点价格曲线
        if 'province' in cols and 'peak' in cols:
            for _, row in df.iterrows():
                prov = str(row.get('province', '')).strip()
                if not prov:
                    continue
                periods_raw = row.get('periods', '[]')
                try:
                    periods = _json.loads(str(periods_raw)) if isinstance(periods_raw, str) else periods_raw
                except Exception:
                    periods = [(0, 8, 'valley'), (8, 11, 'peak'), (11, 13, 'flat'),
                              (13, 17, 'peak'), (17, 22, 'peak'), (22, 24, 'valley')]
                PROVINCE_TARIFF_DB[prov] = {
                    'peak': float(row.get('peak', 1.0)),
                    'valley': float(row.get('valley', 0.3)),
                    'flat': float(row.get('flat', 0.6)),
                    'periods': periods,
                    'mode': str(row.get('mode', '两充两放')),
                    'note': str(row.get('note', 'CSV导入')),
                }
            result = {'count': len(df), 'format': 'csv'}
        elif 'hour' in cols or 'time' in cols:
            # 96点价格曲线 - 简单解析存为自定义省份
            time_col = 'hour' if 'hour' in cols else 'time'
            price_candidates = [c for c in df.columns if c not in (time_col, 'hour', 'time')]
            if not price_candidates:
                return {'error': '未找到价格列,请确保CSV包含price列或其他价格数据列'}
            price_col = price_candidates[0]
            prices = df[price_col].values
            prov_name = os.path.splitext(os.path.basename(filepath))[0]
            PROVINCE_TARIFF_DB[prov_name] = {
                'peak': float(np.max(prices)),
                'valley': float(np.min(prices)),
                'flat': float(np.median(prices)),
                'demand': 25,
                'periods': [(0, 8, 'valley'), (8, 11, 'peak'), (11, 13, 'flat'),
                           (13, 17, 'peak'), (17, 22, 'peak'), (22, 24, 'valley')],
                'mode': '两充两放',
                'note': f'96点价格曲线导入({os.path.basename(filepath)})',
            }
            result = {'province': prov_name, 'format': 'csv_curve'}

    if result:
        logging.getLogger(__name__).info(f"已导入市场化电价: {filepath} -> {result}")
    return result or {'error': '无法识别的文件格式'}

# ═══════════════════════════════════════════════════════════
# v2.18: 煤电容量电价数据库 - 发改价格〔2026〕114号
# 容量电价水平 = 煤电容量电价 x 折算比例
# 折算比例 = 满功率连续放电时长 / 全年最长净负荷高峰持续时长(<=1)
# 2026年起全国最低165元/kW·年,云南/甘肃顶格330,四川/天津231
# 数据来源: 各省发改委2026年煤电容量电价公告
# ═══════════════════════════════════════════════════════════
COAL_CAPACITY_PRICE = {
    # 330元/kW·年档
    '云南': 330, '甘肃': 330,
    # 231元/kW·年档
    '四川': 231, '天津': 231,
    # 165元/kW·年档(2026年全国最低标准)
    '浙江': 165, '江苏': 165, '广东': 165, '山东': 165,
    '河北': 165, '河南': 165, '湖北': 165, '湖南': 165,
    '福建': 165, '安徽': 165, '江西': 165, '山西': 165,
    '陕西': 165, '辽宁': 165, '吉林': 165, '黑龙江': 165,
    '广西': 165, '海南': 165, '贵州': 165, '重庆': 165,
    '北京': 165, '上海': 165, '青海': 165, '宁夏': 165,
    '新疆': 165, '西藏': 165, '蒙东': 165, '蒙西': 165,
}

# 全年最长净负荷高峰持续时长(小时)- 各省根据电力负荷特性估算
# 典型值: 夏季晚高峰4-6h,冬季晚高峰3-5h
PEAK_DURATION_DEFAULT = 5.0  # 默认全年最长净负荷高峰持续5小时

def calc_capacity_revenue(power_kw: float, discharge_hours: float, province: str = None,
                          coal_price: float = None, peak_duration: float = None,
                          storage_type: str = 'user_side', project_year: int = 2026) -> dict:
    """v2.19: 基于114号文计算储能容量电价年收益(含退坡+类型校验).

    Args:
        power_kw: 储能额定功率(kW)
        discharge_hours: 满功率连续放电时长(h)
        province: 省份名(用于查煤电容量电价)
        coal_price: 手动指定煤电容量电价(元/kW·年)
        peak_duration: 全年最长净负荷高峰持续时长(h)
        storage_type: 'grid_side'(独立储能,可获容量电价) | 'user_side'(用户侧,不可获)
        project_year: 项目运营起始年份(用于退坡计算)

    Returns:
        {'annual_revenue': 年容量电费收益, 'price_per_kw': 容量电价, 'ratio': 折算比例,
         'degradation_factor': 退坡系数, 'applicable': 是否适用}
    """
    # v2.19: 仅独立储能可获容量电价(114号文第三条)
    if storage_type != 'grid_side':
        return {
            'annual_revenue': 0, 'price_per_kw': 0, 'ratio': 0,
            'coal_price': 0, 'price_per_kwh': 0, 'peak_duration': 0,
            'applicable': False, 'note': '用户侧储能不适用容量电价(114号文仅覆盖独立储能)'
        }

    if coal_price is None:
        coal_price = COAL_CAPACITY_PRICE.get(province, 165) if province else 165
    if peak_duration is None or peak_duration <= 0:
        peak_duration = PEAK_DURATION_DEFAULT

    # v2.19: 114号文退坡规则 - 2026-2030年按100/90/80/70/60%逐年退坡
    _DEGRADATION_SCHEDULE = {2026: 1.00, 2027: 0.90, 2028: 0.80, 2029: 0.70, 2030: 0.60}
    # v2.22fix: 边界年份处理 - 2026前无退坡,2030后维持60%
    if project_year < 2026:
        deg_factor = 1.00
    elif project_year > 2030:
        deg_factor = 0.60
    else:
        deg_factor = _DEGRADATION_SCHEDULE[project_year]
    coal_price *= deg_factor

    # 折算比例 = 放电时长 / 高峰持续时长,上限1
    ratio = min(discharge_hours / peak_duration, 1.0) if peak_duration > 0 else 0.0
    price_per_kw = coal_price * ratio
    annual_revenue = price_per_kw * power_kw
    annual_energy = power_kw * discharge_hours * CAP_DAYS_PER_YEAR  # v2.23: 使用全局常量
    price_per_kwh = annual_revenue / max(annual_energy, 1)

    return {
        'annual_revenue': round(annual_revenue, 0),
        'price_per_kw': round(price_per_kw, 1),
        'ratio': round(ratio, 3),
        'coal_price': coal_price,
        'price_per_kwh': round(price_per_kwh, 4),
        'peak_duration': peak_duration,
        'applicable': True,
        'degradation_factor': deg_factor,
        'note': f'114号文容量电价(含{project_year}年退坡系数{deg_factor})',
    }

