class PVAlgorithm(Enum):
    """光伏模拟算法枚举"""
    KLEIN = 'klein'            # KLEIN晴空指数法(30城月均晴空指数xHaurwitz底曲线,最精确)
    HAURWITZ = 'haurwitz'      # Haurwitz晴空模型(纯物理计算,全国通用)
    ERBS = 'erbs'              # Erbs散射分解模型(直射/散射分离+倾斜面修正)
    MONTHLY_AVG = 'monthly'    # 月均日照简化(峰值日照小时正弦近似)
    CUSTOM = 'custom'          # 自定义辐照曲线
    PVLIB = 'pvlib'            # v3.2fix: pvlib 工程级(CEC单二极管模型)

