# ── 晴空辐照模型:Haurwitz (1945) 晴空GHI公式 ──
def _haurwitz_clear_sky_ghi(lat: float, doy: int, hour: float, linke: float = 3.5,
                             aerosol_correction: float = 0.80) -> float:
    """计算晴空条件下某时刻的地表总辐照(W/m2).

    Args:
        lat: 纬度(度, 北正)
        doy: 年内第几天(1-365)
        hour: 当地太阳时(0-24, 可小数)
        linke: Linke浑浊度系数(2=非常清澈, 6=浑浊, 中国典型3-4)
        aerosol_correction: 气溶胶/水汽校正系数(0.75-0.90, 高海拔洁净地区可取0.90)
    Returns:
        地表GHI(W/m2), 夜间返回0
    """
    import math as _m
    lat_rad = _m.radians(lat)
    # 太阳赤纬(Spencer 1971)
    b = 2 * _m.pi * (doy - 1) / 365.0
    decl = 0.006918 - 0.399912 * _m.cos(b) + 0.070257 * _m.sin(b) \
           - 0.006758 * _m.cos(2*b) + 0.000907 * _m.sin(2*b) \
           - 0.002697 * _m.cos(3*b) + 0.00148 * _m.sin(3*b)
    # 时角
    omega = _m.radians((hour - 12.0) * 15.0)
    # 太阳天顶角余弦
    cos_theta_z = _m.sin(lat_rad) * _m.sin(decl) + _m.cos(lat_rad) * _m.cos(decl) * _m.cos(omega)
    if cos_theta_z <= 0.017:  # 太阳在地平线以下 (<1deg)
        return 0.0
    # 地外辐照
    g_on = 1361.0 * (1.0 + 0.033 * _m.cos(2 * _m.pi * doy / 365.0))  # v2.23: 太阳常数更新为1361 W/m2(新标准)
    # 大气质量(Kasten & Young 1989)
    theta_z_deg = _m.degrees(_m.acos(cos_theta_z))
    am_ = 1.0 / (cos_theta_z + 0.50572 * (96.07995 - theta_z_deg) ** (-1.6364))
    # Rayleigh光学厚度
    delta_r = 1.0 / (6.6296 + 1.7513 * am_ - 0.1202 * am_**2 + 0.0065 * am_**3 - 0.00013 * am_**4)
    if delta_r <= 0:
        delta_r = 0.09
    # 晴空GHI (Haurwitz)
    ghi = g_on * cos_theta_z * _m.exp(-linke * am_ * delta_r) * aerosol_correction
    return max(0.0, ghi)

def calc_pv_hourly_output(city: str, month: int, capacity_kw: float = 0,
                          pr: float = 0.80, algorithm: PVAlgorithm = PVAlgorithm.KLEIN,
                          tilt: float | None = None, azimuth: float | None = None) -> dict:
    """v2.19: 统一光伏出力计算 - 支持4种算法.

    Args:
        city: 城市名
        month: 月份(1-12),越界自动裁剪
        capacity_kw: 光伏装机容量(kWp),<=0则返回全零
        pr: 综合性能比(Performance Ratio),默认0.80
        algorithm: PVAlgorithm枚举
        tilt: 倾斜角(度), None则默认水平面
        azimuth: 方位角(度, 南=0西=90), None则默认正南
    Returns:
        {'power_kw': [24], 'energy_kwh': [24], 'daily_kwh': float, 'peak_kw': float,
         'irradiance': [24], 'algorithm': str}
    v2.27fix: month 越界裁剪 + capacity_kw<0 转零.
    """
    import math as _m
    # v2.27fix: 边界防御
    if capacity_kw < 0:
        capacity_kw = 0
    month = max(1, min(12, month))
    if capacity_kw <= 0:
        return {'power_kw': [0]*24, 'energy_kwh': [0]*24, 'daily_kwh': 0, 'peak_kw': 0,
                'irradiance': [0]*24, 'algorithm': str(algorithm), 'note': '装机容量为0'}

    irrad = [0.0] * 24

    if algorithm == PVAlgorithm.KLEIN:
        # v2.19 SSS: 直接使用30省会x12月实测辐照曲线(最高精度)
        curve = _PV_KLEIN_CURVES.get((city, month))
        if curve:
            irrad = list(curve)
        else:
            # 非省会城市回退到晴空指数法
            csi = _PV_CLEAR_SKY_INDEX.get(city)
            if csi:
                idx = csi[min(month-1, 11)]
                lat = CITY_LAT_LON.get(city, (35.0, 116.0))[0]
                doy = _KLEIN_DAY_OF_YEAR[min(month-1, 11)]
                lf = _CITY_LINKE_FACTOR.get(city, 1.0)
                linke = _LINKE_MONTHLY_BASE[min(month-1, 11)] * lf
                for h in range(24):
                    ghi_w = _haurwitz_clear_sky_ghi(lat, doy, h + 0.5, linke)
                    irrad[h] = ghi_w * idx / 1000.0
            else:
                algorithm = PVAlgorithm.HAURWITZ

    if algorithm == PVAlgorithm.HAURWITZ:
        lat = CITY_LAT_LON.get(city, (35.0, 116.0))[0]
        doy = _KLEIN_DAY_OF_YEAR[min(month-1, 11)]
        lf = _CITY_LINKE_FACTOR.get(city, 1.0)
        linke = _LINKE_MONTHLY_BASE[min(month-1, 11)] * lf
        for h in range(24):
            ghi_w = _haurwitz_clear_sky_ghi(lat, doy, h + 0.5, linke)
            irrad[h] = ghi_w / 1000.0

    elif algorithm == PVAlgorithm.ERBS:
        # v2.19 SSS: Erbs散射分解 + HDKR倾斜面模型
        lat = CITY_LAT_LON.get(city, (35.0, 116.0))[0]
        doy = _KLEIN_DAY_OF_YEAR[min(month-1, 11)]
        lf = _CITY_LINKE_FACTOR.get(city, 1.0)
        linke = _LINKE_MONTHLY_BASE[min(month-1, 11)] * lf
        decl = _m.radians(23.45 * _m.sin(2*_m.pi*(284+doy)/365))
        lat_rad = _m.radians(lat)
        for h in range(24):
            omega = _m.radians((h + 0.5 - 12.0) * 15.0)
            cos_z = _m.sin(lat_rad)*_m.sin(decl) + _m.cos(lat_rad)*_m.cos(decl)*_m.cos(omega)
            if cos_z <= 0.017:
                irrad[h] = 0.0
                continue
            ghi = _haurwitz_clear_sky_ghi(lat, doy, h + 0.5, linke)
            # Erbs (1982) 散射分数模型
            kt = min(0.85, ghi / max(1367.0 * cos_z, 1.0))  # 晴空指数
            if kt <= 0.22:
                fd = 1.0 - 0.09 * kt
            elif kt <= 0.80:
                fd = 0.9511 - 0.1604*kt + 4.388*kt**2 - 16.638*kt**3 + 12.336*kt**4
            else:
                fd = 0.165
            diffuse = ghi * max(0.0, min(1.0, fd))
            beam = ghi - diffuse
            # HDKR倾斜面: 直射xcos入射角/cos天顶角 + 散射x(1+cosbeta)/2 + 地面反射
            if tilt is not None and tilt > 0:
                beta = _m.radians(tilt)
                az = _m.radians(azimuth if azimuth else 0)
                # v2.22fix: 标准 HDKR 入射角公式 (Duffie & Beckman 2013, eq 1.6.2)
                # 原公式 lat_rad - cos(beta)*cos(lat_rad) 弧度与无量纲量相减,物理无意义
                gamma = az  # 表面方位角
                cos_inc = (_m.sin(decl) * _m.sin(lat_rad) * _m.cos(beta)
                    - _m.sin(decl) * _m.cos(lat_rad) * _m.sin(beta) * _m.cos(gamma)
                    + _m.cos(decl) * _m.cos(lat_rad) * _m.cos(beta) * _m.cos(omega)
                    + _m.cos(decl) * _m.sin(lat_rad) * _m.sin(beta) * _m.cos(gamma) * _m.cos(omega)
                    + _m.cos(decl) * _m.sin(beta) * _m.sin(gamma) * _m.sin(omega))
                cos_inc = max(0.0, cos_inc)
                beam_tilt = beam * cos_inc / max(cos_z, 0.01)
                diffuse_tilt = diffuse * (1 + _m.cos(beta)) / 2
                ground_ref = ghi * 0.2 * (1 - _m.cos(beta)) / 2  # albedo=0.2
                irrad[h] = (beam_tilt + diffuse_tilt + ground_ref) / 1000.0
            else:
                irrad[h] = ghi / 1000.0

    elif algorithm == PVAlgorithm.MONTHLY_AVG:
        psh = CITY_SUNSHINE_HOURS.get(city, 4.0)
        # 正弦近似波形
        for h in range(24):
            if 6 <= h <= 18:
                irrad[h] = psh * _m.sin(_m.pi * (h - 6) / 12.0) / 6.0

    elif algorithm == PVAlgorithm.PVLIB:
        # v3.2fix: pvlib 工程级光伏建模(CEC单二极管)
        try:
            import pvlib
            from pvlib.location import Location
            from pvlib.pvsystem import PVSystem, retrieve_sam
            from pvlib.modelchain import ModelChain
            import pandas as pd
            sandia = retrieve_sam('sandiamod')
            cec = retrieve_sam('cecinverter')
            module = sandia['Canadian_Solar_CS5P_220M___2009_']
            inverter = cec['ABB__MICRO_0_25_I_OUTD_US_208__208V_']
            # v3.2fix: 使用已有城市列表估算坐标
            _city_latlon = {'北京':(39.9,116.4),'上海':(31.2,121.5),'广州':(23.1,113.3),'深圳':(22.5,114.1),
                '杭州':(30.3,120.2),'南京':(32.1,118.8),'武汉':(30.6,114.3),'成都':(30.6,104.1),
                '重庆':(29.6,106.5),'天津':(39.1,117.2),'西安':(34.3,108.9),'郑州':(34.8,113.6)}
            lat, lon = _city_latlon.get(city, (39.9, 116.4))
            loc = Location(lat, lon, tz='Asia/Shanghai')
            n_modules = max(1, int(capacity_kw * 1000 / (module['Impo'] * module['Vmpo'])))
            system = PVSystem(surface_tilt=30, surface_azimuth=180,
                              module_parameters=module, inverter_parameters=inverter,
                              modules_per_string=n_modules, strings_per_inverter=1)
            mc = ModelChain(system, loc, aoi_model='physical', spectral_model='no_loss')
            times = pd.date_range(f'2026-{month:02d}-01', periods=24, freq='h', tz='Asia/Shanghai')
            mc.run_model(pd.DataFrame(index=times))
            ac = mc.results.ac.fillna(0).values[:24]
            irrad = list(np.clip(ac / max(1.0, capacity_kw), 0, 1.2))
        except (ImportError, Exception) as e:
            log.debug(f'pvlib 不可用: {e}, 回退 KLEIN'); irrad = [0.0] * 24

    elif algorithm == PVAlgorithm.CUSTOM:
        raise ValueError("PVAlgorithm.CUSTOM 需要提供 custom_irradiance 参数")

    # v2.23: 倾斜面修正 - ERBS算法已在HDKR模型中完成修正,跳过二次修正避免双重计算
    if tilt is not None and tilt > 0 and algorithm != PVAlgorithm.ERBS:
        lat = CITY_LAT_LON.get(city, (35.0, 116.0))[0]
        doy = _KLEIN_DAY_OF_YEAR[min(month-1, 11)]
        decl = _m.radians(23.45 * _m.sin(2*_m.pi*(284+doy)/365))
        tilt_cos = _m.cos(_m.radians(tilt)) * _m.cos(_m.radians(lat) - decl) + _m.sin(_m.radians(tilt)) * _m.sin(_m.radians(lat) - decl)
        horiz_cos = _m.cos(_m.radians(lat) - decl)
        factor = tilt_cos / max(horiz_cos, 0.1)
        irrad = [i * max(0.8, min(factor, 1.5)) for i in irrad]

    # 出力计算
    power = [capacity_kw * i * pr for i in irrad]
    energy = [p * 1.0 for p in power]  # kWh per hour
    daily_kwh = sum(energy)
    peak_kw = max(power)

    return {
        'power_kw': [round(p, 2) for p in power],
        'energy_kwh': [round(e, 3) for e in energy],
        'daily_kwh': round(daily_kwh, 2),
        'peak_kw': round(peak_kw, 2),
        'irradiance': [round(i, 4) for i in irrad],
        'algorithm': str(algorithm),
    }

