# v2.16: 从电价时段自动推导充放电策略(支持多季节自动切换)
# 规则:谷段(含深谷)->充电,峰段(含尖峰)->放电,平段->根据模式分配
# periods 支持两种格式:
#   1. 单一时段: [(start, end, type), ...]
#   2. 多季节时段: [((months_tuple), [(start, end, type), ...]), ...]
def tariff_to_strategy(province: str, month: int = None) -> list:
    """将省份电价时段转化为充放电策略时段列表.
    month: 当前月份(1-12),None则使用默认/第一个季节模式
    返回: [(start_hour, end_hour, 'charge'|'discharge'), ...]
    """
    info = PROVINCE_TARIFF_DB.get(province)
    if not info or 'periods' not in info:
        return []

    # v2.23: 电价生效日期检查--未到生效日期时给出警告
    effective_from = info.get('effective_from')
    if effective_from:
        try:
            eff_date = datetime.strptime(effective_from, '%Y-%m-%d')
            if datetime.now() < eff_date:
                log.warning(f"{province}电价策略生效日期为{effective_from},当前日期尚未生效,计算结果可能偏离现行政策")
        except ValueError:
            pass

    mode = info.get('mode', '两充两放')
    raw_periods = info['periods']
    if not raw_periods:
        return []  # v2.19: 空时段保护

    # 检测是否为多季节格式
    if isinstance(raw_periods[0], tuple) and len(raw_periods[0]) >= 1 and isinstance(raw_periods[0][0], tuple):
        # 多季节格式: [((1,2,12), [...]), ((6,7,8), [...]), ...]
        if month is None:
            month = 1  # 默认冬季
        periods = None
        for months_tuple, p in raw_periods:
            if month in months_tuple:
                periods = p
                break
        if periods is None:
            periods = raw_periods[0][1]  # fallback to first
    else:
        periods = raw_periods

    strategy = []
    for start, end, ptype in periods:
        # v2.19: 跨零点时段拆分 - 国内多数省份谷段跨零点(如22:00-8:00)
        segments = [(start, 24, ptype), (0, end, ptype)] if start > end else [(start, end, ptype)]
        for seg_start, seg_end, seg_type in segments:
            if seg_type in ('valley', 'deep_valley'):
                strategy.append((seg_start, seg_end, 'charge'))
            elif seg_type == 'peak':
                strategy.append((seg_start, seg_end, 'discharge'))
            elif seg_type == 'flat':
                # v2.23: 平段分配修正 - 两充两放下上午平段充电(准备峰段放电)、下午平段放电
                # 参考: 浙江/江苏等省份实际电价结构,上午平段位于谷段和峰段之间->充电;
                # 下午平段位于两峰段之间或峰段之后->放电
                if mode == CHARGE_MODE_TWO_CYCLES:
                    if seg_start < 12:
                        strategy.append((seg_start, seg_end, 'charge'))
                    else:
                        strategy.append((seg_start, seg_end, 'discharge'))
                else:
                    strategy.append((seg_start, seg_end, 'charge'))

    return strategy

def get_province_presets(month: int = None) -> dict:
    """获取所有省份的预设充放电策略.
    month: 可选月份参数,自动选择对应季节时段
    """
    return {p: tariff_to_strategy(p, month) for p in PROVINCE_TARIFF_DB}

