def _default_plot_processes():
    # v2.28: 放开核数上限——原min(4, cpu-1)在8核+机器上浪费了一半算力
    cpu = mp.cpu_count()
    return min(8, max(4, cpu - 2)) if cpu >= 6 else max(2, cpu - 1)

