_log_root_handler = None

# v2.23: 日志初始化锁
_log_init_lock = threading.Lock()
_log_initialized = False

def _init_logging_now():
    global _log_root_handler, _log_initialized
    with _log_init_lock:
        if _log_initialized:
            return
        os.makedirs(_LOG_DIR, exist_ok=True)
        _log_root_handler = _create_file_handler()
        if _log_root_handler:
            # v2.23: handler绑定到根logger,确保所有模块日志写入同一文件
            root_logger = logging.getLogger()
            root_logger.setLevel(logging.INFO)
            root_logger.addHandler(_log_root_handler)
            logging.captureWarnings(True)
            warnings_logger = logging.getLogger("py.warnings")
            warnings_logger.addHandler(_log_root_handler)
        _log_initialized = True

_init_logging_now()
# v3.2fix: loguru 是可选依赖，缺失时降级到标准 logging。
# 原写法是硬 import，打包环境没装 loguru 时 exe 启动即崩在这一行。
# 代码里只用到 warning/info/error/debug/exception/critical，标准 logging 全都有。
try:
    from loguru import logger as log
    log.remove()
    log.add("logs/ultra_{time}.log", rotation="10 MB", retention="7 days", enqueue=True)
    # v3.2.8fix: windowed 打包后 sys.stderr 是 None，直接 log.add(sys.stderr)
    # 会在模块级抛 TypeError: Cannot log to objects of type 'NoneType'，
    # exe 双击无任何反应（无控制台就看不到错误）。所以先判空再挂控制台 sink。
    if sys.stderr is not None:
        log.add(sys.stderr, colorize=True, format="<green>{time:HH:mm:ss}</green> | <level>{level: <8}</level> | <cyan>{name}</cyan>:<cyan>{function}</cyan> - <level>{message}</level>", level="INFO")
except ImportError:
    log = logging.getLogger("ultra")
    log.setLevel(logging.INFO)
    if not log.handlers and sys.stderr is not None:
        _h = logging.StreamHandler(sys.stderr)
        _h.setFormatter(logging.Formatter("%(asctime)s | %(levelname)-8s | %(name)s - %(message)s", "%H:%M:%S"))
        log.addHandler(_h)

_warned_dup_cols = set()
_warned_dup_lock = threading.Lock()
# endregion

# region 错误信息翻译
_ERROR_TRANSLATION = {
    "MemoryError": "系统内存不足,请关闭其他程序或减少同时处理的文件数量",
    "PermissionError": "文件写入权限不足,请更换输出目录(如桌面)或检查文件是否被其他程序占用",
    "FileNotFoundError": "文件未找到,请检查路径是否正确",
    "UnicodeDecodeError": "文件编码错误,请尝试切换编码格式(设置→CSV编码)",
    "IndexError": "数据索引越界,可能日期与时间点数量不匹配.请检查: ①日期列格式 ②时间列数量",
    "TypeError": "数据类型错误,请检查负荷列是否包含非数值文本",
    "OSError": "系统I/O错误,可能磁盘已满、路径无效或文件被占用",
    "BrokenPipeError": "多进程通信中断,请减少并行度(设置→绘图进程数→1)后重试",
    "RuntimeError": "运行时错误:{msg}",
    "BrokenProcessPool": "渲染工作进程意外退出,已自动重建.如反复出现请减少并行度",
    "ValueError": "数据值异常: {msg}",
    "KeyError": "缺失必需的配置项,请重新进行列映射",
    "NotImplementedError": "该功能在当前模式下不可用,请切换引擎模式",
    "ConnectionRefusedError": "多进程连接被拒绝,请关闭防火墙或安全软件后重试",
}

def _translate_error(exc_type, exc_msg):
    str_type = str(exc_type)
    # v2.23: KeyError精确处理优先--提取缺失列名,比通用模板更友好
    if "KeyError" in str_type:
        match = re.search(r"'([^']*)'", str(exc_msg))
        if match:
            return f'未找到列"{match.group(1)}",请检查列名是否存在多余空格或全角字符'
        return "未找到所需列,请检查列名是否有多余空格或全角符号"
    for tech, template in _ERROR_TRANSLATION.items():
        if tech in str_type:
            if tech == "RuntimeError":
                return template.replace("{msg}", str(exc_msg))
            return template
    if "could not convert" in str(exc_msg).lower():
        return "数据格式错误:无法将文本转换为数值,请检查数据中是否包含非数字字符(如'--'或'N/A')"
    if "cannot reindex" in str(exc_msg).lower():
        return "数据索引不匹配,可能是日期或时间列存在重复值.请检查: ①是否有重复日期 ②资产号是否混用"
    if "no numeric data" in str(exc_msg).lower():
        return "未找到可绘制的数值数据,请检查负荷列是否正确映射"
    if "broadcast" in str(exc_msg).lower():
        return "数据维度不匹配:可能多月份时间点数不同.请检查每个月份的时间列数量是否一致"
    if "shapes" in str(exc_msg).lower():
        return f"数据形状不匹配.请确认: ①所有月份时间点数一致 ②日期与数据行数对应.详情: {exc_msg}"
    if "permission" in str(exc_msg).lower():
        return "文件访问被拒绝,请更换输出目录到桌面或文档文件夹"
    return f"发生错误:{exc_msg}"
# endregion

# region 绘图选项数据类
@dataclass(slots=True)
class PlotOptions:
    show_daily: bool = True
    show_avg: bool = True
    show_max_demand: bool = False
    fit_types: list[str] = field(default_factory=list)
    # 算法拟合曲线(v2.8 新增)
    fit_algorithm: str = 'none'  # 'none' | 'percentile' | 'kmedoids' | 'gmm' | 'svd' | 'dtw_kmedoids'
    enable_fit_overlay: bool = False  # 启用算法拟合
    replace_with_fit: bool = False    # 拟合曲线替代原始日线
    show_fit_clusters: bool = True    # 多簇算法时显示各簇独立曲线
    fit_percentile: float = 90.0      # 分位数(50/90/95)
    fit_n_clusters: int = 3           # 聚类数
    fit_n_components: float = 0.90    # SVD 方差解释率
    fit_auto_k: bool = False          # v2.9: 自动选簇数
    highlight_mode: str = 'none'
    weekday_color: str = DEFAULT_WEEKDAY_COLOR
    weekend_color: str = DEFAULT_WEEKEND_COLOR
    holiday_color: str = DEFAULT_HOLIDAY_COLOR
    weekend_line_width: float = DEFAULT_WEEKEND_LINE_WIDTH
    holiday_line_width: float = DEFAULT_HOLIDAY_LINE_WIDTH
    show_weekend_bg: bool = False
    legend_position: str = 'right'
    mark_anomalies: bool = False
    dark_theme: bool = False

    def to_dict(self):
        return {
            'show_daily': self.show_daily,
            'show_avg': self.show_avg,
            'show_max_demand': self.show_max_demand,
            'fit_types': self.fit_types,
            'fit_algorithm': self.fit_algorithm,
            'enable_fit_overlay': self.enable_fit_overlay,
            'replace_with_fit': self.replace_with_fit,
            'show_fit_clusters': self.show_fit_clusters,
            'fit_percentile': self.fit_percentile,
            'fit_n_clusters': self.fit_n_clusters,
            'fit_n_components': self.fit_n_components,
            'fit_auto_k': self.fit_auto_k,
            'highlight_mode': self.highlight_mode,
            'weekday_color': self.weekday_color,
            'weekend_color': self.weekend_color,
            'holiday_color': self.holiday_color,
            'weekend_line_width': self.weekend_line_width,
            'holiday_line_width': self.holiday_line_width,
            'show_weekend_bg': self.show_weekend_bg,
            'legend_position': self.legend_position,
            'mark_anomalies': self.mark_anomalies,
            'dark_theme': self.dark_theme,
        }

    @classmethod
    def from_dict(cls, d):
        """从字典恢复 PlotOptions,忽略未知字段并警告"""
        known = set(cls.__dataclass_fields__.keys())
        unknown = set(d.keys()) - known
        if unknown:
            log.debug(f"PlotOptions.from_dict 忽略未知字段: {unknown}")
        return cls(**{k: v for k, v in d.items() if k in known})
# endregion

# region GSAP-style 动画工具集 (Qt 等价实现)
class Anim:
    """GSAP 风格动画工厂 v2.所有方法返回 QAbstractAnimation,可组合到时间线.
    新增: quickTo, from, defaults, interpolateColor (gsap.utils), autoAlpha (gsap-core)"""
    EASING = {'none': QEasingCurve.Linear, 'power2.out': QEasingCurve.OutCubic,
              'power3.out': QEasingCurve.OutQuart, 'power2.inOut': QEasingCurve.InOutCubic,
              'back.out': QEasingCurve.OutBack, 'expo.out': QEasingCurve.OutExpo,
              'elastic.out': QEasingCurve.OutElastic, 'bounce.out': QEasingCurve.OutBounce}
    _defaults = {'duration': 0.5, 'ease': 'power2.out'}
    _quickTo_cache = {}
    _quickTo_maxsize = 200  # v2.23: 缓存上限,防止内存无限增长
    _quickTo_lock = threading.Lock()  # v2.23: 线程安全锁

    @classmethod
    def _cleanup_quickto(cls, target_id):
        """v2.23: 清理已销毁target的缓存条目"""
        with cls._quickTo_lock:
            keys_to_remove = [k for k in cls._quickTo_cache if k[0] == target_id]
            for k in keys_to_remove:
                del cls._quickTo_cache[k]

    @classmethod
    def defaults(cls, **kwargs):
        """gsap.defaults(): 设置全局默认参数"""
        cls._defaults.update(kwargs)

    @staticmethod
    def quickTo(target, prop, duration=None, ease=None):
        """gsap.quickTo(): 返回可高频调用的函数,复用同一个动画实例.
        v2.23: target销毁时自动清理缓存,防止内存泄漏."""
        key = (id(target), prop)
        with Anim._quickTo_lock:
            anim = Anim._quickTo_cache.get(key)
        if anim is None:
            anim = QPropertyAnimation(target, prop.encode() if isinstance(prop, str) else prop)
            anim.setDuration(int((duration or Anim._defaults['duration']) * 1000))
            anim.setEasingCurve(Anim.EASING.get(ease or Anim._defaults['ease'], QEasingCurve.OutCubic))
            # v2.23: target销毁时自动清理缓存
            target.destroyed.connect(lambda obj=None, k=key: Anim._cleanup_quickto(id(target)))
            with Anim._quickTo_lock:
                # LRU驱逐
                while len(Anim._quickTo_cache) >= Anim._quickTo_maxsize:
                    oldest = next(iter(Anim._quickTo_cache))
                    del Anim._quickTo_cache[oldest]
                Anim._quickTo_cache[key] = anim
        def _set(val):
            anim.stop()
            anim.setEndValue(val)
            anim.start()
        return _set

    @staticmethod
    def to(target, prop, to_val, duration=0.5, ease='power2.out', delay=0.0):
        """gsap.to() -> QPropertyAnimation from current to target"""
        anim = QPropertyAnimation(target, prop.encode() if isinstance(prop, str) else prop)
        anim.setEndValue(to_val); anim.setDuration(int(duration*1000))
        anim.setEasingCurve(Anim.EASING.get(ease, QEasingCurve.OutCubic))
        if delay > 0:
            g = QSequentialAnimationGroup(); g.addPause(int(delay*1000)); g.addAnimation(anim); return g
        return anim

    @staticmethod
    def from_(target, prop, from_val, duration=0.5, ease='power2.out', delay=0.0):
        """gsap.from(): 从 from_val 动画到当前值.
        v2.23: 简化属性值获取逻辑,统一处理 str/bytes prop."""
        # v2.23: 规范化prop为bytes(QPropertyAnimation需要的格式)
        prop_bytes = prop.encode() if isinstance(prop, str) else prop
        # 获取当前属性值
        cur = target.property(prop_bytes) if isinstance(prop, bytes) else getattr(target, prop, None)
        if cur is None:
            cur = 0  # 回退默认值
        # 先设置到起始值
        target.setProperty(prop_bytes, from_val)
        anim = QPropertyAnimation(target, prop_bytes)
        anim.setStartValue(from_val)
        anim.setEndValue(cur)
        anim.setDuration(int(duration*1000))
        anim.setEasingCurve(Anim.EASING.get(ease, QEasingCurve.OutCubic))
        if delay > 0:
            g = QSequentialAnimationGroup(); g.addPause(int(delay*1000)); g.addAnimation(anim); return g
        return anim
    @staticmethod
    def fromTo(target, prop, fv, tv, duration=0.5, ease='power2.out', delay=0.0):
        anim = QPropertyAnimation(target, prop.encode() if isinstance(prop, str) else prop)
        anim.setStartValue(fv); anim.setEndValue(tv); anim.setDuration(int(duration*1000))
        anim.setEasingCurve(Anim.EASING.get(ease, QEasingCurve.OutCubic))
        if delay > 0:
            g = QSequentialAnimationGroup(); g.addPause(int(delay*1000)); g.addAnimation(anim); return g
        return anim
    @staticmethod
    def fadeIn(target, duration=0.3, ease='power2.out'):
        target.setWindowOpacity(0.0); target.show()
        return Anim.to(target, b'windowOpacity', 1.0, duration=duration, ease=ease)
    @staticmethod
    def fadeOut(target, duration=0.3, ease='power2.inOut', on_finish=None):
        anim = Anim.to(target, b'windowOpacity', 0.0, duration=duration, ease=ease)
        if on_finish: anim.finished.connect(lambda: (on_finish(), target.hide()))
        else: anim.finished.connect(target.hide)
        return anim
    @staticmethod
    def timeline(*animations):
        tl = QSequentialAnimationGroup()
        for a in animations:
            if isinstance(a, QAbstractAnimation): tl.addAnimation(a)
            elif isinstance(a, (int, float)): tl.addPause(int(a*1000))
        return tl
    @staticmethod
    def parallel(*animations):
        pg = QParallelAnimationGroup()
        for a in animations:
            if isinstance(a, QAbstractAnimation): pg.addAnimation(a)
        return pg
    @staticmethod
    def stagger(targets, prop, from_vals, to_vals, stagger_amt=0.08, duration=0.5, ease='power2.out'):
        pg = QParallelAnimationGroup()
        for i, t in enumerate(targets):
            fv = from_vals[i] if isinstance(from_vals, (list, tuple)) else from_vals
            tv = to_vals[i] if isinstance(to_vals, (list, tuple)) else to_vals
            pg.addAnimation(Anim.fromTo(t, prop, fv, tv, duration=duration, ease=ease, delay=i*stagger_amt))
        return pg
    @staticmethod
    def interpolateColor(c1, c2, progress):
        """gsap.utils.interpolate: RGBA 颜色插值"""
        return QColor(int(c1.red()+(c2.red()-c1.red())*progress),
                      int(c1.green()+(c2.green()-c1.green())*progress),
                      int(c1.blue()+(c2.blue()-c1.blue())*progress),
                      int(c1.alpha()+(c2.alpha()-c1.alpha())*progress))
    @staticmethod
    def repeat(anim, count=-1):
        """gsap repeat: 循环动画"""
        anim.setLoopCount(count if count > 0 else -1)
        return anim
    @staticmethod
    def yoyo_pair(target, prop, val_a, val_b, duration=0.5, ease='power2.inOut'):
        """gsap yoyo + repeat: 往返动画对"""
        a = Anim.to(target, prop, val_a, duration=duration, ease=ease)
        b = Anim.to(target, prop, val_b, duration=duration, ease=ease)
        a.finished.connect(b.start)
        b.finished.connect(a.start)
        return a, b
# endregion

# region 粒子动画系统(优化:粒子数量可控,减少 CPU 占用)
class Particle:
    __slots__ = ('pos', 'vel', 'color', 'life', 'max_life', 'size', 'initial_color',
                 'trail_points', 'max_trail_length')
    def __init__(self, x, y, vx, vy, color, life=1.0, size=3.0):
        self.pos = QPointF(x, y)
        self.vel = QPointF(vx, vy)
        self.initial_color = QColor(color)
        self.color = QColor(color)
        self.life = life
        self.max_life = life
        self.size = size
        self.trail_points = []
        self.max_trail_length = 5

    def update(self, dt, target_rect=None, mode='assembly'):
        self.life -= dt
        gravity = 80.0
        friction = 0.5
        if mode == 'assembly':
            if target_rect:
                center = target_rect.center()
                dx = center.x() - self.pos.x()
                dy = center.y() - self.pos.y()
                dist = max(1.0, math.hypot(dx, dy))
                force = 300.0 / dist
                self.vel += QPointF(dx * force * dt, dy * force * dt)
                perp_x = -dy
                perp_y = dx
                rot_force = 80.0 / dist
                self.vel += QPointF(perp_x * rot_force * dt, perp_y * rot_force * dt)
                self.vel += QPointF(random.uniform(-15, 15), random.uniform(-15, 15))
        elif mode == 'disassembly' and target_rect:
            center = target_rect.center()
            dx = self.pos.x() - center.x()
            dy = self.pos.y() - center.y()
            dist = max(1.0, math.hypot(dx, dy))
            force = 400.0 / dist
            self.vel += QPointF(dx * force * dt, dy * force * dt)
            tang_x = -dy
            tang_y = dx
            self.vel += QPointF(tang_x * 80.0 * dt / dist, tang_y * 80.0 * dt / dist)
        self.vel += QPointF(0, gravity * dt)
        vel_mag = math.hypot(self.vel.x(), self.vel.y())
        if vel_mag > 0:
            friction_force = friction * vel_mag * dt / max(1.0, self.size)
            self.vel -= QPointF(self.vel.x() / vel_mag * friction_force,
                                self.vel.y() / vel_mag * friction_force)
        self.pos += self.vel * dt
        if len(self.trail_points) >= self.max_trail_length:
            self.trail_points.pop(0)
        self.trail_points.append(QPointF(self.pos))
        life_ratio = max(0.0, min(1.0, self.life / self.max_life))  # clamp 防止负值闪烁
        r = max(0, min(255, int(self.initial_color.red() * life_ratio)))
        g = max(0, min(255, int(self.initial_color.green() * life_ratio)))
        b = max(0, min(255, int(self.initial_color.blue() * life_ratio)))
        alpha = max(0, min(255, int(255 * life_ratio)))
        self.color = QColor(r, g, b, alpha)
        return self.life > 0

    def draw(self, painter):
        painter.setPen(Qt.NoPen)
        if len(self.trail_points) > 1:
            for i in range(len(self.trail_points) - 1):
                p1 = self.trail_points[i]
                p2 = self.trail_points[i + 1]
                alpha = int(100 * (i + 1) / len(self.trail_points))
                trail_color = QColor(self.color.red(), self.color.green(), self.color.blue(), alpha)
                pen = QPen(trail_color, max(1, self.size * 0.5), Qt.SolidLine, Qt.RoundCap)
                painter.setPen(pen)
                painter.drawLine(p1, p2)
        glow_size = self.size * 2.5
        gradient = QRadialGradient(self.pos, glow_size)
        c = self.color
        gradient.setColorAt(0, QColor(c.red(), c.green(), c.blue(), min(255, int(c.alpha() * 1.5))))
        gradient.setColorAt(0.5, QColor(c.red(), c.green(), c.blue(), int(c.alpha() * 0.8)))
        gradient.setColorAt(1, QColor(c.red(), c.green(), c.blue(), 0))
        painter.setBrush(QBrush(gradient))
        painter.setPen(Qt.NoPen)
        painter.drawEllipse(self.pos, glow_size, glow_size)
        painter.setBrush(self.color)
        painter.drawEllipse(self.pos, self.size, self.size)

class ParticleOverlay(QWidget):
    finished = Signal()

    def __init__(self):
        super().__init__()
        self.particles = []
        self.timer = QTimer(self)
        self.timer.timeout.connect(self._animate)
        self.last_time = time.perf_counter()
        self.mode = 'assembly'
        self.target_rect = QRectF()
        self.on_finish = None
        self._speed_mult = 1.0
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint | Qt.Tool)
        self.setAttribute(Qt.WA_TranslucentBackground)
        screen = QApplication.primaryScreen()
        if screen:
            self.setGeometry(screen.geometry())
        else:
            self.setGeometry(0, 0, 800, 600)

    def start_assembly(self, target_rect, color=None, on_finish=None):
        if color is None:
            color = DesignTokens.current_tokens()['PARTICLE_COLOR']
        self.target_rect = target_rect
        self.on_finish = on_finish
        self.mode = 'assembly'
        # 窗口越小,粒子速度越快(反比于对角线长度)
        ref_diag = 1400.0  # 参考:全屏窗口对角线
        diag = math.hypot(target_rect.width(), target_rect.height())
        self._speed_mult = max(1.0, min(4.0, ref_diag / max(diag, 200)))
        self._generate_assembly_particles(color)
        self.show()
        self.last_time = time.perf_counter()
        self.timer.start(16)

    def start_disassembly(self, pixmap, on_finish=None):
        self.on_finish = on_finish
        self.mode = 'disassembly'
        w, h = pixmap.width(), pixmap.height()
        ref_diag = 1400.0
        diag = math.hypot(w, h)
        self._speed_mult = max(1.0, min(4.0, ref_diag / max(diag, 200)))
        self._generate_from_pixmap(pixmap)
        self.show()
        self.last_time = time.perf_counter()
        self.timer.start(16)

    def _particle_count_for_rect(self, rect):
        area = rect.width() * rect.height()
        return max(25, min(70, int(area / 10000)))

    def _generate_assembly_particles(self, color):
        self.particles.clear()
        count = self._particle_count_for_rect(self.target_rect)
        screen = self.geometry()
        for _ in range(count):
            x = random.uniform(0, screen.width())
            y = random.uniform(0, screen.height())
            vx = random.uniform(-100, 100)
            vy = random.uniform(-100, 100)
            self.particles.append(Particle(x, y, vx, vy, color, life=random.uniform(0.8, 2.0), size=random.uniform(1.5, 3.5)))

    def _generate_from_pixmap(self, pixmap):
        self.particles.clear()
        img = pixmap.toImage()
        w, h = img.width(), img.height()
        count = self._particle_count_for_rect(QRectF(0, 0, w, h))
        for _ in range(count):
            x = random.uniform(0, w)
            y = random.uniform(0, h)
            col = img.pixelColor(int(x), int(y))
            r = min(255, max(0, col.red() + random.randint(-10, 10)))
            g = min(255, max(0, col.green() + random.randint(-10, 10)))
            b = min(255, max(0, col.blue() + random.randint(-10, 10)))
            gray = int(0.3 * r + 0.59 * g + 0.11 * b)
            r, g, b = int(r * 0.8 + gray * 0.2), int(g * 0.8 + gray * 0.2), int(b * 0.8 + gray * 0.2)
            col = QColor(r, g, b)
            vx = random.uniform(-300, 300)
            vy = random.uniform(-400, 200)
            self.particles.append(Particle(x, y, vx, vy, col, life=random.uniform(0.5, 1.5), size=random.uniform(1.5, 3.5)))

    def _animate(self):
        dt = time.perf_counter() - self.last_time
        self.last_time = time.perf_counter()
        dt = min(dt, 0.05) * self._speed_mult
        # OPT: list comprehension 替代 append 循环,减少 Python 字节码
        self.particles[:] = [p for p in self.particles if p.update(dt, self.target_rect, self.mode)]
        self.update()
        if not self.particles:
            self.timer.stop()
            self.hide()
            if self.on_finish:
                self.on_finish()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.fillRect(self.rect(), Qt.transparent)
        for p in self.particles:
            p.draw(painter)
        painter.end()

class WindowAnimator(QObject):
    _instance = None
    _overlay = None

    def __init__(self):
        super().__init__()
        if not WindowAnimator._overlay:
            WindowAnimator._overlay = ParticleOverlay()

    @staticmethod
    def instance():
        if WindowAnimator._instance is None:
            WindowAnimator._instance = WindowAnimator()
        return WindowAnimator._instance

    def show_dialog_async(self, dialog, trigger_widget=None, callback=None):
        if not Config._global_enable_particles:
            dialog.show()
            if callback:
                callback()
            return
        dialog.setWindowOpacity(0.0)
        dialog.show()
        QApplication.processEvents()
        if trigger_widget:
            rect = QRectF(trigger_widget.mapToGlobal(QPoint(0,0)),
                          trigger_widget.size())
        else:
            rect = dialog.geometry()
        def finish():
            dialog.setWindowOpacity(1.0)
            if callback:
                callback()
        WindowAnimator._overlay.start_assembly(rect, on_finish=finish)

    def close_dialog_async(self, dialog, callback=None):
        if not Config._global_enable_particles:
            dialog.hide()
            if callback:
                callback()
            return
        pixmap = dialog.grab()
        def finish():
            if callback:
                callback()
        WindowAnimator._overlay.start_disassembly(pixmap, on_finish=finish)

    def close_window_async(self, window, callback=None):
        if not Config._global_enable_particles:
            window.hide()
            if callback:
                callback()
            return
        pixmap = window.grab()
        window.hide()
        def finish():
            if callback:
                callback()
        WindowAnimator._overlay.start_disassembly(pixmap, on_finish=finish)

# region Toast 通知系统(非阻塞式浮动提示,替代 QMessageBox 中断)
class Toast(QFrame):
    """现代 Toast 通知:从顶部滑入,自动消失"""
    closed = Signal()
    __slots__ = ('_anim_in', '_anim_out', '_slide_anim', '_timer')

    _COLORS = {
        'info':    ('#5B8CBF', '#E6F0F8', 'i'),
        'success': ('#5A9E6F', '#E8F5E9', '✓'),
        'warning': ('#D4915E', '#FFF3E0', '⚠'),
        'error':   ('#C75B4A', '#FFEBEE', '✕'),
    }

    def __init__(self, text, kind='info', duration=3500, parent=None):
        super().__init__(parent)
        self.setObjectName("toast")
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.Tool | Qt.WindowStaysOnTopHint)
        self.setAttribute(Qt.WA_TranslucentBackground, True)
        self.setAttribute(Qt.WA_ShowWithoutActivating, True)
        self.setAttribute(Qt.WA_DeleteOnClose, True)

        accent, bg, icon_char = self._COLORS.get(kind, self._COLORS['info'])

        layout = QHBoxLayout(self)
        layout.setContentsMargins(16, 12, 16, 12)
        layout.setSpacing(10)

        icon_lbl = QLabel(icon_char)
        icon_lbl.setFont(get_default_font(18, bold=True))
        icon_lbl.setStyleSheet(f"color: {accent}; background: transparent;")
        icon_lbl.setFixedWidth(24)
        layout.addWidget(icon_lbl)

        text_lbl = QLabel(text)
        text_lbl.setWordWrap(True)
        text_lbl.setFont(get_default_font(12, bold=True))
        text_lbl.setStyleSheet(f"color: {DesignTokens.current_tokens()['TEXT_PRIMARY'].name()}; background: transparent;")
        text_lbl.setMaximumWidth(420)
        layout.addWidget(text_lbl, 1)

        close_btn = QPushButton("x")
        close_btn.setFixedSize(22, 22)
        close_btn.setFont(get_default_font(14, bold=True))
        close_btn.setStyleSheet(f"QPushButton {{ border: none; color: {DesignTokens.current_tokens()['TEXT_SECONDARY'].name()}; background: transparent; border-radius: 11px; }} QPushButton:hover {{ background: {DesignTokens.current_tokens()['BTN_BG_HOVER'].name()}; }}")
        close_btn.clicked.connect(self._dismiss)
        layout.addWidget(close_btn)

        self.setStyleSheet(f"""
            #toast {{
                background: {bg};
                border: 1px solid {accent};
                border-radius: 12px;
            }}
        """)

        self._anim_in = Anim.to(self, b'windowOpacity', 1.0, duration=0.3, ease='power2.out')
        self._anim_out = Anim.to(self, b'windowOpacity', 0.0, duration=0.25, ease='power2.inOut')
        self._anim_out.finished.connect(self._on_fade_done)
        self._slide_anim = QPropertyAnimation(self, b'pos')
        self._slide_anim.setDuration(350)
        self._slide_anim.setEasingCurve(QEasingCurve.OutBack)

        self._timer = QTimer(self)
        self._timer.setSingleShot(True)
        self._timer.timeout.connect(self._start_dismiss)
        self._timer.start(duration)

    def show_at(self, parent_rect: QRect):
        self.adjustSize()
        w, h = self.sizeHint().width(), self.sizeHint().height()
        x = parent_rect.center().x() - w // 2
        y = parent_rect.top() + 48
        self.setGeometry(x, y - 40, w, h)
        self.show()
        self.raise_()
        self._anim_in.start()
        self._slide_anim.setStartValue(QPoint(x, y - 40))
        self._slide_anim.setEndValue(QPoint(x, y))
        self._slide_anim.start()

    def _start_dismiss(self):
        self._anim_out.start()

    def _dismiss(self):
        self._timer.stop()
        self._anim_out.start()

    def _on_fade_done(self):
        self.closed.emit()
        self.close()


class ToastManager(QObject):
    """全局 Toast 管理器,确保同一窗口同时最多显示 3 条"""
    # ToastManager 锁
    _toast_lock = threading.Lock()  # v2.23: 线程安全
    _instances = {}
    _max_visible = 3
    _stack_offset = 0

    @classmethod
    def show(cls, parent, text, kind='info', duration=3500):
        with cls._toast_lock:
            parent_id = id(parent)
        if parent_id not in cls._instances:
            cls._instances[parent_id] = []
        active = cls._instances[parent_id]
        active[:] = [t for t in active if t.isVisible()]
        if len(active) >= cls._max_visible:
            oldest = active.pop(0)
            oldest._dismiss()
        toast = Toast(text, kind, duration, parent)
        active.append(toast)
        toast.closed.connect(lambda: cls._cleanup(parent_id, toast))
        if parent and parent.isVisible():
            parent_rect = parent.geometry()
            if parent_rect.width() > 0:
                offset = len(active) * 55
                toast.show_at(parent_rect.translated(0, offset))
                return
        screen = QApplication.primaryScreen()
        toast.show_at(screen.availableGeometry())

    @classmethod
    def _cleanup(cls, parent_id, toast):
        with cls._toast_lock:
            if parent_id in cls._instances:
                lst = cls._instances[parent_id]
                if toast in lst:
                    lst.remove(toast)
        # v2.23: Toast消失后重新排列剩余Toast位置
        cls._reposition(parent_id)

    @classmethod
    def _reposition(cls, parent_id):
        """v2.23: Toast消失后重新计算剩余Toast的垂直偏移"""
        if parent_id not in cls._instances:
            return
        active = [t for t in cls._instances[parent_id] if t.isVisible()]
        for i, t in enumerate(active):
            parent = t.parent()
            if parent and parent.isVisible():
                rect = parent.geometry()
                if rect.width() > 0:
                    t.show_at(rect.translated(0, i * 55))
# endregion

class AnimatedDialog(QDialog):
    """带动画效果的对话框基类.v2.23: 嵌套事件循环加30s超时保护.v2.15: closeEvent清理信号连接"""
    def __init__(self, parent=None):
        super().__init__(parent)
        self._animator = WindowAnimator.instance()
        self._result = QDialog.Rejected
        self._was_accepted = False

    def closeEvent(self, event):
        """v3.2fix: 定向清理内部信号,不用 self.disconnect() 全切断(会误伤外部连接)."""
        # 只停内部定时器,Qt parent-child 自动清理其余信号
        for attr in ('_timeout_timer', '_particle_timer', '_fade_timer'):
            t = getattr(self, attr, None)
            if t is not None and t.isActive():
                t.stop()
        super().closeEvent(event)

    def exec(self):
        if not Config._global_enable_particles:
            return super().exec()
        self._result = QDialog.Rejected
        loop = QEventLoop()
        # v2.23: 30秒超时保护,防止粒子动画回调未触发导致永久阻塞
        _timeout_timer = QTimer(self)
        _timeout_timer.setSingleShot(True)
        _timeout_timer.timeout.connect(loop.quit)
        _timeout_timer.start(30000)
        def after_show():
            self._result = super(AnimatedDialog, self).exec()
            loop.exit()
        self._animator.show_dialog_async(self, None, after_show)
        loop.exec()
        _timeout_timer.stop()
        return self._result

    def done(self, r):
        if not Config._global_enable_particles:
            super().done(r)
            return
        self._result = r
        try:
            pixmap = self.grab()
        except Exception:
            pixmap = None  # v2.28fix: grab失败时跳过粒子动画
        super().done(r)
        if pixmap and not pixmap.isNull() and WindowAnimator._overlay:
            WindowAnimator._overlay.start_disassembly(pixmap)
# endregion

# region 缓存与工具函数
class LRUCache:
    """线程安全 LRU 缓存,含命中率统计"""
    __slots__ = ('cache', 'maxsize', '_lock', 'hits', 'misses', 'evictions')
    def __init__(self, maxsize=20000):
        self.cache = OrderedDict()
        self.maxsize = maxsize
        self._lock = threading.RLock()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
    def get(self, key):
        with self._lock:
            if key in self.cache:
                self.cache.move_to_end(key)
                self.hits += 1
                return self.cache[key]
            self.misses += 1
            return None
    def put(self, key, value):
        with self._lock:
            # v2.23: 重复key先更新热key顺序,防止高频热key被误驱逐
            if key in self.cache:
                self.cache.move_to_end(key)
            self.cache[key] = value
            while len(self.cache) > self.maxsize:
                self.cache.popitem(last=False)
                self.evictions += 1
    def clear(self):
        with self._lock:
            self.cache.clear()
    @property
    def hit_rate(self):
        total = self.hits + self.misses
        return self.hits / total if total else 0.0
    def stats(self):
        return {'size': len(self.cache), 'maxsize': self.maxsize,
                'hits': self.hits, 'misses': self.misses, 'evictions': self.evictions,
                'hit_rate': f'{self.hit_rate:.1%}'}

class MemoryLimitedCache:
    """基于内存限制的 LRU 缓存,线程安全,含统计"""
    __slots__ = ('cache', 'max_memory', 'current_memory', '_lock', '_size_cache',
                 'hits', 'misses', 'evictions', 'put_count')
    def __init__(self, max_memory_bytes=FILE_CACHE_MAX_MEMORY):
        self.cache = OrderedDict()
        self.max_memory = max_memory_bytes
        self.current_memory = 0
        self._lock = threading.RLock()
        self._size_cache = {}
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.put_count = 0

    @staticmethod
    def _sizeof(obj):
        """v2.23: 多层次内存估算--numpy/pandas/list/dict/sys.getsizeof"""
        if isinstance(obj, np.ndarray):
            return obj.nbytes
        pd_mod = sys.modules.get('pandas')
        if pd_mod is not None and isinstance(obj, pd_mod.DataFrame):
            return obj.memory_usage(deep=True).sum()
        # v2.23: 递归估算容器类型
        if isinstance(obj, (list, tuple, set)):
            return sys.getsizeof(obj) + sum(MemoryLimitedCache._sizeof(i) for i in obj)
        if isinstance(obj, dict):
            return sys.getsizeof(obj) + sum(MemoryLimitedCache._sizeof(k) + MemoryLimitedCache._sizeof(v) for k, v in obj.items())
        return sys.getsizeof(obj)

    def get(self, key):
        with self._lock:
            if key in self.cache:
                self.cache.move_to_end(key)
                self.hits += 1
                return self.cache[key]
            self.misses += 1
            return None

    def put(self, key, value):
        """v2.15: 修复重复 key 时旧内存未释放导致的 current_memory 漂移.
        v2.23: _sizeof 改进--对 list/dict 做递归深度估算."""
        with self._lock:
            # 若 key 已存在,先释放旧条目的内存跟踪
            if key in self.cache:
                old_size = self._size_cache.pop(key, 0)
                self.current_memory -= old_size
                self.cache.pop(key)
            size = self._sizeof(value)
            # 批量驱逐:一次性驱逐多个旧条目直到空间够用,减少锁持有时间
            victims = []
            while self.current_memory + size > self.max_memory and self.cache:
                oldest_key = next(iter(self.cache))
                victims.append(oldest_key)
                old_size = self._size_cache.pop(oldest_key, 0)
                self.current_memory -= old_size
                self.cache.pop(oldest_key)
                self.evictions += 1
            self.cache[key] = value
            self._size_cache[key] = size
            self.current_memory += size
            self.put_count += 1

    def remove(self, key):
        with self._lock:
            if key in self.cache:
                old_val = self.cache.pop(key)
                old_size = self._size_cache.pop(key, self._sizeof(old_val))
                self.current_memory -= old_size

    def clear(self):
        with self._lock:
            self.cache.clear()
            self._size_cache.clear()
            self.current_memory = 0

    def __contains__(self, key):
        with self._lock:
            return key in self.cache

    def items(self):
        with self._lock:
            return list(self.cache.items())

TIME_CACHE = LRUCache(maxsize=TIME_CACHE_MAXSIZE)

_CLEAN_RE = re.compile(r'[\x00-\x1f\x7f]')
_TIME_HHMM_RE = re.compile(r'(\d{1,2}:\d{2})')
_TIME_T_SLOT_RE = re.compile(r'[TtPp](\d{1,2})')
_PATH_ILLEGAL_CHARS_RE = re.compile(r'[<>:"/\\|?*]')
_PATH_DOT_RE = re.compile(r'\.{2,}')
# 预编译高频正则 (性能优化:避免每次调用时重复编译)
_RE_DATE_YYYYMM = re.compile(r'^(\d{4}-\d{2})$')
_RE_DATE_YYYY_M = re.compile(r'^(\d{4})-(\d{1,2})$')
_RE_AMPM = re.compile(r'(\d{1,2}):(\d{2})(?:\s*)(AM|PM|am|pm)', re.IGNORECASE)
_RE_DATE_FULL = re.compile(r'(\d{4}-\d{2}-\d{2})')
_RE_DIGITS_ALL = re.compile(r'\d+')
_RE_TIME_CN_COLON = re.compile(r'^(\d{1,2})\s*[时点](?:钟)?$')
_RE_TIME_CN_HM = re.compile(r'^(\d{1,2})\s*时\s*(\d{1,2})\s*分$')
_RE_TIME_COLON_SUFFIX = re.compile(r'^(\d{1,2})[:：](\d{2})(?:\s*[时分秒])?$')
_RE_YEAR_DIGITS = re.compile(r'^(\d{4})-(\d{2})$')
def _is_supported_file(path: str) -> bool:
    """O(1) 文件扩展名检查,使用 frozenset 替代 tuple.endswith"""
    return os.path.splitext(path)[1].lower() in SUPPORTED_EXTS_SET

_WINDOWS_RESERVED_NAMES = {
    'CON', 'PRN', 'AUX', 'NUL',
    'COM1', 'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8', 'COM9',
    'LPT1', 'LPT2', 'LPT3', 'LPT4', 'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9'
}

def _clean_plot(s):
    return _CLEAN_RE.sub('', str(s)) if isinstance(s, str) else str(s)

def _clean_series(s):
    pd_lib = _get_pd()
    if isinstance(s, pd_lib.DataFrame):
        if s.shape[1] > 0:
            s = s.iloc[:, 0]
        else:
            return pd_lib.Series(dtype=str)
    return s.astype(str).str.replace(_CLEAN_RE, '', regex=True).str.strip()

def _safe_get_col(df, col_name):
    """安全获取列.仅做全角字符规范化+精确匹配,不做模糊匹配.

    设计原则: 列映射中用户选择的列名必须原样使用,程序不自行替换.
    若列名不存在则直接报错,让上层决定如何处理.
    """
    normalized_col_name = _normalize_fullwidth_chars(str(col_name))
    if normalized_col_name in df.columns:
        return df[normalized_col_name]
    if col_name in df.columns:
        return df[col_name]
    raise KeyError(f"列 '{col_name}' 不存在,可用列: {list(df.columns)}")

# v2.28fix: 全角→半角翻译表。源侧为全角Unicode字符(U+FF10-FF19/U+FF1A/U+FF0C/U+3000)
_FULLWIDTH_TRANS_TABLE = str.maketrans(
    '０１２３４５６７８９：，　',
    '0123456789:, '
)

def _normalize_fullwidth_chars(s: str) -> str:
    """全角字符转半角,使用模块级预计算翻译表.
    注意:调用方应确保传入str类型,非str输入返回原值(调用方自行处理)."""
    if not isinstance(s, str):
        return s  # type: ignore[return] — 调用方需自行类型守卫
    return s.strip().translate(_FULLWIDTH_TRANS_TABLE)

def _normalize_time_key(key: str) -> str:
    """合并全角转换+时间列规范化,一次字符串遍历 (OPT: 1.2 times faster than two-pass)"""
    k = key.strip()
    k = k.translate(_FULLWIDTH_TRANS_TABLE)
    m = _RE_TIME_CN_COLON.match(k)
    if m:
        return f"{int(m.group(1))}:00"
    m = _RE_TIME_CN_HM.match(k)
    if m:
        return f"{int(m.group(1))}:{int(m.group(2)):02d}"
    # v2.23: 补充"X点Y分"格式匹配
    _pt_match = re.match(r'^(\d{1,2})\s*点\s*(\d{1,2})\s*分$', k)
    if _pt_match:
        return f"{int(_pt_match.group(1))}:{int(_pt_match.group(2)):02d}"
    m = _RE_TIME_COLON_SUFFIX.match(k)
    if m:
        return f"{m.group(1)}:{m.group(2)}"
    return k

