# region 时间解析优化(预计算常数 + 快速路径)
_HHMM_RE_CACHED = re.compile(r'^(\d{1,2}):(\d{2})$')

def _parse_min(t) -> int:
    """解析时间点为分钟数。
    解析优先级(6条路径,由上至下):
      PATH-1 datetime.time 对象 → 直接取 hour*60+minute
      PATH-2 ASCII HH:MM → str.split(':') 快速路径(覆盖95%+)
      PATH-3 全角/中文格式 → _normalize_time_key 归一化后 regex
      PATH-4 浮点数(0~24) → 小数转分钟
      PATH-5 AM/PM 格式 → 正则+12h制转换
      PATH-6 T/P 槽位格式 → T1=00:00, T96=23:45
    
    注意: Settlement模块有独立的 _parse_min_stl() 简化版,仅支持 HH:MM.
    如需修改时间解析逻辑,请确保两处保持行为一致."""
    # ═══ PATH-1: datetime.time 对象 ═══
    if isinstance(t, dt_time):
        minutes = t.hour * MINUTES_PER_HOUR + t.minute
        TIME_CACHE.put(str(t), (minutes, f"{t.hour:02d}:{t.minute:02d}"))
        return minutes
    key = str(t).strip()
    # ═══ PATH-2: ASCII HH:MM 纯 Python str.split(覆盖95%+调用) ═══
    if key.isascii():
        parts = key.split(':')
        if len(parts) == 2:
            try:
                h, minute = int(parts[0]), int(parts[1])
                if h == 24 and minute == 0:
                    return MINUTES_PER_DAY
                if 0 <= h < 24 and 0 <= minute < 60:
                    return h * MINUTES_PER_HOUR + minute
            except ValueError:
                pass
    # ═══ PATH-3: SLOW PATH 全角转半角+时间列规范化 ═══
    key = _normalize_time_key(key)
    # 快速路径:标准 HH:MM 格式直接解析
    m = _HHMM_RE_CACHED.match(key)
    if m:
        h, minute = int(m.group(1)), int(m.group(2))
        if h == 24 and minute == 0:
            minutes, lbl = MINUTES_PER_DAY, '24:00'
        elif 0 <= h < 24 and 0 <= minute < 60:
            minutes, lbl = h * MINUTES_PER_HOUR + minute, key
        else:
            minutes, lbl = INVALID_MINUTES, key
        TIME_CACHE.put(key, (minutes, lbl))
        return minutes
    # 缓存查询
    cached = TIME_CACHE.get(key)
    if cached is not None:
        return cached[0]
    if key == '24:00':
        TIME_CACHE.put(key, (MINUTES_PER_DAY, '24:00'))
        return MINUTES_PER_DAY
    # ═══ PATH-4: 浮点数格式(如14.5=14:30) ═══
    try:
        val = float(key)
        if 0 <= val <= 24:
            h = int(val)
            m = int(round((val - h) * 60))
            if h == 24:
                minutes, lbl = MINUTES_PER_DAY, '24:00'
            else:
                minutes, lbl = h * MINUTES_PER_HOUR + m, f"{h:02d}:{m:02d}"
            TIME_CACHE.put(key, (minutes, lbl))
            return minutes
        TIME_CACHE.put(key, (INVALID_MINUTES, key))
        return INVALID_MINUTES
    except ValueError:
        pass
    # ═══ PATH-5: AM/PM 格式 ═══
    amp_match = _RE_AMPM.search(key)
    if amp_match:
        h = int(amp_match.group(1))
        m_val = int(amp_match.group(2))
        is_pm = amp_match.group(3).upper() == 'PM'
        if is_pm and h != 12:
            h += 12
        elif not is_pm and h == 12:
            h = 0
        if 0 <= h < 24 and 0 <= m_val < 60:
            minutes = h * MINUTES_PER_HOUR + m_val
            TIME_CACHE.put(key, (minutes, f"{h:02d}:{m_val:02d}"))
            return minutes
    # v2.28fix: 负号前缀保护——防止"-1:00"被_TiME_HHMM_RE误匹配为"1:00"
    if key.startswith('-'):
        TIME_CACHE.put(key, (INVALID_MINUTES, key))
        return INVALID_MINUTES
    # HH:MM 含其他字符
    time_match = _TIME_HHMM_RE.search(key)
    if time_match:
        parts = time_match.group(1).split(':')
        try:
            h, m_val = int(parts[0]), int(parts[1])
            if h == 24:
                minutes, lbl = MINUTES_PER_DAY, '24:00'
            else:
                minutes, lbl = h * MINUTES_PER_HOUR + m_val, f"{h:02d}:{m_val:02d}"
            TIME_CACHE.put(key, (minutes, lbl))
            return minutes
        except (ValueError, IndexError):
            pass
    # T/P 槽位格式
    # ═══ PATH-6: T/P 槽位格式(T1=00:00..T96=23:45) ═══
    slot_match = _TIME_T_SLOT_RE.fullmatch(key)
    if slot_match:
        try:
            slot = int(slot_match.group(1))
            if 1 <= slot <= 96:
                minutes = (slot - 1) * 15
                lbl = f"{minutes // MINUTES_PER_HOUR:02d}:{minutes % MINUTES_PER_HOUR:02d}"
                TIME_CACHE.put(key, (minutes, lbl))
                return minutes
        except ValueError:
            pass
    TIME_CACHE.put(key, (INVALID_MINUTES, key))
    return INVALID_MINUTES

def _fmt_time(t) -> str:
    key = str(t).strip()
    cached = TIME_CACHE.get(key)
    if not cached:
        minutes = _parse_min(t)
        if minutes == INVALID_MINUTES:
            raise ValueError(f"Invalid time format: {t!r}. Expected 'HH:MM' string, float hours (0-24), or datetime.time.")
        cached = TIME_CACHE.get(key)
    return _clean_plot(cached[1] if cached and cached[0] != INVALID_MINUTES else key)

def _sanitize_name(s, max_len=MAX_FILENAME_LEN):
    if not s:
        s = "未命名"
    s = _CLEAN_RE.sub('', str(s)).strip()
    s = _PATH_ILLEGAL_CHARS_RE.sub('_', s)
    s = _PATH_DOT_RE.sub('_', s)
    s = s.lstrip('.')
    if not s:
        s = "未命名"
    base, ext = os.path.splitext(s)
    if base.upper() in _WINDOWS_RESERVED_NAMES:
        s = base + '_' + ext
    return s[:max_len-3]+"..." if len(s) > max_len else s

def _extract_ym(d):
    s = str(d) if not isinstance(d, str) else d  # v2.17fix: 统一转字符串,修复旧版 NameError
    try:
        dt_val = _get_pd().to_datetime(s, errors='coerce')
        if not _get_pd().isna(dt_val):
            return dt_val.strftime('%Y-%m')
    except Exception as e:
        log.debug(f"_extract_ym: 日期解析失败 {s!r}: {e}")
    m1 = _RE_DATE_YYYYMM.match(s)
    if m1:
        return m1.group(1)
    m2 = _RE_DATE_YYYY_M.match(s)
    if m2:
        return f"{m2.group(1)}-{int(m2.group(2)):02d}"
    try:
        dt2 = _get_pd().to_datetime(s, errors='coerce', dayfirst=False)
        if not _get_pd().isna(dt2):
            return dt2.strftime('%Y-%m')
    except Exception:
        pass
    # v2.9c: 转置宽表列名多格式容错 - 点号/斜线/中文/纯数字
    m_dot = re.match(r'(\d{4})\.(\d{1,2})\.(\d{1,2})', s)  # 2024.01.15
    if m_dot:
        return f"{m_dot.group(1)}-{int(m_dot.group(2)):02d}"
    m_slash = re.match(r'(\d{1,2})/(\d{1,2})/(\d{4})', s)  # 1/15/2024
    if m_slash:
        return f"{m_slash.group(3)}-{int(m_slash.group(1)):02d}"
    m_cn = re.match(r'(\d{4})年(\d{1,2})月(\d{1,2})日', s)  # 2024年1月15日
    if m_cn:
        return f"{m_cn.group(1)}-{int(m_cn.group(2)):02d}"
    m_digits = re.match(r'(\d{4})(\d{2})(\d{2})', s)  # 20240115
    if m_digits and 20200101 <= int(s[:8]) <= 20991231:
        return f"{m_digits.group(1)}-{m_digits.group(2)}"
    log.debug(f"无法从 '{s}' 提取有效年月,标记为未知月份")
    return '未知月份'

def _fmt_date(d):
    try:
        dt_val = _get_pd().to_datetime(d, errors='coerce')
        if not _get_pd().isna(dt_val):
            return dt_val.strftime('%Y-%m-%d')
    except Exception:
        pass
    s = str(d).strip()
    m = _RE_DATE_FULL.search(s)
    if m:
        return m.group(1)
    return s.split()[0] if ' ' in s else s

def parse_flexible_time(s):
    s = s.strip().replace(':', ':')
    if ':' in s:
        parts = s.split(':')
        try:
            h, m = int(parts[0]), int(parts[1]) if len(parts)>=2 else 0
        except Exception:
            raise ValueError(f"无法解析 '{s}'") from None
        if 0<=h<=24 and 0<=m<60:
            if h == 24:
                return 24.0
            return h + m/60.0
    if ' ' in s:
        parts = s.split()
        if len(parts)==2:
            try:
                h, m = int(parts[0]), int(parts[1])
            except Exception:
                pass
            else:
                if 0<=h<=24 and 0<=m<60:
                    if h == 24:
                        return 24.0
                    return h + m/60.0
    try:
        v = float(s)
        if 0<=v<=24:
            return v
    except ValueError:
        pass
    if s.isdigit() and len(s)<=4:
        val = int(s)
        h = val//100
        m = val%100
        if 0<=h<=24 and 0<=m<60:
            if h == 24:
                return 24.0
            return h + m/60.0
    raise ValueError(f"无法解析 '{s}',请使用 HH:MM、8.5 或 8 30 格式")

def _fmt_hour(h):
    if h == 24.0:
        return "24:00"
    hh = int(h)
    mm = int(round((h-hh)*60))
    if mm==60:
        hh+=1
        mm=0
    return f"{hh:02d}:{mm:02d}"


def _screen_load_data_quality(data_dict):
    """v2.9 b: IQR 异常值筛查 - 对 load_array 中超出 Q3+3*IQR 的极端值用中位数替换.
    参考文献: 陆旦宏等(2024) GAN-Transformer 异常检测; 张帅等(2020) 多尺度时序建模.
    """
    if data_dict is None or 'load_array' not in data_dict:
        return data_dict
    arr = np.array(data_dict['load_array'], dtype=np.float64, copy=True)  # v2.17fix
    if arr.ndim != 2 or arr.shape[0] < 3:
        return data_dict  # 少于 3 天不足以做 IQR
    n_days, n_points = arr.shape
    anomaly_count = 0
    for j in range(n_points):
        col = arr[:, j]  # arr已是copy,无需再copy
        valid = ~np.isnan(col)
        if valid.sum() < 3:
            continue
        q1, q3 = np.percentile(col[valid], 25), np.percentile(col[valid], 75)
        iqr = q3 - q1
        if iqr <= 0:
            # v2.9e: IQR=0 时用 MAD (Median Absolute Deviation) 作为回退
            med = np.median(col[valid])
            mad = np.median(np.abs(col[valid] - med))
            if mad <= 0:
                # MAD=0 且 IQR=0:数据在该列几乎恒定,跳过异常检测
                # 使用绝对阈值保护:偏离超过该列中位数绝对值 300% 且 > 1kW 才判定异常
                med_abs = max(abs(med), 1.0)
                outlier_mask = (np.abs(col - med) / med_abs > 3.0) & (np.abs(col - med) > 1.0)
                if outlier_mask.any():
                    col[outlier_mask] = med
                    anomaly_count += outlier_mask.sum()
                continue
            lower, upper = med - 10.0 * mad, med + 10.0 * mad
        else:
            lower, upper = q1 - 3.0 * iqr, q3 + 3.0 * iqr
        outlier_mask = (col < lower) | (col > upper)
        if outlier_mask.any():
            median_val = np.median(col[valid])
            col[outlier_mask] = median_val
            anomaly_count += outlier_mask.sum()
    if anomaly_count > 0:
        data_dict['load_array'] = arr
        log.warning(f"数据质量筛查: 检测到 {anomaly_count} 个极端异常值,已用中位数替换")
    return data_dict


# region 数据清洗引擎 (v2.10) - 基于 MAD 的整日异常日检测与清洗
def _clean_asset_data_mad(monthly_data, mad_threshold=3.0, mode='replace'):
    """对一个资产号下所有月份的日负荷数据进行整日异常检测和清洗.

    算法: 计算全局 P50 中位日曲线 -> 每天对中位日的欧氏距离 ->
          MAD (Median Absolute Deviation) 阈值判定异常日.

    Args:
        monthly_data: {month_str: {'load_array': (n_days, n_points), 'date_labels': [...], ...}}
        mad_threshold: MAD 倍数阈值,默认 3.0(~=Z-score 4.45,保守检测)
        mode: 'replace' - 异常日用中位日替换; 'exclude' - 异常日从数组中移除

    Returns:
        cleaned_data: {month_str: {'load_array': ..., 'date_labels': [...], ...}} 清洗后数据
        stats: {'total_days': int, 'removed_days': int, 'removed_per_month': {month_str: int}}

    Reference:
        基于距离的异常检测在负荷数据清洗中的有效性已由多篇论文验证(2023-2024).
    """
    if not monthly_data:
        return {}, {'total_days': 0, 'removed_days': 0, 'removed_per_month': {}}

    # 收集所有日负荷曲线,统一时间分辨率
    max_points = max(v['load_array'].shape[1] for v in monthly_data.values())
    all_curves = []  # [(month_str, day_idx, curve_array), ...]
    curve_registry = {}  # month_str -> list of day indices

    for month_str, data in monthly_data.items():
        arr = np.asarray(data['load_array'])
        if arr.ndim != 2 or arr.shape[0] == 0:
            continue
        # 统一到最大点数(用最近邻外推)
        if arr.shape[1] < max_points:
            old_hours = np.linspace(0, 24, arr.shape[1])
            new_hours = np.linspace(0, 24, max_points)
            padded = np.zeros((arr.shape[0], max_points))
            for i in range(arr.shape[0]):
                padded[i] = np.interp(new_hours, old_hours, arr[i], left=arr[i, 0], right=arr[i, -1])
            arr = padded
        curve_registry[month_str] = list(range(len(all_curves), len(all_curves) + arr.shape[0]))
        for d in range(arr.shape[0]):
            all_curves.append((month_str, d, arr[d]))

    total_days = len(all_curves)
    if total_days < 5:
        log.warning(f"数据清洗: 仅 {total_days} 天数据,不足以进行可靠的异常检测(至少需 5 天)")
        return dict(monthly_data), {'total_days': total_days, 'removed_days': 0, 'removed_per_month': {}}

    # 1. 计算中位日曲线(P50)
    curves_matrix = np.array([c for _, _, c in all_curves])
    median_curve = np.nanmedian(curves_matrix, axis=0)

    # 2. 计算每天到中位日的欧氏距离
    distances = np.zeros(total_days)
    for i in range(total_days):
        diff = curves_matrix[i] - median_curve
        distances[i] = np.sqrt(np.nanmean(diff * diff))

    # 3. MAD 阈值
    med_dist = np.median(distances)
    mad_dist = np.median(np.abs(distances - med_dist))
    if mad_dist <= 0:
        mad_dist = np.std(distances) * 0.6745  # MAD ~= 0.6745 * sigma for normal distribution
    if mad_dist <= 0:
        return dict(monthly_data), {'total_days': total_days, 'removed_days': 0, 'removed_per_month': {}}

    threshold = med_dist + mad_threshold * mad_dist
    outlier_mask = distances > threshold
    removed_days = int(outlier_mask.sum())

    if removed_days == 0:
        return dict(monthly_data), {'total_days': total_days, 'removed_days': 0, 'removed_per_month': {}}

    # 4. 按月份重新组装数据
    cleaned_data = {}
    removed_per_month = {}
    for month_str, data in monthly_data.items():
        arr = np.asarray(data['load_array'])
        if arr.ndim != 2 or arr.shape[0] == 0:
            cleaned_data[month_str] = data
            continue
        day_indices = curve_registry.get(month_str, [])
        if not day_indices:
            cleaned_data[month_str] = data
            continue

        clean_arr = []
        clean_dates = []
        month_removed = 0
        for local_d, global_idx in enumerate(day_indices):
            if outlier_mask[global_idx]:
                month_removed += 1
                if mode == 'replace':
                    # 用中位日替换异常日
                    clean_arr.append(median_curve[:arr.shape[1]] if arr.shape[1] < max_points else median_curve)
                    clean_dates.append(data['date_labels'][local_d] if 'date_labels' in data else f'day_{local_d}')
                # mode == 'exclude': 直接跳过
            else:
                clean_arr.append(arr[local_d])
                clean_dates.append(data['date_labels'][local_d] if 'date_labels' in data else f'day_{local_d}')

        removed_per_month[month_str] = month_removed
        if clean_arr:
            new_data = dict(data)
            new_data['load_array'] = np.array(clean_arr)
            new_data['date_labels'] = clean_dates
            cleaned_data[month_str] = new_data
        else:
            cleaned_data[month_str] = data

    stats = {'total_days': total_days, 'removed_days': removed_days,
             'removed_per_month': removed_per_month, 'threshold': float(threshold),
             'median_distance': float(med_dist), 'mad': float(mad_dist)}
    log.info(f"数据清洗完成: {removed_days}/{total_days} 天被标记为异常 "
             f"(MAD阈值={mad_threshold}, 距离阈值={threshold:.2f})")
    return cleaned_data, stats
# endregion

# region 负荷诊断分析引擎 (v2.11)
def _assess_data_completeness(monthly_data):
    """数据完整性评估:检测缺失天数、覆盖率和时间分辨率."""
    if not monthly_data:
        return {'total_days': 0, 'missing_days': 0, 'coverage': 0, 'resolution': '未知', 'issues': []}
    all_dates = []
    resolution = None
    for data in monthly_data.values():
        labels = data.get('time_labels', [])
        if labels:
            try:
                pts = len(labels)
                res = 1440 / pts if pts > 0 else 0
                resolution = f'{int(res)}分钟 ({pts}点/天)'
            except (ZeroDivisionError, ValueError, TypeError):
                log.debug(f"无法计算分辨率: labels={len(labels)}")
        dates = data.get('date_labels', [])
        all_dates.extend(dates)
    total = len(all_dates)
    if total == 0:
        return {'total_days': 0, 'missing_days': 0, 'coverage': 0, 'resolution': resolution or '未知', 'issues': ['无日期数据']}
    issues = []
    if total < 30: issues.append(f'数据仅{total}天,建议>=180天')
    if resolution and '60' in str(resolution): issues.append('采样间隔60分钟,15分钟级峰值可能被低估15~25%')
    coverage = min(total / 365.0 * 100, 100.0) if total > 0 else 0
    return {'total_days': total, 'missing_days': 365 - total if total < 365 else 0,
            'coverage': round(coverage, 1), 'resolution': resolution or '未知', 'issues': issues}


def _classify_consumer_type(monthly_data):
    """用电特征自动识别:基于日负荷率和峰谷差率分类."""
    if not monthly_data:
        return {'type': '未知', 'load_factor': 0, 'peak_valley_ratio': 0, 'confidence': '低'}
    all_lf, all_pvr = [], []
    for data in monthly_data.values():
        arr = np.asarray(data.get('load_array', []))
        if arr.ndim != 2 or arr.shape[0] == 0: continue
        for d in range(arr.shape[0]):
            row = arr[d]
            valid = row[~np.isnan(row)]
            if len(valid) < 3: continue
            peak = np.max(valid)
            if peak <= 0: continue
            all_lf.append(np.mean(valid) / peak)
            all_pvr.append((peak - np.min(valid)) / peak)
    if not all_lf:
        return {'type': '未知', 'load_factor': 0, 'peak_valley_ratio': 0, 'confidence': '低'}
    avg_lf = float(np.mean(all_lf))
    avg_pvr = float(np.mean(all_pvr))
    if avg_lf > 0.85: ctype = '连续生产型'
    elif avg_lf > 0.60: ctype = '双班制'
    elif avg_lf > 0.35: ctype = '单班制/商业型'
    else: ctype = '间歇型/低负载率'
    conf = '高' if len(all_lf) >= 30 else '中' if len(all_lf) >= 10 else '低'
    return {'type': ctype, 'load_factor': round(avg_lf, 3), 'peak_valley_ratio': round(avg_pvr, 3),
            'sample_days': len(all_lf), 'confidence': conf}


def _extreme_day_analysis(monthly_data):
    """极端日场景:Top-5 高负荷日和低谷日."""
    high, low = [], []
    for month_str, data in monthly_data.items():
        arr = np.asarray(data.get('load_array', []))
        dates = data.get('date_labels', [])
        if arr.ndim != 2 or arr.shape[0] == 0: continue
        for d in range(arr.shape[0]):
            row = arr[d]
            valid = row[~np.isnan(row)]
            if len(valid) < 3: continue
            date_str = str(dates[d]) if d < len(dates) else f'{month_str}_d{d}'
            high.append((float(np.max(valid)), date_str))
            low.append((float(np.min(valid)), date_str))
    high.sort(key=lambda x: -x[0])
    low.sort(key=lambda x: x[0])
    return {'top_high': high[:5], 'top_low': low[:5]}


def _analyze_demand_characteristics(monthly_data, transformer_capacity=None):
    """需量特征:年最大需量、削减潜力."""
    all_peaks = []
    for data in monthly_data.values():
        arr = np.asarray(data.get('load_array', []))
        if arr.ndim != 2 or arr.shape[0] == 0: continue
        for d in range(arr.shape[0]):
            row = arr[d]
            valid = row[~np.isnan(row)]
            if len(valid) > 0: all_peaks.append(float(np.max(valid)))
    if not all_peaks:
        return {'max_demand': 0, 'p95_demand': 0, 'reducible': 0}
    max_demand = float(np.max(all_peaks))
    p95_demand = float(np.percentile(all_peaks, 95))
    reducible = max(0, max_demand - p95_demand)
    result = {'max_demand': round(max_demand, 1), 'p95_demand': round(p95_demand, 1),
              'reducible': round(reducible, 1)}
    if transformer_capacity:
        result['utilization'] = round(max_demand / transformer_capacity * 100, 1)
    return result


def _decompose_load_trend(monthly_data):
    """趋势分析:年增长率."""
    monthly_max = {}
    for month_str, data in monthly_data.items():
        arr = np.asarray(data.get('load_array', []))
        if arr.ndim != 2 or arr.shape[0] == 0: continue
        monthly_max[month_str] = float(np.max([float(np.nanmax(arr[d])) for d in range(arr.shape[0])]))
    sorted_months = sorted(monthly_max.keys())
    if len(sorted_months) < 3:
        return {'growth_rate': 0, 'r_squared': 0}
    x = np.arange(len(sorted_months))
    y = np.array([monthly_max[m] for m in sorted_months])
    slope, _ = np.polyfit(x, y, 1)
    y_pred = slope * x + _
    ss_res = np.sum((y - y_pred) ** 2)
    ss_tot = np.sum((y - np.mean(y)) ** 2)
    r2 = 1 - ss_res / ss_tot if ss_tot > 0 else 0
    growth_rate = slope / np.mean(y) * 12 * 100 if np.mean(y) > 0 else 0
    return {'growth_rate': round(growth_rate, 1), 'r_squared': round(r2, 3)}
# endregion


def _to_hour(v):
    """v3.2fix(P-30): 将时段端点统一转为小时数(float)。
    支持 float/int、"HH:MM"、"HH:MM:SS"、datetime.time。"""
    if isinstance(v, bool):
        return 0.0
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if ':' in s:
            parts = s.split(':')
            try:
                hh = float(parts[0])
                mm = float(parts[1]) if len(parts) > 1 else 0.0
                return hh + mm / 60.0
            except (ValueError, IndexError):
                return 0.0
        try:
            return float(s)
        except ValueError:
            return 0.0
    if hasattr(v, 'hour'):
        return float(v.hour) + float(getattr(v, 'minute', 0) or 0) / 60.0
    return 0.0


def _normalize_periods(periods):
    """v3.2fix(P-30/P-32): 时段格式与类型词汇表归一化。

    格式三态（系统内并存）：
      ① dict  [{'start':8,'end':11,'type':'flat'}, ...]   ← 核心函数原本只吃这种
      ② 元组  [(8, 11, 'flat'), ...]
      ③ 字符串端点 [('08:00','11:00','flat'), ...]

    类型词表两套（同一个字段两种语义）：
      A. 充放电策略词表：charge / discharge / 充电(低谷) / 放电(高峰)
      B. 电价时段词表：valley / flat / peak / 低谷 / 高峰
    核心函数（_segment_periods / compute_*_spaces）只认 A，而省份电价库存 B。
    传 B 进去时充放判断恒假 → 充电空间和放电空间都是 0，不报错、静默算零。
    这里把 B 统一翻成 A（valley→charge, peak→discharge），flat 保留原样
    （平段既不属于充也不属于放，由下游显式跳过）。
    """
    if not periods:
        return []
    out = []
    for p in periods:
        if isinstance(p, dict):
            s, e, t = p.get('start'), p.get('end'), p.get('type')
        elif isinstance(p, (list, tuple)) and len(p) >= 3:
            s, e, t = p[0], p[1], p[2]
        else:
            continue
        if t is None:
            continue
        out.append({'start': _to_hour(s), 'end': _to_hour(e), 'type': _canon_period_type(t)})
    return out


def _canon_period_type(t):
    """v3.2fix(P-32): 把一个时段类型词归一化到 PeriodType 词汇表。

    charge 系：charge / valley / deep_valley / 低谷 / 深谷 / 充电(低谷) / 充电
    discharge 系：discharge / peak / sharp_peak / 高峰 / 尖峰 / 放电(高峰) / 放电
    flat 及其他：保留原值（平段不参与充放，由下游跳过）
    """
    if t is None:
        return None
    s = str(t).strip()
    low = s.lower()
    if low in ('charge', 'valley', 'deep_valley') or s in ('低谷', '深谷', '充电', '充电(低谷)'):
        return PeriodType.CHARGE.value
    if low in ('discharge', 'peak', 'sharp_peak') or s in ('高峰', '尖峰', '放电', '放电(高峰)'):
        return PeriodType.DISCHARGE.value
    return t


def _expand_overnight(periods):
    periods = _normalize_periods(periods)
    res = []
    for p in periods:
        s, e, t = p["start"], p["end"], p["type"]
        if e < s:
            res.append({"start":s, "end":24.0, "type":t})
            res.append({"start":0.0, "end":e, "type":t})
        else:
            res.append({"start":s, "end":e, "type":t})
    return res

def _valid_periods(periods):
    periods = _normalize_periods(periods)
    if not periods:
        return True, "", []
    errors = []
    for p in periods:
        if not (0<=p["start"]<=24 and 0<=p["end"]<=24):
            errors.append(f"时段越界: {p}")
        if p["start"] == p["end"]:
            errors.append(f"时段开始与结束相同: {p}")
    expanded = _expand_overnight(periods)
    expanded.sort(key=lambda x: x["start"])
    # 使用 zip+pairwise 检测重叠,避免索引操作
    conflicts = []
    for prev, curr in zip(expanded, expanded[1:], strict=False):
        if prev["end"] > curr["start"]:
            conflicts.append((prev, curr))
    if conflicts:
        msg = "时段重叠:"
        for a,b in conflicts:
            msg += f"\n  {a['start']}-{a['end']} 与 {b['start']}-{b['end']}"
        return False, msg, conflicts
    # v2.9b: 零时长段检测
    for seg in expanded:
        if abs(seg["start"] - seg["end"]) < 0.001:
            errors.append(f"零时长时段: start={seg['start']}, end={seg['end']}")
    if errors:
        return False, "; ".join(errors), []
    return True, "", []

def _hour_x(h, pp):
    return h*pp

def _downsample(x, y, target=THUMBNAIL_DOWNSAMPLE):
    """降采样到目标点数,使用整数索引避免浮点开销"""
    n = len(x)
    if n <= target:
        return x, y
    idx = np.linspace(0, n - 1, target, dtype=int)
    return x[idx], y[idx]

def _compute_fits(x, y, types):
    """对负荷矩阵进行多种曲线拟合.

    维度约定:x 长度必须等于 y.shape[1](天数维度).
    y 形状应为 (n_timepoints, n_days),使用 axis=0 取日均值后与 x 进行拟合.

    支持类型:poly2, poly3, moving_avg, gaussian(需scipy), spline(需scipy)
    """
    """计算多种拟合曲线,返回 {fit_name: (y_values, label)} 字典"""
    res = {}
    avg = np.nanmean(y, axis=0)
    n = y.shape[1]
    SCIPY = False
    try:
        from scipy import interpolate, ndimage
        SCIPY = True
    except ImportError:
        pass
    # 二次拟合
    if 'poly2' in types and n >= 3:
        v = ~np.isnan(avg)
        if np.sum(v) >= 3:
            try:
                c = np.polyfit(x[v], avg[v], 2)
                res['poly2'] = (np.poly1d(c)(x), '二次拟合')
            except Exception as _e:
                log.debug(f"二次拟合不可用: {_e}")
    # 三次拟合(独立检查,不再嵌套在 poly2 内)
    if 'poly3' in types and n >= 4:
        v = ~np.isnan(avg)
        if np.sum(v) >= 4:
            try:
                c = np.polyfit(x[v], avg[v], 3)
                res['poly3'] = (np.poly1d(c)(x), '三次拟合')
            except Exception as _e:
                log.debug(f"三次拟合不可用: {_e}")
    # 移动平均
    if ('poly2' in types or 'poly3' in types) and n >= 5:
        w = min(5, n // 4)
        if w >= 2:
            res['moving_avg'] = (np.convolve(avg, np.ones(w)/w, mode='same'), f'移动平均({w})')
    # 高斯平滑
    if 'gaussian' in types and SCIPY:
        try:
            res['gaussian'] = (ndimage.gaussian_filter1d(avg, 1.0), '高斯平滑')
        except Exception as _e:
            log.debug(f"高斯平滑不可用: {_e}")
    # 样条插值
    if 'spline' in types and SCIPY and n >= 4:
        v = ~np.isnan(avg)
        if np.sum(v) >= 4:
            try:
                tck = interpolate.splrep(x[v], avg[v], s=len(x)*0.1)
                res['spline'] = (interpolate.splev(x, tck), '样条插值')
            except Exception as _e:
                log.debug(f"样条插值不可用: {_e}")
    return res
# endregion

