def _grade_color(grade):
    """健康评分等级 -> CSS 颜色"""
    return {'A': '#16a34a', 'B': '#2563eb', 'C': '#ca8a04', 'D': '#ea580c', 'F': '#dc2626'}.get(grade, '#94a3b8')

# region 自定义控件:环形进度条、日志高亮器、文件拖拽列表、拖放覆盖层
class CircularProgressBar(QWidget):
    __slots__ = ('_value', '_maximum', '_pen_width', '_animation')
    def __init__(self, parent=None):
        super().__init__(parent)
        bsize = int(base_size())
        self.setFixedSize(120, 120)
        self._value = 0
        self._maximum = 100
        self._pen_width = max(6, int(bsize * 0.2))
        self._animation = QPropertyAnimation(self, b"_value_prop")
        self._animation.setDuration(300)
        self._animation.setEasingCurve(QEasingCurve.OutCubic)

    def setValue(self, value):
        if self._animation.state() == QPropertyAnimation.Running:
            self._animation.stop()
        self._animation.setStartValue(self._value)
        self._animation.setEndValue(value)
        self._animation.start()

    def value(self):
        return self._value

    def setMaximum(self, maximum):
        self._maximum = maximum
        self.update()

    def get_value(self):
        return self._value

    def set_value(self, v):
        self._value = v
        self.update()

    _value_prop = property(get_value, set_value)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        rect = QRectF(self._pen_width, self._pen_width,
                      self.width() - 2 * self._pen_width,
                      self.height() - 2 * self._pen_width)
        tokens = DesignTokens.current_tokens()
        pen = QPen(tokens['BORDER'], self._pen_width, Qt.SolidLine, Qt.RoundCap)
        painter.setPen(pen)
        painter.drawEllipse(rect)
        if self._maximum > 0 and self._value > 0:
            gradient = QConicalGradient(rect.center(), 90)
            gradient.setColorAt(0, tokens['ACCENT'])
            gradient.setColorAt(0.5, QColor("#42A5F5"))
            gradient.setColorAt(1, tokens['ACCENT'])
            pen = QPen(QBrush(gradient), self._pen_width, Qt.SolidLine, Qt.RoundCap)
            painter.setPen(pen)
            span = int(360 * self._value / self._maximum) * 16
            painter.drawArc(rect, 90 * 16, span)
        painter.setPen(tokens['TEXT_PRIMARY'])
        font = painter.font()
        font.setPointSize(14)
        font.setBold(True)
        painter.setFont(font)
        text = f"{int(self._value * 100 / self._maximum)}%" if self._maximum else "0%"
        painter.save()
        painter.setPen(QColor(0, 0, 0, 80))
        painter.drawText(self.rect().adjusted(1, 1, 1, 1), Qt.AlignCenter, text)
        painter.restore()
        painter.drawText(self.rect(), Qt.AlignCenter, text)

class LogHighlighter(QSyntaxHighlighter):
    __slots__ = ('tokens', 'formats', 'rules')
    def __init__(self, document):
        super().__init__(document)
        self.tokens = DesignTokens.current_tokens()
        self.formats = {
            "info": self.tokens['TEXT_PRIMARY'],
            "error": self.tokens['DANGER_COLOR'],
            "warning": self.tokens['ACCENT_WARM'],
            "success": self.tokens['SUCCESS_COLOR'],
            "title": self.tokens['ACCENT'],
        }
        self.rules = []
        for tag, color in self.formats.items():
            fmt = QTextCharFormat()
            fmt.setForeground(color)
            if tag == "error":
                fmt.setFontWeight(700)
            self.rules.append((tag, fmt))

    def highlightBlock(self, text):
        for tag, fmt in self.rules:
            index = 0
            while index >= 0:
                index = text.find(f"[{tag}]", index)
                if index >= 0:
                    length = len(tag) + 2
                    self.setFormat(index, length, fmt)
                    index += length
                else:
                    break

class FileListWidget(QListWidget):
    files_added = Signal(list)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setSelectionMode(QListWidget.ExtendedSelection)
        self.setDragDropMode(QListWidget.InternalMove)
        self.setDefaultDropAction(Qt.MoveAction)
        tokens = DesignTokens.current_tokens()
        self.setStyleSheet(
            f"QListWidget {{ border: 2px dashed {tokens['BORDER'].name()}; border-radius: {tokens['RADIUS_CARD']}px; padding: 8px; "
            f"background: {tokens['BG_CONTENT'].name()}; color: {tokens['TEXT_PRIMARY'].name()}; }}"
            f"QListWidget::item:selected {{ background: {tokens['BG_HEADER'].name()}; color: {tokens['TEXT_PRIMARY'].name()}; }}"
            f"QListWidget::item {{ padding: 6px; }}"
        )
        self.setToolTip("拖放 Excel/CSV 文件或文件夹\n支持 xlsx、xls、csv\n可拖拽排序")
        self.setContextMenuPolicy(Qt.CustomContextMenu)
        self.customContextMenuRequested.connect(self._context_menu)
        self.itemDoubleClicked.connect(self._on_double_click)  # v2.27

        self._empty_label = QLabel(
            "<div style='text-align:center;'>"
            "<p style='font-size:36px;'>📊</p>"
            "<p style='font-size:14px; font-weight:bold;'>将 Excel / CSV 文件拖放到此处</p>"
            "<p style='font-size:11px;'>支持 .xlsx .xls .csv 格式<br>"
            "也可拖放整个文件夹,自动递归扫描</p>"
            "<p style='font-size:10px; color:gray;'>或点击工具栏 <b>📁 添加文件</b> 按钮</p>"
            "</div>", self)
        self._empty_label.setAlignment(Qt.AlignCenter)
        self._empty_label.setStyleSheet("color: #AAB7C4; font-size: 13px; border: none; background: transparent;")
        self._empty_label.setWordWrap(True)
        self.model().rowsInserted.connect(self._update_empty_label)
        self.model().rowsRemoved.connect(self._update_empty_label)
        self.model().modelReset.connect(self._update_empty_label)
        self._update_empty_label()

    def _update_empty_label(self):
        self._empty_label.setVisible(self.count() == 0)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._empty_label.setGeometry(self.rect())

    def dragEnterEvent(self, event: QDragEnterEvent):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
            self.setProperty("dragOver", True)
            self.style().unpolish(self)
            self.style().polish(self)
        else:
            super().dragEnterEvent(event)

    def dragLeaveEvent(self, event):
        self.setProperty("dragOver", False)
        self.style().unpolish(self)
        self.style().polish(self)
        super().dragLeaveEvent(event)

    def dropEvent(self, event: QDropEvent):
        self.setProperty("dragOver", False)
        self.update()
        if event.mimeData().hasUrls():
            files = []
            for url in event.mimeData().urls():
                p = url.toLocalFile()
                if os.path.isfile(p) and _is_supported_file(p):
                    files.append(p)
                elif os.path.isdir(p):
                    for root, _, fns in os.walk(p):
                        for fn in fns:
                            if _is_supported_file(fn):
                                files.append(os.path.join(root, fn))
            if files:
                self.files_added.emit(files)
            event.acceptProposedAction()
        else:
            super().dropEvent(event)

    def add_file_item(self, filepath):
        """添加文件到列表,缓存文件大小避免重复 stat"""
        fname = os.path.basename(filepath)
        try:
            sz = os.path.getsize(filepath)
            size_str = f"{sz / 1024:.1f} KB" if sz < 1024 * 1024 else f"{sz / (1024 * 1024):.1f} MB"
        except OSError:
            size_str = "未知"
        item = QListWidgetItem(f"📄 {fname}  [{size_str}]")
        item.setData(Qt.UserRole, filepath)
        # v2.27: 添加提示信息(大小+修改时间)
        try:
            mtime = datetime.fromtimestamp(os.path.getmtime(filepath)).strftime('%Y-%m-%d %H:%M')
            item.setToolTip(f"{filepath}\n大小: {size_str}\n修改时间: {mtime}")
        except OSError:
            item.setToolTip(filepath)
        item.setData(Qt.UserRole + 1, {'size': sz, 'name': fname})  # 缓存元信息
        item.setForeground(DesignTokens.current_tokens()['TEXT_PRIMARY'])
        # 超大文件标记警告色
        if sz > HUGE_FILE_SIZE:
            item.setForeground(DesignTokens.current_tokens()['ACCENT_WARM'])
        self.addItem(item)

    def set_health_score(self, filepath, score_info):
        """v2.30fix: QColor着色圆点, 恢复颜色标识"""
        for i in range(self.count()):
            item = self.item(i)
            if item and item.data(Qt.UserRole) == filepath:
                meta = item.data(Qt.UserRole + 1) or {}
                fname = meta.get('name', os.path.basename(filepath))
                sz = meta.get('size', 0)
                size_str = f"{sz / 1024:.1f} KB" if 0 < sz < 1048576 else (f"{sz / 1048576:.1f} MB" if sz >= 1048576 else "未知")
                grade = score_info.get('grade', '?')
                score = score_info.get('score', 0)
                # 按等级着色圆点
                grade_colors = {'A': QColor('#4CAF50'), 'B': QColor('#2196F3'), 'C': QColor('#FF9800'),
                              'D': QColor('#FF5722'), 'F': QColor('#F44336')}
                color = grade_colors.get(grade, QColor('#9E9E9E'))
                item.setText(f"● {fname}  [{size_str}]")
                item.setForeground(color)
                item.setToolTip(
                    f"<b>数据健康评分: {score}/100 ({grade}级)</b><br>" +
                    '<br>'.join(score_info.get('warnings', ['数据质量良好']))
                    if score_info.get('warnings') else f"数据质量良好 ({score}分)"
                )
                break

    def remove_item_by_row(self, row):
        if 0 <= row < self.count():
            self.takeItem(row)

    def clear_files(self):
        self.clear()

    def get_file_paths(self):
        paths = []
        for i in range(self.count()):
            item = self.item(i)
            if item:
                fp = item.data(Qt.UserRole)
                if fp:
                    paths.append(fp)
        return paths

    def _on_double_click(self, item):
        """v2.27: 双击文件项——选中后触发打开(复用现有列映射流程)"""
        if item:
            item.setSelected(True)
            # 尝试调用父窗口的列映射(如果存在)
            parent = self.parent()
            if parent and hasattr(parent, '_start_processing'):
                pass  # 双击选中,用户手动点开始处理

    def _context_menu(self, pos):
        item = self.itemAt(pos)
        menu = QMenu()
        if item:
            act_open = menu.addAction("📂 打开文件所在位置")
            act_remove = menu.addAction("🗑 从列表中移除")
            action = menu.exec(self.viewport().mapToGlobal(pos))
            if action == act_open:
                fp = item.data(Qt.UserRole)
                if fp and os.path.exists(fp):
                    try:
                        if os.name == 'nt':
                            subprocess.run(['explorer', os.path.dirname(fp)])
                        else:
                            subprocess.run(['xdg-open', os.path.dirname(fp)])
                    except Exception:
                        pass
            elif action == act_remove:
                self.remove_item_by_row(self.row(item))
        else:
            act_clear = menu.addAction("🧹 清空列表")
            if menu.exec(self.viewport().mapToGlobal(pos)) == act_clear:
                self.clear_files()

class DropOverlay(QWidget):
    __slots__ = ('_label',)
    files_dropped = Signal(list)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.WindowStaysOnTopHint)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.setVisible(False)
        self._label = QLabel(self)
        self._label.setFixedSize(0, 0)

    def paintEvent(self, event):
        if not self.isVisible(): return
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing)
        w, h = self.width(), self.height()
        # 冰蓝色玻璃蒙层
        p.fillRect(self.rect(), QColor(0, 160, 220, 12))
        # 极细亮边
        pen = QPen(QColor(0, 210, 255, 180), 1.0)
        p.setPen(pen); p.setBrush(Qt.NoBrush)
        p.drawRoundedRect(QRectF(0.5, 0.5, w-1, h-1), 10, 10)
        p.end()

    def dragEnterEvent(self, event):
        event.acceptProposedAction()
        self.setVisible(True)
        self.raise_()

    def dragLeaveEvent(self, event):
        self.setVisible(False)

    def dropEvent(self, event):
        self.setVisible(False)
        if event.mimeData().hasUrls():
            paths = []
            for url in event.mimeData().urls():
                p = url.toLocalFile()
                if os.path.isfile(p) and _is_supported_file(p): paths.append(p)
                elif os.path.isdir(p):
                    try:
                        for entry in os.scandir(p):
                            if entry.is_file() and _is_supported_file(entry.name): paths.append(entry.path)
                    except OSError: pass
            if paths: self.files_dropped.emit(paths)
            event.acceptProposedAction()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.setGeometry(self.parent().rect())

# endregion

