# ========================================================================
# 负荷曲线批量生成工具 Ultra -- 第三部分
# ========================================================================

# region 滑动窗口需量计算(向量化优化 + 预计算)
def _calc_sliding_window_demand(load_array, time_labels, window_minutes=WINDOW_MINUTES_DEFAULT):
    """
    计算滑动窗口需量.在 window_minutes 宽度滑动窗口内取平均功率,
    窗口随时间向前滑动,始终覆盖最近的 window_minutes 分钟区间.
    数据点窄于窗口时才滑动平均,否则退化为逐点 max.
    OPT: cumsum 预计算 + 双指针,O(n_days x n_points),消除 Python 内层循环.
    输入: load_array (n_days, n_points), time_labels
    输出: (max_demand: float, daily_max: np.ndarray)
    注意: 若时间标签未排序,内部会做排序副本,不修改调用者数据.
    """
    n_days, n_points = load_array.shape
    if n_points < 2:
        return (float(np.nanmax(load_array)) if n_days > 0 and n_points > 0 else 0.0), np.full(n_days, np.nan)
    # 向量化时间预计算
    hours = np.array([_parse_min(t) / 60.0 for t in time_labels], dtype=np.float64)
    if not np.all(np.diff(hours) >= 0):
        sort_idx = np.argsort(hours)
        hours = hours[sort_idx]
        # 用 fancy indexing 产生副本,不修改调用者的 load_array
        load_array = load_array[:, sort_idx].copy()
    window_hours = window_minutes / 60.0
    dts = np.diff(hours)
    dts = np.append(dts, dts[-1] if len(dts) > 0 else window_hours / n_points)
    dts_clipped = np.clip(dts, 1e-12, window_hours)
    vals_all = np.asarray(load_array, dtype=np.float64)
    nan_mask = np.isnan(vals_all)
    # OPT: cumsum 预计算,消除 per-point 累加循环
    energy_all = np.where(nan_mask, 0.0, vals_all * dts_clipped[np.newaxis, :])
    time_all = np.where(nan_mask, 0.0, dts_clipped[np.newaxis, :])
    cum_energy = np.pad(np.cumsum(energy_all, axis=1), ((0, 0), (1, 0)))
    cum_time = np.pad(np.cumsum(time_all, axis=1), ((0, 0), (1, 0)))
    daily_max = np.zeros(n_days)
    for d in range(n_days):
        if nan_mask[d].all():
            daily_max[d] = np.nan
            continue
        left = 0
        max_avg = 0.0
        n_pts = len(hours)
        for right in range(n_pts):
            # 双指针:当窗口宽度超过 window_hours 时收缩左边界
            while right > left and hours[right] - hours[left] > window_hours:
                left += 1
            te = cum_energy[d, right + 1] - cum_energy[d, left]
            tt = cum_time[d, right + 1] - cum_time[d, left]
            if tt > 1e-12:
                avg = te / tt
                max_avg = max(max_avg, avg)
        daily_max[d] = max_avg
    max_demand = np.nanmax(daily_max) if n_days > 0 else 0.0
    return max_demand, daily_max
# endregion

# region 统一绘图核心函数(优化:LineCollection 段数限制、取消事件检查、滑动需量)
def _draw_curves_core(ax, dates, load_array, time_labels, title, opts=None, bill=None, periods=None,
                      precomputed_day_types=None, cancel_event=None):
    _init_matplotlib()
    if opts is None:
        opts = {}
    show_daily = opts.get('show_daily', True)
    show_avg = opts.get('show_avg', True)
    show_max_demand = opts.get('show_max_demand', False)
    fit_types = opts.get('fit_types', [])
    fit_algorithm = opts.get('fit_algorithm', 'none')
    enable_fit_overlay = opts.get('enable_fit_overlay', False)
    replace_with_fit = opts.get('replace_with_fit', False)
    show_fit_clusters = opts.get('show_fit_clusters', True)  # v2.28fix: 保存到变量
    highlight_mode = opts.get('highlight_mode', 'none')
    weekday_color = opts.get('weekday_color', DEFAULT_WEEKDAY_COLOR)
    weekend_color = opts.get('weekend_color', DEFAULT_WEEKEND_COLOR)
    holiday_color = opts.get('holiday_color', DEFAULT_HOLIDAY_COLOR)
    weekend_line_width = opts.get('weekend_line_width', DEFAULT_WEEKEND_LINE_WIDTH)
    holiday_line_width = opts.get('holiday_line_width', DEFAULT_HOLIDAY_LINE_WIDTH)
    show_weekend_bg = opts.get('show_weekend_bg', False)
    legend_position = opts.get('legend_position', 'right')
    mark_anomalies = opts.get('mark_anomalies', False)
    dark_theme = opts.get('dark_theme', False)
    max_legend_dates = 5

    n_dates, n_times = load_array.shape
    # v2.27fix: day_types先赋值再校验维度(修正原bug:校验在赋值之前)
    if precomputed_day_types is None:
        enable_holiday = highlight_mode in ('holiday', 'grouped')
        day_types = [_get_day_type(d, enable_holiday=enable_holiday) for d in dates]
    else:
        day_types = precomputed_day_types
    # 维度一致性守卫
    if n_dates != len(dates):
        log.warning(f"_draw_curves_core: load_array天数({n_dates})与dates({len(dates)})不一致,已自动截断对齐")
        min_days = min(n_dates, len(dates))
        load_array = load_array[:min_days]
        dates = dates[:min_days]
        day_types = day_types[:min_days]
        n_dates = min_days
    if len(day_types) != n_dates:
        log.warning(f"_draw_curves_core: day_types({len(day_types)})与n_dates({n_dates})不一致,已截断")
        day_types = day_types[:n_dates]
    if n_times < 2:
        raise ValueError("时间点数量小于2,无法绘制有意义曲线")
    x = np.arange(n_times)
    pp = n_times / 24.0
    thresh = 300

    idx_down = np.linspace(0, n_times - 1, thresh, dtype=int) if n_times > thresh else None

    if dark_theme:
        ax.set_facecolor(DesignTokens.DARK['BG_CONTENT'].name())  # v2.28fix: 使用主题颜色
        ax.tick_params(colors='white')
        ax.xaxis.label.set_color('white')
        ax.yaxis.label.set_color('white')
        ax.title.set_color('white')
        for spine in ax.spines.values():
            spine.set_color('white')
        ax.grid(True, alpha=0.2, color='white')

    if periods:
        for p in _expand_overnight(periods):
            xs = _hour_x(p["start"], pp)
            xe = min(_hour_x(p["end"], pp), n_times - 1)
            color = ColorConst.CHARGE_BG if p["type"] in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL) else ColorConst.DISCHARGE_BG
            ax.axvspan(xs, xe, alpha=0.44, color=color, zorder=0)

    if show_weekend_bg and highlight_mode != 'none':
        has_weekend = any(dt in ('weekend', 'holiday') for dt in day_types)
        if has_weekend:
            ax.axvspan(0, n_times - 1, alpha=WEEKEND_BG_ALPHA, color='gray', zorder=1)

    if show_daily and not replace_with_fit:
        too_many = n_dates > max_legend_dates and highlight_mode not in ('grouped', 'none')
        from matplotlib.collections import LineCollection
        # OPT: 批量 numpy 构建替代 per-curve extend,2. times 加速
        all_segs = []
        all_colors = []
        all_lws = []
        max_segments = 50000
        total_segs = 0
        for i in range(n_dates):
            # 优化:在循环内检查取消事件,支持提前退出
            if cancel_event is not None and cancel_event.is_set():
                return
            day_type = day_types[i]
            # v2.15: 统一 day_type 判断逻辑,消除重复分支
            if highlight_mode == 'grouped' or highlight_mode != 'none':
                if day_type == 'holiday':
                    color, lw = holiday_color, holiday_line_width
                elif day_type == 'weekend':
                    color, lw = weekend_color, weekend_line_width
                else:
                    color, lw = weekday_color, 1.5
            else:
                # v3.0fix: 色盲友好模式 (通过全局配置切换)
                if getattr(__builtins__, '_colorblind_mode', False):
                    color = COLORBLIND_SAFE_PALETTE[i % len(COLORBLIND_SAFE_PALETTE)]
                else:
                    color = _get_plt().cm.tab10(i % 10)
                lw = 1.5

            if idx_down is not None:
                x_plt = x[idx_down]
                y_plt = load_array[i][idx_down]
            else:
                x_plt, y_plt = x, load_array[i]
            points = np.column_stack((x_plt, y_plt))
            n_segs = len(points) - 1
            if total_segs + n_segs > max_segments:
                too_many = True
                break
            total_segs += n_segs
            # 批量构建段:无需中间 reshape+concatenate
            segs = np.empty((n_segs, 2, 2))
            segs[:, 0] = points[:-1]
            segs[:, 1] = points[1:]
            all_segs.append(segs)
            all_colors.append(color)
            all_lws.append(lw)

        if all_segs:
            segments = np.concatenate(all_segs, axis=0)
            # OPT v2.15: vectorized color/linewidth repeat (numpy.repeat 替代 Python 循环 + extend)
            seg_counts = np.array([len(s) for s in all_segs])
            # v2.22fix: 形状守卫 - 防止seg_counts与all_colors维度不匹配(如拟合曲线替换后日期数变化)
            if len(seg_counts) != len(all_colors):
                n_expected = len(all_colors)
                n_actual = len(seg_counts)
                # v2.22: 诊断形状不匹配根因
                diag_msg = (f"LineCollection形状不匹配: load_array.shape={load_array.shape}, "
                           f"n_dates={n_dates}, n_times={n_times}, "
                           f"len(all_segs)={len(all_segs)}, len(all_colors)={n_expected}, "
                           f"seg_counts前5={seg_counts[:5].tolist() if len(seg_counts)>=5 else seg_counts.tolist()}")
                log.warning(diag_msg)
                print(diag_msg, file=sys.stderr, flush=True)
                min_len = min(n_expected, n_actual)
                all_colors = all_colors[:min_len]
                all_lws = all_lws[:min_len]
                seg_counts = seg_counts[:min_len]
                # 重新截断segments
                total_segs_corrected = int(np.sum(seg_counts))
                segments = segments[:total_segs_corrected]
            colors = np.repeat(np.array(all_colors), seg_counts, axis=0).tolist()
            linewidths = np.repeat(np.array(all_lws), seg_counts, axis=0).tolist()
            lc = LineCollection(segments, colors=colors, linewidths=linewidths, alpha=0.75, zorder=10)
            ax.add_collection(lc)
            ax.autoscale_view()
        else:
            segments = []
            colors = []
            linewidths = []

        if highlight_mode != 'grouped' and not too_many:
            if highlight_mode == 'none':
                # 不突出日期时: 显示每一天的图例
                for i in range(n_dates):
                    # v3.0fix: 色盲友好模式
                    if getattr(__builtins__, '_colorblind_mode', False):
                        c = COLORBLIND_SAFE_PALETTE[i % len(COLORBLIND_SAFE_PALETTE)]
                    else:
                        c = _get_plt().cm.tab10(i % 10)
                    ax.plot([], [], color=c, lw=1.5, label=dates[i])
            else:
                first_color = colors[0] if colors else weekday_color
                first_lw = linewidths[0] if linewidths else 1.5
                ax.plot([], [], color=first_color, lw=first_lw, label=dates[0])

    anomaly_handle = None
    if mark_anomalies:
        # v2.15: vectorized anomaly detection - precompute all anomaly coords, single scatter
        # v2.21fix: 零负荷或极小负值是正常数据(光伏返送),仅< -1e-6 为异常
        anomaly_mask = load_array < -1e-6
        anomaly_rows, anomaly_cols = np.where(anomaly_mask)
        if len(anomaly_rows) > 0:
            # respect cancel in hot path
            if cancel_event is not None and cancel_event.is_set():
                return
            anomaly_handle = ax.scatter(x[anomaly_cols], load_array[anomaly_rows, anomaly_cols],
                      color='red', marker='x', s=30, zorder=50, label='_nolegend_')

    avg = np.nanmean(load_array, axis=0)
    if show_avg:
        if idx_down is not None:
            x_plt = x[idx_down]
            y_plt = avg[idx_down]
        else:
            x_plt, y_plt = x, avg
        ax.plot(x_plt, y_plt, label=CurveLabel.AVERAGE.value, color='black' if not dark_theme else 'white', ls='--', lw=2.0, zorder=20)

    if show_max_demand:
        if cancel_event is not None and cancel_event.is_set():
            return
        # 优化:统一使用滑动窗口需量,符合行业标准
        max_demand_val, _ = _calc_sliding_window_demand(load_array, time_labels)
        if max_demand_val > 0:
            ax.axhline(y=max_demand_val, color='blue' if not dark_theme else 'cyan', ls='--', lw=2.0,
                      label=f'{CurveLabel.MAX_DEMAND.value}({max_demand_val:.2f})', zorder=25)

    if fit_types:
        for _nm, (curve, lab) in _compute_fits(x, load_array, fit_types).items():
            if idx_down is not None:
                x_plt = x[idx_down]
                y_plt = curve[idx_down]
            else:
                x_plt, y_plt = x, curve
            ax.plot(x_plt, y_plt, label=lab, ls='-.', lw=2.0, zorder=20)

    # ── 算法拟合曲线渲染 (v2.8) ──
    if enable_fit_overlay and fit_algorithm != 'none' and fit_algorithm in FIT_ALGORITHM_NAMES:
        fitted, fit_meta = compute_fitted_curves(load_array, algorithm=fit_algorithm,
                                        fit_percentile=opts.get('fit_percentile', 90.0),
                                        fit_n_clusters=opts.get('fit_n_clusters', 3),
                                        fit_n_components=opts.get('fit_n_components', 0.90))
        colors = FIT_ALGORITHM_COLORS.get(fit_algorithm, ('#4A7FB5', '#C8815A', '#5A9E6F'))
        for i, (curve, lab) in enumerate(fitted):
            color = colors[i % len(colors)]
            # 对齐时间点:拟合曲线可能因 NaN 列裁剪而变短
            curve_len = len(curve)
            if curve_len < n_times:
                # 填充 NaN 以保持对齐
                padded = np.full(n_times, np.nan)
                padded[:curve_len] = curve
                curve = padded
            elif curve_len > n_times:
                curve = curve[:n_times]
            if idx_down is not None:
                x_plt = x[idx_down]
                y_plt = curve[idx_down]
            else:
                x_plt, y_plt = x, curve
            # v2.28fix: 深色主题下用QColor.lighter()提亮,替代硬编码RGB偏移
            if dark_theme:
                color = QColor(color).lighter(150).name()
            ax.plot(x_plt, y_plt, label=f'[拟合] {lab}', color=color, lw=2.8, ls='-', zorder=35, alpha=0.9)

    if bill and bill.get('type') == 'capacity' and bill.get('value'):
        ax.axhline(y=bill['value'], color='red' if not dark_theme else 'lightcoral', ls=':', lw=2.0,
                  label=f'{CurveLabel.CAPACITY_LINE.value}({bill["value"]:.2f})', zorder=30)

    # ── 图例渲染 ──
    handles, labels = ax.get_legend_handles_labels()
    filtered_handles, filtered_labels = [], []
    for handle, label in zip(handles, labels, strict=False):
        if label == '_nolegend_':
            continue
        filtered_handles.append(handle)
        filtered_labels.append(label)

    if show_daily and too_many:  # v2.28fix: 曲线过多时始终显示汇总图例,不依赖highlight_mode
        filtered_handles.append(mpatches.Patch(color=weekday_color, alpha=0.75, label=f'每日曲线({n_dates}条)'))
        filtered_labels.append(f'每日曲线({n_dates}条)')

    if periods:
        filtered_handles.extend([
            mpatches.Patch(color=ColorConst.CHARGE_BG, alpha=0.6, label=PeriodType.CHARGE_LABEL.value),
            mpatches.Patch(color=ColorConst.DISCHARGE_BG, alpha=0.6, label=PeriodType.DISCHARGE_LABEL.value)
        ])
        filtered_labels.extend([PeriodType.CHARGE_LABEL.value, PeriodType.DISCHARGE_LABEL.value])

    if highlight_mode == 'grouped':
        filtered_handles.extend([
            mpatches.Patch(color=weekday_color, alpha=0.6, label='工作日'),
            mpatches.Patch(color=weekend_color, alpha=0.6, label='周末'),
        ])
        filtered_labels.extend(['工作日', '周末'])
        if _is_holiday_available():
            filtered_handles.append(mpatches.Patch(color=holiday_color, alpha=0.6, label='节假日'))
            filtered_labels.append('节假日')
    elif highlight_mode == 'weekend':
        filtered_handles.extend([
            mpatches.Patch(color=weekday_color, alpha=0.6, label='工作日'),
            mpatches.Patch(color=weekend_color, alpha=0.6, label='周末')
        ])
        filtered_labels.extend(['工作日', '周末'])
    elif highlight_mode == 'holiday':
        filtered_handles.extend([
            mpatches.Patch(color=weekday_color, alpha=0.6, label='工作日'),
            mpatches.Patch(color=weekend_color, alpha=0.6, label='周末'),
            mpatches.Patch(color=holiday_color, alpha=0.6, label='节假日')
        ])
        filtered_labels.extend(['工作日', '周末', '节假日'])

    if show_weekend_bg and highlight_mode != 'none':
        filtered_handles.append(mpatches.Patch(color='gray', alpha=WEEKEND_BG_ALPHA, label='周末背景'))
        filtered_labels.append('周末背景')

    if mark_anomalies and anomaly_handle is not None:
        filtered_handles.append(mpatches.Patch(color='red', alpha=0.6, label='异常值(零/负)'))
        filtered_labels.append('异常值(零/负)')

    if filtered_handles or mark_anomalies:
        legend_kwargs = dict(handles=filtered_handles, labels=filtered_labels, fontsize=9)
        if dark_theme:
            legend_kwargs.update(facecolor='#333333', edgecolor='#666666', labelcolor='white')
        if legend_position == 'bottom':
            legend_kwargs.update(loc='upper center', bbox_to_anchor=(0.5, -0.15), ncol=4)
        else:
            legend_kwargs.update(bbox_to_anchor=(1.02, 1), loc='upper left')
        ax.legend(**legend_kwargs)

    # v2.22: 图表美化--网格、坐标轴、边框全面优化
    # v2.22: 同步旧版 v2.3 经典图表样式
    if title:
        ax.set_title(title, fontsize=16, fontweight='bold', pad=12)
    ax.set_xlabel('时间', fontsize=12)
    ax.set_ylabel('负荷值', fontsize=12)
    if n_times >= 25:
        step = max(1, n_times // 24)
        idxs = list(range(0, n_times, step))
        pp_val = n_times / 24.0 if n_times > 0 else 1
        lbls = [f"{int(i // pp_val):02d}:00" for i in idxs]
        ax.set_xticks(idxs)
        ax.set_xticklabels(lbls, rotation=45, fontsize=9)
    else:
        ax.set_xticks(range(n_times))
        ax.set_xticklabels([str(t)[:5] for t in time_labels], rotation=45, fontsize=9)
    ax.grid(True, alpha=0.3)
