# region 实际绘图函数(优化:临时文件唯一性,取消事件细粒度检查)
def _plot_curves(dates, load, time_labels, title, outpath, opts=None, bill=None, periods=None, ctitle=None, cancel_event=None, output_format='png'):
    _init_matplotlib()
    ext = f'.{output_format}'
    # 使用唯一临时文件,避免多进程冲突
    try:
        fd, tmp_path = tempfile.mkstemp(suffix=ext, prefix='loadcurve_', dir=os.path.dirname(outpath))
        os.close(fd)
    except Exception:
        tmp_path = outpath + '.tmp'
    fig = None
    try:
        with _get_plt().rc_context({'font.sans-serif': ['Microsoft YaHei', 'SimHei', 'Noto Sans CJK SC', 'DejaVu Sans'],
                             'axes.unicode_minus': False}):
            if opts is None:
                opts = {'show_daily': True, 'show_avg': True, 'fit_types': [], 'show_max_demand': False,
                        'highlight_mode': 'none', 'mark_anomalies': False, 'dark_theme': False}
            dark = opts.get('dark_theme', False)
            enable_holiday = opts.get('highlight_mode', 'none') in ('holiday', 'grouped')
            precomputed_day_types = [_get_day_type(d, enable_holiday=enable_holiday) for d in dates]
            fig, ax = _get_plt().subplots(figsize=EXPORT_FIGSIZE)
            if dark:
                fig.patch.set_facecolor('#1e1e1e')
                ax.set_facecolor('#2e2e2e')
            if cancel_event and cancel_event.is_set():
                return False
            # 传递 cancel_event 以实现绘图循环内提前退出
            _draw_curves_core(ax, dates, load, time_labels, ctitle or title, opts, bill, periods,
                              precomputed_day_types=precomputed_day_types, cancel_event=cancel_event)
            if cancel_event and cancel_event.is_set():
                return False
            fig.tight_layout()
            if cancel_event and cancel_event.is_set():
                return False
            os.makedirs(os.path.dirname(outpath), exist_ok=True)
            if cancel_event and cancel_event.is_set():
                return False
            # ✅ 优化:savefig 前再次检查取消,支持 SVG/PDF 等格式
            if cancel_event and cancel_event.is_set():
                return False
            fig.savefig(tmp_path, dpi=EXPORT_DPI, bbox_inches='tight', format=output_format)
            os.replace(tmp_path, outpath)
            return True
    except np.linalg.LinAlgError:
        raise RuntimeError("数据矩阵运算异常,可能包含无效值") from None
    except ValueError as e:
        raise RuntimeError(f"数据形状错误: {e}") from e
    except MemoryError:
        raise RuntimeError("绘图时内存不足,请减少数据量或关闭其他程序") from None
    except Exception as e:
        raise RuntimeError(f"绘图失败: {e}") from e
    finally:
        if fig is not None:
            _get_plt().close(fig)
        if os.path.exists(tmp_path):
            with suppress(Exception):
                os.remove(tmp_path)
        gc.collect()
# endregion

# region 充放电空间计算(保留原函数,后续容量规划会在 ProfessionalWindow 中修正)
def _compute_time_dt(hours, start_hour=None, end_hour=None):
    """v2.9a: 统一的时间步长计算,供所有空间计算函数共用.
    对内部点使用中点法,对边界点(如果提供 start/end)使用段端点补偿."""
    n = len(hours)
    dt = np.zeros(n)
    if n == 1:
        span = (end_hour or 24.0) - (start_hour or 0.0)
        dt[0] = max(span, 0.0)
        return dt
    # 边界处理
    if start_hour is not None:
        dt[0] = max(0.0, hours[0] - start_hour + (hours[1] - hours[0]) / 2.0)
    else:
        dt[0] = max(0.0, hours[1] - hours[0])
    if end_hour is not None:
        dt[-1] = max(0.0, end_hour - hours[-1] + (hours[-1] - hours[-2]) / 2.0)
    else:
        dt[-1] = max(0.0, hours[-1] - hours[-2])
    # 内部点: 中点法
    for i in range(1, n - 1):
        dt[i] = (hours[i + 1] - hours[i - 1]) / 2.0
    return np.maximum(dt, 0.0)
def _segment_periods(periods):
    """v2.27fix: 将时段列表合并为连续的充/放电段. 从备份恢复."""
    if not periods:
        return []
    expanded = _expand_overnight(periods)
    expanded.sort(key=lambda p: p['start'])
    segments = []
    current_type = None
    current_start = None
    current_end = None
    current_sub = []
    charge_idx = 0
    discharge_idx = 0
    for p in expanded:
        ptype = p['type']
        if current_type is None:
            current_type = ptype
            current_start = p['start']
            current_end = p['end']
            current_sub = [p]
        elif ptype == current_type and abs(p['start'] - current_end) < 0.01:
            current_end = p['end']
            current_sub.append(p)
        else:
            label = ''
            if current_type in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL):
                charge_idx += 1
                label = f'充电{charge_idx}'
            elif current_type in (PeriodType.DISCHARGE, PeriodType.DISCHARGE_LABEL):
                discharge_idx += 1
                label = f'放电{discharge_idx}'
            else:
                # v3.2fix(P-32): 平段单独命名，不再错标为放电场次
                label = '平段'
            segments.append({'type': current_type, 'start': current_start,
                           'end': current_end, 'label': label, 'sub_periods': current_sub})
            current_type = ptype
            current_start = p['start']
            current_end = p['end']
            current_sub = [p]
    if current_type is not None:
        label = ''
        if current_type in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL):
            charge_idx += 1
            label = f'充电{charge_idx}'
        elif current_type in (PeriodType.DISCHARGE, PeriodType.DISCHARGE_LABEL):
            discharge_idx += 1
            label = f'放电{discharge_idx}'
        else:
            # v3.2fix(P-32): 平段单独命名
            label = '平段'
        segments.append({'type': current_type, 'start': current_start,
                       'end': current_end, 'label': label, 'sub_periods': current_sub})
    return segments
