# v3.2fix: 简化日空间计算 + 容量辅助函数 (from Pro v2.3)
# ═══════════════════════════════════════════════════════════


def compute_daily_spaces(load_array, time_labels, periods, billing=None, mode='A',
                         rated_power=None, ignore_negative=False):
    """v3.2fix: Mode A/B/C 每日充放电空间快速计算."""
    n_days, n_points = load_array.shape
    if n_points < 2:
        return np.zeros(n_days), np.zeros(n_days)
    hours = np.array([_parse_min(t)/60.0 for t in time_labels])
    dt = np.zeros(n_points)
    dt[0] = hours[1] - hours[0] if n_points > 1 else 1.0
    dt[-1] = hours[-1] - hours[-2] if n_points > 1 else 1.0
    for i in range(1, n_points-1):
        dt[i] = (hours[i+1] - hours[i-1]) / 2.0
    dt = np.maximum(dt, 0.0)
    work_load = load_array.copy()
    if ignore_negative:
        work_load = np.maximum(work_load, 0.0)
    charge = np.zeros(n_days)
    discharge = np.zeros(n_days)
    if mode == 'A':
        if not periods or not billing or not billing.get('value'):
            return charge, discharge
        cap = billing['value']
        expanded = _expand_overnight(periods)
        charge_mask = np.zeros(n_points, dtype=bool)
        discharge_mask = np.zeros(n_points, dtype=bool)
        for p in expanded:
            start_idx = np.searchsorted(hours, p['start'], side='left')
            end_idx = np.searchsorted(hours, p['end'], side='left')
            if p['type'] in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL):
                charge_mask[start_idx:end_idx] = True
            elif p['type'] in (PeriodType.DISCHARGE, PeriodType.DISCHARGE_LABEL):
                # v3.2fix(P-32): 明确只让放电类型置放电 mask；
                # 平段（flat）不属于充也不属于放，原 else 分支会把它当放电段，导致放电空间虚高。
                discharge_mask[start_idx:end_idx] = True
        # v3.2.1fix(N3): Mode A 充电口径统一。
        # 本函数原在这里乘了 CHARGING_EFFICIENCY，与 compute_segmented_spaces（不乘）
        # 以及 calc_economic_summary 的口径注释（「Mode A 充电 = max(cap-load)×dt →
        # 已是电网侧吸收量，不再除 η」）矛盾，快算比精算少 7.53%。
        # 充电空间的定义是「电网侧还能灌进去多少」，电池侧换算由下游 SOC 递推负责。
        charge = np.sum(np.maximum(cap - work_load, 0) * charge_mask * dt, axis=1)
        pos_load = np.maximum(work_load, 0)
        discharge = np.sum(np.minimum(pos_load, cap) * discharge_mask * dt, axis=1) * DISCHARGING_EFFICIENCY
    elif mode == 'B':
        if rated_power is None or rated_power <= 0:
            return charge, discharge
        neg_load = np.maximum(-work_load, 0)
        charge = np.sum(np.minimum(rated_power, neg_load) * dt, axis=1) * CHARGING_EFFICIENCY
        pos_load = np.maximum(work_load, 0)
        discharge = np.sum(np.minimum(rated_power, pos_load) * dt, axis=1) * DISCHARGING_EFFICIENCY
    elif mode == 'C':
        if rated_power is None or rated_power <= 0:
            return charge, discharge
        discharge_mask = np.zeros(n_points, dtype=bool)
        if periods:
            expanded = _expand_overnight(periods)
            for p in expanded:
                if p['type'] in (PeriodType.DISCHARGE, PeriodType.DISCHARGE_LABEL):
                    start_idx = np.searchsorted(hours, p['start'], side='left')
                    end_idx = np.searchsorted(hours, p['end'], side='left')
                    discharge_mask[start_idx:end_idx] = True
        else:
            discharge_mask[:] = True
        pos_load = np.maximum(work_load, 0)
        discharge = np.sum(np.minimum(rated_power, pos_load) * discharge_mask * dt, axis=1) * DISCHARGING_EFFICIENCY
        charge_mask = np.zeros(n_points, dtype=bool)
        charge_mask_2d = (work_load < 0)
        if periods:
            for p in expanded:
                if p['type'] in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL):
                    start_idx = np.searchsorted(hours, p['start'], side='left')
                    end_idx = np.searchsorted(hours, p['end'], side='left')
                    charge_mask[start_idx:end_idx] = True
        neg_load = np.maximum(-work_load, 0)
        charge = np.sum(np.minimum(rated_power, neg_load) * np.maximum(charge_mask, charge_mask_2d) * dt, axis=1) * CHARGING_EFFICIENCY
        if billing and billing.get('value'):
            cap = billing['value']
            charge = np.minimum(charge, np.sum(np.maximum(cap - work_load, 0) * charge_mask * dt, axis=1) * CHARGING_EFFICIENCY)
            discharge = np.minimum(discharge, np.sum(np.minimum(pos_load, cap) * discharge_mask * dt, axis=1) * DISCHARGING_EFFICIENCY)
    return charge, discharge


def calc_capacity_for_days(target_days, charge_kwh, discharge_kwh=None):
    """满充满放——挑target_days个最好的天,容量=升序[总数-target_days]"""
    if discharge_kwh is None:
        mins = np.asarray(charge_kwh)
    else:
        mins = np.minimum(np.asarray(charge_kwh), np.asarray(discharge_kwh))
    if target_days > len(mins) or target_days <= 0:
        return 0.0
    sorted_mins = np.sort(mins)
    idx = max(0, len(sorted_mins) - target_days)
    return sorted_mins[idx]


def calc_days_for_capacity(capacity, charge_kwh, discharge_kwh):
    """计算满足指定容量的天数"""
    satisfied = (charge_kwh >= capacity) & (discharge_kwh >= capacity)
    return np.sum(satisfied)



def compute_segmented_spaces(load_array, time_labels, segments, billing=None, mode='A',
                             rated_power=None, ignore_negative=False):
    """v2.27fix: 分充放时段计算每日能量空间. 从备份恢复.
    ⚠️ v3.2: 本函数 Ultra(200行) 与 Pro(95行) 独立实现, 修改任一侧需同步更新."""
    n_days, n_points = load_array.shape
    if n_points != len(time_labels):
        log.error(f"compute_segmented_spaces 形状不匹配: load_array={load_array.shape}, time_labels={len(time_labels)}")
        return [], [], [], []
    hours = np.array([_parse_min(_normalize_time_column_name(t)) / 60.0 for t in time_labels])
    if not np.all(np.diff(hours) >= 0):
        sort_idx = np.argsort(hours)
        hours = hours[sort_idx]
        load_array = load_array[:, sort_idx]
    work_load = load_array.copy()
    if ignore_negative:
        work_load = np.maximum(work_load, 0.0)
    charge_segments = []
    discharge_segments = []
    charge_labels = []
    discharge_labels = []
    cap = billing.get('value') if billing and billing.get('value') else None
    for seg in segments:
        seg_start = seg['start']
        seg_end = seg['end']
        # v2.27fix: 跨午夜时段(如22→2)需拆分为[22,24)和[0,2)两段
        if seg_start > seg_end:
            sub_ranges = [(seg_start, 24.0), (0.0, seg_end)]
        else:
            sub_ranges = [(seg_start, seg_end)]
        for sub_start, sub_end in sub_ranges:
            left = np.searchsorted(hours, sub_start, side='left')
            right = np.searchsorted(hours, sub_end, side='right')
            if left == right:
                space = np.zeros(n_days)
            else:
                sub_hours = hours[left:right]
                sub_load = work_load[:, left:right]
                seg_dt = _compute_time_dt(sub_hours, start_hour=sub_start, end_hour=sub_end)
                seg_dt = np.maximum(seg_dt, 0.0)
                if seg_dt.ndim == 1 and len(seg_dt) != sub_load.shape[1]:
                    log.error(f"seg_dt形状不匹配: seg_dt={seg_dt.shape}, sub_load[:,{left}:{right}]={sub_load.shape}")
                    if seg['type'] in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL):
                        charge_segments.append(np.zeros(n_days))
                    else:
                        discharge_segments.append(np.zeros(n_days))
                    continue
                if seg['type'] in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL):
                    if mode == 'A':
                        if cap is None:
                            space = np.zeros(n_days)
                        else:
                            headroom = np.maximum(cap - sub_load, 0)
                            # v2.29fix: Mode A充电空间加功率约束——电池C-rate限制
                            if rated_power and rated_power > 0:
                                headroom = np.minimum(rated_power, headroom)
                            space = np.sum(headroom * seg_dt, axis=1)
                    elif mode in ('B', 'C'):
                        if rated_power is None or rated_power <= 0:
                            space = np.zeros(n_days)
                        else:
                            neg_load = np.maximum(-sub_load, 0)
                            space = np.sum(np.minimum(rated_power, neg_load) * seg_dt, axis=1) * CHARGING_EFFICIENCY
                            # v3.0fix: Mode B/C 充电同时受容量线约束
                            if cap and cap > 0:
                                cap_space = np.sum(np.maximum(cap - sub_load, 0) * seg_dt, axis=1) * CHARGING_EFFICIENCY
                                space = np.minimum(space, cap_space)
                    else:
                        space = np.zeros(n_days)
                    space = np.nan_to_num(space, nan=0.0)
                    charge_segments.append(space)
                    charge_labels.append(seg['label'])
                    # v3.2.1fix(N4): 四个列表必须同长（segs 与 labels 一一对应）。
                    # 原实现充电段不向放电列表补位，导致 charge 5 项 / discharge 4 项，
                    # 下游 _compute_segment_power_summary 按全局 label 取索引时错位。
                    discharge_segments.append(np.zeros(n_days))
                    discharge_labels.append(seg['label'])
                elif seg['type'] in (PeriodType.DISCHARGE, PeriodType.DISCHARGE_LABEL):
                    # v3.2fix(P-32): 原为 else，会把平段当放电段
                    pos_sub_load = np.maximum(sub_load, 0)
                    if mode == 'A':
                        space = np.zeros(n_days) if cap is None else np.sum(np.minimum(pos_sub_load, cap) * seg_dt, axis=1) * DISCHARGING_EFFICIENCY
                    elif mode in ('B', 'C'):
                        if rated_power is None or rated_power <= 0:
                            space = np.zeros(n_days)
                        else:
                            space = np.sum(np.minimum(rated_power, pos_sub_load) * seg_dt, axis=1) * DISCHARGING_EFFICIENCY
                            # v3.0fix: Mode B/C 放电同时受容量线约束
                            if cap and cap > 0:
                                space = np.minimum(space, np.sum(np.minimum(cap, pos_sub_load) * seg_dt, axis=1))
                    else:
                        space = np.zeros(n_days)
                    space = np.nan_to_num(space, nan=0.0)
                    discharge_segments.append(space)
                    discharge_labels.append(seg['label'])
                    # v3.2.1fix(N4): 同上，放电段向充电列表补零占位
                    charge_segments.append(np.zeros(n_days))
                    charge_labels.append(seg['label'])
                else:
                    # v3.2fix(P-32): 平段既不充也不放。
                    # 四个列表必须同步追加（segs 与 labels 必须一一对应），否则 zip 会错位。
                    charge_segments.append(np.zeros(n_days))
                    discharge_segments.append(np.zeros(n_days))
                    charge_labels.append(seg['label'])
                    discharge_labels.append(seg['label'])
    return charge_segments, discharge_segments, charge_labels, discharge_labels


class PeriodEditDialog(AnimatedDialog):
    __slots__ = ('config_manager', 'result', '_initial_period', 'start_spin', 'end_spin', 'type_combo')
    def __init__(self, parent, period=None, config_manager=None):
        super().__init__(parent)
        self.setWindowTitle("✏️ 编辑时段")
        bsize = int(base_size())
        self.setMinimumSize(400, 260)
        self.config_manager = config_manager
        self.result = None

        if self.config_manager:
            geom = self.config_manager.get_window_geometry("PeriodEditDialog")
            if geom:
                self.restoreGeometry(geom)
            else:
                self.resize(400, 260)
        else:
            self.resize(400, 260)

        layout = QVBoxLayout(self)
        layout.setSpacing(10)
        layout.setContentsMargins(24, 24, 24, 24)

        start_label = QLabel("⏱ 开始时间")
        start_label.setFont(get_default_font(13, bold=True))
        layout.addWidget(start_label)
        self.start_edit = QLineEdit(_fmt_hour(period['start']) if period else "08:00")
        self.start_edit.setPlaceholderText("例: 08:30 / 8.5 / 8 30")
        self.start_edit.setMinimumHeight(bsize)
        self.start_edit.setFont(get_default_font(12))
        layout.addWidget(self.start_edit)

        end_label = QLabel("⏱ 结束时间")
        end_label.setFont(get_default_font(13, bold=True))
        layout.addWidget(end_label)
        self.end_edit = QLineEdit(_fmt_hour(period['end']) if period else "11:00")
        self.end_edit.setPlaceholderText("例: 11:00 / 11.5")
        self.end_edit.setMinimumHeight(bsize)
        self.end_edit.setFont(get_default_font(12))
        layout.addWidget(self.end_edit)

        type_label = QLabel("⚡ 类型")
        type_label.setFont(get_default_font(13, bold=True))
        layout.addWidget(type_label)
        self.type_combo = QComboBox()
        self.type_combo.addItems([PeriodType.CHARGE_LABEL.value, PeriodType.DISCHARGE_LABEL.value])
        self.type_combo.setMinimumHeight(bsize)
        self.type_combo.setFont(get_default_font(12))
        if period and period['type'] in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL):
            self.type_combo.setCurrentIndex(0)
        layout.addWidget(self.type_combo)

        hint_label = QLabel("支持格式: 08:30 / 8.5 / 8 30 / 830")
        hint_label.setStyleSheet("color: #5D6D7E; font-size: 11px;")
        hint_label.setFont(get_default_font(11))
        layout.addWidget(hint_label)

        btn_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        btn_box.accepted.connect(self._ok)
        btn_box.rejected.connect(self.reject)
        ok_btn = btn_box.button(QDialogButtonBox.Ok)
        if ok_btn:
            ok_btn.setObjectName("primary")
            ok_btn.setMinimumHeight(bsize)
            ok_btn.setFont(get_default_font(13, bold=True))
        cancel_btn = btn_box.button(QDialogButtonBox.Cancel)
        if cancel_btn:
            cancel_btn.setObjectName("secondary")
            cancel_btn.setMinimumHeight(bsize)
            cancel_btn.setFont(get_default_font(13, bold=True))
        layout.addWidget(btn_box)

    def _ok(self):
        try:
            s = parse_flexible_time(self.start_edit.text())
            e = parse_flexible_time(self.end_edit.text())
            if not (0 <= s <= 24 and 0 <= e <= 24):
                raise ValueError("时间必须在 0~24 之间")
            typ = PeriodType.CHARGE if '充电' in self.type_combo.currentText() else PeriodType.DISCHARGE
            self.result = {'start': s, 'end': e, 'type': typ}
            self.accept()
        except Exception as ex:
            log.exception("时段编辑时间解析错误")
            QMessageBox.critical(self, "时间格式错误", f"请输入正确的时间:\n{ex}")

    def closeEvent(self, event):
        if self.config_manager:
            self.config_manager.set_window_geometry("PeriodEditDialog", self.saveGeometry())
        super().closeEvent(event)


class GroupPeriodEditDialog(AnimatedDialog):
    __slots__ = ('config_manager', 'province_name', 'original_name', 'result', 'current_periods',
                 'selected_months', '_undo_stack', '_redo_stack', '_max_history', '_skip_history',
                 'name_edit', 'select_all_check', 'month_checks', 'tree', 'conflict_label',
                 'undo_btn', 'redo_btn', 'shortcut_undo', 'shortcut_redo', '_save_callback')
    def __init__(self, parent, config_manager, province_name, group_data=None, save_callback=None):
        super().__init__(parent)
        bsize = int(base_size())
        self.config_manager = config_manager
        self.province_name = province_name
        self.original_name = group_data['name'] if group_data else None
        self.result = None
        self.current_periods = group_data['periods'][:] if group_data else []
        self.selected_months = set(group_data['months']) if group_data else set()
        self._undo_stack = []
        self._redo_stack = []
        self._max_history = 30
        self._skip_history = False
        self._save_callback = save_callback  # v2.19fix: 保存回调->弹窗内完成事务

        self.setWindowTitle("📋 编辑策略组" if group_data else "📋 新建策略组")
        self.setMinimumSize(820, 640)

        if self.config_manager:
            geom = self.config_manager.get_window_geometry("GroupPeriodEditDialog")
            if geom:
                self.restoreGeometry(geom)
            else:
                self.resize(850, 640)
        else:
            self.resize(850, 640)

        layout = QVBoxLayout(self)
        layout.setSpacing(12)
        layout.setContentsMargins(24, 24, 24, 24)

        name_layout = QHBoxLayout()
        name_label = QLabel("🏷 策略组名称:")
        name_label.setFont(get_default_font(13, bold=True))
        name_layout.addWidget(name_label)
        self.name_edit = QLineEdit(group_data['name'] if group_data else "")
        self.name_edit.setPlaceholderText("如:夏季高峰")
        self.name_edit.setMinimumHeight(bsize)
        self.name_edit.setFont(get_default_font(13))
        name_layout.addWidget(self.name_edit)
        layout.addLayout(name_layout)

        months_group = QGroupBox("📅 适用月份")
        months_group.setFont(get_default_font(14, bold=True))
        months_main_layout = QVBoxLayout(months_group)
        self.select_all_check = QCheckBox("全选所有月份")
        self.select_all_check.setTristate(False)
        self.select_all_check.setFont(get_default_font(13, bold=True))
        self.select_all_check.toggled.connect(self._on_select_all_months)
        months_main_layout.addWidget(self.select_all_check)
        months_grid = QGridLayout()
        self.month_checks = {}
        for i in range(1, 13):
            cb = QCheckBox(f"{i}月")
            cb.setFont(get_default_font(12, bold=True))
            if i in self.selected_months:
                cb.setChecked(True)
            cb.toggled.connect(lambda checked, m=i: self._on_month_toggled(m, checked))
            self.month_checks[str(i)] = cb
            row = (i-1) // 4
            col = (i-1) % 4
            months_grid.addWidget(cb, row, col)
        months_main_layout.addLayout(months_grid)
        layout.addWidget(months_group)

        self.tree = QTreeWidget()
        self.tree.setHeaderLabels(['开始', '结束', '类型'])
        self.tree.setFont(get_default_font(12))
        self.tree.setSelectionMode(QTreeWidget.ExtendedSelection)
        self.tree.setDragDropMode(QTreeWidget.InternalMove)
        self.tree.setDefaultDropAction(Qt.MoveAction)
        self.tree.itemDoubleClicked.connect(self._edit_selected)
        self.tree.model().rowsMoved.connect(self._on_rows_moved)
        layout.addWidget(self.tree)

        self.conflict_label = QLabel("")
        self.conflict_label.setStyleSheet("color: #C0392B; font-weight: bold;")
        self.conflict_label.setFont(get_default_font(12, bold=True))
        layout.addWidget(self.conflict_label)

        tool_layout = QHBoxLayout()
        tool_layout.setSpacing(8)
        add_btn = QPushButton("➕ 添加")
        add_btn.setObjectName("primary")
        add_btn.setMinimumHeight(bsize)
        add_btn.clicked.connect(self._add_period)
        edit_btn = QPushButton("✏️ 编辑")
        edit_btn.setObjectName("secondary")
        edit_btn.setMinimumHeight(bsize)
        edit_btn.clicked.connect(self._edit_selected)
        del_btn = QPushButton("🗑 删除")
        del_btn.setObjectName("danger")
        del_btn.setMinimumHeight(bsize)
        del_btn.clicked.connect(self._delete_selected)
        clear_btn = QPushButton("🧹 清空")
        clear_btn.setObjectName("secondary")
        clear_btn.setMinimumHeight(bsize)
        clear_btn.clicked.connect(self._clear_periods)
        tool_layout.addWidget(add_btn)
        tool_layout.addWidget(edit_btn)
        tool_layout.addWidget(del_btn)
        tool_layout.addWidget(clear_btn)

        type_btn = QPushButton("🔄 改类型")
        type_btn.setMinimumHeight(bsize)
        type_btn.clicked.connect(self._batch_change_type)
        classic_btn = QPushButton("📋 经典模板")
        classic_btn.setMinimumHeight(bsize)
        classic_btn.clicked.connect(self._preset_classic)
        summer_btn = QPushButton("☀️ 夏季模板")
        summer_btn.setMinimumHeight(bsize)
        summer_btn.clicked.connect(self._preset_summer)
        tool_layout.addWidget(type_btn)
        tool_layout.addWidget(classic_btn)
        tool_layout.addWidget(summer_btn)

        self.undo_btn = QPushButton("↩ 撤销")
        self.undo_btn.setMinimumHeight(bsize)
        self.undo_btn.clicked.connect(self._undo)
        self.redo_btn = QPushButton("↪ 重做")
        self.redo_btn.setMinimumHeight(bsize)
        self.redo_btn.clicked.connect(self._redo)
        tool_layout.addWidget(self.undo_btn)
        tool_layout.addWidget(self.redo_btn)

        tool_layout.addStretch()
        layout.addLayout(tool_layout)

        dlg_btns = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        dlg_btns.accepted.connect(self._save)
        dlg_btns.rejected.connect(self.reject)
        save_btn = dlg_btns.button(QDialogButtonBox.Save)
        if save_btn:
            save_btn.setObjectName("primary")
            save_btn.setMinimumHeight(bsize)
            save_btn.setFont(get_default_font(13, bold=True))
        cancel_btn = dlg_btns.button(QDialogButtonBox.Cancel)
        if cancel_btn:
            cancel_btn.setObjectName("secondary")
            cancel_btn.setMinimumHeight(bsize)
            cancel_btn.setFont(get_default_font(13, bold=True))
        layout.addWidget(dlg_btns)

        self._populate_list()
        self._update_undo_redo_buttons()
        self._check_conflicts()
        self._update_select_all_check()

        self.shortcut_undo = QAction("撤销", self)
        self.shortcut_undo.setShortcut("Ctrl+Z")
        self.shortcut_undo.triggered.connect(self._undo)
        self.addAction(self.shortcut_undo)
        self.shortcut_redo = QAction("重做", self)
        self.shortcut_redo.setShortcut("Ctrl+Y")
        self.shortcut_redo.triggered.connect(self._redo)
        self.addAction(self.shortcut_redo)

    def _on_select_all_months(self, checked):
        with suppress(Exception):
            self._push_history()
        for cb in self.month_checks.values():
            cb.setChecked(checked)
        self.selected_months = set(range(1, 13)) if checked else set()
        self._check_conflicts()

    def _on_month_toggled(self, month, checked):
        """v2.19: 单月勾选->更新集合并实时检测冲突"""
        if checked:
            self.selected_months.add(month)
        else:
            self.selected_months.discard(month)
        self._update_select_all_check()
        self._check_conflicts()

    def _update_select_all_check(self):
        all_checked = all(cb.isChecked() for cb in self.month_checks.values())
        any_checked = any(cb.isChecked() for cb in self.month_checks.values())
        if all_checked:
            self.select_all_check.setCheckState(Qt.Checked)
        elif any_checked:
            self.select_all_check.setCheckState(Qt.PartiallyChecked)
        else:
            self.select_all_check.setCheckState(Qt.Unchecked)

    def _push_history(self):
        if self._skip_history:
            return
        self._undo_stack.append((copy.deepcopy(self.current_periods), self.selected_months.copy()))
        if len(self._undo_stack) > self._max_history:
            self._undo_stack.pop(0)
        self._redo_stack.clear()
        self._update_undo_redo_buttons()

    def _undo(self):
        if not self._undo_stack:
            return
        self._redo_stack.append((copy.deepcopy(self.current_periods), self.selected_months.copy()))
        periods, months = self._undo_stack.pop()
        self.current_periods = periods
        self.selected_months = months
        self._apply_months_to_ui()
        self._populate_list()
        self._update_undo_redo_buttons()
        self._check_conflicts()

    def _redo(self):
        if not self._redo_stack:
            return
        self._undo_stack.append((self.current_periods[:], self.selected_months.copy()))
        periods, months = self._redo_stack.pop()
        self.current_periods = periods
        self.selected_months = months
        self._apply_months_to_ui()
        self._populate_list()
        self._update_undo_redo_buttons()
        self._check_conflicts()

    def _update_undo_redo_buttons(self):
        self.undo_btn.setEnabled(len(self._undo_stack) > 0)
        self.redo_btn.setEnabled(len(self._redo_stack) > 0)

    def _apply_months_to_ui(self):
        for m_str, cb in self.month_checks.items():
            cb.setChecked(int(m_str) in self.selected_months)
        self._update_select_all_check()

    def _find_overnight_indices(self):
        indices = set()
        for i in range(len(self.current_periods)-1):
            p1, p2 = self.current_periods[i], self.current_periods[i+1]
            if p1['end'] == 24.0 and p2['start'] == 0.0 and p1['type'] == p2['type']:
                indices.add(i)
                indices.add(i+1)
        return indices

    def _populate_list(self):
        self.tree.clear()
        overnight = self._find_overnight_indices()
        for i, p in enumerate(self.current_periods):
            s = _fmt_hour(p['start'])
            e = _fmt_hour(p['end'])
            is_charge = p['type'] in (PeriodType.CHARGE, PeriodType.CHARGE_LABEL)
            t = PeriodType.CHARGE_LABEL if is_charge else PeriodType.DISCHARGE_LABEL
            if i in overnight:
                t += " (跨夜)"
            item = QTreeWidgetItem([s, e, t])
            if is_charge:
                item.setBackground(2, QColor(ColorConst.READY_BG))
                item.setForeground(2, QColor(ColorConst.READY_FG))
            else:
                item.setBackground(2, QColor(ColorConst.DISCHARGE_BG_ITEM))
                item.setForeground(2, QColor(ColorConst.DISCHARGE_FG))
            self.tree.addTopLevelItem(item)

    def _on_rows_moved(self, parent, start, end, destination, row):
        new_periods = []
        for i in range(self.tree.topLevelItemCount()):
            item = self.tree.topLevelItem(i)
            start_text = item.text(0)
            end_text = item.text(1)
            for p in self.current_periods:
                if _fmt_hour(p['start']) == start_text and _fmt_hour(p['end']) == end_text:
                    new_periods.append(p)
                    break
        if len(new_periods) == len(self.current_periods):
            self._push_history()
            self.current_periods = new_periods
        self._check_conflicts()

    def _add_period(self):
        self._push_history()
        dlg = PeriodEditDialog(self, config_manager=self.config_manager)
        if dlg.exec() == QDialog.Accepted and dlg.result:
            self.current_periods.append(dlg.result)
            ok, msg, _ = _valid_periods(self.current_periods)
            if not ok:
                self.current_periods.pop()
                QMessageBox.critical(self, "时段冲突", msg)
            else:
                self._populate_list()
        elif self._undo_stack:
            self._undo_stack.pop()
            self._update_undo_redo_buttons()
        self._check_conflicts()

    def _edit_selected(self):
        items = self.tree.selectedItems()
        if not items:
            return
        self._push_history()
        idx = self.tree.indexOfTopLevelItem(items[0])
        dlg = PeriodEditDialog(self, self.current_periods[idx], config_manager=self.config_manager)
        if dlg.exec() == QDialog.Accepted and dlg.result:
            old = self.current_periods[idx]
            self.current_periods[idx] = dlg.result
            ok, msg, _ = _valid_periods(self.current_periods)
            if not ok:
                self.current_periods[idx] = old
                QMessageBox.critical(self, "时段冲突", msg)
            else:
                self._populate_list()
        elif self._undo_stack:
            self._undo_stack.pop()
            self._update_undo_redo_buttons()
        self._check_conflicts()

    def _delete_selected(self):
        items = self.tree.selectedItems()
        if not items:
            return
        self._push_history()
        if QMessageBox.question(self, "确认", f"删除选中的 {len(items)} 个时段?") == QMessageBox.Yes:
            for item in reversed(items):
                idx = self.tree.indexOfTopLevelItem(item)
                del self.current_periods[idx]
            self._populate_list()
        elif self._undo_stack:
            self._undo_stack.pop()
            self._update_undo_redo_buttons()
        self._check_conflicts()

    def _clear_periods(self):
        if self.current_periods:
            self._push_history()
            if QMessageBox.question(self, "确认", "清空所有时段?") == QMessageBox.Yes:
                self.current_periods.clear()
                self._populate_list()
            elif self._undo_stack:
                self._undo_stack.pop()
                self._update_undo_redo_buttons()
        self._check_conflicts()

    def _batch_change_type(self):
        items = self.tree.selectedItems()
        if not items:
            return
        self._push_history()
        dlg = QDialog(self)
        dlg.setWindowTitle("修改类型")
        layout = QVBoxLayout(dlg)
        layout.addWidget(QLabel("将选中的时段改为:"))
        combo = QComboBox()
        combo.addItems([PeriodType.CHARGE_LABEL.value, PeriodType.DISCHARGE_LABEL.value])
        combo.setMinimumHeight(int(base_size()))
        layout.addWidget(combo)
        btns = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        btns.accepted.connect(dlg.accept)
        btns.rejected.connect(dlg.reject)
        ok_btn = btns.button(QDialogButtonBox.Ok)
        if ok_btn:
            ok_btn.setMinimumHeight(int(base_size()))
        cancel_btn = btns.button(QDialogButtonBox.Cancel)
        if cancel_btn:
            cancel_btn.setMinimumHeight(int(base_size()))
        layout.addWidget(btns)
        if dlg.exec() == QDialog.Accepted:
            new_type = PeriodType.CHARGE if '充电' in combo.currentText() else PeriodType.DISCHARGE
            for item in items:
                idx = self.tree.indexOfTopLevelItem(item)
                self.current_periods[idx]['type'] = new_type
            self._populate_list()
        elif self._undo_stack:
            self._undo_stack.pop()
            self._update_undo_redo_buttons()
        self._check_conflicts()

    def _preset_classic(self):
        self._push_history()
        new_periods = [
            {'start': 8, 'end': 11, 'type': PeriodType.DISCHARGE},
            {'start': 18, 'end': 21, 'type': PeriodType.DISCHARGE},
            {'start': 23, 'end': 7, 'type': PeriodType.CHARGE}
        ]
        ok, msg, _ = _valid_periods(new_periods)
        if not ok:
            QMessageBox.critical(self, "快速模板无效", msg)
            if self._undo_stack:
                self._undo_stack.pop()
            self._update_undo_redo_buttons()
            return
        self.current_periods = new_periods
        self._populate_list()
        self._check_conflicts()

    def _preset_summer(self):
        self._push_history()
        new_periods = [
            {'start': 10, 'end': 12, 'type': PeriodType.DISCHARGE},
            {'start': 14, 'end': 16, 'type': PeriodType.DISCHARGE},
            {'start': 19, 'end': 22, 'type': PeriodType.DISCHARGE},
            {'start': 22, 'end': 6, 'type': PeriodType.CHARGE}
        ]
        ok, msg, _ = _valid_periods(new_periods)
        if not ok:
            QMessageBox.critical(self, "快速模板无效", msg)
            if self._undo_stack:
                self._undo_stack.pop()
            self._update_undo_redo_buttons()
            return
        self.current_periods = new_periods
        self._populate_list()
        self._check_conflicts()

    def _check_conflicts(self):
        """v2.19: 实时检查时段重叠+月份跨组重叠"""
        ok, msg, _ = _valid_periods(self.current_periods)
        if not ok:
            self.conflict_label.setText(f"⚠ {msg}")
            return
        # v2.19: 月份跨组重叠实时检测
        selected = {int(m) for m, cb in self.month_checks.items() if cb.isChecked()}
        groups = self.config_manager.get_province_groups(self.province_name)
        used = {}
        for g in groups:
            if self.original_name and g['name'] == self.original_name:
                continue
            for m in g['months']:
                used[m] = g['name']
        overlap = [m for m in sorted(selected) if m in used]
        if overlap:
            conflict_names = {used[m] for m in overlap}
            self.conflict_label.setText(f"⚠ 月份 {overlap} 已被 [{', '.join(conflict_names)}] 占用")
        else:
            self.conflict_label.setText("")

    def _save(self):
        name = self.name_edit.text().strip()
        if not name:
            QMessageBox.warning(self, "提示", "请输入策略组名称")
            return

        self.selected_months = {int(m) for m, cb in self.month_checks.items() if cb.isChecked()}
        selected_months = sorted(self.selected_months)
        if not selected_months:
            QMessageBox.warning(self, "提示", "请至少选择一个适用月份")
            return
        if not self.current_periods:
            QMessageBox.warning(self, "提示", "请至少添加一个充放电时段")
            return

        ok, msg, _ = _valid_periods(self.current_periods)
        if not ok:
            QMessageBox.critical(self, "时段校验失败", msg)
            return

        # v2.19: 月份跨组重叠校验 - 在对话框内检查,不关闭窗口
        groups = self.config_manager.get_province_groups(self.province_name)
        used_months = {}
        for g in groups:
            # 编辑模式下排除当前组自身
            if self.original_name and g['name'] == self.original_name:
                continue
            for m in g['months']:
                used_months[m] = g['name']
        overlap = [m for m in selected_months if m in used_months]
        if overlap:
            conflict_groups = {used_months[m] for m in overlap}
            self.conflict_label.setText(
                f"⚠ 月份 {overlap} 已被策略组 {conflict_groups} 占用,请调整月份选择"
            )
            QMessageBox.warning(self, "月份重叠",
                f"以下月份已被其他策略组占用:\n{overlap}\n\n"
                f"冲突策略组:{', '.join(conflict_groups)}\n\n"
                f'请取消冲突月份的勾选后重试.')
            return

        # v2.19fix: 通过save_callback完成保存事务->成功才关闭弹窗
        if self._save_callback:
            success = self._save_callback(name, selected_months, self.current_periods[:])
            if not success:
                QMessageBox.warning(self, "保存失败",
                    "策略组保存失败,可能原因:\n"
                    "• 月份与已有策略组重叠\n• 策略组名称已存在\n\n"
                    "弹窗将保持打开,请调整后重试.")
                return
        else:
            # 无回调时兼容旧逻辑:仅设置result
            self.result = {
                'name': name,
                'months': selected_months,
                'periods': self.current_periods[:]
            }
        self.result = {
            'name': name,
            'months': selected_months,
            'periods': self.current_periods[:]
        }
        self.accept()

    def reject(self):
        self.result = None
        super().reject()

    def closeEvent(self, event):
        if self.config_manager:
            self.config_manager.set_window_geometry("GroupPeriodEditDialog", self.saveGeometry())
        super().closeEvent(event)


class ProvinceStrategyEditDialog(AnimatedDialog):
    __slots__ = ('config_manager', 'province_name', 'group_tree', 'month_labels', 'month_panel')
    strategy_saved = Signal()

    def __init__(self, parent, config_manager, province_name):
        super().__init__(parent)
        bsize = int(base_size())
        self.config_manager = config_manager
        self.province_name = province_name
        self.setWindowTitle(f"🗺 编辑省份策略 - {province_name}")
        self.setMinimumSize(750, 500)

        if self.config_manager:
            geom = self.config_manager.get_window_geometry("ProvinceStrategyEditDialog")
            if geom:
                self.restoreGeometry(geom)
            else:
                self.resize(800, 550)
        else:
            self.resize(800, 550)

        layout = QVBoxLayout(self)
        layout.setSpacing(12)
        layout.setContentsMargins(24, 24, 24, 24)

        title = QLabel(f"省份: {self.province_name}")
        title.setFont(get_default_font(16, bold=True))
        layout.addWidget(title)

        self.group_tree = QTreeWidget()
        self.group_tree.setHeaderLabels(['策略组名称', '适用月份', '时段数'])
        self.group_tree.setFont(get_default_font(12))
        self.group_tree.itemDoubleClicked.connect(self._edit_group)
        layout.addWidget(self.group_tree)

        self.month_panel = QWidget()
        month_grid = QGridLayout(self.month_panel)
        self.month_labels = {}
        for i in range(1, 13):
            lbl = QLabel(f"{i}月")
            lbl.setAlignment(Qt.AlignCenter)
            lbl.setFixedSize(int(bsize * 1.5), int(bsize * 0.7))
            lbl.setStyleSheet("background-color: #EBF0F5; border: 1px solid #D5DCE6; border-radius: 4px;")
            lbl.setFont(get_default_font(10, bold=True))
            self.month_labels[i] = lbl
            month_grid.addWidget(lbl, (i-1)//4, (i-1)%4)
        layout.addWidget(QLabel("月份覆盖:"))
        layout.addWidget(self.month_panel)

        btn_layout = QHBoxLayout()
        add_btn = QPushButton("➕ 添加策略组")
        add_btn.setObjectName("primary")
        add_btn.setMinimumHeight(bsize)
        add_btn.clicked.connect(self._add_group)
        edit_btn = QPushButton("✏️ 编辑选中组")
        edit_btn.setMinimumHeight(bsize)
        edit_btn.clicked.connect(self._edit_group)
        del_btn = QPushButton("🗑 删除选中组")
        del_btn.setObjectName("danger")
        del_btn.setMinimumHeight(bsize)
        del_btn.clicked.connect(self._delete_group)
        # v3.2fix: akshare 电价数据
        self.fetch_price_btn = QPushButton("📡 拉取最新电价")
        self.fetch_price_btn.setMinimumHeight(bsize)
        self.fetch_price_btn.clicked.connect(self._fetch_price_akshare)
        btn_layout.addWidget(add_btn)
        btn_layout.addWidget(edit_btn)
        btn_layout.addWidget(del_btn)
        btn_layout.addWidget(self.fetch_price_btn)
        btn_layout.addStretch()
        layout.addLayout(btn_layout)

        dlg_btns = QDialogButtonBox(QDialogButtonBox.Close)
        dlg_btns.rejected.connect(self.accept)
        close_btn = dlg_btns.button(QDialogButtonBox.Close)
        if close_btn:
            close_btn.setObjectName("secondary")
            close_btn.setMinimumHeight(bsize)
        layout.addWidget(dlg_btns)

        self._refresh()

    def _refresh(self):
        self.group_tree.clear()
        groups = self.config_manager.get_province_groups(self.province_name)
        used_months = set()
        for g in groups:
            months_str = ','.join(str(m) for m in g['months'])
            self.group_tree.addTopLevelItem(QTreeWidgetItem([g['name'], months_str, str(len(g['periods']))]))
            used_months.update(g['months'])

        for m in range(1, 13):
            lbl = self.month_labels[m]
            if m in used_months:
                lbl.setStyleSheet("background-color: #E8F5E9; border: 1px solid #999; border-radius: 4px;")
            else:
                lbl.setStyleSheet("background-color: #FFEBEE; border: 1px solid #999; border-radius: 4px;")

    def _add_group(self):
        # v2.19fix: save_callback->弹窗内部完成保存事务,失败时弹窗保持打开
        def _save(name, months, periods):
            return self.config_manager.add_group(self.province_name, name, months, periods)
        dlg = GroupPeriodEditDialog(self, self.config_manager, self.province_name, save_callback=_save)
        if dlg.exec() == QDialog.Accepted:
            self._refresh()
            self.strategy_saved.emit()

    def _edit_group(self):
        items = self.group_tree.selectedItems()
        if not items:
            return
        group_name = items[0].text(0)
        groups = self.config_manager.get_province_groups(self.province_name)
        target = next((g for g in groups if g['name'] == group_name), None)
        if not target:
            return
        # v2.19fix: save_callback->弹窗内部完成保存事务,失败时弹窗保持打开
        def _save(name, months, periods):
            return self.config_manager.update_group(self.province_name, group_name, name, months, periods)
        dlg = GroupPeriodEditDialog(self, self.config_manager, self.province_name, target, save_callback=_save)
        if dlg.exec() == QDialog.Accepted:
            self._refresh()
            self.strategy_saved.emit()

    def _delete_group(self):
        items = self.group_tree.selectedItems()
        if not items:
            return
        group_name = items[0].text(0)
        if QMessageBox.question(self, "确认", f'删除策略组"{group_name}"?') == QMessageBox.Yes:
            self.config_manager.delete_group(self.province_name, group_name)
            self._refresh()
            self.strategy_saved.emit()

    def closeEvent(self, event):
        if self.config_manager:
            self.config_manager.set_window_geometry("ProvinceStrategyEditDialog", self.saveGeometry())
        super().closeEvent(event)


class ChargeDischargeManagerDialog(AnimatedDialog):
    __slots__ = ('cfg', 'result', 'tree')
    strategy_selected = Signal(str)

    def __init__(self, parent, cfg):
        super().__init__(parent)
        bsize = int(base_size())
        self.cfg = cfg
        self.result = None
        self.setWindowTitle("🔋 充放时段策略管理")
        self.setMinimumSize(550, 420)

        if self.cfg:
            geom = self.cfg.get_window_geometry("ChargeDischargeManagerDialog")
            if geom:
                self.restoreGeometry(geom)
            else:
                self.resize(550, 420)
        else:
            self.resize(550, 420)

        layout = QVBoxLayout(self)
        layout.setSpacing(12)
        layout.setContentsMargins(24, 24, 24, 24)

        self.tree = QTreeWidget()
        self.tree.setHeaderLabels(['省份/策略组', '月份/时段数'])
        self.tree.setFont(get_default_font(12))
        self.tree.itemDoubleClicked.connect(self._edit_item)
        self.tree.setContextMenuPolicy(Qt.CustomContextMenu)  # v2.17: 右键菜单
        self.tree.customContextMenuRequested.connect(self._on_tree_context_menu)

        # v2.17: 策略区域提示
        hint = QLabel("💡 默认策略基于浙江2026年政策.已取消固定分时电价省份(湖北/陕西/贵州/云南/重庆/辽宁/吉林)结果仅供参考,请根据实际项目配置.")
        hint.setWordWrap(True)
        hint.setStyleSheet("color: #B8860B; font-size: 10px; padding: 2px 0;")

        layout.addWidget(hint)
        layout.addWidget(self.tree)

        btn_layout = QHBoxLayout()
        new_prov_btn = QPushButton("🌏 新建省份")
        new_prov_btn.setObjectName("primary")
        new_prov_btn.setMinimumHeight(bsize)
        new_prov_btn.clicked.connect(self._new_province)
        edit_prov_btn = QPushButton("✏️ 编辑省份")
        edit_prov_btn.setMinimumHeight(bsize)
        edit_prov_btn.clicked.connect(self._edit_province)
        del_prov_btn = QPushButton("🗑 删除省份")
        del_prov_btn.setObjectName("danger")
        del_prov_btn.setMinimumHeight(bsize)
        del_prov_btn.clicked.connect(self._delete_province)
        btn_layout.addWidget(new_prov_btn)
        btn_layout.addWidget(edit_prov_btn)
        btn_layout.addWidget(del_prov_btn)
        # v2.23: 一键导入内置32省电价策略
        import_builtin_btn = QPushButton("📥 导入内置策略")
        import_builtin_btn.setMinimumHeight(bsize)
        import_builtin_btn.setToolTip("从内置数据库导入尚未配置的省份(32省分时电价+充放电策略)")
        import_builtin_btn.clicked.connect(self._import_builtin_strategies)
        btn_layout.addWidget(import_builtin_btn)
        btn_layout.addStretch()
        layout.addLayout(btn_layout)

        dlg_btns = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        dlg_btns.accepted.connect(self._accept)
        dlg_btns.rejected.connect(self.reject)
        ok_btn = dlg_btns.button(QDialogButtonBox.Ok)
        if ok_btn:
            ok_btn.setObjectName("primary")
            ok_btn.setMinimumHeight(bsize)
        cancel_btn = dlg_btns.button(QDialogButtonBox.Cancel)
        if cancel_btn:
            cancel_btn.setObjectName("secondary")
            cancel_btn.setMinimumHeight(bsize)
        layout.addWidget(dlg_btns)

        self.refresh_tree()

    def refresh_tree(self):
        self.tree.clear()
        for prov_name in self.cfg.provinces():
            prov_item = QTreeWidgetItem([prov_name, ""])
            prov_item.setData(0, Qt.UserRole, ('province', prov_name))
            groups = self.cfg.get_province_groups(prov_name)
            for g in groups:
                months_str = ','.join(str(m) for m in g['months'])
                g_item = QTreeWidgetItem([g['name'], months_str])
                g_item.setData(0, Qt.UserRole, ('group', prov_name, g['name']))
                prov_item.addChild(g_item)
            self.tree.addTopLevelItem(prov_item)
            self.tree.expandItem(prov_item)

    def _new_province(self):
        name, ok = QInputDialog.getText(self, "新建省份", "输入省份名称:")
        if ok and name.strip():
            if name.strip() in self.cfg.provinces():
                QMessageBox.warning(self, "错误", "省份已存在")
                return
            self.cfg.add_province(name.strip())
            self.refresh_tree()

    def _import_builtin_strategies(self):
        """v2.23: 从 PROVINCE_TARIFF_DB 一键导入所有内置省份策略到 Config.
        只导入尚未在 Config 中配置的省份,不会覆盖用户已编辑的策略."""
        existing = set(self.cfg.provinces())
        imported = 0
        skipped = 0
        for prov_name, info in PROVINCE_TARIFF_DB.items():
            if prov_name in existing:
                skipped += 1
                continue
            # 将内置电价数据结构转换为 Config 策略组格式
            periods = info.get('periods', [])
            info.get('mode', CHARGE_MODE_TWO_CYCLES)
            # 多季节格式转为 groups
            groups = []
            if periods and isinstance(periods[0], tuple) and isinstance(periods[0][0], tuple):
                # 多季节格式: [((1,2,12), [...]), ...]
                for months_tuple, p_list in periods:
                    segments = []
                    for s, e, t in p_list:
                        seg_type = PeriodType.CHARGE if t in ('valley', 'deep_valley') else PeriodType.DISCHARGE
                        segments.append({'start': s, 'end': e, 'type': seg_type})
                    groups.append({'name': f'{prov_name}{"夏冬" if set(months_tuple) & {1,7,8,12} else "春秋"}',
                                   'months': list(months_tuple), 'periods': segments})
            else:
                # 单季节格式
                segments = []
                for s, e, t in periods:
                    seg_type = PeriodType.CHARGE if t in ('valley', 'deep_valley') else PeriodType.DISCHARGE
                    segments.append({'start': s, 'end': e, 'type': seg_type})
                groups.append({'name': f'{prov_name}全年', 'months': list(range(1,13)), 'periods': segments})
            # 写入Config
            self.cfg.add_province(prov_name)
            for g in groups:
                self.cfg.add_group(prov_name, g['name'], g['months'], g['periods'])
            imported += 1
        if imported > 0:
            QMessageBox.information(self, "导入完成",
                f"已导入 {imported} 个内置省份策略.\n"
                f"跳过 {skipped} 个已配置省份(未覆盖).\n\n"
                f'内置策略基于各省发改委公开电价政策,建议根据实际项目调整.')
        else:
            QMessageBox.information(self, "提示",
                f"所有 {skipped} 个内置省份已存在于配置中,无需重复导入.")
        self.refresh_tree()

    def _edit_province(self):
        items = self.tree.selectedItems()
        if not items:
            return
        data = items[0].data(0, Qt.UserRole)
        if data[0] == 'province' or data[0] == 'group':
            prov_name = data[1]
        else:
            return
        dlg = ProvinceStrategyEditDialog(self, self.cfg, prov_name)
        dlg.strategy_saved.connect(self.refresh_tree)
        dlg.exec()
        self.refresh_tree()

    def _delete_province(self):
        items = self.tree.selectedItems()
        if not items:
            return
        data = items[0].data(0, Qt.UserRole)
        if data[0] == 'province' or data[0] == 'group':
            prov_name = data[1]
        else:
            return
        if QMessageBox.question(self, "确认", f'删除省份"{prov_name}"及其所有策略组?') == QMessageBox.Yes:
            self.cfg.delete_province(prov_name)
            self.refresh_tree()

    def _edit_item(self, item):
        data = item.data(0, Qt.UserRole)
        if data and data[0] == 'province':
            self._edit_province()
        elif data and data[0] == 'group':
            prov_name = data[1]
            dlg = ProvinceStrategyEditDialog(self, self.cfg, prov_name)
            dlg.strategy_saved.connect(self.refresh_tree)
            dlg.exec()
            self.refresh_tree()

    # v2.17: 右键菜单 - 重命名/编辑/删除省份
    def _on_tree_context_menu(self, pos):
        item = self.tree.itemAt(pos)
        if not item:
            return
        data = item.data(0, Qt.UserRole)
        if not data:
            return
        menu = QMenu(self)
        if data[0] == 'province':
            prov_name = data[1]
            rename_action = menu.addAction("✏️ 重命名省份")
            edit_action = menu.addAction("📋 编辑时段策略")
            menu.addSeparator()
            delete_action = menu.addAction("🗑 删除省份")
            action = menu.exec(self.tree.viewport().mapToGlobal(pos))
            if action == rename_action:
                self._rename_province(prov_name)
            elif action == edit_action:
                self._edit_province()
            elif action == delete_action:
                self._delete_province()
        elif data[0] == 'group':
            edit_action = menu.addAction("📋 编辑策略组")
            action = menu.exec(self.tree.viewport().mapToGlobal(pos))
            if action == edit_action:
                prov_name = data[1]
                dlg = ProvinceStrategyEditDialog(self, self.cfg, prov_name)
                dlg.strategy_saved.connect(self.refresh_tree)
                dlg.exec()
                self.refresh_tree()

    def _rename_province(self, old_name):
        new_name, ok = QInputDialog.getText(self, "重命名省份", "输入新名称:", text=old_name)
        if ok and new_name.strip() and new_name.strip() != old_name:
            success, err = self.cfg.rename_province(old_name, new_name.strip())
            if success:
                self.refresh_tree()
                ToastManager.show(self, f"省份已重命名为「{new_name.strip()}」", 'success', 2000)
            else:
                QMessageBox.warning(self, "重命名失败", err)

    def _accept(self):
        items = self.tree.selectedItems()
        if items:
            data = items[0].data(0, Qt.UserRole)
            if data and data[0] == 'province' or data and data[0] == 'group':
                self.result = data[1]
        self.accept()

    def _fetch_price_akshare(self):
        """v3.2fix: akshare 拉取最新分时电价并填入策略字段."""
        try:
            import akshare as ak
            df = ak.energy_province_electricity_price()
            if df is not None and not df.empty:
                QMessageBox.information(self, "电价数据已拉取",
                    f"获取到 {len(df)} 条记录.\n请根据数据手动填入时段配置.")
                # 省名匹配
                prov = getattr(self, 'province_name', '')
                if prov and prov != '无':
                    matched = df[df.iloc[:, 0].astype(str).str.contains(prov[:2], na=False)]
                    if not matched.empty:
                        QMessageBox.information(self, "匹配到数据", str(matched.head(10)))
            else:
                QMessageBox.warning(self, "提示", "未获取到电价数据")
        except Exception as e:
            QMessageBox.warning(self, "错误", f"拉取失败: {e}")

    def closeEvent(self, event):
        if self.cfg:
            self.cfg.set_window_geometry("ChargeDischargeManagerDialog", self.saveGeometry())
        super().closeEvent(event)

    # ── v3.2fix(特性同步): 从参考程序补回 ChargeDischargeManagerDialog._on_save_strategy ──
    def _on_save_strategy(self):
            """v3.2fix(特性同步): 从参考程序补回并适配宿主——导出策略。"""
            # 宿主 ChargeDischargeManagerDialog 无 _selected_province()，
            # 改为读树选中项（与本类 _delete_province 同一取法）。
            _items = self.tree.selectedItems()
            prov_name = None
            if _items:
                _d = _items[0].data(0, Qt.UserRole)
                if _d and len(_d) > 1:
                    prov_name = _d[1]
            if not prov_name:
                QMessageBox.warning(self, "提示", "请选择省份")
                return
            strategies = self.cfg.get_strat(prov_name)
            if not strategies:
                QMessageBox.warning(self, "提示", f"省份'{prov_name}'无可用策略")
                return
            new_name, ok = QInputDialog.getText(self, "导出策略", "策略名称:", text=f"{prov_name}_导出")
            if not ok or not new_name:
                return
            if self.cfg.save_strat(new_name, strategies):
                self.refresh_tree()
                QMessageBox.information(self, "完成", f"策略'{new_name}'已导出")
            else:
                QMessageBox.warning(self, "失败", "策略保存失败")
# endregion

# region 映射对话框(优化:列匹配阈值提升至0.9)

# ═══════════════════════════════════════════════════════════
# v2.28: 数据感知列选择头——直接在表格列头上标记类型+拖选范围
# ═══════════════════════════════════════════════════════════

class ColumnTypeHeader(QHeaderView):
    """自定义QHeaderView:列头显示类型标签+支持Shift选择宽表范围.
    
    列类型(循环切换): IGNORE(默认) → DATE → TIME → LOAD → ASSET → IGNORE
    右键菜单可直接指定类型.
    宽表模式: Shift+点击首尾列划定负荷范围,中间列自动设为LOAD.
    """
    _TYPE_ORDER = ['IGNORE', 'DATE', 'TIME', 'DATETIME', 'LOAD', 'ASSET']
    _TYPE_COLORS = {
        'DATE': QColor('#1E88E5'),
        'TIME': QColor('#F0A040'),
        'DATETIME': QColor('#00897B'),  # 青绿色=日期+时间合并
        'LOAD': QColor('#43A047'),
        'ASSET': QColor('#8E6AB8'),
        'IGNORE': QColor('#BDBDBD'),
    }
    _TYPE_LABELS = {'DATE': '📅日期', 'TIME': '🕐时间', 'DATETIME': '📅🕐日期时间', 
                    'LOAD': '⚡负荷', 'ASSET': '🏷资产', 'IGNORE': '—'}

    def __init__(self, orientation, parent_table=None):
        super().__init__(orientation, parent_table)
        self._col_types = {}       # {logical_index: 'DATE'|'TIME'|'LOAD'|'ASSET'|'IGNORE'}
        self._auto_recommended = set()  # 自动推荐的列索引
        self._wide_mode = False
        self._range_start = None   # Shift选择起点
        self._required_labels = {'DATE': '日期⭐', 'LOAD': '负荷⭐', 'DATETIME': '日期时间⭐'}
        self._hovered_col = -1     # v3.0: 键盘快捷键跟踪悬停列
        self._stats_callback = None  # v3.0: 类型变更回调(更新统计条)
        self.setSectionsClickable(True)
        self.setHighlightSections(True)
        # v2.28fix: 增加默认行高,确保两行文本(类型标签+列名)完整显示
        self.setDefaultSectionSize(56)
        self.setMinimumSectionSize(40)
    
    def set_wide_mode(self, enabled):
        self._wide_mode = enabled
    
    def set_column_type(self, col_idx, col_type):
        """设置单列类型."""
        if col_type in self._TYPE_ORDER:
            self._col_types[col_idx] = col_type
            self.headerDataChanged(Qt.Horizontal, col_idx, col_idx)
            if self._stats_callback:
                self._stats_callback()  # v3.0: 通知统计条更新
    
    def get_type_counts(self):
        """v3.0: 返回各类型列数统计."""
        counts = {t: 0 for t in self._TYPE_ORDER}
        for t in self._col_types.values():
            if t in counts:
                counts[t] += 1
        return counts
    
    def mouseMoveEvent(self, event):
        """v3.0: 追踪鼠标悬停列,用于键盘快捷键."""
        idx = self.logicalIndexAt(event.pos())
        if idx >= 0:
            self._hovered_col = idx
        super().mouseMoveEvent(event)
    
    def get_column_type(self, col_idx):
        return self._col_types.get(col_idx, 'IGNORE')
    
    def set_auto_recommended(self, col_indices):
        self._auto_recommended = set(col_indices)
    
    def get_date_col(self):
        for idx, typ in self._col_types.items():
            if typ == 'DATE':
                return idx
        return None
    
    def get_time_col(self):
        for idx, typ in self._col_types.items():
            if typ == 'TIME':
                return idx
        return None
    
    def get_load_cols(self):
        return sorted([idx for idx, typ in self._col_types.items() if typ == 'LOAD'])
    
    def get_asset_col(self):
        for idx, typ in self._col_types.items():
            if typ == 'ASSET':
                return idx
        return None
    
    def set_range_load(self, start_idx, end_idx):
        """宽表模式:将范围内的列全部设为LOAD."""
        lo, hi = min(start_idx, end_idx), max(start_idx, end_idx)
        for i in range(lo, hi + 1):
            self.set_column_type(i, 'LOAD')
        # 自动检测左侧日期列
        if lo > 0:
            self.set_column_type(lo - 1, 'DATE')
    
    def mousePressEvent(self, event):
        idx = self.logicalIndexAt(event.pos())
        if idx < 0:
            return super().mousePressEvent(event)
        if event.button() == Qt.RightButton:
            self._show_context_menu(idx, event.globalPos())
            return
        # 宽表模式Shift+点击:选择范围
        if self._wide_mode and event.modifiers() & Qt.ShiftModifier and self._range_start is not None:
            self.set_range_load(self._range_start, idx)
            self._range_start = None
        else:
            # 左键点击:循环切换类型
            if self._wide_mode:
                self._range_start = idx
            current = self.get_column_type(idx)
            next_idx = (self._TYPE_ORDER.index(current) + 1) % len(self._TYPE_ORDER)
            self.set_column_type(idx, self._TYPE_ORDER[next_idx])
        self.headerDataChanged(Qt.Horizontal, 0, self.count() - 1)
    
    def _show_context_menu(self, col_idx, global_pos):
        menu = QMenu()
        for typ in self._TYPE_ORDER:
            label = self._TYPE_LABELS.get(typ, typ)
            if typ in self._required_labels:
                label = self._required_labels[typ]
            action = menu.addAction(f"{label}")
            action.setData(typ)
            if self.get_column_type(col_idx) == typ:
                action.setCheckable(True)
                action.setChecked(True)
        chosen = menu.exec(global_pos)
        if chosen:
            self.set_column_type(col_idx, chosen.data())
    
    def paintSection(self, painter, rect, logical_index):
        painter.save()
        # 背景
        col_type = self.get_column_type(logical_index)
        bg = self._TYPE_COLORS.get(col_type, self._TYPE_COLORS['IGNORE'])
        if col_type == 'IGNORE':
            painter.fillRect(rect, QColor('#F5F6FA'))
        else:
            painter.fillRect(rect, bg.lighter(175))
        # 底部色条
        bar_rect = QRect(rect.left(), rect.bottom() - 4, rect.width(), 4)
        painter.fillRect(bar_rect, bg)
        # 类型标签
        label = self._TYPE_LABELS.get(col_type, '—')
        if col_type in self._required_labels:
            label = self._required_labels[col_type]
        is_auto = logical_index in self._auto_recommended and col_type != 'IGNORE'
        if is_auto:
            label = '⭐' + label
        font = painter.font()
        font.setPointSize(8)
        font.setBold(col_type != 'IGNORE')
        painter.setFont(font)
        painter.setPen(QColor('#333333') if col_type != 'IGNORE' else QColor('#999999'))
        text_rect = QRect(rect.left() + 4, rect.top() + 2, rect.width() - 8, 16)
        painter.drawText(text_rect, Qt.AlignLeft | Qt.AlignVCenter, label)
        # 列名
        col_name = self.model().headerData(logical_index, Qt.Horizontal, Qt.DisplayRole)
        if col_name:
            font.setPointSize(9)
            font.setBold(False)
            painter.setFont(font)
            painter.setPen(QColor('#555555'))
            name_rect = QRect(rect.left() + 4, rect.top() + 18, rect.width() - 8, rect.height() - 22)
            painter.drawText(name_rect, Qt.AlignLeft | Qt.AlignVCenter, str(col_name)[:30])
        painter.restore()


class DataPreviewDialog(QDialog):
    """v2.28: 数据预览——支持可视化列选择(长表)和宽表范围划定.
    
    mapper_mode='long': 列头点击循环切换类型(DATE/TIME/LOAD/ASSET/IGNORE)
    mapper_mode='wide': Shift+点击首尾列划定负荷范围
    mapper_mode=None: 纯预览(原行为)
    """
    def __init__(self, parent, df, fp, sheet, mapper_mode=None, auto_mapping=None):
        super().__init__(parent)
        self.df = df
        self.fp = fp
        self.sheet = sheet
        self.mapper_mode = mapper_mode
        self.result = None  # 映射结果: {date_col, time_col, load_cols[], asset_col, format_type}
        
        title = f"📋 数据预览 - {os.path.basename(fp)} [{sheet}]"
        if mapper_mode:
            title = f"{'📊 可视化选列(长表)' if mapper_mode == 'long' else '📊 划定负荷范围(宽表)'} - {os.path.basename(fp)} [{sheet}]"
        self.setWindowTitle(title)
        self.setMinimumSize(600, 400)
        self._init_ui(auto_mapping)
    
    def _init_ui(self, auto_mapping=None):
        bsize = int(base_size())
        layout = QVBoxLayout(self)
        
        # v3.0: 类型统计条
        self._stats_bar = QLabel()
        self._stats_bar.setStyleSheet(
            "font-size:13px;padding:6px 10px;background:#F0F4F8;border-radius:8px;font-weight:bold;"
        )
        self._stats_bar.setVisible(False)
        layout.addWidget(self._stats_bar)
        
        # 顶部提示
        hint_row = QHBoxLayout()
        if self.mapper_mode == 'long':
            hint = QLabel("💡 点击列头循环切换类型 | 右键列头直接指定 | 快捷键 D/T/L/A/I | 日期(蓝)和负荷(绿)为必选")
        elif self.mapper_mode == 'wide':
            hint = QLabel("💡 Shift+点击首列和末列划定负荷范围 | 左键点击单列切换类型")
        else:
            hint = QLabel("")
        hint.setStyleSheet("color:#5D6D7E;font-size:11px;padding:4px 8px;")
        if self.mapper_mode:
            hint_row.addWidget(hint)
            hint_row.addStretch()
            # v3.0: 折叠忽略列按钮
            self._toggle_ignored_btn = QPushButton("📋 折叠忽略列")
            self._toggle_ignored_btn.setCheckable(True)
            self._toggle_ignored_btn.setMinimumHeight(bsize)
            self._toggle_ignored_btn.setToolTip("隐藏所有标记为忽略的列,便于聚焦关键数据")
            self._toggle_ignored_btn.toggled.connect(self._toggle_ignored_columns)
            self._toggle_ignored_btn.setVisible(self.mapper_mode == 'long')
            hint_row.addWidget(self._toggle_ignored_btn)
            layout.addLayout(hint_row)
        elif self.mapper_mode:
            layout.addWidget(hint)
        
        # 表格
        self.table = QTableWidget()
        self.table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.table.setAlternatingRowColors(True)
        if self.mapper_mode:
            # 替换默认header为ColumnTypeHeader
            self.col_header = ColumnTypeHeader(Qt.Horizontal, self.table)
            self.col_header.set_wide_mode(self.mapper_mode == 'wide')
            self.col_header._stats_callback = self._update_stats_bar  # v3.0: 类型变更→更新统计条
            self.table.setHorizontalHeader(self.col_header)
        else:
            self.col_header = None
        layout.addWidget(self.table)
        
        # 信息栏
        self.info = QLabel()
        layout.addWidget(self.info)
        
        # 底部按钮(仅映射模式)
        if self.mapper_mode:
            btn_layout = QHBoxLayout()
            btn_layout.addStretch()
            cancel_btn = QPushButton("取消")
            cancel_btn.setMinimumHeight(bsize)
            cancel_btn.clicked.connect(self.reject)
            ok_btn = QPushButton("✅ 确认选择")
            ok_btn.setObjectName("primary")
            ok_btn.setMinimumHeight(bsize)
            ok_btn.clicked.connect(self._accept_mapping)
            btn_layout.addWidget(cancel_btn)
            btn_layout.addWidget(ok_btn)
            layout.addLayout(btn_layout)
        
        self._pop('all', auto_mapping)
    
    def _pop(self, mode, auto_mapping=None):
        if self.df is None or self.df.empty:
            self.info.setText("无可用数据"); return
        df = self.df
        if mode == 'datetime':
            d = [c for c in df.columns if any(k in str(c).lower() for k in ['date','日期','时间','time'])]
            load_cols = [c for c in df.columns if c not in d]
            cols = d[:3] + load_cols[:10]
        elif mode == 'timeonly':
            cols = [c for c in df.columns if any(k in str(c).lower() for k in ['time','时间','t','p'])]
            if not cols: cols = list(df.columns)[:12]
        else:
            col_limit = 50 if self.mapper_mode == 'wide' else 30
            cols = list(df.columns)[:col_limit]  # v2.28: 宽表扩展到50列
        self._current_cols = cols  # v2.28fix: 存储当前列名供_accept_mapping使用
        dd = df[cols].head(100)
        self.table.setRowCount(len(dd)); self.table.setColumnCount(len(cols))
        self.table.setHorizontalHeaderLabels([str(c)[:20] for c in cols])
        # v2.28fix: setHorizontalHeaderLabels会替换header,需要重新设置自定义header
        if self.col_header:
            self.table.setHorizontalHeader(self.col_header)
            # 重新连接model更新信号,确保paintSection能读取到headerData
            self.col_header.setModel(self.table.model())
        for r in range(len(dd)):
            for ci, cn in enumerate(cols):
                raw_val = dd[cn].iloc[r]
                # v3.0: 按类型格式化单元格
                col_type = self.col_header.get_column_type(ci) if self.col_header else 'IGNORE'
                formatted = self._format_cell(raw_val, col_type)
                item = QTableWidgetItem(str(formatted)[:40])
                # 数字列右对齐, 其他左对齐
                if col_type == 'LOAD' and isinstance(raw_val, (int, float)):
                    item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                self.table.setItem(r, ci, item)
        self.table.resizeColumnsToContents()
        # v2.28fix: 强制恢复列头高度(被resizeColumnsToContents覆盖)
        if self.col_header:
            self.col_header.setMinimumHeight(56)
            self.col_header.setDefaultSectionSize(56)
        self.info.setText(f"共{len(df)}行x{len(df.columns)}列 | 显示{len(cols)}列x{len(dd)}行")
        w = min(self.table.horizontalHeader().length() + 40, 1400)
        h = min(self.table.verticalHeader().length() + 120, 800)
        self.resize(max(w, 600), max(h, 400))
        # v2.28: 自动推荐列类型
        if self.col_header and auto_mapping:
            self._apply_auto_mapping(cols, auto_mapping)
        elif self.col_header:
            self._auto_detect(cols)
    
    def _auto_detect(self, cols):
        """对当前列运行智能分类,自动标记推荐类型."""
        try:
            smart = _smart_classify_columns(cols, self.df.head(100))
            recommended = set()
            if smart.get('date_col'):
                idx = cols.index(smart['date_col']) if smart['date_col'] in cols else -1
                if idx >= 0:
                    self.col_header.set_column_type(idx, 'DATE')
                    recommended.add(idx)
            if smart.get('time_col'):
                idx = cols.index(smart['time_col']) if smart['time_col'] in cols else -1
                if idx >= 0:
                    self.col_header.set_column_type(idx, 'TIME')
                    recommended.add(idx)
            if smart.get('load_col'):
                lc = smart['load_col']
                if isinstance(lc, str):
                    lc = [lc]
                for c in lc:
                    if c in cols:
                        idx = cols.index(c)
                        self.col_header.set_column_type(idx, 'LOAD')
                        recommended.add(idx)
            if smart.get('asset_col'):
                idx = cols.index(smart['asset_col']) if smart['asset_col'] in cols else -1
                if idx >= 0:
                    self.col_header.set_column_type(idx, 'ASSET')
                    recommended.add(idx)
            self.col_header.set_auto_recommended(recommended)
            self._update_stats_bar()  # v3.0: 自动推荐后刷新统计条
        except Exception as e:
            log.debug(f"_auto_detect 失败: {e}")
    
    @staticmethod
    def _format_cell(raw_val, col_type):
        """v3.0: 按列类型格式化单元格值."""
        if raw_val is None or (isinstance(raw_val, float) and (raw_val != raw_val)):
            return ''
        if col_type == 'DATE' and isinstance(raw_val, str):
            return raw_val[:16]  # 日期时间截断到分钟
        if col_type == 'LOAD' and isinstance(raw_val, (int, float)):
            if abs(raw_val) >= 10000:
                return f'{raw_val:,.0f}'
            elif abs(raw_val) >= 1:
                return f'{raw_val:.1f}'
            else:
                return f'{raw_val:.4f}'
        if isinstance(raw_val, float):
            return f'{raw_val:.2f}' if abs(raw_val) < 1000 else f'{raw_val:,.0f}'
        return str(raw_val)
    
    def _apply_auto_mapping(self, cols, auto_mapping):
        """根据已有映射设置列类型."""
        recommended = set()
        if auto_mapping.get('date_col') and auto_mapping['date_col'] in cols:
            idx = cols.index(auto_mapping['date_col'])
            self.col_header.set_column_type(idx, 'DATE')
            recommended.add(idx)
        if auto_mapping.get('time_col') and auto_mapping['time_col'] in cols:
            idx = cols.index(auto_mapping['time_col'])
            self.col_header.set_column_type(idx, 'TIME')
            recommended.add(idx)
        lc = auto_mapping.get('load_col', [])
        if isinstance(lc, str):
            lc = [lc]
        for c in lc:
            if c in cols:
                idx = cols.index(c)
                self.col_header.set_column_type(idx, 'LOAD')
                recommended.add(idx)
        if auto_mapping.get('asset_col') and auto_mapping['asset_col'] in cols:
            idx = cols.index(auto_mapping['asset_col'])
            self.col_header.set_column_type(idx, 'ASSET')
            recommended.add(idx)
        self.col_header.set_auto_recommended(recommended)
        self._update_stats_bar()  # v3.0
    
    # ═══════════════════════════════════════════════════════════
    # v3.0: 极致可视化选列 — 统计条/快捷键/忽略折叠/格染色
    # ═══════════════════════════════════════════════════════════
    
    def _update_stats_bar(self):
        """更新类型统计条: 📅1 🕐1 ⚡5 🏷0 —"""
        if not self.col_header:
            return
        counts = self.col_header.get_type_counts()
        icons = {'DATE': '📅', 'TIME': '🕐', 'DATETIME': '📅🕐', 'LOAD': '⚡', 'ASSET': '🏷', 'IGNORE': '—'}
        parts = []
        for typ in self.col_header._TYPE_ORDER:
            c = counts.get(typ, 0)
            if c > 0 or typ in ('DATE', 'LOAD'):  # 必选类型始终显示
                parts.append(f"{icons.get(typ,'')}{typ}={c}")
        missing = []
        if counts.get('DATE', 0) == 0 and not counts.get('DATETIME', 0):
            missing.append('日期列')
        if counts.get('LOAD', 0) == 0:
            missing.append('负荷列')
        if missing:
            parts.append(f"⚠️ 缺少: {'、'.join(missing)}")
            self._stats_bar.setStyleSheet(
                "font-size:13px;padding:6px 10px;background:#FFF3E0;border-radius:8px;font-weight:bold;color:#E65100;"
            )
        else:
            self._stats_bar.setStyleSheet(
                "font-size:13px;padding:6px 10px;background:#E8F5E9;border-radius:8px;font-weight:bold;color:#2E7D32;"
            )
        self._stats_bar.setText("  ".join(parts))
        self._stats_bar.setVisible(True)
    
    def _toggle_ignored_columns(self, checked):
        """折叠/展开所有IGONRE列."""
        if not self.col_header:
            return
        for ci in range(self.table.columnCount()):
            if self.col_header.get_column_type(ci) == 'IGNORE':
                self.table.setColumnHidden(ci, checked)
        self._toggle_ignored_btn.setText("📋 展开忽略列" if checked else "📋 折叠忽略列")
    
    def keyPressEvent(self, event):
        """v3.0: 键盘快捷键——悬停在列头上按 D/T/L/A/I 设置列类型."""
        if not self.col_header or not self.mapper_mode:
            return super().keyPressEvent(event)
        key_map = {
            Qt.Key_D: 'DATE', Qt.Key_T: 'TIME', Qt.Key_L: 'LOAD',
            Qt.Key_A: 'ASSET', Qt.Key_I: 'IGNORE',
        }
        typ = key_map.get(event.key())
        if typ and self.col_header._hovered_col >= 0:
            self.col_header.set_column_type(self.col_header._hovered_col, typ)
            return
        super().keyPressEvent(event)
    
    def _accept_mapping(self):
        """构造映射结果."""
        cols = getattr(self, '_current_cols', list(self.df.columns)[:self.table.columnCount()])
        date_idx = self.col_header.get_date_col()
        time_idx = self.col_header.get_time_col()
        load_indices = self.col_header.get_load_cols()
        asset_idx = self.col_header.get_asset_col()
        # v2.28fix: 检查DATETIME类型(日期时间同列)
        dt_idx = None
        for idx, typ in self.col_header._col_types.items():
            if typ == 'DATETIME':
                dt_idx = idx; break
        
        if date_idx is None and dt_idx is None:
            QMessageBox.warning(self, "提示", "请至少选择一个日期列(蓝色)或日期时间列(青色)")
            return
        if not load_indices:
            QMessageBox.warning(self, "提示", "请至少选择一个负荷列(绿色)")
            return
        # DATETIME同时充当date和time
        if dt_idx is not None:
            date_idx = dt_idx
            time_idx = dt_idx
        
        # v2.28fix: 列名反查全量列索引,供_apply_visual_mapping精准定位
        full_cols = list(self.df.columns)
        def _full_index(name):
            if name is None:
                return None
            try:
                return full_cols.index(name)
            except ValueError:
                clean = name.strip().strip('"').strip("'")
                for i, c in enumerate(full_cols):
                    if str(c).strip() == clean:
                        return i
                return None
        
        self.result = {
            'date_col': cols[date_idx] if date_idx < len(cols) else str(self.df.columns[date_idx]),
            'date_full_idx': _full_index(cols[date_idx]) if date_idx < len(cols) else date_idx,
            'time_col': cols[time_idx] if time_idx is not None and time_idx < len(cols) else None,
            'time_full_idx': _full_index(cols[time_idx]) if time_idx is not None and time_idx < len(cols) else None,
            'load_col': [cols[i] if i < len(cols) else str(self.df.columns[i]) for i in load_indices],
            'load_full_indices': [_full_index(cols[i]) for i in load_indices if i < len(cols)],
            'asset_col': cols[asset_idx] if asset_idx is not None and asset_idx < len(cols) else None,
            'asset_full_idx': _full_index(cols[asset_idx]) if asset_idx is not None and asset_idx < len(cols) else None,
            'format_type': 'wide' if self.mapper_mode == 'wide' else 'long',
        }
        self.accept()


class MappingDialog(AnimatedDialog):
    __slots__ = ('fp', 'sheet', 'sheet_combo', 'cfg', 'cols', 'hrow', 'result',
                 '_sample_df', '_refresh_task', '_pre_auto_state', '_closed',
                 'date_combo', 'time_combo', 'asset_combo', 'load_combo', 'load_list',
                 'fmt_long', 'fmt_wide', 'fmt_accumulated', 'fmt_group_btns', 'transpose_cb',
                 'header_row_spin', 'enc_combo', 'delim_combo', 'save_cb',
                 'cols_label', 'refresh_status', 'refresh_btn', 'confidence_label',
                 'auto_btn', 'undo_auto_btn', 'last_btn', 'skip_btn', 'ok_btn',
                 'all_sheets_cb', 'all_files_cb', 'time_label', 'accumulated_hint_label',
                 'transpose_preview_label',
                 'date_preview', 'time_preview', 'asset_preview', 'load_preview')
    def __init__(self, parent, fp, sheet, cfg=None, hrow=0, multi_sheet=False, enc=None, delimiter=',',
                 batch_multi_file=False, initial_format_type=None, initial_mapping=None):
        super().__init__(parent)
        bsize = int(base_size())
        self.fp = fp
        self.sheet = sheet
        self.cfg = cfg
        self.result = None
        self.hrow = hrow
        self.enc = enc if enc else 'auto'
        self.delimiter = delimiter
        self._refresh_task = None
        self._highlighted_controls = []
        self._batch_multi_file = batch_multi_file
        self._initial_format_type = initial_format_type
        self._initial_mapping = initial_mapping or {}
        self._pre_auto_state = None

        fname = os.path.basename(fp)
        self.setWindowTitle(f"🔧 配置字段映射 - {fname} [{sheet}]")
        self.setMinimumSize(950, 680)

        if self.cfg:
            geom = self.cfg.get_window_geometry("MappingDialog")
            if geom:
                self.restoreGeometry(geom)
            else:
                self.resize(950, 680)
        else:
            self.resize(950, 680)

        try:
            self.cols = get_columns_fast(fp, sheet if sheet != "CSV文件" else None, hrow, self.enc, self.delimiter)
        except Exception as e:
            self._handle_column_read_error(fname, e)
            # v2.21fix: 重试成功则继续初始化UI,只有skip/cancel才退出
            if self.result is not None:
                return

        if not self.cols:
            QMessageBox.warning(self, "警告", "未能识别任何列名.")
            self.result = 'skip'
            self.accept()
            return

        self._sample_df = None
        try:
            pd_lib = _get_pd()
            if os.path.splitext(fp)[1].lower() == '.csv':
                e = self.enc if self.enc != 'auto' else _detect_enc(fp)
                self._sample_df = pd_lib.read_csv(fp, encoding=e, nrows=200, header=hrow)
            else:
                self._sample_df = pd_lib.read_excel(fp, sheet_name=sheet if sheet != "CSV文件" else 0, nrows=200, header=hrow)
            self._sample_df.columns = [str(c) for c in self._sample_df.columns]
            # v3.0fix: 列名去重统一为 _N 格式,与 get_columns_fast 保持一致
            seen = {}
            deduped = []
            for c in self._sample_df.columns:
                if c in seen:
                    seen[c] += 1
                    deduped.append(f"{c}_{seen[c]}")
                else:
                    seen[c] = 0
                    deduped.append(c)
            self._sample_df.columns = deduped
            # v3.0fix: 列名去重统一为 _N 格式,与 get_columns_fast 保持一致
            seen = {}
            deduped = []
            for c in self._sample_df.columns:
                if c in seen:
                    seen[c] += 1
                    deduped.append(f"{c}_{seen[c]}")
                else:
                    seen[c] = 0
                    deduped.append(c)
            self._sample_df.columns = deduped
        except Exception:
            log.exception("读取样本数据失败,智能识别将降级")

        self._init_ui(multi_sheet, bsize)

        self._apply_initial_format()
        smart_rec = _smart_classify_columns(self.cols, self._sample_df)
        if smart_rec and 'date_col' in smart_rec:
            self._apply_smart_rec(smart_rec)
            self.confidence_label.setText("✅ 已自动推荐(智能识别)")
        else:
            rec = cfg.recommend(fp, sheet, self.cols) if cfg else None
            if rec:
                self._apply_rec(rec)
                self.confidence_label.setText("✅ 已自动推荐(历史配置匹配)")
            else:
                # v2.29fix: 提示具体缺失的列类型
                missing = []
                if not smart_rec or 'date_col' not in smart_rec:
                    missing.append('日期列')
                if not smart_rec or 'load_col' not in smart_rec:
                    missing.append('负荷列')
                hint = '；'.join(missing) if missing else '日期列/负荷列'
                self.confidence_label.setText(f'未找到推荐配置,请手动选择（缺少: {hint}）')

    def _handle_column_read_error(self, fname, error):
        QMessageBox.warning(self, "警告", f"无法读取列名: {error}\n\n您可以选择重试、跳过此文件或取消.")
        msg_box = QMessageBox(self)
        msg_box.setWindowTitle("列名读取失败")
        msg_box.setText(f'无法读取文件"{fname}"的列名:\n{error}')
        msg_box.setInformativeText(f"请检查文件是否损坏或编码是否正确.当前标题行设为第{self.hrow+1}行,编码为{self.enc}.")
        retry_btn = msg_box.addButton("重试", QMessageBox.ActionRole)
        skip_btn = msg_box.addButton("跳过此文件", QMessageBox.ActionRole)
        msg_box.addButton("取消全部", QMessageBox.RejectRole)
        msg_box.exec()
        clicked = msg_box.clickedButton()
        if clicked == retry_btn:
            try:
                self.cols = get_columns_fast(self.fp, self.sheet if self.sheet != "CSV文件" else None,
                                            self.hrow, self.enc, self.delimiter)
                return
            except Exception:
                log.exception("重试读取列名失败")
                self.result = 'skip'
                self.accept()
                return
        elif clicked == skip_btn:
            self.result = 'skip'
            self.accept()
            return
        else:
            self.result = 'cancel'
            self.reject()
            return

