# region 分组树控制器(优化:增量更新,避免全量重建)
class _GroupTreeController(QObject):
    selectionChanged = Signal(set)
    itemClicked = Signal(int)
    statusUpdateRequest = Signal(int, str)

    def __init__(self, tree_widget: QTreeWidget, parent=None):
        super().__init__(parent)
        self.tree = tree_widget
        self.summaries = []
        self.selected_indices = set()
        self.no_data_indices = set()
        self._sort_key = "按表号"
        self._block_signals = False
        self._status_map = {}
        self._last_snapshot = None
        self._item_index_map = {}  # 新增:item -> index 映射,支持增量更新

        self.tree.itemClicked.connect(self._on_item_clicked)
        self.tree.itemChanged.connect(self._on_item_changed)
        self.statusUpdateRequest.connect(self._apply_status_update)

    def load(self, summaries, no_data_indices=None):
        self.summaries = summaries
        if no_data_indices is not None:
            self.no_data_indices = no_data_indices
        self._status_map.clear()
        self._rebuild()

    def set_sort_key(self, key):
        if self._sort_key != key:
            self._sort_key = key
            self._rebuild()

    def filter_tree(self, text):
        t = text.strip().lower()
        for i in range(self.tree.topLevelItemCount()):
            asset_item = self.tree.topLevelItem(i)
            asset_visible = False
            for j in range(asset_item.childCount()):
                child = asset_item.child(j)
                match = not t or t in child.text(0).lower() or t in asset_item.text(0).lower()
                child.setHidden(not match)
                if match:
                    asset_visible = True
            asset_item.setHidden(not asset_visible)
            if asset_visible and t:
                self.tree.expandItem(asset_item)

    def set_all_check(self, checked):
        self._last_snapshot = self.selected_indices.copy()
        if checked:
            self.selected_indices = set(range(len(self.summaries))) - self.no_data_indices
        else:
            self.selected_indices.clear()
        # 优化:仅更新勾选状态,不重建树
        self._update_all_check_states()
        QTimer.singleShot(2000, lambda: setattr(self, '_last_snapshot', None))

    def _update_all_check_states(self):
        self._block_signals = True
        self.tree.setUpdatesEnabled(False)  # 批量操作期间禁用绘制
        try:
            for i in range(self.tree.topLevelItemCount()):
                asset_item = self.tree.topLevelItem(i)
                for j in range(asset_item.childCount()):
                    child = asset_item.child(j)
                    idx = child.data(0, Qt.UserRole)
                    if idx is not None and idx >= 0 and idx not in self.no_data_indices:
                        state = Qt.Checked if idx in self.selected_indices else Qt.Unchecked
                        if child.flags() & Qt.ItemIsUserCheckable:
                            child.setCheckState(0, state)
                self._update_parent_check(asset_item)
        finally:
            self.tree.setUpdatesEnabled(True)
            self._block_signals = False

    def undo_check_change(self):
        if self._last_snapshot is not None:
            self.selected_indices = self._last_snapshot.copy()
            self._last_snapshot = None
            self._update_all_check_states()
            return True
        return False

    def select_by_asset_dialog(self, parent_widget):
        assets = sorted(set(s.asset_value for s in self.summaries if s.asset_value))
        if not assets:
            QMessageBox.information(parent_widget, "提示", "没有识别到任何表号")
            return
        dlg = QDialog(parent_widget)
        dlg.setWindowTitle("按表号多选")
        layout = QVBoxLayout(dlg)
        layout.addWidget(QLabel("勾选表号:"))
        checks = {}
        for a in assets:
            cb = QCheckBox(a)
            checks[a] = cb
            layout.addWidget(cb)
        btn_box = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        btn_box.accepted.connect(dlg.accept)
        btn_box.rejected.connect(dlg.reject)
        layout.addWidget(btn_box)
        if dlg.exec() == QDialog.Accepted:
            targets = {a for a, cb in checks.items() if cb.isChecked()}
            for i, s in enumerate(self.summaries):
                if s.asset_value in targets and i not in self.no_data_indices:
                    self.selected_indices.add(i)
            self._update_all_check_states()

    def get_checked_indices(self):
        return self.selected_indices.copy()

    def update_status(self, idx, status):
        self.statusUpdateRequest.emit(idx, status)

    def _apply_status_update(self, idx, status):
        self._status_map[idx] = status
        # 增量更新:直接修改对应项的文本
        for i in range(self.tree.topLevelItemCount()):
            asset_item = self.tree.topLevelItem(i)
            for j in range(asset_item.childCount()):
                child = asset_item.child(j)
                if child.data(0, Qt.UserRole) == idx:
                    child.setText(1, status)
                    return

    def set_current_index(self, idx):
        self._block_signals = True
        for i in range(self.tree.topLevelItemCount()):
            asset_item = self.tree.topLevelItem(i)
            for j in range(asset_item.childCount()):
                child = asset_item.child(j)
                if child.data(0, Qt.UserRole) == idx:
                    self.tree.setCurrentItem(child)
                    self.tree.scrollToItem(child)  # 优化:自动滚动到当前项
                    break
        self._block_signals = False

    def _rebuild(self):
        """仅在数据变化或排序变化时全量重建,一般操作使用增量更新"""
        self._block_signals = True
        self.tree.clear()
        self._item_index_map.clear()
        summaries = list(enumerate(self.summaries))
        if self._sort_key == "按月份":
            summaries.sort(key=lambda x: x[1].month_str)
        else:
            summaries.sort(key=lambda x: x[1].asset_value or '')

        asset_dict = OrderedDict()
        for idx, s in summaries:
            asset = s.asset_value or "未命名"
            asset_dict.setdefault(asset, []).append((idx, s))

        for asset, items in asset_dict.items():
            asset_item = QTreeWidgetItem([asset, ""])
            asset_item.setFlags(asset_item.flags() | Qt.ItemIsUserCheckable)
            asset_item.setData(0, Qt.UserRole, -1)
            self.tree.addTopLevelItem(asset_item)

            for idx, s in items:
                status = self._status_map.get(idx, "等待加载...")
                month_item = QTreeWidgetItem([s.month_str, status])
                if idx in self.no_data_indices:
                    month_item.setFlags(month_item.flags() & ~Qt.ItemIsUserCheckable)
                    month_item.setCheckState(0, Qt.Unchecked)
                    month_item.setForeground(0, QColor('gray'))
                    month_item.setToolTip(0, "该分组无有效数据,无法勾选")
                else:
                    month_item.setFlags(month_item.flags() | Qt.ItemIsUserCheckable)
                    checked = Qt.Checked if idx in self.selected_indices else Qt.Unchecked
                    month_item.setCheckState(0, checked)
                month_item.setData(0, Qt.UserRole, idx)
                asset_item.addChild(month_item)
                self._item_index_map[id(month_item)] = idx

            self._update_parent_check(asset_item)
            self.tree.expandItem(asset_item)

        self._block_signals = False

    def _update_parent_check(self, parent_item):
        all_checked = all(parent_item.child(i).checkState(0) == Qt.Checked for i in range(parent_item.childCount()) if parent_item.child(i).flags() & Qt.ItemIsUserCheckable)
        any_checked = any(parent_item.child(i).checkState(0) == Qt.Checked for i in range(parent_item.childCount()) if parent_item.child(i).flags() & Qt.ItemIsUserCheckable)
        if all_checked:
            parent_item.setCheckState(0, Qt.Checked)
        elif any_checked:
            parent_item.setCheckState(0, Qt.PartiallyChecked)
        else:
            parent_item.setCheckState(0, Qt.Unchecked)

    def _on_item_clicked(self, item, col):
        idx = item.data(0, Qt.UserRole)
        if idx is not None and idx >= 0:
            self.itemClicked.emit(idx)

    def _on_item_changed(self, item, col):
        if self._block_signals:
            return
        idx = item.data(0, Qt.UserRole)
        if idx == -1:
            state = item.checkState(0)
            self._block_signals = True
            for i in range(item.childCount()):
                child = item.child(i)
                if not child.flags() & Qt.ItemIsUserCheckable:
                    continue
                child.setCheckState(0, state)
                cidx = child.data(0, Qt.UserRole)
                if cidx >= 0 and cidx not in self.no_data_indices:
                    if state == Qt.Checked:
                        self.selected_indices.add(cidx)
                    else:
                        self.selected_indices.discard(cidx)
            self._block_signals = False
            self._update_parent_check(item)
            self.selectionChanged.emit(self.selected_indices.copy())
        elif idx >= 0 and idx not in self.no_data_indices:
            if item.checkState(0) == Qt.Checked:
                self.selected_indices.add(idx)
            else:
                self.selected_indices.discard(idx)
            parent = item.parent()
            if parent:
                self._block_signals = True
                self._update_parent_check(parent)
                self._block_signals = False
            self.selectionChanged.emit(self.selected_indices.copy())
# endregion

# region 分组设置模型
class _PerGroupSettings(QObject):
    settingsChanged = Signal()

    def __init__(self, summaries, global_multiplier, billing_dict=None, parent=None):
        super().__init__(parent)
        self.summaries = summaries
        self.global_multiplier = global_multiplier
        self._custom_mult = {}
        self._custom_billing = {}
        self._global_billing = billing_dict or {}
        self._history_mult = {}
        self._history_billing = {}

    def effective_multiplier(self, idx):
        return self._custom_mult.get(idx, self.global_multiplier)

    def effective_billing(self, idx):
        if idx in self._custom_billing:
            return self._custom_billing[idx]
        s = self.summaries[idx]
        return self._global_billing.get(s.asset_value)

    def set_custom_multiplier(self, idx, value):
        self._history_mult[idx] = self._custom_mult.get(idx, self.global_multiplier)
        self._custom_mult[idx] = value
        self.settingsChanged.emit()

    def set_custom_billing(self, idx, billing):
        self._history_billing[idx] = self._custom_billing.get(idx) or self._global_billing.get(self.summaries[idx].asset_value)
        if billing is None:
            self._custom_billing.pop(idx, None)
        else:
            self._custom_billing[idx] = billing
        self.settingsChanged.emit()

    def clear_custom_multiplier(self, idx):
        self._history_mult[idx] = self._custom_mult.get(idx, self.global_multiplier)
        self._custom_mult.pop(idx, None)
        self.settingsChanged.emit()

    def clear_custom_billing(self, idx):
        self._history_billing[idx] = self._custom_billing.get(idx) or self._global_billing.get(self.summaries[idx].asset_value)
        self._custom_billing.pop(idx, None)
        self.settingsChanged.emit()

    def has_custom_mult(self, idx):
        return idx in self._custom_mult

    def has_custom_bill(self, idx):
        return idx in self._custom_billing

    def set_global_multiplier(self, value):
        self.global_multiplier = value
        self.settingsChanged.emit()

    def set_global_billing(self, asset, billing):
        if billing is None:
            self._global_billing.pop(asset, None)
        else:
            self._global_billing[asset] = billing
        self.settingsChanged.emit()

    def get_custom_multipliers(self):
        return self._custom_mult.copy()

    def get_custom_billings(self):
        return self._custom_billing.copy()

    def undo_last_mult(self, idx):
        if idx in self._history_mult:
            old_val = self._history_mult.pop(idx)
            if old_val == self.global_multiplier:
                self._custom_mult.pop(idx, None)
            else:
                self._custom_mult[idx] = old_val
            self.settingsChanged.emit()
            return True
        return False

    def undo_last_bill(self, idx):
        if idx in self._history_billing:
            old_bill = self._history_billing.pop(idx)
            if old_bill is None:
                self._custom_billing.pop(idx, None)
            else:
                self._custom_billing[idx] = old_bill
            self.settingsChanged.emit()
            return True
        return False
# endregion

# region 预览渲染调度器(优化:max_tasks_per_child=50)

# ═══════════════════════════════════════════════════════════
# v2.28: Windows 强制性能增强引擎
# ═══════════════════════════════════════════════════════════
def _bind_performance_cores(current_process, kernel32):
    """将进程绑定到性能核心(P-cores),排除能效核心(E-cores).

    策略(按优先级尝试):
    1. SYSTEM_CPU_SET_INFORMATION (Win11) — 精确识别 EfficiencyClass
    2. GetActiveProcessorCount 推算 — P-cores 通常在前半段
    3. 所有核心 — 不设置亲和性(回退)

    返回: 实际绑定的核心数,0 表示未绑定."""
    import struct

    # ── 策略1: Win10 20348+ / Win11 SYSTEM_CPU_SET_INFORMATION ──
    try:
        SystemCpuSetInformation = 0
        # 第一次调用获取所需buffer大小
        buf_size = ctypes.c_uint32(0)
        kernel32.GetSystemCpuSetInformation(None, 0, ctypes.byref(buf_size), 0)
        if buf_size.value > 0:
            buf = (ctypes.c_byte * buf_size.value)()
            if kernel32.GetSystemCpuSetInformation(buf, buf_size.value, ctypes.byref(buf_size), 0):
                # 解析 CPU_SET 结构体,筛选 EfficiencyClass=1 的P-core
                pcore_mask = 0
                offset = 0
                while offset + 8 <= buf_size.value:
                    # SYSTEM_CPU_SET_INFORMATION 头部: Size(DWORD), Type(DWORD)
                    info_size = struct.unpack_from('I', buf, offset)[0]
                    info_type = struct.unpack_from('I', buf, offset + 4)[0]
                    if info_type == 0 and info_size >= 48:
                        # CpuSet 结构: Id, Group, LogicalIndex, CoreIndex, LastLevelCacheIndex,
                        # NumaNodeIndex, EfficiencyClass, 2xAllFlags, Parked, Allocated, ...
                        eff_class = struct.unpack_from('B', buf, offset + 40)[0]
                        logical_idx = struct.unpack_from('I', buf, offset + 12)[0]
                        group = struct.unpack_from('H', buf, offset + 8)[0]
                        if eff_class == 1 and group == 0 and logical_idx < 64:
                            pcore_mask |= (1 << logical_idx)
                    if info_size == 0:
                        break
                    offset += info_size
                if pcore_mask > 0:
                    kernel32.SetProcessAffinityMask(current_process, pcore_mask)
                    return bin(pcore_mask).count('1')
    except Exception:
        pass

    # ── 策略2: GetActiveProcessorCount 推算 ──
    # Intel混合架构: P-cores通常在前半段,E-cores在后半段
    try:
        ALL_PROCESSOR_GROUPS = 0xFFFF
        total_logical = kernel32.GetActiveProcessorCount(ALL_PROCESSOR_GROUPS)
        if total_logical >= 8:
            # 假设前 2/3 是 P-cores (典型: 6P+8E=14逻辑=20线程)
            p_count = min(total_logical, int(total_logical * 0.6))
            p_count = max(p_count, 4)  # 至少4个
            mask = (1 << p_count) - 1
            if mask > 0 and mask != (1 << total_logical) - 1:
                kernel32.SetProcessAffinityMask(current_process, mask)
                return p_count
    except Exception:
        pass

    return 0
def _win_boost_process_performance():
    """Windows 强制性能增强: 提升进程优先级 + 禁用功率节流.
    在所有渲染子进程和主进程中调用,确保 CPU/IO 资源不被 Windows 节流.
    非 Windows 系统静默跳过."""
    if sys.platform != 'win32':
        return
    try:
        import ctypes
        kernel32 = ctypes.windll.kernel32
        current_process = kernel32.GetCurrentProcess()

        # ── 1. 进程优先级提升至 HIGH ──
        HIGH_PRIORITY_CLASS = 0x00000080
        if not kernel32.SetPriorityClass(current_process, HIGH_PRIORITY_CLASS):
            # 回退: 尝试 ABOVE_NORMAL (不需要管理员权限)
            ABOVE_NORMAL_PRIORITY_CLASS = 0x00008000
            kernel32.SetPriorityClass(current_process, ABOVE_NORMAL_PRIORITY_CLASS)

        # ── 2. 禁用 Windows 功率节流 (Win10 1709+) ──
        # 功率节流会使后台进程的CPU频率被限制,渲染性能下降可达40-60%
        try:
            class _PROCESS_POWER_THROTTLING_STATE(ctypes.Structure):
                _fields_ = [
                    ("Version", ctypes.c_uint32),
                    ("ControlMask", ctypes.c_uint32),
                    ("StateMask", ctypes.c_uint32),
                ]
            _PROCESS_POWER_THROTTLING_CURRENT_VERSION = 1
            _PROCESS_POWER_THROTTLING_EXECUTION_SPEED = 0x1
            _ProcessPowerThrottling = 4  # ProcessInformationClass 枚举值

            throttling_state = _PROCESS_POWER_THROTTLING_STATE()
            throttling_state.Version = _PROCESS_POWER_THROTTLING_CURRENT_VERSION
            throttling_state.ControlMask = _PROCESS_POWER_THROTTLING_EXECUTION_SPEED
            throttling_state.StateMask = _PROCESS_POWER_THROTTLING_EXECUTION_SPEED

            kernel32.SetProcessInformation(
                current_process,
                _ProcessPowerThrottling,
                ctypes.byref(throttling_state),
                ctypes.sizeof(throttling_state)
            )
        except Exception:
            pass  # 旧版 Windows 或权限不足,跳过功率节流设置

        # ── 2.5. P-core 亲和性绑定 (Intel 12代+ 混合架构) ──
        pcore_count = 0
        try:
            pcore_count = _bind_performance_cores(current_process, kernel32)
        except Exception:
            pass

        # ── 3. 进程优先级动态降级已通过HIGH_PRIORITY_CLASS阻止

        # ── 4. 工作集锁定: 防止渲染缓冲区被换出到虚拟内存 ──
        try:
            class _MEMORYSTATUSEX(ctypes.Structure):
                _fields_ = [("dwLength", ctypes.c_uint32), ("dwMemoryLoad", ctypes.c_uint32),
                           ("ullTotalPhys", ctypes.c_uint64), ("ullAvailPhys", ctypes.c_uint64)]
            ms = _MEMORYSTATUSEX()
            ms.dwLength = ctypes.sizeof(ms)
            if hasattr(kernel32, 'GlobalMemoryStatusEx'):
                kernel32.GlobalMemoryStatusEx(ctypes.byref(ms))
                # 锁定当前工作集,确保不会被trim到虚拟内存
                min_ws = ctypes.c_size_t(64 * 1024 * 1024)  # 64MB 最小工作集
                max_ws = ctypes.c_size_t(256 * 1024 * 1024)  # 256MB 最大工作集
                kernel32.SetProcessWorkingSetSize(current_process, min_ws, max_ws)
                log.debug("工作集已锁定: 64-256MB")
        except Exception:
            pass

        # ── 5. 当前线程优先级提升至 TIME_CRITICAL ──
        try:
            THREAD_PRIORITY_TIME_CRITICAL = 15
            thread_handle = kernel32.GetCurrentThread()
            kernel32.SetThreadPriority(thread_handle, THREAD_PRIORITY_TIME_CRITICAL)
        except Exception:
            pass

        pcore_msg = f" + P-core亲和性({pcore_count}核)" if pcore_count > 0 else ""
        log.debug(f"Windows 性能增强已启用: HIGH_PRIORITY_CLASS + 功率节流已禁用{pcore_msg}")
    except Exception as _e:
        log.debug(f"Windows 性能增强失败(可能权限不足): {_e}")


# ═══════════════════════════════════════════════════════════
# v2.28: 独立显卡自动检测与优先调度引擎
# ═══════════════════════════════════════════════════════════
_DISCRETE_GPU_DETECTED = None
_DISCRETE_GPU_INFO = None
_DISCRETE_GPU_LOCK = threading.Lock()

# 独显品牌关键词(用于从WMI/WMIC结果中识别)
_DISCRETE_GPU_KEYWORDS = [
    'NVIDIA', 'GeForce', 'Quadro', 'RTX', 'GTX', 'Tesla', 'TITAN',
    'Radeon RX', 'Radeon Pro', 'Radeon WX', 'Radeon VII',
    'Arc A', 'Arc Pro',
]
# 集成显卡关键词(排除用)
_INTEGRATED_GPU_KEYWORDS = [
    'Microsoft Basic', 'Intel(R) HD', 'Intel(R) UHD', 'Intel(R) Iris',
]

def _detect_discrete_gpu():
    """检测系统是否拥有独立显卡.
    返回: (has_discrete: bool, gpu_names: list[str])
    检测链: WMI(WMIC) → DXGI(ctypes) → 环境变量回退"""
    global _DISCRETE_GPU_DETECTED, _DISCRETE_GPU_INFO
    with _DISCRETE_GPU_LOCK:
        if _DISCRETE_GPU_DETECTED is not None:
            return _DISCRETE_GPU_DETECTED, _DISCRETE_GPU_INFO

        gpu_names = []
        has_discrete = False

        # ── 方法1: WMIC 查询显卡列表(最可靠) ──
        try:
            import subprocess as _sp
            result = _sp.run(
                ['wmic', 'path', 'win32_VideoController', 'get', 'name', '/format:csv'],
                capture_output=True, text=True, timeout=5,
                creationflags=_sp.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
            )
            if result.returncode == 0 and result.stdout:
                for line in result.stdout.strip().split('\n'):
                    line = line.strip()
                    if not line or line.startswith('Node,') or line.startswith('Name'):
                        continue
                    # 取逗号后的GPU名称(WMIC CSV格式: Node,Name)
                    parts = line.split(',', 1)
                    name = parts[1].strip() if len(parts) > 1 else line
                    if name and name not in gpu_names:
                        gpu_names.append(name)
        except Exception:
            pass

        # ── 方法2: WMIC 备选查询(兼容旧版Windows) ──
        if not gpu_names:
            try:
                import subprocess as _sp
                result = _sp.run(
                    ['wmic', 'path', 'win32_VideoController', 'get', 'name'],
                    capture_output=True, text=True, timeout=5,
                    creationflags=_sp.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
                )
                if result.returncode == 0 and result.stdout:
                    for line in result.stdout.strip().split('\n'):
                        name = line.strip()
                        if name and name != 'Name' and name not in gpu_names:
                            gpu_names.append(name)
            except Exception:
                pass

        # ── 判断: WMIC 查询足以覆盖所有现代 Windows ──        # ── 判断是否有独显 ──
        discrete_candidates = []
        integrated_candidates = []
        for name in gpu_names:
            is_integrated = any(kw.lower() in name.lower() for kw in _INTEGRATED_GPU_KEYWORDS)
            if is_integrated:
                integrated_candidates.append(name)
                continue
            is_discrete = any(kw.lower() in name.lower() for kw in _DISCRETE_GPU_KEYWORDS)
            if is_discrete:
                discrete_candidates.append(name)

        # 汇总判断
        if discrete_candidates:
            has_discrete = True
            _DISCRETE_GPU_INFO = discrete_candidates
        elif len(gpu_names) >= 2 and not all(
            any(kw.lower() in n.lower() for kw in _INTEGRATED_GPU_KEYWORDS)
            for n in gpu_names
        ):
            # 多显卡且不全是集显 → 推断有独显
            has_discrete = True
            _DISCRETE_GPU_INFO = [n for n in gpu_names if not any(
                kw.lower() in n.lower() for kw in _INTEGRATED_GPU_KEYWORDS
            )]
        else:
            _DISCRETE_GPU_INFO = gpu_names

        _DISCRETE_GPU_DETECTED = has_discrete
        return has_discrete, _DISCRETE_GPU_INFO


def _enable_discrete_gpu_rendering():
    """如果检测到独立显卡,强制程序优先使用独显进行渲染.
    策略:
      1. NVIDIA Optimus: 设置 SHIM_MCCOMPAT 环境变量
      2. AMD Switchable Graphics: 无标准环境变量,依赖驱动注册
      3. Qt QSurfaceFormat: 启用 OpenGL 硬件加速,设置最佳适配器
      4. Windows Graphics Settings: 通过注册表注册为高性能GPU应用
    返回: (enabled: bool, gpu_info: str)"""
    has_discrete, gpu_names = _detect_discrete_gpu()
    if not has_discrete:
        info = ', '.join(gpu_names) if gpu_names else '未检测到显卡'
        log.info(f"独显检测: 未发现独立显卡 ({info}),使用默认渲染")
        return False, info

    discrete_names = gpu_names if isinstance(gpu_names, list) else [gpu_names]
    gpu_str = ' | '.join(discrete_names)
    actions = []

    # ── 策略1: NVIDIA Optimus 高性能GPU请求 ──
    # SHIM_MCCOMPAT 值 0x800000000 告知NVIDIA驱动此为高性能应用
    has_nvidia = any('nvidia' in n.lower() or 'geforce' in n.lower() or 'quadro' in n.lower() or 'rtx' in n.lower() for n in discrete_names)
    if has_nvidia:
        os.environ.setdefault('SHIM_MCCOMPAT', '0x800000000')
        actions.append('NVIDIA Optimus 已激活')

    # ── 策略2: 通用Windows高性能GPU请求(通过注册表) ──
    # 在 HKCU\Software\Microsoft\DirectX\UserGpuPreferences 注册应用偏好
    # 格式: "exe_path"="GpuPreference=2;" (2=高性能)
    try:
        import winreg
        exe_path = sys.executable
        python_dir = os.path.dirname(exe_path)
        pythonw_path = os.path.join(python_dir, 'pythonw.exe')
        candidates = [exe_path, pythonw_path]
        for candidate in candidates:
            if os.path.isfile(candidate):
                try:
                    key = winreg.OpenKey(
                        winreg.HKEY_CURRENT_USER,
                        r'Software\Microsoft\DirectX\UserGpuPreferences',
                        0, winreg.KEY_SET_VALUE
                    )
                    winreg.SetValueEx(key, candidate, 0, winreg.REG_SZ, 'GpuPreference=2;')
                    winreg.CloseKey(key)
                    actions.append('DirectX 高性能GPU已注册')
                    break
                except Exception:
                    pass
    except Exception:
        pass

    # ── 策略3: NVIDIA 线程优化 + 高性能电源模式 ──
    if has_nvidia:
        # GL线程优化: 让NVIDIA驱动使用多线程编译着色器
        os.environ.setdefault('__GL_THREADED_OPTIMIZATIONS', '1')
        # 显卡最大性能: 阻止GPU进入低功耗状态
        try:
            import winreg
            # 定位NVIDIA适配器GUID
            guid_pattern = r'{4d36e968-e325-11ce-bfc1-08002be10318}'
            class_key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                f'SYSTEM\\CurrentControlSet\\Control\\Class\\{guid_pattern}',
                0, winreg.KEY_READ)
            for i in range(20):
                try:
                    subkey_name = winreg.EnumKey(class_key, i)
                    subkey = winreg.OpenKey(class_key, subkey_name, 0, winreg.KEY_READ | winreg.KEY_SET_VALUE)
                    try:
                        provider = winreg.QueryValueEx(subkey, 'ProviderName')[0]
                        if 'NVIDIA' in provider.upper():
                            # PerfLevelSrc=0x3322(手动), PowerMizerEnable=1(高性能)
                            with suppress(Exception):
                                winreg.SetValueEx(subkey, 'PerfLevelSrc', 0, winreg.REG_DWORD, 0x3322)
                                winreg.SetValueEx(subkey, 'PowerMizerEnable', 0, winreg.REG_DWORD, 0)
                                winreg.SetValueEx(subkey, 'PowerMizerLevel', 0, winreg.REG_DWORD, 1)
                                winreg.SetValueEx(subkey, 'PowerMizerLevelAC', 0, winreg.REG_DWORD, 1)
                            actions.append('NVIDIA 最大性能模式已激活')
                            break
                    except Exception:
                        pass
                    finally:
                        winreg.CloseKey(subkey)
                except Exception:
                    break
            winreg.CloseKey(class_key)
        except Exception:
            pass

    # ── 策略4: AMD 驱动性能优先级 ──
    has_amd = any('radeon' in n.lower() or 'amd' in n.lower() for n in discrete_names)
    if has_amd:
        # 设置AMD显卡优先级: Main3D=1 (强制高性能)
        os.environ.setdefault('AMD_3D_API', 'DIRECTX')
        try:
            import winreg
            for candidate in candidates:
                if os.path.isfile(candidate):
                    try:
                        key = winreg.OpenKey(
                            winreg.HKEY_CURRENT_USER,
                            r'Software\\AMD\\DXX',
                            0, winreg.KEY_SET_VALUE
                        )
                        winreg.SetValueEx(key, candidate, 0, winreg.REG_DWORD, 1)
                        winreg.CloseKey(key)
                        actions.append('AMD 高性能模式已激活')
                        break
                    except Exception:
                        pass
        except Exception:
            pass

    # ── 策略5: Qt OpenGL 后端强化 ──
    # 强制 ANGLE D3D11 后端 — 绕过 Intel 集显 OpenGL 驱动的性能坑
    os.environ.setdefault('QT_ANGLE_PLATFORM', 'd3d11')
    # 使用独立显卡适配器(索引0通常是集显,独显需要遍历)
    dgpu_enabled = has_discrete  # v3.2fix: 独显检测到即启用
    if has_discrete and dgpu_enabled:
        os.environ['QT_D3D_ADAPTER_INDEX'] = '0'  # ANGLE会优先使用高性能适配器
    actions.append('Qt D3D11 ANGLE 硬件加速已启用')

    log.info(f"独显检测: 发现独立显卡 → {gpu_str} | {', '.join(actions)}")
    return True, gpu_str


def _init_render_worker():
    """进程池初始化器:Windows性能增强 + numpy线程控制 + 设置非交互式后端."""
    _win_boost_process_performance()  # v2.28: 每个渲染子进程都提升性能
    # v2.28: numpy线程数控制——多进程模式下每个子进程只开1个数学线程
    # 否则 4子进程×8核MKL=32线程超订 → CPU颠簸 → 实际性能倒退30-50%
    for env_key in ('OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'OPENBLAS_NUM_THREADS', 'NUMEXPR_NUM_THREADS', 'VECLIB_MAXIMUM_THREADS'):
        os.environ[env_key] = '1'
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as _plt
    _plt.rcParams['font.sans-serif'] = ['Microsoft YaHei', 'SimHei', 'Noto Sans CJK SC', 'DejaVu Sans']
    _plt.rcParams['axes.unicode_minus'] = False
    import builtins
    builtins._plt = _plt

def _process_render_in_subprocess(idx, load_array, time_labels, date_labels, title, opts_dict, billing_dict, periods_list, precomputed_day_types):
    """子进程渲染函数,含错误恢复和资源复用. v2.28: 直接接受numpy数组(跳过tolist往返)."""
    try:
        import builtins
        import gc as _gc
        mplt = getattr(builtins, '_plt', None)
        if mplt is None:
            import matplotlib
            matplotlib.use('Agg')
            import matplotlib.pyplot as mplt
            mplt.rcParams['font.sans-serif'] = ['Microsoft YaHei', 'SimHei', 'Noto Sans CJK SC', 'DejaVu Sans']
            mplt.rcParams['axes.unicode_minus'] = False
            builtins._plt = mplt
        # Figure 复用池
        fig = getattr(builtins, '_render_fig', None)
        if fig is None:
            fig, ax = mplt.subplots(figsize=RENDER_FIGSIZE, dpi=RENDER_DPI)
            builtins._render_fig = fig
            builtins._render_ax = ax
        else:
            ax = builtins._render_ax
            ax.clear()
            # v2.24: 重置可能被前次渲染污染的 rcParams(颜色/线型/图例等)
            mplt.rcdefaults()
            mplt.rcParams['font.sans-serif'] = ['Microsoft YaHei', 'SimHei', 'Noto Sans CJK SC', 'DejaVu Sans']
            mplt.rcParams['axes.unicode_minus'] = False
        with mplt.rc_context():
            # v2.28: 直接使用numpy数组(已通过pickle高效传递),无需tolist→np.array往返
            arr = np.asarray(load_array)
            if arr.ndim != 2 or arr.size == 0:
                return (idx, None, "数据形状异常")
            if opts_dict.get('dark_theme', False):
                fig.patch.set_facecolor('#1e1e1e')
                ax.set_facecolor('#2e2e2e')
            else:
                fig.patch.set_facecolor('white')
                ax.set_facecolor('white')
            billing = billing_dict if billing_dict and billing_dict.get('value') else None
            try:
                _draw_curves_core(ax, date_labels, arr, time_labels, title, opts_dict, billing, periods_list,
                                  precomputed_day_types=precomputed_day_types)
            except ValueError as e:
                raise ValueError(f"绘图数据形状异常: arr.shape={arr.shape}, "
                               f"n_dates={arr.shape[0] if arr.ndim==2 else '?'}, "
                               f"n_times={arr.shape[1] if arr.ndim==2 else '?'}, "
                               f"{e}") from e
            # v2.28: 图表占70%宽度(左5%→右75%),图例占25%
            fig.subplots_adjust(left=0.05, right=0.75, top=0.93, bottom=0.08)
            buf = io.BytesIO()
            fig.savefig(buf, format='png', dpi=RENDER_DPI)
            buf.seek(0)
            data = buf.read()
            _gc.collect()  # 子进程主动 GC
            return (idx, data)
    except MemoryError:
        import gc as _gc2
        _gc2.collect()
        return (idx, None, "内存不足,建议减少并行进程数")
    except Exception as e:
        import traceback as _tb2
        _tb2.print_exc(file=sys.stderr)
        return (idx, None, f"{e}\n{_tb2.format_exc()[-500:]}")

class _PreviewRenderScheduler(QObject):
    renderReady = Signal(int, QPixmap)
    renderError = Signal(int, str)
    cacheProgress = Signal(str)

    def __init__(self, provider, summaries, settings_model, strategy_getter, title_tpl_getter, parent=None):
        super().__init__(parent)
        self.provider = provider
        self.summaries = summaries
        self.settings_model = settings_model
        self._get_strat = strategy_getter
        self._get_title_tpl = title_tpl_getter
        self._no_data_indices = set()
        self._rendering_set = set()
        self._param_fingerprints = {}
        self._cleaned_data = None  # v2.10
        self._render_lock = threading.RLock()  # v2.17fix
        self._pixmap_cache = OrderedDict()
        self._max_cache = PREVIEW_CACHE_MAXSIZE
        self._render_futures = {}
        self._data_futures = {}
        self._max_concurrent_renders = 4
        # v2.28: pending队列—超并发限制的任务排队而非丢弃
        self._pending_queue = deque()
        # v2.28: precomputed_day_types缓存—避免重复list comprehension
        self._day_types_cache = {}
        self.plot_options = PlotOptions()
        try:
            self._process_pool = ProcessPoolExecutor(
                max_workers=min(4, max(2, mp.cpu_count() // 2)),
                initializer=_init_render_worker,
                max_tasks_per_child=50
            )
        except Exception:
            self._process_pool = None
        try:
            self._data_load_executor = ThreadPoolExecutor(max_workers=min(4, max(1, mp.cpu_count())))
        except Exception:
            self._data_load_executor = None

    def set_cleaned_data(self, cleaned_data):
        """v2.27: 线程安全的数据重置 - 收集futures后释放锁再取消.
        v2.27fix: 先建后拆——新池创建成功后再关闭旧池,避免新池创建失败时
        _process_pool 被置为 None 导致后续渲染请求 NoneType 崩溃."""
        old_futures = []
        with self._render_lock:
            old_futures = list(self._render_futures.values())
            self._render_futures.clear()
            self._data_futures.clear()
            self._pixmap_cache.clear()
            self._cleaned_data = cleaned_data
        # 在锁外取消,避免cancel()阻塞拖慢调度器
        for fut in old_futures:
            with suppress(Exception): fut.cancel()
        # v2.27fix: 先建后拆——新池先创建,成功后再淘汰旧池
        new_pool = None
        try:
            new_pool = ProcessPoolExecutor(
                max_workers=min(4, max(2, mp.cpu_count() // 2)),
                initializer=_init_render_worker,
                max_tasks_per_child=50
            )
        except Exception:
            log.warning("PreviewRender: 新进程池创建失败,保留旧池继续服务")
        new_thread = None
        try:
            new_thread = ThreadPoolExecutor(max_workers=min(4, max(1, mp.cpu_count())))
        except Exception:
            log.warning("PreviewRender: 新线程池创建失败,保留旧池继续服务")
        # 新旧交接——新池就绪后才关闭旧池
        old_pool = self._process_pool
        old_thread = self._data_load_executor
        if new_pool is not None:
            self._process_pool = new_pool
        if new_thread is not None:
            self._data_load_executor = new_thread
        # 旧池安全关闭
        if old_pool is not None and new_pool is not None:
            with suppress(Exception):
                old_pool.shutdown(wait=False, cancel_futures=True)
        if old_thread is not None and new_thread is not None:
            with suppress(Exception): old_thread.shutdown(wait=False)

    def set_plot_options(self, opts: PlotOptions):
        self.plot_options = opts

    def set_no_data_indices(self, indices):
        self._no_data_indices = set(indices)

    # v2.28fix: 公开缓存查询API,消除 PreviewDialog 对 _pixmap_cache/_rendering_set 的直接访问
    def has_pixmap(self, idx):
        """检查索引是否有已缓存的渲染结果."""
        with self._render_lock:
            return idx in self._pixmap_cache

    def get_pixmap(self, idx):
        """获取缓存的渲染结果(仅供UI线程读取)."""
        with self._render_lock:
            return self._pixmap_cache.get(idx)

    def is_rendering(self, idx):
        """检查索引是否正在渲染中."""
        with self._render_lock:
            return idx in self._rendering_set

    def clear_all_caches(self):
        with self._render_lock:
            self._pixmap_cache.clear()
            self._param_fingerprints.clear()
        self.cancel_all()

    def clear_cache_for_index(self, idx):
        with self._render_lock:
            if idx in self._pixmap_cache:
                self._pixmap_cache.pop(idx, None)
            if idx in self._param_fingerprints:
                self._param_fingerprints.pop(idx, None)
            if idx in self._render_futures:
                fut = self._render_futures.pop(idx)
                fut.cancel()
                self._rendering_set.discard(idx)
        if idx in self._data_futures:
            self._data_futures[idx].cancel()
            self._data_futures.pop(idx, None)

    def cancel_all(self):
        with self._render_lock:
            # v2.22fix: 先拷贝再遍历--fut.cancel()回调可能修改_render_futures
            for fut in list(self._render_futures.values()):
                fut.cancel()
            self._render_futures.clear()
            self._rendering_set.clear()
        for _idx, fut in list(self._data_futures.items()):
            fut.cancel()
        self._data_futures.clear()

    # v2.28: 翻页聚焦——取消远离焦点的渲染,优先渲染当前页
    def cancel_distant(self, focus_idx, radius=5):
        """取消 |idx - focus_idx| > radius 的所有渲染任务(不清缓存)."""
        with self._render_lock:
            to_cancel = [idx for idx in list(self._render_futures.keys())
                        if abs(idx - focus_idx) > radius]
            for idx in to_cancel:
                fut = self._render_futures.pop(idx, None)
                if fut:
                    fut.cancel()
                    self._rendering_set.discard(idx)
        to_cancel_data = [idx for idx in list(self._data_futures.keys())
                         if abs(idx - focus_idx) > radius]
        for idx in to_cancel_data:
            fut = self._data_futures.pop(idx, None)
            if fut:
                fut.cancel()

    def shutdown(self):
        """v2.15: 先取消所有 future,再 wait=True 等待子进程安全退出,避免 use-after-free.
        v2.23: 关闭复用figure防止内存泄漏."""
        self.cancel_all()
        self._process_pool.shutdown(wait=True)
        self._data_load_executor.shutdown(wait=True)
        # v2.23: 关闭复用的matplotlib figure
        import builtins
        fig = getattr(builtins, '_render_fig', None)
        if fig is not None:
            _get_plt().close(fig)
            builtins._render_fig = None
            builtins._render_ax = None

    def allow_retry(self, idx):
        self._no_data_indices.discard(idx)

    def schedule_render(self, idx):
        if idx in self._no_data_indices:
            return
        new_fp = self._compute_fingerprint(idx)
        with self._render_lock:
            if idx in self._pixmap_cache and self._param_fingerprints.get(idx) == new_fp:
                pix = self._pixmap_cache[idx]
                self._pixmap_cache.move_to_end(idx)
                self.renderReady.emit(idx, pix)
                return
            if idx in self._rendering_set:
                return
            if len(self._rendering_set) >= self._max_concurrent_renders:
                # v2.28: 超并发限制→加入pending队列
                if idx in self._pending_queue:
                    # 已排队→提升到队首(用户刚导航到它)
                    self._pending_queue.remove(idx)
                self._pending_queue.appendleft(idx)
                return
            self._rendering_set.add(idx)

        if idx not in self._data_futures:
            if self._data_load_executor is None:
                self.renderError.emit(idx, "数据加载线程池不可用,请重启程序")
                return
            data_future = self._data_load_executor.submit(self._load_data_for_render, idx)
            self._data_futures[idx] = data_future
            data_future.add_done_callback(lambda f: self._on_data_loaded(idx, f))

    def _load_data_for_render(self, idx):
        summary = self.summaries[idx]
        data = self.provider.get_group_data(summary)
        # v2.10: 如果启用了数据清洗,用清洗后数据替换
        if data and self._cleaned_data and summary.month_str in self._cleaned_data:
            cleaned = self._cleaned_data[summary.month_str]
            if cleaned and 'load_array' in cleaned:
                data = dict(data)
                data['load_array'] = cleaned['load_array']
                data['date_labels'] = cleaned.get('date_labels', data.get('date_labels', []))
        # v2.22: 形状+数值诊断--记录渲染前数据形状和值范围
        if data and 'load_array' in data:
            arr = data['load_array']
            if hasattr(arr, 'shape'):
                vmin = float(np.nanmin(arr)) if arr.size > 0 else 0
                vmax = float(np.nanmax(arr)) if arr.size > 0 else 0
                log.info(f"[render] idx={idx} month={summary.month_str} shape={arr.shape} range=[{vmin:.1f}, {vmax:.1f}]")
        return data

    def _on_data_loaded(self, idx, future):
        # v2.22fix: 被取消的 future 不报错--clear_all_caches 会取消旧 future
        if future.cancelled():
            return
        try:
            data = future.result(timeout=120)  # v2.27: 2分钟超时防卡死
        except Exception:
            data = None
        finally:
            with self._render_lock:
                if idx in self._data_futures:
                    self._data_futures.pop(idx, None)

        if not data:
            summary = self.summaries[idx]
            error_msg = self.provider.get_load_error(summary)
            self.renderError.emit(idx, error_msg)
            with self._render_lock:
                self._rendering_set.discard(idx)
            return

        multiplier = self.settings_model.effective_multiplier(idx)
        billing = self.settings_model.effective_billing(idx)
        periods = self._get_strat(idx) if self._get_strat else []
        title_tpl = self._get_title_tpl() if self._get_title_tpl else ''
        opts = self.plot_options.to_dict()
        enable_holiday = opts.get('highlight_mode', 'none') in ('holiday', 'grouped')
        # v2.28: 缓存precomputed_day_types—同一组数据的日期类型不变,避免重复list comprehension
        dt_cache_key = (idx, enable_holiday)
        if dt_cache_key in self._day_types_cache:
            precomputed_day_types = self._day_types_cache[dt_cache_key]
        else:
            precomputed_day_types = [_get_day_type(d, enable_holiday=enable_holiday) for d in data['date_labels']]
            self._day_types_cache[dt_cache_key] = precomputed_day_types
            if len(self._day_types_cache) > 200:  # 防无限膨胀
                self._day_types_cache.clear()

        load_array = np.asarray(data['load_array']) * multiplier
        time_labels = data['time_labels']
        date_labels = data['date_labels']
        ctx = {
            'year_month': data.get('month_str', ''),
            'table_no': data.get('table_no', ''),
            'asset': data.get('asset', ''),
            'sheet': data.get('sheet', '')
        }
        title = parse_title_template(title_tpl, ctx) if title_tpl else generate_default_title(ctx)
        billing_dict = billing if billing else {}
        periods_list = list(periods)

        # v2.19: 进程池None保护 - 创建失败时优雅降级
        if self._process_pool is None:
            self.renderError.emit(idx, "渲染进程池不可用,请重启程序")
            return

        try:
            fut = self._process_pool.submit(
                _process_render_in_subprocess,
                idx, load_array, time_labels, date_labels,
                title, opts, billing_dict, periods_list, precomputed_day_types
            )
        except BrokenProcessPool:
            log.warning(f"[render] 进程池崩溃,重建中... idx={idx}")
            with suppress(Exception):
                self._process_pool.shutdown(wait=True, cancel_futures=True)  # v2.29fix: wait=True+cancel_futures防僵尸进程
            # v2.27: 多次重试重建,避免单次失败永久哑火
            rebuilt = False
            for attempt in range(1, 4):
                try:
                    self._process_pool = ProcessPoolExecutor(
                        max_workers=min(4, max(2, mp.cpu_count() // 2)),
                        initializer=_init_render_worker,
                        max_tasks_per_child=50
                    )
                    fut = self._process_pool.submit(
                        _process_render_in_subprocess,
                        idx, load_array, time_labels, date_labels,
                        title, opts, billing_dict, periods_list, precomputed_day_types
                    )
                    rebuilt = True
                    break
                except Exception as rebuild_err:
                    log.warning(f"[render] 第{attempt}次重建失败: {rebuild_err}")
                    time.sleep(0.5 * attempt)
            if not rebuilt:
                log.critical("[render] 进程池3次重建均失败,后续渲染将跳过.请重启程序")
                self._process_pool = None
                self.renderError.emit(idx, "渲染进程崩溃且多次重建失败,请重启程序")
                return
        with self._render_lock:
            self._render_futures[idx] = fut
        fut.add_done_callback(lambda f: self._handle_render_done(idx, f))

    def _handle_render_done(self, idx, future):
        with self._render_lock:
            self._rendering_set.discard(idx)
            if idx in self._render_futures:
                del self._render_futures[idx]
        if future.cancelled():
            return
        try:
            result = future.result(timeout=120)  # v2.27: 2分钟超时防卡死
            if isinstance(result, tuple) and result[1] is None:
                err_msg = result[2] if len(result) >= 3 else "未知错误"
                self.renderError.emit(idx, err_msg)
            else:
                png_bytes = result[1] if isinstance(result, tuple) else result
                pix = QPixmap()
                pix.loadFromData(png_bytes, "PNG")
                with self._render_lock:
                    self._param_fingerprints[idx] = self._compute_fingerprint(idx)
                    if idx in self._pixmap_cache:
                        self._pixmap_cache.pop(idx, None)
                    while len(self._pixmap_cache) >= self._max_cache:
                        self._pixmap_cache.popitem(last=False)
                    self._pixmap_cache[idx] = pix
                self.renderReady.emit(idx, pix)
                self._update_cache_progress()
        except Exception as e:
            self.renderError.emit(idx, str(e))
        finally:
            self._update_cache_progress()
            # v2.28: 渲染完成后从pending队列取下一个
            self._drain_pending()

    def _drain_pending(self):
        """从pending队列取下一个等待渲染的任务."""
        to_render = None
        with self._render_lock:
            while self._pending_queue and len(self._rendering_set) < self._max_concurrent_renders:
                next_idx = self._pending_queue.popleft()
                # 跳过已在渲染中或已缓存的
                if next_idx in self._rendering_set:
                    continue
                fp = self._compute_fingerprint(next_idx)
                if next_idx in self._pixmap_cache and self._param_fingerprints.get(next_idx) == fp:
                    continue
                self._rendering_set.add(next_idx)
                to_render = next_idx
                break  # 只取一个,释放锁后提交
        # 在锁外提交数据加载
        if to_render is not None and to_render not in self._data_futures:
            if self._data_load_executor is None:
                self.renderError.emit(to_render, "数据加载线程池不可用,请重启程序")
                return
            data_future = self._data_load_executor.submit(self._load_data_for_render, to_render)
            self._data_futures[to_render] = data_future
            data_future.add_done_callback(lambda f: self._on_data_loaded(to_render, f))

    def schedule_batch(self, priority_indices):
        all_indices = set(range(len(self.summaries))) - self._no_data_indices
        ordered = list(priority_indices) + [i for i in all_indices if i not in priority_indices]
        for idx in ordered:
            self.schedule_render(idx)

    def _compute_fingerprint(self, idx):
        periods = self._get_strat(idx) if self._get_strat else []
        # v3.2fix: 原实现用 id(periods) 做缓存键, 列表对象释放后 id 可被复用,
        # 会导致指纹假命中并返回旧图。改为直接按内容构造元组(时段数量很小, 排序开销可忽略)。
        periods_tuple = tuple(sorted(
            (p.get('start'), p.get('end'), str(getattr(p.get('type'), 'value', p.get('type'))))
            for p in periods
        ))
        fp = (
            self.settings_model.effective_multiplier(idx),
            self.settings_model.effective_billing(idx)['value'] if self.settings_model.effective_billing(idx) else None,
            self.plot_options.show_daily,
            self.plot_options.show_avg,
            self.plot_options.show_max_demand,
            self.plot_options.fit_algorithm,
            self.plot_options.enable_fit_overlay,
            self.plot_options.replace_with_fit,
            self.plot_options.show_fit_clusters,
            self.plot_options.fit_percentile,
            self.plot_options.fit_n_clusters,
            self.plot_options.fit_n_components,
            self.plot_options.highlight_mode,
            self.plot_options.weekday_color,
            self.plot_options.weekend_color,
            self.plot_options.holiday_color,
            self.plot_options.weekend_line_width,
            self.plot_options.holiday_line_width,
            self.plot_options.show_weekend_bg,
            self.plot_options.legend_position,
            self.plot_options.mark_anomalies,
            self.plot_options.dark_theme,
            periods_tuple
        )
        return hash(fp)

    def _update_cache_progress(self):
        # 节流:最多每秒更新一次缓存进度文本
        now = time.monotonic()
        last = getattr(self, '_last_cache_update', 0)
        if now - last < 1.0:
            return
        self._last_cache_update = now
        total = len(self.summaries) - len(self._no_data_indices)
        cached = len(self._pixmap_cache)
        self.cacheProgress.emit(f"已缓存: {cached} / {total}")
# endregion

# region 光伏反馈对话框
class PVFeedbackDialog(AnimatedDialog):
    __slots__ = ('monthly_data', 'global_multiplier', 'result_feedback')
    def __init__(self, monthly_data, global_multiplier, parent=None):
        super().__init__(parent)
        self.monthly_data = monthly_data
        self.global_multiplier = global_multiplier
        self.setWindowTitle("☀️ 光伏返送详情")
        self.setMinimumSize(700, 500)
        self._init_ui()

    def _init_ui(self):
        bsize = int(base_size())
        layout = QVBoxLayout(self)
        layout.setSpacing(12)
        layout.setContentsMargins(24, 24, 24, 24)
        top_layout = QHBoxLayout()
        top_layout.addWidget(QLabel("选择月份:"))
        self.month_combo = QComboBox()
        self.month_combo.addItems(sorted(self.monthly_data.keys()))
        self.month_combo.setMinimumHeight(bsize)
        self.month_combo.setFont(get_default_font(12))
        self.month_combo.currentTextChanged.connect(self._refresh)
        top_layout.addWidget(self.month_combo)
        top_layout.addStretch()
        layout.addLayout(top_layout)
        self.summary_label = QLabel("")
        self.summary_label.setStyleSheet("font-weight: bold; color: #2C5F8A;")
        self.summary_label.setFont(get_default_font(12, bold=True))
        layout.addWidget(self.summary_label)
        self.table = QTableWidget()
        self.table.setAlternatingRowColors(True)
        self.table.setFont(get_default_font(11))
        layout.addWidget(self.table)
        btn_box = QDialogButtonBox(QDialogButtonBox.Ok)
        btn_box.accepted.connect(self.accept)
        ok_btn = btn_box.button(QDialogButtonBox.Ok)
        if ok_btn:
            ok_btn.setObjectName("primary")
            ok_btn.setMinimumHeight(bsize)
            ok_btn.setFont(get_default_font(13, bold=True))
        layout.addWidget(btn_box)
        if self.month_combo.count() > 0:
            self._refresh(self.month_combo.currentText())

    def _refresh(self, month):
        if not month or month not in self.monthly_data:
            self.table.setRowCount(0)
            self.summary_label.setText("")
            return
        data = self.monthly_data[month]
        load_array = np.asarray(data['load_array']) * self.global_multiplier
        dates = data.get('date_labels', [])
        n_days = load_array.shape[0]
        time_labels = data.get('time_labels', [])
        hours = np.array([_parse_min(_normalize_time_column_name(t)) / 60.0 for t in time_labels])
        dt = np.zeros_like(hours)
        if len(hours) > 1:
            dt[0] = hours[1] - hours[0]
            dt[-1] = hours[-1] - hours[-2]
            for i in range(1, len(hours) - 1):
                dt[i] = (hours[i + 1] - hours[i - 1]) / 2.0
        dt = np.maximum(dt, 0.0)
        daily_neg_energy = []
        daily_neg_max_power = []
        for d in range(n_days):
            neg_mask = load_array[d] < 0
            if not np.any(neg_mask):
                daily_neg_energy.append(0.0)
                daily_neg_max_power.append(0.0)
            else:
                daily_neg_energy.append(np.sum(np.abs(load_array[d][neg_mask]) * dt[neg_mask]))
                daily_neg_max_power.append(np.max(np.abs(load_array[d][neg_mask])))
        col_labels = ['日期', '返送电量 (kWh)', '最大返送功率 (kW)']
        self.table.setColumnCount(len(col_labels))
        self.table.setHorizontalHeaderLabels(col_labels)
        self.table.setRowCount(n_days)
        for d in range(n_days):
            self.table.setItem(d, 0, QTableWidgetItem(str(dates[d])))
            self.table.setItem(d, 1, QTableWidgetItem(f"{daily_neg_energy[d]:.3f}"))
            self.table.setItem(d, 2, QTableWidgetItem(f"{daily_neg_max_power[d]:.3f}"))
        self.table.resizeColumnsToContents()
        total_energy = np.sum(daily_neg_energy)
        max_power = max(daily_neg_max_power) if daily_neg_max_power else 0.0
        self.summary_label.setText(f"本月总返送电量: {total_energy:.3f} kWh,最大返送功率: {max_power:.3f} kW")
# endregion

# region 专业模式选择对话框
class ProfessionalModeDialog(AnimatedDialog):
    def __init__(self, parent, config_manager, settings_model, summaries, current_province, current_idx):
        super().__init__(parent)
        bsize = int(base_size())
        self.config_manager = config_manager
        self.settings_model = settings_model
        self.summaries = summaries
        self.current_province = current_province
        self.current_idx = current_idx
        self.selected_mode = None
        self.setWindowTitle("💼 选择专业分析模式")
        self.setMinimumSize(500, 400)
        self.setContentsMargins(24, 24, 24, 24)
        layout = QVBoxLayout(self)
        layout.setSpacing(12)
        layout.addWidget(QLabel("<b>请选择分析场景:</b>"))
        self.mode_group = QButtonGroup(self)
        self.radio_a = QRadioButton("A:需量管理 / 峰谷套利")
        self.radio_b = QRadioButton("B:纯光伏消纳")
        self.radio_c = QRadioButton("C:光伏消纳 + 峰谷套利(混合)")
        self.radio_a.setChecked(True)
        self.mode_group.addButton(self.radio_a, 0)
        self.mode_group.addButton(self.radio_b, 1)
        self.mode_group.addButton(self.radio_c, 2)
        desc_layout = QVBoxLayout()
        desc_layout.addWidget(QLabel("A:充放电时段+容量线,适用于需量管理/峰谷套利"))
        desc_layout.addWidget(QLabel("B:仅光伏返送存电,无需充放策略和容量线,需输入储能额定功率"))
        desc_layout.addWidget(QLabel("C:光伏充电+峰谷放电,需策略放电时段,可选容量限制"))
        layout.addWidget(self.radio_a)
        layout.addWidget(self.radio_b)
        layout.addWidget(self.radio_c)
        layout.addLayout(desc_layout)
        status_group = QGroupBox("📊 当前参数状态")
        status_group.setFont(get_default_font(14, bold=True))
        status_layout = QVBoxLayout(status_group)
        province_label = QLabel(f"当前省份:{current_province}")
        province_label.setFont(get_default_font(12))
        status_layout.addWidget(province_label)
        has_strategy = current_province != "无" and current_province in self.config_manager.provinces()
        status_layout.addWidget(QLabel(f"策略组数量:{len(self.config_manager.get_province_groups(current_province)) if has_strategy else '无'}"))
        any_bill = False
        for s in summaries:
            for i, sm in enumerate(settings_model.summaries):
                if sm == s:
                    bill = settings_model.effective_billing(i)
                    if bill and bill.get('value'):
                        any_bill = True
                        break
            if any_bill:
                break
        status_layout.addWidget(QLabel(f"容量线:{'已设置' if any_bill else '未设置'}"))
        layout.addWidget(status_group)
        self.warning_label = QLabel("")
        self.warning_label.setStyleSheet("color: #C0392B; font-weight: bold;")
        self.warning_label.setWordWrap(True)
        layout.addWidget(self.warning_label)
        btn_layout = QHBoxLayout()
        btn_layout.addStretch()
        cancel_btn = QPushButton("❌ 取消")
        cancel_btn.setObjectName("secondary")
        cancel_btn.setMinimumHeight(bsize)
        cancel_btn.clicked.connect(self.reject)
        enter_btn = QPushButton("✅ 进入分析")
        enter_btn.setObjectName("primary")
        enter_btn.setMinimumHeight(bsize)
        enter_btn.clicked.connect(self._on_enter)
        btn_layout.addWidget(cancel_btn)
        btn_layout.addWidget(enter_btn)
        layout.addLayout(btn_layout)

    def _on_enter(self):
        mode_id = self.mode_group.checkedId()
        if mode_id == 0:
            mode = 'A'
        elif mode_id == 1:
            mode = 'B'
        else:
            mode = 'C'
        errors = []
        any_bill = False
        for s in self.summaries:
            for i, sm in enumerate(self.settings_model.summaries):
                if sm == s:
                    bill = self.settings_model.effective_billing(i)
                    if bill and bill.get('value'):
                        any_bill = True
                        break
            if any_bill:
                break
        has_strategy = self.current_province != "无" and self.current_province in self.config_manager.provinces()
        if mode == 'A':
            if not has_strategy:
                errors.append("需量管理/峰谷套利模式必须选择省份策略.")
            if not any_bill:
                errors.append("未设置容量线(需量限制).")
        elif mode == 'C':
            if not has_strategy:
                errors.append("混合模式建议选择省份策略以定义放电时段.")
        if errors:
            self.warning_label.setText("\n".join(errors))
            return
        self.selected_mode = mode
        self.accept()
# endregion

