    def _recalc_spaces_basic(self):
        """v2.16: 基础模式充放电空间计算 - 旧版修复后算法.
        无拟合、无SOC连续性、无DOD修正.仅做原始充放电空间计算,速度快结果稳定.
        """
        strategy_periods = {}
        if self.config_manager and self.province_name and self.province_name != "无":
            strategy_periods = self.config_manager.get_periods_for_all_months(self.province_name)

        billing = None
        for s in self.summaries:
            key = (s.asset_value, s.month_str)
            idx = self._summary_idx_map.get(key)
            if idx is not None:
                bill = self.settings_model.effective_billing(idx)
                if bill and bill.get('value'):
                    billing = bill
                    break
        if self.mode == 'C' and not self.need_capacity:
            billing = None

        work_data = self._get_work_data()
        for month_str, data in work_data.items():
            key = (self.summaries[0].asset_value if self.summaries else None, month_str)
            idx = self._summary_idx_map.get(key)
            mult = self.settings_model.effective_multiplier(idx) if idx is not None else self.global_multiplier
            # v3.0fix: 每月独立取billing
            month_billing = billing
            if idx is not None:
                mb = self.settings_model.effective_billing(idx)
                if mb and mb.get('value'):
                    month_billing = mb
            load_array = np.asarray(data['load_array']) * mult
            time_labels = data['time_labels']
            month_num = month_str.split('-')[1] if '-' in month_str else month_str
            periods = strategy_periods.get(str(int(month_num)), [])
            segments = _segment_periods(periods)
            c_segs, d_segs, c_labs, d_labs = compute_segmented_spaces(
                load_array, time_labels, segments,
                billing=month_billing, mode=self.mode, rated_power=self.rated_power,
                ignore_negative=self.ignore_negative
            )
            self.charge_segments_dict[month_str] = c_segs
            self.discharge_segments_dict[month_str] = d_segs
            # v2.30fix: 标签取所有月份并集
            for lab in c_labs:
                if lab not in self.charge_labels:
                    self.charge_labels.append(lab)
            for lab in d_labs:
                if lab not in self.discharge_labels:
                    self.discharge_labels.append(lab)

    # ═══════════════════════════════════════════
    # v2.17: 光伏模拟
    # ═══════════════════════════════════════════
    def _apply_pv_simulation(self):
        """v2.28: 应用光伏模拟 - 逐月独立计算,替换硬编码month=6.
        支持KLEIN/Haurwitz/Erbs/月均4种算法.
        v2.28fix: 使用原始负荷数据防止二次减扣; _pv_profile改为{month_str: array}字典."""
        capacity = self.pv_capacity_spin.value()
        if capacity <= 0:
            self._pv_profile = None
            self._pv_applied = False
            self.pv_info_label.setText("光伏已禁用")
            self._recalc_spaces()
            self._refresh_all_displays()
            return

        # v2.28fix: 使用原始月度数据而非_get_work_data,防止光伏二次减扣
        raw_data = self.simulated_monthly_data if self._use_simulation and self.simulated_monthly_data else self.monthly_data
        if not raw_data:
            QMessageBox.warning(self, "警告", "无可用负荷数据")
            return

        city = self.pv_city_combo.currentText()
        eff = self.pv_eff_spin.value() / 100.0

        # v2.19: 算法选择
        algo_map = {0: PVAlgorithm.KLEIN, 1: PVAlgorithm.HAURWITZ, 2: PVAlgorithm.ERBS, 3: PVAlgorithm.MONTHLY_AVG, 4: PVAlgorithm.PVLIB}
        algo = algo_map.get(self.pv_algo_combo.currentIndex(), PVAlgorithm.KLEIN)

        # v2.28: 逐月独立计算光伏曲线
        pv_profile = {}  # {month_str: (n_days, n_points) array}
        pv_total_kwh = 0.0
        consumed_kwh = 0.0
        exported_kwh = 0.0
        result_meta = None
        month_count = 0

        for key, data in raw_data.items():
            # 从 key 提取月份数字 (格式: asset|YYYY-MM 或 asset|M 或 YYYY-MM)
            parts = key.split('|')
            month_str = parts[-1] if len(parts) > 1 else parts[0]
            try:
                if '-' in month_str:
                    month_num = int(month_str.split('-')[1])
                else:
                    month_num = int(month_str)
            except (ValueError, IndexError):
                continue
            if not (1 <= month_num <= 12):
                continue

            # 逐月计算光伏
            try:
                result = calc_pv_hourly_output(city, month_num, capacity, pr=eff, algorithm=algo)
            except Exception as e:
                log.warning(f'光伏计算失败 month={month_num}: {e}')
                continue
            if result_meta is None:
                result_meta = result
            month_count += 1

            hourly_pv = np.array(result['power_kw'])
            arr = np.asarray(data['load_array'])
            n_days, n_points = arr.shape

            # 时间分辨率对齐
            if len(hourly_pv) >= n_points:
                pv_curve = hourly_pv[:n_points]
            else:
                src_hours = np.linspace(0, 24, len(hourly_pv))
                tgt_hours = np.linspace(0, 24, n_points)
                pv_curve = np.interp(tgt_hours, src_hours, hourly_pv, left=0, right=0)

            # 平铺到该月所有天数
            month_pv = np.tile(pv_curve, (n_days, 1))
            pv_profile[key] = month_pv

            # 汇总自发自用
            original_load = data.get('_original_load', arr)
            pv_total_kwh += float(np.sum(month_pv))
            consumed_kwh += float(np.sum(np.minimum(month_pv, original_load[:n_days, :n_points])))
            net = original_load[:n_days, :n_points] - month_pv
            exported_kwh += float(np.sum(np.maximum(-net, 0)))

        if month_count == 0:
            QMessageBox.warning(self, "警告", "无法从数据中提取有效月份")
            return

        self._pv_profile = pv_profile
        self._pv_applied = True

        # v2.28: 年发电量=各月汇总,非单个6月×365
        annual_kwh_est = sum(
            calc_pv_hourly_output(city, m, capacity, pr=eff, algorithm=algo)['daily_kwh']
            for m in range(1, 13)
        ) * 30.42  # 月均天数
        self._pv_metadata = {'peak_sunshine_hours': result_meta['daily_kwh'] / max(capacity, 1) if result_meta else 0,
                            'annual_kwh_est': round(annual_kwh_est),
                            'city': city, 'online': False,
                            'algorithm': result_meta['algorithm'] if result_meta else str(algo)}

        self_suff_rate = (consumed_kwh / max(pv_total_kwh, 1)) * 100

        algo_names = {PVAlgorithm.KLEIN: 'KLEIN晴空指数', PVAlgorithm.HAURWITZ: 'Haurwitz晴空',
                      PVAlgorithm.ERBS: 'Erbs+HDKR', PVAlgorithm.MONTHLY_AVG: '月均简化',
                      PVAlgorithm.PVLIB: 'pvlib工程级'}
        self.pv_info_label.setText(
            f"✅ 光伏已应用 | {algo_names.get(algo, '')} | {month_count}个月 | 总发电: {pv_total_kwh:,.0f}kWh\n"
            f"自发自用率: {self_suff_rate:.0f}% | 年估: {annual_kwh_est:,.0f}kWh"
        )

        self._recalc_spaces()
        self._refresh_all_displays()

    def _get_pv_config(self):
        """v2.28: 获取当前光伏配置用于报告. 汇总所有月份计算自发自用率."""
        if not getattr(self, '_pv_applied', False) or not self._pv_metadata:
            return None
        meta = self._pv_metadata
        # v2.28: 汇总所有月份计算pv_total和consumed
        pv_total = 0.0
        consumed = 0.0
        if isinstance(self._pv_profile, dict):
            work_data = self._get_work_data()
            for key, pv_arr in self._pv_profile.items():
                pv_total += float(np.sum(pv_arr))
                if work_data and key in work_data:
                    arr = np.asarray(work_data[key].get('_original_load', work_data[key]['load_array']))
                    n_d, n_p = min(pv_arr.shape[0], arr.shape[0]), min(pv_arr.shape[1], arr.shape[1])
                    consumed += float(np.sum(np.minimum(pv_arr[:n_d, :n_p], arr[:n_d, :n_p])))
        else:
            pv_total = float(np.sum(self._pv_profile)) if self._pv_profile is not None else 0
        return {
            'capacity_kwp': self.pv_capacity_spin.value(),
            'city': meta.get('city', ''),
            'efficiency': self.pv_eff_spin.value() / 100.0,
            'peak_hours': meta.get('peak_sunshine_hours', 0),
            'annual_kwh': meta.get('annual_kwh_est', 0),
            'self_use_rate': round(consumed / max(pv_total, 1) * 100, 1) if pv_total > 0 else 0,
            'model': 'PVGIS在线' if meta.get('online') else '离线简化模型',
        }

    def _refresh_all_displays(self):
        """v2.17: 刷新所有显示组件(充放电空间/表格/经济标签)"""
        self._update_mode_options()
        self._populate_space_table()
        if getattr(self, 'daily_month_combo', None) and self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self._update_system_scale()
        with suppress(Exception):
            self.update_economic_label()

    def switch_engine_mode(self, new_mode: str):
        """v2.16: 无感切换引擎模式 - 无需关闭窗口,实时生效.
        线程安全:计算进行中时拒绝切换,防止竞态条件导致混合算法输出错误结果.
        """
        if new_mode not in ('basic', 'professional'):
            return
        if new_mode == ANALYSIS_ENGINE_MODE:
            return

        # v2.16: 线程安全 - 计算进行中禁止切换
        with self._compute_lock:
            if self._is_computing:
                QMessageBox.warning(self, "计算进行中",
                    "当前正在执行计算任务(如 Monte Carlo 模拟),请等待计算完成后再切换引擎模式.\n\n"
                    "切换引擎模式可能导致正在运行的计算使用混合算法,输出不可靠的结果.")
                return

        set_engine_mode(new_mode)
        meta = ENGINE_MODE_META[new_mode]
        log.info(f"专业分析窗口无感切换引擎: {meta['label']}")

        # 1. 更新标题栏模式指示器
        mode_icon = meta.get('icon', '🔹')
        asset = self.summaries[0].asset_value if self.summaries else "未知"
        self.asset_info_label.setText(
            f"<b>🏷 资产:{asset}</b>  模式:{self.mode}  {mode_icon} {meta.get('label', '')}"
        )
        self.asset_info_label.setToolTip(
            f"当前分析引擎: {meta.get('label', '')}\n{meta.get('desc', '')}"
        )

        # 2. 更新高级功能按钮状态
        # v2.16: 动态管理模式提示标签
        mode_hint = getattr(self, '_mode_hint_label', None)
        if mode_hint:
            mode_hint.setVisible(new_mode == 'basic')
        advanced_btns = [
            (getattr(self, 'mc_btn', None), "🎲 Monte Carlo"),
            (getattr(self, 'dispatch_btn', None), "📡 调度仿真"),
            (getattr(self, 'sensitivity_btn', None), "🎚 敏感性分析"),
            (getattr(self, 'scenario_btn', None), "📊 场景对比"),
        ]
        for btn, name in advanced_btns:
            if btn is None:
                continue
            if new_mode == 'basic':
                btn.setEnabled(False)
                benefit_hints = {
                    "🎲 Monte Carlo": "切换专业模式可:运行1000次风险模拟,获取P10/P50/P90置信区间,量化投资不确定性",
                    "📡 调度仿真": "切换专业模式可:逐日模拟SOC轨迹,校验变压器负载约束,评估充放电策略可行性",
                    "🎚 敏感性分析": "切换专业模式可:拖动滑块实时查看电价/成本变化对IRR的影响,定位关键风险因子",
                    "📊 场景对比": "切换专业模式可:并行对比2-3组储能配置方案,自动推荐IRR最优方案",
                }
                btn.setToolTip(benefit_hints.get(name, f"{name} 需要专业模式.切换引擎为「🔮 专业」即可使用."))
                btn.setStyleSheet(btn.styleSheet() + " QPushButton:disabled { color: #94a3b8; }")
            else:
                btn.setEnabled(True)
                btn.setToolTip("")
                btn.setStyleSheet(btn.styleSheet().replace(" QPushButton:disabled { color: #94a3b8; }", ""))

        # 3. 重新计算充放电空间(_recalc_spaces 内部已根据 ANALYSIS_ENGINE_MODE 路由)
        self._recalc_spaces()

        # v2.16: 双引擎结果一致性校验 - 切换到专业模式时对比基础模式结果
        if new_mode == 'professional':
            self._check_dual_engine_consistency()

        # 4. 刷新所有显示
        self._update_mode_options()
        self._populate_space_table()
        if getattr(self, 'daily_month_combo', None) and self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self._update_system_scale()
        if hasattr(self, 'update_economic_label'):
            # 专业模式才更新经济标签
            with suppress(Exception):
                self.update_economic_label()

    def _check_dual_engine_consistency(self):
        """v2.16: 双引擎结果一致性校验.
        切换至专业模式时,对比基础模式的空间计算结果.
        若偏差超过15%,弹出警告提示用户核对.
        v2.27fix: 多月份数据分辨率不一致时 concatenate 会因维度不匹配崩溃,
        增加安全对齐逻辑——统一截断到最小维度后 concatenate.
        """
        def _safe_segment_sum(v):
            """安全拼接并求和:自动对齐不同分辨率的 segment 数组."""
            if not v:
                return 0.0
            arrays = [np.asarray(s) for s in v]
            shapes = {a.shape for a in arrays}
            if len(shapes) == 1:
                return float(np.nansum(np.concatenate(arrays)))
            # 维度不一致:统一截断到最小维度
            min_dim = min(s[1] for s in shapes if len(s) >= 2)
            log.debug(f"双引擎校验: 多月份数据分辨率不一致,截断至最小维度={min_dim}(原始维度: {shapes})")
            aligned = [a[:, :min_dim] if a.ndim >= 2 and a.shape[1] > min_dim else a for a in arrays]
            try:
                return float(np.nansum(np.concatenate(aligned)))
            except ValueError:
                return float(np.nansum([np.nansum(a) for a in aligned]))

        if not self.charge_segments_dict:
            return
        # 保存当前专业模式结果
        prof_charge = {k: _safe_segment_sum(v)
                       for k, v in self.charge_segments_dict.items()}
        prof_discharge = {k: _safe_segment_sum(v)
                          for k, v in self.discharge_segments_dict.items()}

        # 临时切到基础模式重算
        prev_mode = get_engine_mode()
        try:
            set_engine_mode('basic')  # v2.27: 线程安全切换
            self._recalc_spaces_basic()
            basic_charge = {k: _safe_segment_sum(v)
                            for k, v in self.charge_segments_dict.items()}
            basic_discharge = {k: _safe_segment_sum(v)
                               for k, v in self.discharge_segments_dict.items()}
        finally:
            set_engine_mode(prev_mode)  # v2.27: 线程安全恢复
            self._recalc_spaces()

        # 对比
        warnings_list = []
        for month in set(list(prof_charge.keys()) + list(basic_charge.keys())):
            pc = prof_charge.get(month, 0)
            bc = basic_charge.get(month, 0)
            pd = prof_discharge.get(month, 0)
            bd = basic_discharge.get(month, 0)

            for label, pv, bv in [('充电', pc, bc), ('放电', pd, bd)]:
                if max(pv, bv) < 0.1:  # 量级太小不比较
                    continue
                dev = abs(pv - bv) / max(abs(pv), abs(bv), 1e-6)
                threshold = self.config_manager.app_set('deviation_threshold', 8.0) / 100.0 if hasattr(self, 'config_manager') else 0.08
                if dev > threshold:
                    warnings_list.append(
                        f"  {month} {label}: 专业={pv:.0f}kWh vs 基础={bv:.0f}kWh (偏差 {dev*100:.0f}%)"
                    )

        if warnings_list:
            log.warning(f"双引擎结果一致性告警 ({len(warnings_list)}项偏差>{threshold*100:.0f}%):\n" + "\n".join(warnings_list[:5]))
            if not is_warning_muted('dual_engine_deviation', getattr(self, 'config_manager', None)):
                msg_box = QMessageBox(self)
                msg_box.setWindowTitle("⚡ 双引擎结果偏差告警")
                msg_box.setIcon(QMessageBox.Warning)
                msg_box.setText(f"专业模式与基础模式的充放电空间计算结果存在 {len(warnings_list)} 处显著差异(>{threshold*100:.0f}%):")
                msg_box.setInformativeText(
                    "\n".join(warnings_list[:8])
                    + ("\n..." if len(warnings_list) > 8 else "")
                    + "\n\n💡 差异原因:专业模式含变压器约束、DOD修正、算法拟合等工程约束,"
                      "基础模式为简化计算.建议以专业模式结果为准进行正式评估."
                )
                cb = QCheckBox("不再提示此告警")
                msg_box.setCheckBox(cb)
                msg_box.exec()
                if cb.isChecked():
                    mute_warning('dual_engine_deviation', self.config_manager)

