    def _update_month_checkboxes(self):
        """v2.28: 更新月份勾选框——仅启用已有数据的月份"""
        data = self._get_work_data()
        available = set()
        if data:
            for k in data.keys():
                try:
                    m = int(k.split('-')[1]) if '-' in k else int(k)
                    if 1 <= m <= 12:
                        available.add(m)
                except ValueError:
                    pass
        for m, cb in self._month_checks.items():
            cb.setEnabled(m in available)
            if m not in available:
                cb.setChecked(False)

    def _on_month_filter_changed(self):
        """v2.28: 月份勾选变更时重新计算"""
        self._recalc_spaces()
        self._populate_space_table()
        if hasattr(self, 'daily_month_combo') and self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self._update_effective_days_label()

    def _get_enabled_months(self):
        """v2.28: 返回用户勾选的月份集合"""
        return {m for m, cb in self._month_checks.items() if cb.isChecked() and cb.isEnabled()}

