    def _on_capacity_mode_changed(self, index):
        if index == 0:
            self.capacity_mode = "two_two"
            self.charge_option_combo.setVisible(False)
            self.discharge_option_combo.setVisible(False)
        else:
            self.capacity_mode = "one_one"
            self.charge_option_combo.setVisible(True)
            self.discharge_option_combo.setVisible(True)
        self._calc_capacity_from_days()

    def _on_est_strategy_changed(self, index):
        """v3.0: 评估策略切换——最小可行时隐藏充放段选择, 满载利用率尊重模式."""
        is_min = ("最小可行" in self.est_combo.currentText())
        is_two_two = (self.capacity_mode == "two_two")
        if hasattr(self, 'charge_option_combo'):
            self.charge_option_combo.setVisible(not is_min and not is_two_two)
        if hasattr(self, 'discharge_option_combo'):
            self.discharge_option_combo.setVisible(not is_min and not is_two_two)
        self._cached_daily_needs = None  # 清缓存
        self._cached_sorted_needs = None
        self._calc_capacity_from_days()

    def _on_demand_reduce_toggled(self, checked):
        """v2.28: 切换降需测算模式"""
        self.demand_reduce_slider.setVisible(checked)
        self.demand_reduce_label.setVisible(checked)
        if checked:
            self._run_demand_reduction()
        else:
            self._recalc_spaces()
            self._populate_space_table()

    def _run_demand_reduction(self):
        """v2.28: 降需测算——计算储能配置削平超过目标需量的负荷峰值."""
        reduce_pct = self.demand_reduce_slider.value() / 100.0
        work_data = self._get_work_data()
        if not work_data:
            QMessageBox.warning(self, "提示", "无可用负荷数据")
            return
        all_loads = []
        for data in work_data.values():
            arr = np.asarray(data['load_array'], dtype=np.float64)
            if arr.size > 0:
                all_loads.append(arr.flatten())
        if not all_loads:
            return
        all_flat = np.concatenate(all_loads)
        original_peak = float(np.max(all_flat))
        target_peak = original_peak * (1 - reduce_pct)
        excess = np.maximum(all_flat - target_peak, 0)
        required_power = float(np.max(excess))
        n_days = len(work_data)
        required_energy = float(np.sum(excess)) / max(n_days, 1)
        billing = self.settings_model.effective_billing(
            self._summary_idx_map.get((self.summaries[0].asset_value, self.summaries[0].month_str), 0))
        demand_price = billing.get('demand_price', 30) if billing else 30
        monthly_before = original_peak * demand_price / 1000
        monthly_after = target_peak * demand_price / 1000
        annual_saving = (monthly_before - monthly_after) * 12
        summary = (f'📉 降需测算结果 (目标降需 {int(reduce_pct*100)}%)\n\n'
                   f'原始峰值: {original_peak:.0f}kW\n'
                   f'目标峰值: {target_peak:.0f}kW\n'
                   f'需储能功率: >= {required_power:.0f}kW\n'
                   f'日均需削能量: {required_energy:.0f}kWh\n'
                   f'建议储能容量: >= {required_energy*2:.0f}kWh (2h配置)\n\n'
                   f'年降需电费节省: ¥{annual_saving:,.0f}')
        QMessageBox.information(self, "降需测算", summary)

    # ═══════════════════════════════════════════════════════════
    # v3.2fix: 容量评估方法 (from Pro v2.3)
    # ═══════════════════════════════════════════════════════════
    def _on_est_combo_changed(self, index):
        """评估策略切换——最小可行时隐藏充放段选择."""
        is_min = ("最小可行" in self.est_combo.currentText())
        is_two_two = (self.capacity_mode == "two_two")
        if hasattr(self, 'charge_option_combo'):
            self.charge_option_combo.setVisible(not is_min and not is_two_two)
        if hasattr(self, 'discharge_option_combo'):
            self.discharge_option_combo.setVisible(not is_min and not is_two_two)
        self._calc_capacity_from_days()

    def _get_all_filtered_daily_mins(self):
        """遍历所有月份,返回每天的最小段值列表(用于容量计算)."""
        use_min = (hasattr(self, 'est_combo') and self.est_combo.currentText() != "满载利用率")
        daily_mins = []
        work_data = self._get_work_data()
        for month in work_data.keys():
            c_arrs, d_arrs = self._get_relevant_segments_for_month(month)
            if not c_arrs and not d_arrs:
                continue
            n_days = len(c_arrs[0]) if c_arrs else (len(d_arrs[0]) if d_arrs else 0)
            if n_days == 0:
                continue
            for d in range(n_days):
                if use_min:
                    all_vals = [arr[d] for arr in c_arrs if d < len(arr)] + \
                               [arr[d] for arr in d_arrs if d < len(arr)]
                    daily_cap = min(all_vals) if all_vals else 0.0
                else:
                    n_pairs = max(len(c_arrs), len(d_arrs))
                    daily_cap = 0.0
                    for i in range(n_pairs):
                        cv = c_arrs[i][d] if i < len(c_arrs) and d < len(c_arrs[i]) else float('inf')
                        dv = d_arrs[i][d] if i < len(d_arrs) and d < len(d_arrs[i]) else float('inf')
                        pair_min = min(cv, dv)
                        if pair_min != float('inf'):
                            daily_cap = max(daily_cap, pair_min)
                if daily_cap > 0 or (c_arrs or d_arrs):
                    daily_mins.append(daily_cap)
        return daily_mins

    def _check_day_satisfied(self, month, day_index, cap):
        """按充放配对判断——应用DOD折算可用容量后比较."""
        dod_val = self.dod_spin.value() if hasattr(self, 'dod_spin') else int(BESS_DOD_DEFAULT * 100)
        usable_cap = cap * dod_val / 100.0
        c_arrs, d_arrs = self._get_relevant_segments_for_month(month)
        n_pairs = max(len(c_arrs), len(d_arrs))
        for i in range(n_pairs):
            cv = c_arrs[i][day_index] if i < len(c_arrs) and day_index < len(c_arrs[i]) else float('inf')
            dv = d_arrs[i][day_index] if i < len(d_arrs) and day_index < len(d_arrs[i]) else float('inf')
            if cv >= usable_cap and dv >= usable_cap:
                return True
        return False

    def _get_relevant_segments_for_month(self, month):
        charge = self.charge_segments_dict.get(month, [])
        discharge = self.discharge_segments_dict.get(month, [])
        return charge, discharge

    def _get_all_daily_capacity_needs(self):
        """获取全年每日的容量需求.
        
        v3.0: 三策略
          - 最小可行容量: min(c₁,d₁,c₂,d₂) 所有段取最小(最保守)
          - 满载利用率: max(min(c₁,d₁), min(c₂,d₂)) 配对取最大(保证跑满)
          - SOC 仿真: 时序SOC轨迹 max_soc-min_soc(最精准)
        """
        est_mode = self.est_combo.currentText() if hasattr(self, 'est_combo') else "最小可行容量"
        if "SOC" in est_mode:
            # 原始SOC轨迹法(带缓存)
            if hasattr(self, '_cached_daily_needs') and self._cached_daily_needs is not None:
                return self._cached_daily_needs
            all_needs = []
            work_data = self._get_work_data()
            for month in work_data:
                if month in self._month_capacity_needs:
                    all_needs.extend(self._month_capacity_needs[month])
            self._cached_daily_needs = all_needs
            self._cached_sorted_needs = None
            return all_needs
        else:
            # 静态法(与Pro对齐): 直接从充放段数组计算
            return self._get_static_daily_needs(est_mode)

    def _get_static_daily_needs(self, est_mode):
        """v3.2fix: 静态容量评估——走_get_relevant_segments_for_month, 尊重1C1D选段."""
        use_min = ("最小可行" in est_mode)
        all_needs = []
        for month in self._get_work_data():
            c_arrs, d_arrs = self._get_relevant_segments_for_month(month)
            if not c_arrs and not d_arrs:
                continue
            n_days = len(c_arrs[0]) if c_arrs else (len(d_arrs[0]) if d_arrs else 0)
            for d in range(n_days):
                if use_min:
                    vals = [arr[d] for arr in c_arrs if d < len(arr)] + \
                           [arr[d] for arr in d_arrs if d < len(arr)]
                    daily_cap = min(vals) if vals else 0.0
                else:
                    n_pairs = max(len(c_arrs), len(d_arrs))
                    daily_cap = 0.0
                    for i in range(n_pairs):
                        cv = c_arrs[i][d] if i < len(c_arrs) and d < len(c_arrs[i]) else float('inf')
                        dv = d_arrs[i][d] if i < len(d_arrs) and d < len(d_arrs[i]) else float('inf')
                        p = min(cv, dv)
                        if p != float('inf'):
                            daily_cap = max(daily_cap, p)
                all_needs.append(daily_cap)
        return all_needs

    def _show_annual_summary(self):
        """v2.27: 展示全年总览汇总卡"""
        data = self._get_work_data()
        if not data:
            return
        months = len(data)
        total_days = self.available_days
        # 全年总充放电空间
        total_charge = sum(np.sum(np.nan_to_num(s, 0)) for segs in self.charge_segments_dict.values() for s in segs)
        total_discharge = sum(np.sum(np.nan_to_num(s, 0)) for segs in self.discharge_segments_dict.values() for s in segs)
        avg_daily_charge = total_charge / max(total_days, 1)
        avg_daily_discharge = total_discharge / max(total_days, 1)
        self.available_days_label.setText(f"📊 全年总览: {months}个月 / {total_days}天 | 日均充电 {avg_daily_charge:.0f}kWh | 日均放电 {avg_daily_discharge:.0f}kWh")
        # v2.29: 更新计算说明
        if hasattr(self, 'space_explain'):
            self.space_explain.setHtml(self._get_space_explanation())

    def _populate_space_table(self):
        months = sorted(self._get_work_data().keys())
        tokens = DesignTokens.current_tokens()
        charge_bg = QColor(tokens['ACCENT_LIGHT'])
        discharge_bg = QColor(tokens['ACCENT_WARM']); discharge_bg.setAlpha(40)
        col_labels = ['月份'] + self.charge_labels + self.discharge_labels + ['容量线(kW)', '月最小值(kWh)']
        self.space_table.setColumnCount(len(col_labels))
        self.space_table.setHorizontalHeaderLabels(col_labels)
        self.space_table.setRowCount(len(months))
        for row, month in enumerate(months):
            c_segs = self.charge_segments_dict.get(month, [])
            d_segs = self.discharge_segments_dict.get(month, [])
            self.space_table.setItem(row, 0, QTableWidgetItem(month))
            seg_values = []
            col = 1
            # v2.30fix: 按标签索引填充, 段数不足时填0
            for i in range(len(self.charge_labels)):
                val = np.sum(np.nan_to_num(c_segs[i], nan=0.0)) if i < len(c_segs) else 0.0
                seg_values.append(val)
                item = QTableWidgetItem(f"{val:.2f}")
                item.setBackground(charge_bg)
                self.space_table.setItem(row, col, item)
                col += 1
            for i in range(len(self.discharge_labels)):
                val = np.sum(np.nan_to_num(d_segs[i], nan=0.0)) if i < len(d_segs) else 0.0
                seg_values.append(val)
                item = QTableWidgetItem(f"{val:.2f}")
                item.setBackground(discharge_bg)
                self.space_table.setItem(row, col, item)
                col += 1
            min_val = min(seg_values) if seg_values else 0.0
            # v3.2fix: 填充容量线列
            cap_val = 0
            for s in self.summaries:
                if s.month_str == month:
                    idx = self._summary_idx_map.get((s.asset_value, s.month_str))
                    if idx is not None:
                        bill = self.settings_model.effective_billing(idx)
                        cap_val = bill.get('value', 0) if bill and bill.get('value') else 0
                        break
            cap_col = col
            cap_item = QTableWidgetItem(f"{cap_val:.0f}")
            self.space_table.setItem(row, cap_col, cap_item)
            col += 1
            min_item = QTableWidgetItem(f"{min_val:.2f}")
            font = min_item.font(); font.setBold(True); min_item.setFont(font)
            self.space_table.setItem(row, col, min_item)
        self.space_table.resizeColumnsToContents()
        # v3.2fix: 刷新容量线显示
        self._update_cap_label()

    def _update_cap_label(self):
        """v3.2fix: 优先取当前预览月的billing, 回退到第一个summary."""
        if not hasattr(self, '_cap_label'):
            return
        cap_val = 0
        try:
            current_month = None
            if hasattr(self, 'daily_month_combo') and self.daily_month_combo.count() > 0:
                current_month = self.daily_month_combo.currentText()
            if not current_month and self.summaries:
                current_month = self.summaries[0].month_str
            if current_month:
                for s in self.summaries:
                    if s.month_str == current_month:
                        idx = self._summary_idx_map.get((s.asset_value, s.month_str))
                        if idx is not None:
                            bill = self.settings_model.effective_billing(idx)
                            cap_val = bill.get('value', 0) if bill and bill.get('value') else 0
                            break
            if cap_val == 0 and self.summaries:
                s = self.summaries[0]
                idx = self._summary_idx_map.get((s.asset_value, s.month_str))
                if idx is not None:
                    bill = self.settings_model.effective_billing(idx)
                    cap_val = bill.get('value', 0) if bill and bill.get('value') else 0
        except Exception:
            log.debug("ProfessionalWindow error suppressed", exc_info=True)
            pass
        # v3.2fix: 有容量线时自动勾选需量限制按钮
        if cap_val > 0 and hasattr(self, 'need_cap_cb') and self.need_cap_cb:
            if not self.need_cap_cb.isChecked():
                self.need_cap_cb.setChecked(True)
        self._cap_label.setText(f"容量线:{cap_val:.2f}")

    def _populate_daily_month_combo(self):
        self.daily_month_combo.blockSignals(True)
        self.daily_month_combo.clear()
        self.daily_month_combo.addItems(sorted(self._get_work_data().keys()))
        self.daily_month_combo.blockSignals(False)

    def _fill_daily_table(self, month):
        work_data = self._get_work_data()
        if month not in work_data:
            self.daily_table.setRowCount(0)
            return
        data = work_data[month]
        # v3.0: 切换到当月容量线显示
        try:
            for s in self.summaries:
                if s.month_str == month:
                    idx = self._summary_idx_map.get((s.asset_value, s.month_str))
                    if idx is not None:
                        bill = self.settings_model.effective_billing(idx)
                        self._current_cap = bill.get('value', 0) if bill and bill.get('value') else 0
                        if hasattr(self, '_cap_label'):
                            self._cap_label.setText(f"容量线:{self._current_cap:.2f}")
                        break
        except Exception:
            log.debug("ProfessionalWindow error suppressed", exc_info=True)
            pass
        dates = data.get('date_labels', [])
        c_segs = self.charge_segments_dict.get(month, [])
        d_segs = self.discharge_segments_dict.get(month, [])
        tokens = DesignTokens.current_tokens()
        charge_bg = QColor(tokens['ACCENT_LIGHT'])
        discharge_bg = QColor(tokens['ACCENT_WARM']); discharge_bg.setAlpha(40)
        col_labels = ['日期'] + self.charge_labels + self.discharge_labels + ['日最小值(kWh)']
        self.daily_table.setColumnCount(len(col_labels))
        self.daily_table.setHorizontalHeaderLabels(col_labels)
        n_days = len(dates)
        self.daily_table.setRowCount(n_days)
        for d in range(n_days):
            self.daily_table.setItem(d, 0, QTableWidgetItem(str(dates[d])))
            vals = []
            col = 1
            # v2.30fix: 按标签索引填充, 段数不足时填0
            for i in range(len(self.charge_labels)):
                val = c_segs[i][d] if i < len(c_segs) and d < len(c_segs[i]) else 0.0
                vals.append(val)
                item = QTableWidgetItem(f"{val:.3f}")
                item.setBackground(charge_bg)
                self.daily_table.setItem(d, col, item)
                col += 1
            for i in range(len(self.discharge_labels)):
                val = d_segs[i][d] if i < len(d_segs) and d < len(d_segs[i]) else 0.0
                vals.append(val)
                item = QTableWidgetItem(f"{val:.3f}")
                item.setBackground(discharge_bg)
                self.daily_table.setItem(d, col, item)
                col += 1
            min_val = min(vals) if vals else 0.0
            # v3.0: 日需求跟策略走
            est_mode = self.est_combo.currentText() if hasattr(self, 'est_combo') else '最小可行容量'
            if '满载' in est_mode:
                n_pairs = max(len(c_segs), len(d_segs))
                daily_need = 0.0
                for i in range(n_pairs):
                    cv = c_segs[i][d] if i < len(c_segs) and d < len(c_segs[i]) else float('inf')
                    dv = d_segs[i][d] if i < len(d_segs) and d < len(d_segs[i]) else float('inf')
                    p = min(cv, dv)
                    if p != float('inf'):
                        daily_need = max(daily_need, p)
            else:
                daily_need = min_val
            min_item = QTableWidgetItem(f"{daily_need:.3f}")
            font = min_item.font(); font.setBold(True); min_item.setFont(font)
            self.daily_table.setItem(d, col, min_item)
        self.daily_table.resizeColumnsToContents()

    def _update_effective_days_label(self):
        input_days = self.target_days_spin.value()
        effective = int(input_days * self.available_days / 365.0) if self.available_days > 0 else 0
        self.effective_days_label.setText(f"等效分析天数: {effective} 天")

    def _calc_capacity_from_days(self):
        self._update_effective_days_label()
        input_days = self.target_days_spin.value()
        target_days = int(input_days * self.available_days / 365.0) if self.available_days > 0 else 0
        if target_days < 1:
            self.config_cap_spin.setValue(0.0)
            self._update_system_scale()
            return
        daily_needs = self._get_all_daily_capacity_needs()
        if not daily_needs:
            QMessageBox.warning(self, "警告", "无可用数据")
            return
        # v3.0: SOC 仿真自动计算每日需求, 排序取百分位
        # v3.0fix: 满充满放——在available_days中挑出target_days个最好的天,
        # 这些天都能满足的最小容量 = 升序跳过最差的(available-target)天,取下一个
        # 例: 365天中选330天 → 升序[365-330]=升序[35] → 跳过最差35天
        daily_needs_sorted = np.sort(daily_needs)  # 升序
        idx = max(0, len(daily_needs_sorted) - target_days)
        cap = float(daily_needs_sorted[idx]) if idx < len(daily_needs_sorted) else 0.0
        # v3.2fix: 可用容量÷DOD=安装容量
        dod_val = self.dod_spin.value() if hasattr(self, 'dod_spin') else int(BESS_DOD_DEFAULT * 100)
        installed_cap = cap / (dod_val / 100.0) if dod_val > 0 else cap
        self.config_cap_spin.setValue(round(installed_cap, 3))
        self._update_system_scale()
        self.update_economic_label()  # v2.9
        self._update_step_indicators()  # v3.2

    def _build_milp_config(self, work: dict):
        """v3.1: 从当前UI状态构建MILP所需的(dataframe, config, dod_val).
        抽取自_run_milp_planning以缩小try块."""
        # 获取省策略时段
        strategy_periods = {}
        if hasattr(self, 'config_manager') and self.config_manager:
            strategy_periods = self.config_manager.get_periods_for_all_months(
                self.province_name) if self.province_name and self.province_name != "无" else {}
        # 获取需量电价
        demand_price = 40
        if hasattr(self, 'settings_model') and self.settings_model:
            for s in self.summaries:
                idx = self._summary_idx_map.get((s.asset_value, s.month_str))
                if idx is not None:
                    bill = self.settings_model.effective_billing(idx)
                    if bill and bill.get('demand_price'):
                        demand_price = bill['demand_price']
                        break
        # 获取折现率
        discount_rate = -1.0
        if hasattr(self, 'econ_discount_spin'):
            discount_rate = self.econ_discount_spin.value()
        # 获取光伏数据
        pv_data = None
        if hasattr(self, '_pv_profile') and self._pv_profile:
            pv_data = {k: v for k, v in self._pv_profile.items()
                       if isinstance(v, np.ndarray) and v.size > 0}
        # 获取峰谷电价
        peak_p, valley_p = 1.1, 0.27
        if hasattr(self, '_get_price_params'):
            peak_p, valley_p = self._get_price_params()
        # v3.2fix: 取真实分时电价时段(尖峰平谷)。原实现只传充放电策略,
        # 而桥接函数按 peak/valley 关键字判价, 会导致电价全部落平段、套利项恒为0。
        tariff_periods = {}
        if self.province_name and self.province_name in PROVINCE_TARIFF_DB:
            raw_periods = PROVINCE_TARIFF_DB[self.province_name].get('periods', [])
            for _mk in work.keys():
                try:
                    _mnum = int(str(_mk).split('-')[1])
                except (IndexError, ValueError):
                    continue
                _sel = None
                for _months, _plist in raw_periods:
                    if _mnum in _months:
                        _sel = _plist
                        break
                if _sel is None and raw_periods:
                    _sel = raw_periods[0][1]
                if _sel:
                    tariff_periods[str(_mnum)] = _sel
        # 桥接数据
        df = bridge_ultra_to_milp(work, strategy_periods=strategy_periods,
                                  pv_data=pv_data, peak_price=peak_p, valley_price=valley_p,
                                  tariff_periods=tariff_periods)
        if df.empty:
            raise ValueError("数据桥接失败")
        # 构建设备
        unit_cap = self.unit_cap_spin.value() or 261.248
        unit_pow = self.unit_power_spin.value() or 125
        unit_price = self.system_cost_spin.value() if hasattr(self, 'system_cost_spin') else 150000
        dod_val = self.dod_spin.value() if hasattr(self, 'dod_spin') else 95
        devices = [MilpDevice(
            capacity=unit_cap * dod_val / 100.0,
            max_c_rate=unit_pow / (unit_cap or 261.248),
            price=unit_price
        )]
        config = MilpConfig(
            devices=devices,
            demands_price={m: demand_price for m in sorted(df['month'].unique())},
            discount_rate=discount_rate,
            lifecycle=25,
        )
        return df, config, dod_val

    @safe_ui_op
    def _run_milp_planning(self):
        """v3.1: MILP 精准容量规划."""
        work = self._get_work_data()
        if not work:
            QMessageBox.warning(self, "警告", "无可用负荷数据")
            return
        self.milp_btn.setEnabled(False)
        self.milp_status_label.setText("⏳ 求解中(8760h MILP, 可能需要数十秒)...")
        QApplication.processEvents()
        try:
            df, config, dod_val = self._build_milp_config(work)
        except Exception as e:
            self.milp_status_label.setText("❌ 配置错误")
            QMessageBox.warning(self, "MILP配置失败", str(e))
            self.milp_btn.setEnabled(True)
            return
        try:
            # v3.1: 求解前数据校验 + 进度反馈
            if len(df) < 24:
                raise ValueError(f"数据量不足: 仅{len(df)}行, 至少需要24行(1天)")
            if df['consume'].max() <= 0:
                raise ValueError("负荷数据全为零或负值")
            self.milp_status_label.setText(f"⏳ MILP求解中({len(df)}行, {df['month'].nunique()}个月)...")
            QApplication.processEvents()
            result = _cached_milp_solve(df, config)
            if result.status in ('optimal', 'feasible'):
                cap = round(result.capacity_kwh * 100.0 / dod_val, 1) if dod_val > 0 else result.capacity_kwh
                self.config_cap_spin.setValue(cap)
                self._update_system_scale()
                self.update_economic_label()
                self.milp_status_label.setText(
                    f"✅ MILP: {cap:.0f}kWh ({result.device_count}台) "
                    f"| {'缓存命中' if result.solve_time_s == 0 else f'求解{result.solve_time_s:.1f}s'} | {result.status}"
                )
            elif result.status == 'timeout':
                self.milp_status_label.setText(f"⏰ 超时({MILP_TIMEOUT_S}s)")
                QMessageBox.warning(self, "MILP超时",
                    f"求解超过{MILP_TIMEOUT_S}秒未完成.\n建议: 减少数据量或使用快速模式")
            else:
                self.milp_status_label.setText(f"❌ {result.status}")
                msg = f"求解器状态: {result.status}\n\n"
                msg += f"数据: {len(df)}行, {df['month'].nunique()}个月\n"
                msg += "建议:\n- 检查负荷数据是否有异常极值\n- 调大设备功率上限或容量上限\n- 关闭需量帽(demand_limit=0)"
                QMessageBox.warning(self, "MILP无解", msg)
        except Exception as e:
            self.milp_status_label.setText("❌ 错误")
            import traceback
            QMessageBox.warning(self, "MILP异常", f"{e}\n\n{traceback.format_exc()[-300:]}")
        finally:
            self.milp_btn.setEnabled(True)

    @safe_ui_op
    def _run_forecast(self):
        """v3.2: 智能负荷预测——5模型竞赛+图表+场景+导出."""
        work = self._get_work_data()
        if not work:
            QMessageBox.warning(self, "提示", "无可用负荷数据")
            return
        all_arr = []; all_dates = []
        for _, d in sorted(work.items()):
            arr = np.asarray(d.get('load_array', []))
            if arr.size > 0:
                all_arr.append(arr)
                all_dates.extend(d.get('date_labels', []))
        if not all_arr:
            QMessageBox.warning(self, "提示", "无有效数据")
            return
        full = np.concatenate(all_arr, axis=0)
        n_pts = full.shape[1]
        freq = int(24 * 60 / n_pts)
        self.forecast_btn.setEnabled(False)
        self.forecast_btn.setText("⏳ 预测中...")
        QApplication.processEvents()
        try:
            cfg = ForecastConfig(horizon_hours=168, freq_minutes=freq, auto_model=True)
            engine = ForecastEngine(cfg)
            result = engine.fit_predict(full, all_dates)
            # ── 对话框 ──
            from PySide6.QtWidgets import (QDialog, QVBoxLayout, QHBoxLayout,
                QLabel, QTextEdit, QTabWidget, QWidget, QPushButton)
            dlg = QDialog(self)
            dlg.setWindowTitle("🔮 智能负荷预测")
            dlg.setMinimumSize(800, 600)
            layout = QVBoxLayout(dlg)
            tabs = QTabWidget()
            # Tab 0: 图表
            tab0 = QWidget()
            t0 = QVBoxLayout(tab0)
            chart_label = QLabel()
            chart_label.setAlignment(Qt.AlignCenter)
            chart_label.setMinimumSize(700, 350)
            pix = result.render_chart()
            chart_label.setPixmap(pix.scaled(750, 380, Qt.KeepAspectRatio, Qt.SmoothTransformation))
            t0.addWidget(chart_label)
            tabs.addTab(tab0, "📈 图表")
            # Tab 1: 报告
            tab1 = QWidget()
            t1 = QVBoxLayout(tab1)
            text = QTextEdit(); text.setReadOnly(True)
            pred = result.point
            peak_idx = np.argmax(pred)
            peak_h = peak_idx * freq / 60
            peak_day = int(peak_h // 24) + 1
            peak_hour = peak_h % 24
            daily_kwh = np.sum(np.maximum(pred, 0)) * freq / 60
            lines = [f"模型: {result.model_name} | MAPE: {result.mape:.1f}% | RMSE: {result.rmse:.0f}kW",
                     f"峰值: {pred[peak_idx]:.0f}kW @ 第{peak_day}天 {peak_hour:.0f}:00",
                     f"谷值: {np.min(pred):.0f}kW | 均值: {np.mean(pred):.0f}kW",
                     f"预测总电量: {daily_kwh:.0f}kWh", ""]
            if result.recommendations:
                lines.append("── 行动建议 ──")
                lines.extend(result.recommendations)
            # v3.2: 特征重要性(基于模型权重和特征)
            lines.append("\n── 影响因素 ──")
            if hasattr(result, 'point') and result.point is not None:
                peak_pred = np.max(result.point)
                lines.append(f"🏭 基础负荷: {np.mean(full[-n_pts:]):.0f}kW (近期24h均值)")
                lines.append(f"📅 时段影响: {'峰段偏高' if 9 <= (np.argmax(result.point)*freq/60)%24 < 21 else '正常'}")
                if result.decomposition and 'holiday' in result.decomposition:
                    h_effect = np.mean(result.decomposition['holiday'])
                    if abs(h_effect) > 1:
                        lines.append(f"🎌 节假日效应: {h_effect:+.0f}kW")
            lines.append(f"🤖 模型: {result.model_name}")
            if result.scenarios:
                lines.append("\n── 场景分析 ──")
                for s, arr in result.scenarios.items():
                    lines.append(f"{s}: 峰值{np.max(arr):.0f}kW 均值{np.mean(arr):.0f}kW")
            # v3.2: 决策链路——预测→容量建议
            cap_est = daily_kwh * 0.35
            lines.append("\n── 决策链路 ──")
            lines.append(f"推荐储能容量: {cap_est:.0f}kWh (基于预测负荷)")
            lines.append(f"推荐储能功率: {peak_pred*0.3:.0f}kW (预测峰值的30%)")
            text.setPlainText('\n'.join(lines))
            t1.addWidget(text)
            tabs.addTab(tab1, "📊 报告")
            # Tab 2: 场景对比
            tab2 = QWidget()
            t2 = QVBoxLayout(tab2)
            t2.addWidget(QLabel("<b>三情景推演</b> (乐观/基准/悲观)"))
            if result.scenarios:
                for s in ['optimistic', 'baseline', 'pessimistic']:
                    if s in result.scenarios:
                        arr = result.scenarios[s]
                        label_map = {'optimistic': '🟢 乐观(-8%)', 'baseline': '🔵 基准', 'pessimistic': '🔴 悲观(+12%)'}
                        t2.addWidget(QLabel(f"{label_map.get(s,s)}: 峰值 {np.max(arr):.0f}kW, "
                            f"谷值 {np.min(arr):.0f}kW, 均值 {np.mean(arr):.0f}kW"))
            tabs.addTab(tab2, "🎯 场景")
            layout.addWidget(tabs)
            # 底部按钮
            btn_row = QHBoxLayout()
            btn_row.addStretch()
            export_btn = QPushButton("📥 导出CSV")
            export_btn.clicked.connect(lambda: self._export_forecast_csv(result, freq))
            btn_row.addWidget(export_btn)
            close_btn = QPushButton("关闭")
            close_btn.clicked.connect(dlg.accept)
            btn_row.addWidget(close_btn)
            layout.addLayout(btn_row)
            dlg.exec()
        except Exception as e:
            QMessageBox.warning(self, "预测失败", str(e))
        finally:
            self.forecast_btn.setEnabled(True)
            self.forecast_btn.setText("🔮 负荷预测")

    def _export_forecast_csv(self, result, freq):
        """导出预测结果为CSV并加入文件列表, 同时触发在线学习."""
        import tempfile, os
        fd, path = tempfile.mkstemp(suffix='.csv', prefix='forecast_')
        os.close(fd)
        result.to_csv(path, freq_minutes=freq)
        # v3.2: 导出时触发在线学习——用历史最后一周做伪反馈
        try:
            work = self._get_work_data()
            all_arr = [np.asarray(d.get('load_array',[])) for d in work.values() if d and 'load_array' in d]
            if all_arr:
                actual = np.concatenate([a for a in all_arr if a.size > 0], axis=0).flatten()
                n_hist = min(len(result.point), len(actual))
                engine = ForecastEngine()
                engine.online_update(actual[-n_hist:], result.point[:n_hist])
        except Exception:
            log.debug("ProfessionalWindow error suppressed", exc_info=True)
            pass
        QMessageBox.information(self, "导出完成", f"已保存+反馈学习:\n{path}")
        # 加入文件列表
        if hasattr(self, '_on_files_dropped'):
            self._on_files_dropped([path])
        elif hasattr(self, 'parent') and hasattr(self.parent(), '_on_files_dropped'):
            self.parent()._on_files_dropped([path])

