    def _restore_panel_states(self, groups):
        """v3.2: 恢复折叠面板状态."""
        if hasattr(self, 'config_manager') and self.config_manager:
            states = self.config_manager.app_set('panel_states', {})
            for name, gb in groups.items():
                if name in states:
                    gb.setChecked(states[name])

    def _run_mpc(self):
        """v3.2: MPC 模型预测控制——滚动优化充放策略."""
        work = self._get_work_data()
        if not work:
            QMessageBox.warning(self, "提示", "无可用负荷数据")
            return
        all_arr = [np.asarray(d.get('load_array',[])) for d in work.values() if d and 'load_array' in d]
        if not all_arr:
            QMessageBox.warning(self, "提示", "无有效数据")
            return
        full = np.concatenate([a for a in all_arr if a.size > 0], axis=0)
        n_pts = full.shape[1]
        cap = self.config_cap_spin.value() if hasattr(self,'config_cap_spin') else 500
        pow_kw = self.unit_power_spin.value() if hasattr(self,'unit_power_spin') else 250
        self.mpc_btn.setEnabled(False)
        self.mpc_btn.setText("⏳ 优化中...")
        QApplication.processEvents()
        try:
            cfg = MPCConfig(battery_capacity_kwh=cap, battery_power_kw=pow_kw)
            controller = MPCController(cfg)
            result = controller.optimize(full)
            # 显示结果
            from PySide6.QtWidgets import QDialog, QVBoxLayout, QLabel, QTextEdit
            dlg = QDialog(self)
            dlg.setWindowTitle("🎯 MPC 滚动优化结果")
            dlg.setMinimumSize(600, 400)
            layout = QVBoxLayout(dlg)
            layout.addWidget(QLabel(f"<b>MPC 24h滚动优化</b> | "
                f"充电:{result.total_charge_kwh:.0f}kWh | 放电:{result.total_discharge_kwh:.0f}kWh | "
                f"削峰:{result.peak_reduction_kw:.0f}kW"))
            text = QTextEdit(); text.setReadOnly(True)
            lines = [f"{'='*40}", "       MPC 模型预测控制报告", f"{'='*40}", ""]
            lines.append(f"电池: {cap:.0f}kWh / {pow_kw:.0f}kW")
            lines.append(f"总充电: {result.total_charge_kwh:.0f}kWh")
            lines.append(f"总放电: {result.total_discharge_kwh:.0f}kWh")
            lines.append(f"预估节省: ¥{result.total_saving:.0f}")
            lines.append(f"削峰量: {result.peak_reduction_kw:.0f}kW")
            if result.soc_trajectory is not None:
                lines.append(f"终态SOC: {result.soc_trajectory[-1]*100:.0f}%")
            if result.recommendations:
                lines.append("\n── 建议 ──")
                lines.extend(result.recommendations)
            text.setPlainText('\n'.join(lines))
            layout.addWidget(text)
            dlg.exec()
        except Exception as e:
            QMessageBox.warning(self, "MPC失败", str(e))
        finally:
            self.mpc_btn.setEnabled(True)
            self.mpc_btn.setText("🎯 MPC控制")

    def _update_step_indicators(self):
        """v3.2: 更新五步进度条状态."""
        if not hasattr(self, '_step_labels'):
            return
        # 步骤1: 导入
        work = self._get_work_data()
        s1 = 'done' if work and len(work) > 0 else 'pending'
        # 步骤2: 分析
        s2 = 'done' if hasattr(self, 'charge_segments_dict') and len(self.charge_segments_dict) > 0 else 'pending'
        # 步骤3: 配置
        cap = self.config_cap_spin.value() if hasattr(self, 'config_cap_spin') else 0
        s3 = 'done' if cap > 0 else 'pending'
        # 步骤4: 经济
        econ_text = self.econ_label.text() if hasattr(self, 'econ_label') else ''
        s4 = 'done' if econ_text and 'NPV' in econ_text else 'pending'
        # 步骤5: 报告
        s5 = getattr(self, '_report_generated', False)
        status = {'import': s1, 'analyze': s2, 'config': s3, 'econ': s4, 'report': s5}
        colors = {'done': '#4CAF50', 'pending': '#BDBDBD', 'active': '#FF9800'}
        for key, lbl in self._step_labels.items():
            s = status.get(key, 'pending')
            c = colors.get(s, '#BDBDBD')
            icon = {'done': '✅', 'pending': '⏸', 'active': '⏳'}.get(s, '⏸')
            text = {'import': '导入', 'analyze': '分析', 'config': '配置', 'econ': '经济', 'report': '报告'}.get(key, '')
            lbl.setText(f'{icon} {text}')
            lbl.setStyleSheet(f'font-size:11px; font-weight:bold; color:{c}; background:transparent; padding:2px 4px;')

    def _on_step_clicked(self, step_key):
        """v3.2: 点击步骤跳转."""
        actions = {
            'import': lambda: None,  # 导入在主窗口完成
            'analyze': self._recalc_spaces,
            'config': self._calc_capacity_from_days,
            'econ': self.update_economic_label,
            'report': self._generate_proposal,
        }
        if step_key in actions and actions[step_key]:
            actions[step_key]()
            self._update_step_indicators()

    def _run_full_flow(self):
        """v3.2: 一键全流程——5步自动串行, 实时进度反馈."""
        steps = [
            ('analyze', '📊 分析中...', self._recalc_spaces),
            ('config', '🔋 配置中...', self._calc_capacity_from_days),
            ('econ', '💰 计算中...', self.update_economic_label),
        ]
        for key, label, fn in steps:
            if key in self._step_labels:
                self._step_labels[key].setText(label)
                self._step_labels[key].setStyleSheet('font-size:11px; font-weight:bold; color:#FF9800; background:transparent; padding:2px 4px;')
            QApplication.processEvents()
            try:
                fn()
                if key in self._step_labels:
                    self._step_labels[key].setText({'analyze':'✅ 分析','config':'✅ 配置','econ':'✅ 经济'}[key])
                    self._step_labels[key].setStyleSheet('font-size:11px; font-weight:bold; color:#4CAF50; background:transparent; padding:2px 4px;')
            except Exception as e:
                if key in self._step_labels:
                    self._step_labels[key].setText('❌ 失败')
                QMessageBox.warning(self, "步骤失败", f"{key}: {e}")
                break
        self._update_step_indicators()
        # v3.2: 全流程完成摘要
        cap = self.config_cap_spin.value() if hasattr(self, 'config_cap_spin') else 0
        unit_cap = self.unit_cap_spin.value() if hasattr(self, 'unit_cap_spin') else 261.248
        num_units = max(1, round(cap / unit_cap)) if unit_cap > 0 else 1
        econ_text = self.econ_label.text() if hasattr(self, 'econ_label') else ''
        summary = f"✅ 全流程完成\n\n推荐配置: {cap:.0f}kWh ({num_units}台)\n"
        if econ_text:
            summary += f"{econ_text}\n"
        summary += "\n下一步: 📋 方案建议书 或 🌐 HTML报告"
        QMessageBox.information(self, "一键全流程", summary)
        self._full_flow_btn.setText("✅ 完成")
        QTimer.singleShot(3000, lambda: self._full_flow_btn.setText("🚀 一键全流程"))

    def _run_pareto_analysis(self):
        """v3.2: 四目标Pareto对比——真经济引擎+真PV数据."""
        from PySide6.QtWidgets import QDialog, QTableWidget, QTableWidgetItem, QHeaderView
        from PySide6.QtGui import QColor
        strategies = ["最小可行容量", "满载利用率"]
        if hasattr(self, 'est_combo'):
            for idx in range(self.est_combo.count()):
                txt = self.est_combo.itemText(idx)
                if txt not in strategies:
                    strategies.append(txt)
        results = []
        orig_strategy = self.est_combo.currentText() if hasattr(self, 'est_combo') else strategies[0]
        orig_cap = self.config_cap_spin.value()
        for strat in strategies:
            if hasattr(self, 'est_combo'):
                idx = self.est_combo.findText(strat)
                if idx >= 0:
                    self.est_combo.setCurrentIndex(idx)
            self._calc_capacity_from_days()
            cap = self.config_cap_spin.value()
            unit_cap = self.unit_cap_spin.value() or 261.248
            num_units = max(1, round(cap / unit_cap)) if unit_cap > 0 else 1
            unit_price = self.system_cost_spin.value() if hasattr(self, 'system_cost_spin') else 150000
            total_investment = num_units * unit_price
            # v3.2fix: 真经济引擎
            discount = self.econ_discount_spin.value() if hasattr(self, 'econ_discount_spin') else 0.06
            lifecycle = 25
            degradation = 0.02  # 年衰减2%
            # 年收益: 调用现有经济模型
            try:
                total_ch_kwh = sum(float(np.nansum(s)) for segs in self.charge_segments_dict.values() for s in segs)
                total_dis_kwh = sum(float(np.nansum(s)) for segs in self.discharge_segments_dict.values() for s in segs)
                peak_p, valley_p = self._get_price_params() if hasattr(self, '_get_price_params') else (1.1, 0.27)
                annual_revenue = total_dis_kwh * peak_p - total_ch_kwh * valley_p
            except Exception:
                log.debug("ProfessionalWindow fallback", exc_info=True)
                annual_revenue = cap * 365 * 0.35
            # NPV with degradation
            npv_val = -total_investment
            for y in range(1, lifecycle + 1):
                cf = annual_revenue * ((1 - degradation) ** (y - 1))
                # 电芯更换(第10年)
                if y == 10:
                    cf -= total_investment * 0.6
                npv_val += cf / ((1 + discount) ** y)
            # 回收期
            cumulative = -total_investment
            payback = lifecycle
            for y in range(1, lifecycle + 1):
                cf = annual_revenue * ((1 - degradation) ** (y - 1))
                cumulative += cf
                if cumulative >= 0:
                    payback = y - 1 + (cumulative - cf) / max(cf, 1)
                    break
            # v3.2fix: 真光利率——从光伏数据计算
            pv_rate = 0
            try:
                work = self._get_work_data()
                all_loads = []
                pv_data = getattr(self, '_pv_profile', None)
                if pv_data and work:
                    total_pv = 0; total_load = 0
                    for m, d in work.items():
                        arr = np.asarray(d.get('load_array', []))
                        total_load += np.sum(np.maximum(arr, 0))
                        if m in pv_data:
                            pv_arr = np.asarray(pv_data[m])
                            total_pv += np.sum(np.maximum(pv_arr, 0))
                    if total_pv > 0:
                        pv_consumed = min(total_pv, total_load)
                        pv_rate = min(95, (pv_consumed / max(total_pv, 1)) * 100)
                    else:
                        pv_rate = min(95, (cap / max(total_load * 0.3, 1)) * 100)
                else:
                    pv_rate = 0
            except Exception:
                log.debug("ProfessionalWindow fallback", exc_info=True)
                pv_rate = 0
            results.append({
                'strategy': strat, 'capacity': cap, 'units': num_units,
                'investment': total_investment, 'annual_rev': annual_revenue,
                'payback': payback, 'npv': npv_val, 'pv_rate': pv_rate,
            })
        if hasattr(self, 'est_combo'):
            idx = self.est_combo.findText(orig_strategy)
            if idx >= 0:
                self.est_combo.setCurrentIndex(idx)
        self.config_cap_spin.setValue(orig_cap)
        self._update_system_scale()
        dlg = QDialog(self)
        dlg.setWindowTitle("📊 四目标 Pareto 对比")
        dlg.setMinimumSize(800, 400)
        layout = QVBoxLayout(dlg)
        layout.addWidget(QLabel("<b>四目标并排对比</b> — 不同策略下经济/环保指标"))
        table = QTableWidget(len(results), 8)
        table.setHorizontalHeaderLabels([
            "策略", "容量(kWh)", "台数", "投资(万元)",
            "年收益(万元)", "回收期(年)", "25年NPV(万元)", "光利率(%)"
        ])
        for r, row in enumerate(results):
            vals = [row['strategy'], f"{row['capacity']:.0f}", str(row['units']),
                    f"{row['investment']/10000:.1f}", f"{row['annual_rev']/10000:.1f}",
                    f"{row['payback']:.1f}", f"{row['npv']/10000:.1f}", f"{row['pv_rate']:.0f}"]
            for c, v in enumerate(vals):
                item = QTableWidgetItem(v)
                item.setTextAlignment(Qt.AlignCenter)
                if c == 5 and row['payback'] <= 5:
                    item.setBackground(QColor(200, 255, 200))
                if c == 6 and row['npv'] > 0:
                    item.setBackground(QColor(200, 230, 255))
                table.setItem(r, c, item)
        table.resizeColumnsToContents()
        table.horizontalHeader().setSectionResizeMode(QHeaderView.Stretch)
        layout.addWidget(table)
        layout.addWidget(QLabel("<i>回收期≤5年(绿底)=投资方认可 | NPV>0(蓝底)=盈利 | 25年折现率=6%</i>"))
        dlg.exec()

    def _calc_days_from_capacity(self):
        cap = self.config_cap_spin.value()
        daily_needs = np.array(self._get_all_daily_capacity_needs())
        if len(daily_needs) == 0:
            self.satisfy_days_label.setText("满足天数: 0")
            return
        satisfied = np.sum(daily_needs <= cap)
        self.satisfy_days_label.setText(f"满足天数: {satisfied}")
        self.actual_satisfy_label.setText(f"实际满足天数: {satisfied}")
        effective = int(satisfied * 365.0 / self.available_days) if self.available_days > 0 else 0
        self.effective_satisfy_label.setText(f"等效满足天数: {effective}")
        self.update_economic_label()  # v2.9

    def _update_system_scale(self):
        cap = self.config_cap_spin.value()
        unit_cap = self.unit_cap_spin.value()
        unit_pow = self.unit_power_spin.value()
        # v3.0: DOD 影响公式
        dod_val = self.dod_spin.value() if hasattr(self, 'dod_spin') else 95
        cap_before_dod = cap * dod_val / 100.0 if dod_val > 0 else cap
        dod_info = f" DOD={dod_val}%(实际可用{cap_before_dod:.1f}kWh)"
        if unit_cap > 0:
            num_units = max(1, int(math.ceil(cap / unit_cap)))
            total_pow = num_units * unit_pow
            total_cap = num_units * unit_cap
            self.system_result_label.setText(
                f"单柜数量: {num_units} 台,系统总功率: {total_pow:.1f} kW,系统总容量: {total_cap:.1f} kWh | {dod_info}"
            )
        else:
            self.system_result_label.setText(f"单柜容量必须大于0 | {dod_info}")

    def _show_pv_feedback(self):
        """显示光伏返送详情对话框"""
        work_data = self._get_work_data()
        if not work_data:
            return
        month = self.daily_month_combo.currentText()
        key = (self.summaries[0].asset_value if self.summaries else None, month)
        idx = self._summary_idx_map.get(key)
        mult = self.settings_model.effective_multiplier(idx) if idx is not None else self.global_multiplier
        dlg = PVFeedbackDialog(work_data, mult, self)
        dlg.exec()

    def _run_dispatch_simulation(self):
        """v2.11: 运行逐日充放电调度仿真"""
        work_data = self._get_work_data()
        if not work_data:
            QMessageBox.warning(self, "警告", "无可用数据")
            return
        cap = self.config_cap_spin.value()
        power = self.rated_power or 100.0
        periods = self.config_manager.get_periods_for_all_months(self.province_name).get('1', []) if self.province_name else []
        first_data = list(work_data.values())[0]
        result = simulate_daily_dispatch(
            np.array(first_data['load_array']), first_data['time_labels'],
            periods, cap, power,
            transformer_capacity=getattr(self, 'transformer_capacity', None)
        )
        summary = (f'📡 调度仿真结果\n\n'
                   f"月均充电量: {result['charge_kwh'].mean():.0f} kWh\n"
                   f"月均放电量: {result['discharge_kwh'].mean():.0f} kWh\n"
                   f"终态SOC: {result['final_soc']:.1f}%\n"
                   f"最大SOC: {result['soc_trajectory'].max():.1f}%\n"
                   f"最小SOC: {result['soc_trajectory'].min():.1f}%"
                   + (f"\n⚠ 变压器限功率事件: {result['transformer_limit_events']}次" if result.get('transformer_limit_events', 0) > 0 else ""))
        QMessageBox.information(self, "调度仿真", summary)

    def _run_monte_carlo(self):
        """v2.17: 运行 Monte Carlo 风险分析 - 支持取消+进度.
        NOTE: 参数用正态分布近似(行业标准),适合敏感性分析.
        电价政策离散跳变无法模拟,投资决策建议结合场景分析."""
        if not self.monthly_data:
            QMessageBox.warning(self, "警告", "无可用数据,请先加载负荷数据.")
            return
        # v2.19: 防重复触发
        with self._compute_lock:
            if self._is_computing:
                return
            self._is_computing = True
        self._mc_cancel = threading.Event()

        # 切换按钮为取消按钮
        self.mc_btn.setText("⏹ 取消模拟")
        self.mc_btn.setEnabled(True)
        with suppress(Exception):
            self.mc_btn.clicked.disconnect()
        self.mc_btn.clicked.connect(self._mc_cancel.set)
        QApplication.processEvents()

        def _on_progress(current, total):
            self.mc_btn.setText(f"🎲 {current}/{total}")
            QApplication.processEvents()

        try:
            base_peak, base_valley = self._get_price_params()

            def econ_fn(**overrides):
                peak = overrides.get('peak_price', base_peak)
                valley = overrides.get('valley_price', base_valley)
                deg = overrides.get('annual_degradation', 0.015)
                cost = overrides.get('system_cost_per_kwh', 750.0)
                demand = overrides.get('demand_charge', 30.0)
                return self.calc_economic_summary(
                    peak_price=peak, valley_price=valley,
                    annual_degradation=deg, system_cost_per_kwh=cost,
                    demand_charge=demand
                )

            uncertainties = {
                'peak_price': {'base': base_peak, 'std': base_peak * 0.08, 'type': 'normal', 'min': base_peak * 0.7},
                'valley_price': {'base': base_valley, 'std': base_valley * 0.1, 'type': 'normal', 'min': base_valley * 0.5},
                'annual_degradation': {'base': 0.015, 'std': 0.005, 'type': 'normal', 'min': 0.005, 'max': 0.04},
                'system_cost_per_kwh': {'base': 750.0, 'std': 100.0, 'type': 'normal', 'min': 600.0},
                'demand_charge': {'base': 30.0, 'std': 5.0, 'type': 'normal', 'min': 15.0},
            }

            result = run_monte_carlo(econ_fn, uncertainties, n_simulations=1000,
                                     cancel_event=self._mc_cancel, progress_callback=_on_progress)
            if result.get('cancelled'):
                ToastManager.show(self, f"模拟已取消(完成{result.get('n_simulations', 0)}次)", kind='info')
                return

            summary = (f'🎲 Monte Carlo 风险分析 (1000次模拟)\n\n'
                       f"💰 IRR: P10={result['irr']['p10']}% | P50={result['irr']['p50']}% | P90={result['irr']['p90']}% | 均值={result['irr']['mean']}%\n\n"
                       f"💵 NPV: P10=¥{result['npv']['p10']:,.0f} | P50=¥{result['npv']['p50']:,.0f} | P90=¥{result['npv']['p90']:,.0f}\n\n"
                       f"📅 回收期: P10={result['payback']['p10']}年 | P50={result['payback']['p50']}年 | P90={result['payback']['p90']}年\n\n"
                       f'⚠️ 风险评估:\n'
                       f"  亏损概率 (IRR<0): {result['loss_probability']}%\n"
                       f"  低于行业基准8%概率: {result['below_benchmark_probability']}%\n\n"
                       f"💡 解读: P90 IRR={result['irr']['p90']}% 意味着90%的模拟场景下IRR高于此值,\n"
                       f'   只有10%的极端不利场景会低于此值.若P90仍>基准,项目风险可控.')
            QMessageBox.information(self, "Monte Carlo 分析", summary)
            self._show_mc_histogram(result)  # v2.25: 收益分布直方图
        except Exception as e:
            QMessageBox.critical(self, "模拟失败", str(e))
        finally:
            # v2.17: 恢复按钮状态和信号连接
            self._mc_cancel = None
            with suppress(Exception):
                self.mc_btn.clicked.disconnect()
            self.mc_btn.clicked.connect(self._run_monte_carlo)
            self.mc_btn.setEnabled(True)
            self.mc_btn.setText("🎲 蒙特卡洛模拟")
            self._is_computing = False

    def _run_margin_analysis(self):
        """v2.25: 边际收益--枚举容量找最优"""
        work_data = self._get_work_data()
        if not work_data: return
        first = list(work_data.values())[0]
        arr = np.asarray(first['load_array'])
        result = EnergyStorageEngineer.sweep_capacity(
            arr, time_labels=first.get('time_labels',[]),
            province=self.province_name,
            system_cost_per_kwh=ECON_SYSTEM_COST_PER_KWH)
        QMessageBox.information(self, "边际收益",
            f"最优: {result['best_power']}kW/{result['best_capacity']}kWh\n"
            f"回收期: {result['best_payback']:.1f}年 | 年收益: ¥{result['best_revenue']:,.0f}")

    def _run_stress_test(self):
        """v2.28fix: 极端日压力测试 - 对比峰值功率与额定功率(原bug: 误对比kWh容量)"""
        work_data = self._get_work_data()
        if not work_data: return
        overload_days = total_days = 0
        rated_power = self.rated_power or 100.0  # kW
        for data in work_data.values():
            arr = np.asarray(data['load_array'])
            if arr.ndim != 2: continue
            for d in range(arr.shape[0]):
                total_days += 1
                if float(np.nanmax(arr[d])) * 1.2 > rated_power: overload_days += 1
        if total_days > 0:
            pct = overload_days / total_days * 100
            level = "🔴" if pct > 20 else ("🟡" if pct > 5 else "🟢")
            QMessageBox.information(self, "压力测试",
                f"{level} 负荷+20%过载: {overload_days}/{total_days}天({pct:.1f}%)")

    def _show_space_heatmap(self):
        """v3.2fix: seaborn 热力图——全年充放电空间一览."""
        import seaborn as sns
        import matplotlib.pyplot as plt
        months = sorted(self._get_work_data().keys())
        if not months:
            QMessageBox.warning(self, "提示", "无可用数据")
            return
        c_data, d_data = [], []
        for m in months:
            c_segs = self.charge_segments_dict.get(m, [])
            d_segs = self.discharge_segments_dict.get(m, [])
            c_data.append([np.nansum(s) if len(s) > 0 else 0 for s in c_segs])
            d_data.append([np.nansum(s) if len(s) > 0 else 0 for s in d_segs])
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 5))
        c_arr = np.array(c_data).T if c_data else np.zeros((max(1, len(self.charge_labels or ['C']), 12)))
        d_arr = np.array(d_data).T if d_data else np.zeros((max(1, len(self.discharge_labels or ['D']), 12)))
        sns.heatmap(c_arr, ax=ax1, xticklabels=months,
                    yticklabels=self.charge_labels or ['Charge'],
                    cmap='Blues', annot=True, fmt='.0f')
        ax1.set_title('月度充电空间 (kWh)')
        sns.heatmap(d_arr, ax=ax2, xticklabels=months,
                    yticklabels=self.discharge_labels or ['Discharge'],
                    cmap='Oranges', annot=True, fmt='.0f')
        ax2.set_title('月度放电空间 (kWh)')
        fig.tight_layout()
        fig.show()

    def _show_demand_peak_comparison(self):
        """v2.25: 削峰前后需量对比柱状图"""
        work_data = self._get_work_data()
        if not work_data: return
        months, before, after = [], [], []
        rated = self.rated_power or 100
        for m, data in sorted(work_data.items()):
            arr = np.asarray(data['load_array'])
            if arr.ndim != 2: continue
            peak = float(max(np.nanmax(arr[d]) for d in range(arr.shape[0])))
            months.append(m[-2:]); before.append(peak)
            after.append(max(0, peak - min(rated, peak * 0.7)))
        try:
            import matplotlib.pyplot as plt
            fig, ax = plt.subplots(figsize=(10, 5))
            x = range(len(months)); w = 0.35
            ax.bar([i-w/2 for i in x], before, w, label='削峰前', color='#E74C3C', alpha=0.7)
            ax.bar([i+w/2 for i in x], after, w, label='削峰后', color='#27AE60', alpha=0.7)
            ax.set_xticks(x); ax.set_xticklabels(months); ax.set_ylabel('kW')
            ax.set_title('削峰前后月最大需量对比'); ax.legend()
            fig.tight_layout()
            buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
            plt.close(fig)
            pix = QPixmap(); pix.loadFromData(buf.read(), "PNG")
            dlg = QDialog(self); dlg.setWindowTitle("削峰对比"); dlg.resize(700, 400)
            lbl = QLabel(); lbl.setPixmap(pix.scaled(680, 380, Qt.KeepAspectRatio, Qt.SmoothTransformation))
            QVBoxLayout(dlg); dlg.layout().addWidget(lbl); dlg.exec()
        except Exception: log.warning("削峰对比预览失败", exc_info=True)

    def _validate_dispatch(self):
        """v2.25: 校验模拟后调度可行性"""
        try:
            cap = self.config_cap_spin.value()
            if cap <= 0: return
            first = list(self._get_work_data().values())[0]
            arr = np.asarray(first['load_array'])
            daily_ch = np.sum(np.maximum(0, np.minimum(arr, self.rated_power or 100)), axis=1)
            if np.mean(daily_ch) > cap * 0.95:
                ToastManager.show(self, "⚠ 充电需求接近容量上限", 'warning', 4000)
        except Exception: log.warning("容量校验失败", exc_info=True)

    def _calc_net_demand_saving(self, work_data, demand_charge):
        """v3.0: 净需量法——用储能充放电数据重构净负荷,计算真实需量节省."""
        if not self.charge_segments_dict or not self.discharge_segments_dict:
            return 0.0
        total_saving = 0.0
        for month_str, data in work_data.items():
            arr = np.asarray(data['load_array'], dtype=np.float64)
            if arr.ndim != 2 or arr.shape[0] == 0:
                continue
            n_days, n_points = arr.shape
            time_labels = data.get('time_labels', [])
            if not time_labels:
                time_labels = [f'{i*24/n_points:.0f}:00' for i in range(n_points)]
            c_segs = self.charge_segments_dict.get(month_str, [])
            d_segs = self.discharge_segments_dict.get(month_str, [])
            if not c_segs and not d_segs:
                continue
            net_load = arr.copy()
            for d_idx in range(min(len(d_segs), n_days)):
                seg = np.asarray(d_segs[d_idx])
                if seg.ndim == 1 and len(seg) == n_points:
                    net_load[d_idx] -= seg
            for c_idx in range(min(len(c_segs), n_days)):
                seg = np.asarray(c_segs[c_idx])
                if seg.ndim == 1 and len(seg) == n_points:
                    net_load[c_idx] += seg
            orig_max, _ = _calc_sliding_window_demand(arr, time_labels)
            net_max, _ = _calc_sliding_window_demand(np.maximum(net_load, 0), time_labels)
            total_saving += max(0, orig_max - net_max) * demand_charge
        return total_saving

    def _run_battery_comparison(self):
        """v2.26: 电池选型对比"""
        work_data = self._get_work_data()
        if not work_data: return
        first = list(work_data.values())[0]
        arr = np.asarray(first['load_array'])
        results = compare_battery_options(arr, time_labels=first.get('time_labels',[]),
                                           date_labels=first.get('date_labels',[]),
                                           province=self.province_name)
        lines = ["🔋 电池选型对比 (按回收期排序)\n"]
        for i, r in enumerate(results[:5]):
            icon = "🥇" if i == 0 else ("🥈" if i == 1 else ("🥉" if i == 2 else f"{i+1}."))
            lines.append(f"{icon} {r['name']} ({r['chemistry']})")
            lines.append(f"   回收期:{r['payback_years']:.1f}年 | 收益:¥{r['annual_revenue']:,.0f}")
            lines.append(f"   成本:{r['cost_per_kwh']}元/kWh | 循环:{r['cycle_life']}次 | 安全:{r['safety']}")
        QMessageBox.information(self, "电池选型对比", '\n'.join(lines))

    def _show_mc_histogram(self, mc_result):
        """v2.25: 绘制Monte Carlo收益分布直方图"""
        try:
            irr_samples = mc_result.get('irr_samples', [])
            if not irr_samples or len(irr_samples) < 10:
                return
            import matplotlib.pyplot as plt
            fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))
            ax1.hist(irr_samples, bins=30, color='steelblue', edgecolor='white', alpha=0.8)
            ax1.axvline(x=mc_result['irr']['p50'], color='red', ls='--', label=f"P50={mc_result['irr']['p50']}%")
            ax1.axvline(x=mc_result['irr']['p90'], color='orange', ls=':', label=f"P90={mc_result['irr']['p90']}%")
            ax1.set_xlabel('IRR (%)'); ax1.set_ylabel('频次'); ax1.set_title('IRR概率分布')
            ax1.legend()
            pb = mc_result.get('payback_samples', [])
            if pb:
                ax2.hist(pb, bins=25, color='darkorange', edgecolor='white', alpha=0.8)
                ax2.axvline(x=mc_result['payback']['p50'], color='red', ls='--')
                ax2.set_xlabel('回收期(年)'); ax2.set_title('回收期分布')
            fig.tight_layout()
            buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
            plt.close(fig)
            pix = QPixmap(); pix.loadFromData(buf.read(), "PNG")
            if pix.width() > 100:
                dlg = QDialog(self); dlg.setWindowTitle("收益分布直方图")
                dlg.resize(900, 450)
                lbl = QLabel(); lbl.setPixmap(pix.scaled(880, 430, Qt.KeepAspectRatio, Qt.SmoothTransformation))
                layout = QVBoxLayout(dlg); layout.addWidget(lbl); dlg.exec()
        except Exception:
            log.debug("ProfessionalWindow error suppressed", exc_info=True)

    def _import_market_price(self):
        """v2.18: 导入市场化电价CSV/JSON文件"""
        path, _ = QFileDialog.getOpenFileName(
            self, "导入市场化电价", "",
            "电价文件 (*.csv *.json);;CSV (*.csv);;JSON (*.json)")
        if not path:
            return
        try:
            result = import_market_prices(path)
            if 'error' in result:
                QMessageBox.warning(self, "导入失败", result['error'])
                return
            prov = result.get('province', result.get('provinces', ['未知'])[0] if 'provinces' in result else '未知')
            count = result.get('count', 1)
            QMessageBox.information(
                self, "导入成功",
                f"已导入 {count} 个省份的市场化电价数据.\n"
                f"省份: {prov if isinstance(prov, str) else ', '.join(prov)}\n\n"
                f'提示:导入后请重新选择省份以使用最新电价.')
            # 刷新省份列表
            if hasattr(self, '_update_province_list'):
                self._update_province_list()
        except Exception as e:
            QMessageBox.critical(self, "导入失败", f"解析电价文件时出错:\n{str(e)[:200]}")

    def _open_scenario_comparison(self):
        """v2.15: 打开场景对比对话框"""
        if not self.monthly_data:
            QMessageBox.warning(self, "警告", "请先加载负荷数据")
            return
        # 构建经济计算闭包
        def _econ_fn(power, capacity, dod, efficiency, system_cost, demand_charge, project_years):
            return self.calc_economic_summary(
                peak_price=getattr(self, '_sensitivity_peak_price', 1.0),
                valley_price=getattr(self, '_sensitivity_valley_price', 0.35),
                demand_charge=demand_charge,
                system_cost_per_kwh=system_cost,
                annual_degradation=getattr(self, '_sensitivity_degradation', 0.015),
                project_years=project_years,
                dod=min(dod / 100.0 if dod > 1 else dod, 0.95)
            )
        base_config = {'power_kW': self.rated_power or 100, 'capacity_kWh': self.config_cap_spin.value(),
                       'dod': self.dod_spin.value(), 'efficiency': self.efficiency_spin.value()}
        dlg = ScenarioComparisonDialog(self, _econ_fn, base_config)
        if dlg.exec() == QDialog.Accepted:
            best = dlg.result
            if best:
                summary = (f"✅ 已选择最优方案\n\nIRR: {best.get('irr','?')}%\nNPV: ¥{best.get('npv',0):,.0f}\n"
                           f"回收期: {best.get('payback_years','?')}年")
                QMessageBox.information(self, "场景对比结果", summary)

    def _toggle_sensitivity_panel(self, checked):
        """v2.15: 展开/收起敏感性分析滑块面板"""
        if checked:
            if not hasattr(self, '_sensitivity_panel') or self._sensitivity_panel is None:
                self._sensitivity_panel = SensitivitySliderPanel()
                self._sensitivity_panel.param_changed.connect(self._on_sensitivity_changed)
                if hasattr(self, '_left_panel') and self._left_panel:
                    self._left_panel.layout().addWidget(self._sensitivity_panel)
            self._sensitivity_panel.show()
        elif hasattr(self, '_sensitivity_panel') and self._sensitivity_panel:
            # 从布局中移除并隐藏,防止反复 toggle 累积
            self._sensitivity_panel.hide()
            if hasattr(self, '_left_panel') and self._left_panel:
                self._left_panel.layout().removeWidget(self._sensitivity_panel)
            self._sensitivity_panel.setParent(None)
            with suppress(Exception):
                self._sensitivity_panel.param_changed.disconnect()
            self._sensitivity_panel.deleteLater()
            self._sensitivity_panel = None

    def _on_sensitivity_changed(self, params):
        """敏感性滑块变化时实时更新经济指标"""
        if not self.monthly_data:
            return
        try:
            self._sensitivity_peak_price = params.get('peak_price', 1.0)
            self._sensitivity_valley_price = params.get('valley_price', 0.35)
            self._sensitivity_system_cost = params.get('system_cost', 1.4) * 1000  # 元/Wh -> 元/kWh
            self._sensitivity_degradation = params.get('degradation', 0.015)
            dod_val = params.get('dod', 0.90)  # v2.21fix: 敏感性分析取DOD而非效率值
            econ = self.calc_economic_summary(
                peak_price=self._sensitivity_peak_price,
                valley_price=self._sensitivity_valley_price,
                system_cost_per_kwh=self._sensitivity_system_cost,
                annual_degradation=min(self._sensitivity_degradation, 0.04),
                dod=min(dod_val, 0.95)
            )
            for key in params:
                self._sensitivity_panel.update_results(key, econ.get('irr', 0), econ.get('npv', 0))
            self.update_economic_label()
        except Exception as e:
            log.debug(f"敏感性分析更新失败: {e}")

    # region 经济分析与滑动窗口需量 (v2.9)
    # v2.28fix: 充放电效率统一使用全局常量,与_recalc_spaces保持一致
    EFF_CHARGE = BESS_EFF_CHARGE    # 0.93 (含PCS+线损+辅助能耗)
    EFF_DISCHARGE = BESS_EFF_DISCHARGE  # 0.93
    # v3.0fix: 运行时验证效率值合法性(防止误配置导致充放方向错误)
    assert 0.5 < EFF_CHARGE <= 1.0, f"充电效率异常: {EFF_CHARGE}"
    assert 0.5 < EFF_DISCHARGE <= 1.0, f"放电效率异常: {EFF_DISCHARGE}"
    _EFF_ROUNDTRIP = BESS_EFF_ROUNDTRIP  # ~0.865

    def calc_economic_summary(self, peak_price=1.0, valley_price=0.3, flat_price=0.6,
                               demand_charge=30.0, system_cost_per_kwh=750.0,
                               annual_degradation=0.015, project_years=10, discount_rate=0.06,
                               rated_cycle_life=6000, dod=0.90):
        """v2.19: 全投资财务模型 - NPV/IRR/回收期/容量电价综合计算.

        收益构成(互斥校验):
            - 用户侧: 峰谷套利 + 需量节省 (storage_type='user_side')
            - 电网侧: 容量电价 (storage_type='grid_side')

        关键修正:
            - 充放电效率: 电网端=电池端xeff修正 (v2.16)
            - 首年衰减: yxdegradation (v2.19fix, 原为(y-1)高估首年收益)
            - IRR: 牛顿法迭代<=50次, 范围限制0-100%, 边界值标记irr_risk
            - 电池更换: 按循环寿命判定, 成本系数0.4

        Args:
            peak_price: 峰时电价(元/kWh)
            valley_price: 谷时电价(元/kWh)
            flat_price: 平时电价(元/kWh)
            demand_charge: 需量电价(元/kW/月)
            system_cost_per_kwh: 系统单价(元/kWh)
            annual_degradation: 年容量衰减率(默认0.015=1.5%)
            project_years: 项目周期(年)
            discount_rate: 折现率
            rated_cycle_life: 电池循环寿命(次)
            dod: 放电深度

        Returns:
            dict: annual_charge_kwh, annual_discharge_kwh, annual_arbitrage,
                  demand_saving, capacity_revenue, capacity_ratio,
                  annual_benefit, system_cost, payback_years, npv, irr,
                  irr_risk, price_spread, reducible_kw, annual_cycles,
                  battery_life_years, replacement_year

        References:
            - NREL SAM v2023: Financial model for battery storage
            - 能耀科技(2024): 江苏1MW/2MWh工商业储能经济性分析
            - 行业标准: DOD=90%, 循环寿命6000次@25degC, 往返效率90%
        """
        total_charge_kwh = sum(float(np.nansum(seg)) for c in self.charge_segments_dict.values() for seg in c)
        total_discharge_kwh = sum(float(np.nansum(seg)) for d in self.discharge_segments_dict.values() for seg in d)

        # v3.2fix: 统一电侧口径, 消除效率重复折算
        # 口径事实(见 compute_segmented_spaces / compute_daily_spaces):
        #   Mode A 充电 = max(cap-load)×dt      → 已是电网侧吸收量, 不再除η
        #   Mode B/C 充电 = min(额定,-load)×dt×η → 电池侧存入量, 需 ÷η 换回电网侧
        #   三种模式放电均为 min(负荷,上限)×dt×η  → 已是电网侧供出量, 不再乘η
        grid_charge_kwh = total_charge_kwh
        if self.mode in ('B', 'C') and self.EFF_CHARGE > 0:
            grid_charge_kwh = total_charge_kwh / self.EFF_CHARGE
        grid_discharge_kwh = total_discharge_kwh

        # 峰谷套利: 区分模式
        if self.mode == 'B':
            # 光伏消纳: 充电来自光伏返送(0成本),放电节省购电
            annual_arbitrage = grid_discharge_kwh * peak_price
        elif self.mode == 'C':
            # 混合: 平充峰放
            annual_arbitrage = grid_discharge_kwh * peak_price - grid_charge_kwh * flat_price
        else:
            # 需量管理/纯套利: 谷充峰放
            annual_arbitrage = grid_discharge_kwh * peak_price - grid_charge_kwh * valley_price

        cap = self.config_cap_spin.value()

        # v2.13: 需量电费按削减功率计算(非储能容量)
        demand = _analyze_demand_characteristics(self._get_work_data()) if self.monthly_data else {}
        reducible_kw = demand.get('reducible', 0)
        rated_power = self.rated_power or 100.0
        effective_kw = min(reducible_kw, rated_power)
        # v2.20: 需量电费逐月计算 - 每月节省不超过当月实际峰值负荷
        monthly_demand_saving = 0.0
        work_data = self._get_work_data()
        for _month_str, data in work_data.items():
            arr = np.asarray(data.get('load_array', []))
            if arr.ndim != 2 or arr.shape[0] == 0:
                continue
            month_peak = float(max((np.nanmax(arr[d]) for d in range(arr.shape[0]) if not np.all(np.isnan(arr[d]))), default=0))
            # 当月可削减量不超过当月峰值(储能无法将需量降到0以下)
            effective_monthly_kw = min(reducible_kw, rated_power, month_peak)
            monthly_demand_saving += effective_monthly_kw * demand_charge
        demand_saving = monthly_demand_saving if monthly_demand_saving > 0 else effective_kw * demand_charge * 12.0  # 回退兼容

        # v3.0: 进阶算法——净需量法(可选) 仿真储能充放电后的真实需量节省
        net_demand_saving = 0.0
        if getattr(self, '_use_net_demand', False):
            net_demand_saving = self._calc_net_demand_saving(work_data, demand_charge)
        if net_demand_saving > 0:
            demand_saving = net_demand_saving  # 净需量值优先

        # v2.19: 容量电价收益 - 仅独立储能(grid_side)适用(114号文第三条)
        # 用户侧储能(user_side)不可申领容量电价,避免与峰谷套利叠加
        province = getattr(self, 'province_name', None)
        discharge_hours = cap / max(rated_power, 1.0) if rated_power > 0 else 2.0
        storage_type = getattr(self, '_storage_type', 'user_side')
        cap_rev = calc_capacity_revenue(rated_power, discharge_hours, province=province,
                                        storage_type=storage_type)
        capacity_revenue = cap_rev['annual_revenue']  # user_side时为0

        # v2.19: 税费+运维成本 - 必须先定义再使用
        vat_effective = 0.065  # 增值税13%x即征即退50%=6.5%,影响电力交易价差收益
        om_rate = 0.025  # 年运维费率(2.5% CAPEX)
        income_tax_rate = 0.25

        full_annual_benefit = annual_arbitrage * (1 - vat_effective) + demand_saving + capacity_revenue
        annual_om = cap * system_cost_per_kwh * om_rate
        annual_depreciation = cap * system_cost_per_kwh / max(project_years, 1)
        salvage_value = cap * system_cost_per_kwh * 0.05  # 残值5%

        # v2.19: 电池更换按循环寿命+日历寿命双重约束判定
        CALENDAR_LIFE_MAX = 15  # 磷酸铁锂电池日历寿命上限(年),无论循环次数多少
        # v2.20: daily_cycles 改用 min(charge, discharge) 替代加和平均--物理上一次完整循环受限于较小的方向
        # v3.0fix: 2C2D/多充多放策略自动适配——总充放电量/cap*dod 即为等效日循环次数
        daily_cycles = min(total_charge_kwh, total_discharge_kwh) / (cap * dod) if cap > 0 and dod > 0 else 1
        annual_cycles = daily_cycles * 365

        # v3.2fix: rainflow 电池循环计数——比总量÷容量更精确
        if _HAS_RAINFLOW and hasattr(self, 'charge_segments_dict') and self.charge_segments_dict:
            try:
                months = sorted(self._get_work_data().keys()) if hasattr(self, '_get_work_data') else []
                daily_depths = []
                for m in months[:12]:
                    c_segs = self.charge_segments_dict.get(m, [])
                    d_segs = self.discharge_segments_dict.get(m, [])
                    if c_segs and d_segs:
                        n_days = min(len(c_segs[0]) if c_segs else 0, len(d_segs[0]) if d_segs else 0)
                        for day in range(n_days):
                            ch = sum(s[day] for s in c_segs if day < len(s))
                            dh = sum(s[day] for s in d_segs if day < len(s))
                            daily_depths.append(min(ch, dh))
                if daily_depths:
                    cycles = list(rainflow.extract_cycles(np.array(daily_depths)))
                    if cycles:
                        total_equiv = sum(float(c[0]) * min(float(c[1]) / max(cap * dod, 1), 1.0) for c in cycles if len(c) >= 2)
                        rf_annual = total_equiv * (365.0 / max(len(daily_depths), 1))
                        annual_cycles = max(annual_cycles, rf_annual) if rf_annual > 0 else annual_cycles
            except Exception:
                pass

        cycle_life_years = rated_cycle_life / max(annual_cycles, 0.01)
        battery_life_years = min(cycle_life_years, CALENDAR_LIFE_MAX)
        replacement_year = int(battery_life_years) if battery_life_years < project_years else -1

        # 逐年现金流(税后)
        cashflows = [-cap * system_cost_per_kwh]
        for y in range(1, project_years + 1):
            effective_cap = cap * max(0.0, 1.0 - annual_degradation * y)
            ratio = effective_cap / max(cap, 1.0)
            pre_tax_cf = full_annual_benefit * ratio - annual_om
            taxable = max(0.0, pre_tax_cf - annual_depreciation)
            tax = taxable * income_tax_rate
            cf = pre_tax_cf - tax  # 税后现金流
            if replacement_year > 0 and y == replacement_year:
                cf -= cap * system_cost_per_kwh * 0.4
            if y == project_years:
                cf += salvage_value  # 期末残值回收
            cashflows.append(cf)

        # NPV / IRR (v2.20: 增加发散保护)
        npv = sum(cf / ((1 + discount_rate) ** i) for i, cf in enumerate(cashflows))

        def _npv_at_rate(r):
            if r <= -0.99:  # 防止分母趋零
                return float('-inf') if cashflows[0] < 0 else float('inf')
            return sum(cf / ((1 + r) ** i) for i, cf in enumerate(cashflows))

        irr = discount_rate
        irr_converged = False
        for _ in range(50):
            npv_val = _npv_at_rate(irr)
            deriv = sum(-i * cf / ((1 + irr) ** (i + 1)) for i, cf in enumerate(cashflows) if i > 0)
            if abs(deriv) < 1e-12 or np.isnan(deriv) or np.isinf(deriv):
                break
            irr_new = irr - npv_val / deriv
            if np.isnan(irr_new) or np.isinf(irr_new):
                break
            if abs(irr_new - irr) < 1e-6:
                irr = irr_new
                irr_converged = True
                break
            irr = irr_new
        # v3.0fix: 保留真实IRR(包括负值), 截断[-1.0, 1.0]范围外的异常值
        irr = min(max(irr, -1.0), 1.0) if not np.isnan(irr) else 0.0
        _irr_risk = (abs(irr) < 1e-10 or not irr_converged or irr < 0)  # 零值/未收敛/负收益→标记风险

        cum = 0; payback = float('inf')
        for i, cf in enumerate(cashflows[1:], 1):
            cum += cf
            if cum >= -cashflows[0]:
                payback = i - 1 + (-cashflows[0] - (cum - cf)) / cf if cf > 0 else i
                break

        system_cost = cap * system_cost_per_kwh
        return {
            'annual_charge_kwh': round(total_charge_kwh, 1),
            'annual_discharge_kwh': round(total_discharge_kwh, 1),
            'annual_arbitrage': round(annual_arbitrage, 0),
            'demand_saving': round(demand_saving, 0),
            'capacity_revenue': round(capacity_revenue, 0),
            'capacity_ratio': cap_rev['ratio'],
            'annual_benefit': round(full_annual_benefit, 0),
            'system_cost': round(system_cost, 0),
            'payback_years': round(payback, 2) if payback != float('inf') else float('inf'),
            'npv': round(npv, 0), 'irr': round(irr * 100, 2),
            'irr_risk': _irr_risk,
            'price_spread': round(peak_price - valley_price, 2),
            'spread_warning': (peak_price - valley_price) < 0.30,  # v2.19: 价差过低警告
            'annual_om': round(annual_om, 0),
            'effective_tax_rate': round(income_tax_rate * 100, 1),
            'reducible_kw': round(reducible_kw, 1),
            'annual_cycles': round(annual_cycles, 0),
            'battery_life_years': round(battery_life_years, 1),
            'replacement_year': replacement_year,
        }

    def update_economic_label(self):
        """v2.17: 经济标签防抖更新 - 300ms内多次调用只刷新一次"""
        if hasattr(self, '_econ_debounce_timer') and self._econ_debounce_timer:
            self._econ_debounce_timer.start()

    def _do_update_economic_label(self):
        """实际更新经济标签(由防抖定时器触发)"""
        if not hasattr(self, 'econ_label') or self.econ_label is None:
            return
        try:
            econ = self.calc_economic_summary()
            self.config_cap_spin.value()
            cap_rev = econ.get('capacity_revenue', 0)
            econ.get('capacity_ratio', 0)
            cap_info = f" | 容量费: ¥{cap_rev:,.0f}/年" if cap_rev > 0 else ""
            text = (f"💰 经济概览 | IRR: {econ['irr']}% | NPV: ¥{econ['npv']:,.0f} | "
                    f"年收益: ¥{econ['annual_benefit']:,.0f}{cap_info} | 回收期: "
                    f"{'无法计算' if econ['payback_years'] == float('inf') else str(econ['payback_years']) + '年'} | "
                    f"削峰: {econ.get('reducible_kw',0)}kW | 电池寿命: {econ.get('battery_life_years','-')}年")
            self.econ_label.setText(text)
            self._update_step_indicators()  # v3.2
        except Exception:
            log.debug("ProfessionalWindow error suppressed", exc_info=True)
            pass
    # endregion

    def _export_space_csv(self):
        """导出月度充放电空间汇总为 CSV"""
        path, _ = QFileDialog.getSaveFileName(self, "导出CSV", "充放电空间汇总.csv", "CSV (*.csv)")
        if not path: return
        try:
            with open(path, 'w', encoding='utf-8-sig', newline='') as f:
                w = csv.writer(f)
                months = sorted(self._get_work_data().keys())
                header = ['月份'] + [f'充电_{lbl}' for lbl in self.charge_labels] + [f'放电_{lbl}' for lbl in self.discharge_labels] + ['月最小值(kWh)']
                w.writerow(header)
                for month in months:
                    c_segs = self.charge_segments_dict.get(month, [])
                    d_segs = self.discharge_segments_dict.get(month, [])
                    row = [month]
                    vals = []
                    # v2.30fix: 按标签索引填充
                    for i in range(len(self.charge_labels)):
                        v = np.sum(np.nan_to_num(c_segs[i], nan=0.0)) if i < len(c_segs) else 0.0
                        row.append(f'{v:.2f}'); vals.append(v)
                    for i in range(len(self.discharge_labels)):
                        v = np.sum(np.nan_to_num(d_segs[i], nan=0.0)) if i < len(d_segs) else 0.0
                        row.append(f'{v:.2f}'); vals.append(v)
                    row.append(f'{min(vals):.2f}' if vals else '0')
                    w.writerow(row)
            ToastManager.show(self, f'已导出 {path}', 'success', 3000)
        except Exception as e:
            QMessageBox.critical(self, '导出失败', str(e))

    def _export_report_xlsx(self, path):
        """v2.19: 导出为Excel(.xlsx)格式"""
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment  # noqa: F401
        except ImportError:
            QMessageBox.critical(self, '导出失败', '需要安装 openpyxl: pip install openpyxl')
            return
        wb = Workbook()
        ws = wb.active; ws.title = '充放电空间'
        months = sorted(self._get_work_data().keys())
        # v2.27fix: 无充放电标签时添加占位列,防止导出空表无意义
        c_labels = self.charge_labels if self.charge_labels else ['(未配置充电时段)']
        d_labels = self.discharge_labels if self.discharge_labels else ['(未配置放电时段)']
        ws.append(['月份'] + [f'充电_{lbl}' for lbl in c_labels] + [f'放电_{lbl}' for lbl in d_labels] + ['月最小值(kWh)'])
        for month in months:
            row = [month]
            vals = []
            c_segs = self.charge_segments_dict.get(month, [])
            d_segs = self.discharge_segments_dict.get(month, [])
            # v2.30fix: 按标签索引填充
            for i in range(len(c_labels)):
                v = np.sum(np.nan_to_num(c_segs[i], nan=0.0)) if i < len(c_segs) else 0.0
                vals.append(v); row.append(round(v, 2))
            for i in range(len(d_labels)):
                v = np.sum(np.nan_to_num(d_segs[i], nan=0.0)) if i < len(d_segs) else 0.0
                vals.append(v); row.append(round(v, 2))
            row.append(round(min(vals), 2) if vals else 0)
            ws.append(row)
        wb.save(path)
        ToastManager.show(self, f'已导出 {path}', 'success', 3000)

    def _export_report(self):
        """v2.19: 导出分析报告 - 根据后缀选择CSV或Excel格式"""
        path, _ = QFileDialog.getSaveFileName(self, "导出分析报告", "储能分析报告.csv",
                                               "CSV 文件 (*.csv);;Excel 文件 (*.xlsx)")
        if not path:
            return
        try:
            ext = os.path.splitext(path)[1].lower()
            if ext == '.xlsx':
                self._export_report_xlsx(path)
                return
            # CSV导出
            import csv
            months = sorted(self._get_work_data().keys())
            c_segs_all = {m: self.charge_segments_dict.get(m, []) for m in months}
            d_segs_all = {m: self.discharge_segments_dict.get(m, []) for m in months}
            with open(path, 'w', encoding='utf-8-sig', newline='') as f:
                writer = csv.writer(f)
                writer.writerow(["负荷曲线批量生成工具 Ultra - 专业分析报告"])
                writer.writerow(["模式", self.mode])
                writer.writerow(["省份", self.province_name or "无"])
                writer.writerow(["实际数据天数", str(self.available_days)])
                writer.writerow([])
                # 月度汇总
                writer.writerow(["月度充放电空间汇总 (kWh)"])
                headers = ["月份"]
                if self.charge_labels:
                    headers += [f"充电({lbl})" for lbl in self.charge_labels]
                if self.discharge_labels:
                    headers += [f"放电({lbl})" for lbl in self.discharge_labels]
                headers.append("日最小值(kWh)")
                writer.writerow(headers)
                for month in months:
                    row = [month]
                    vals = []
                    # v2.30fix: 按标签索引填充
                    c_segs_m = c_segs_all.get(month, [])
                    d_segs_m = d_segs_all.get(month, [])
                    for i in range(len(self.charge_labels)):
                        val = np.sum(np.nan_to_num(c_segs_m[i], nan=0.0)) if i < len(c_segs_m) else 0.0
                        vals.append(val)
                        row.append(f"{val:.2f}")
                    for i in range(len(self.discharge_labels)):
                        val = np.sum(np.nan_to_num(d_segs_m[i], nan=0.0)) if i < len(d_segs_m) else 0.0
                        vals.append(val)
                        row.append(f"{val:.2f}")
                    row.append(f"{min(vals) if vals else 0:.2f}")
                    writer.writerow(row)
                # 逐日明细(所有月份)
                writer.writerow([])
                writer.writerow(["逐日充放电明细"])
                work_data = self._get_work_data()
                for month in months:
                    if month not in work_data:
                        continue
                    data = work_data[month]
                    dates = data.get('date_labels', [])
                    writer.writerow([f"--- {month} ---"])
                    day_headers = ["日期"] + [f"充电({lbl})" for lbl in self.charge_labels] + [f"放电({lbl})" for lbl in self.discharge_labels] + ["日最小值(kWh)"]
                    writer.writerow(day_headers)
                    c_segs = c_segs_all.get(month, [])
                    d_segs = d_segs_all.get(month, [])
                    for d_idx in range(len(dates)):
                        row = [str(dates[d_idx])]
                        vals = []
                        # v2.30fix: 按标签索引填充
                        for i in range(len(self.charge_labels)):
                            val = c_segs[i][d_idx] if i < len(c_segs) and d_idx < len(c_segs[i]) else 0.0
                            vals.append(val); row.append(f"{val:.2f}")
                        for i in range(len(self.discharge_labels)):
                            val = d_segs[i][d_idx] if i < len(d_segs) and d_idx < len(d_segs[i]) else 0.0
                            vals.append(val); row.append(f"{val:.2f}")
                        row.append(f"{min(vals) if vals else 0:.2f}")
                        writer.writerow(row)
            QMessageBox.information(self, "导出成功", f"报告已保存至:\n{path}")
        except Exception as e:
            QMessageBox.critical(self, "导出失败", str(e))

    def _open_simulation_dialog(self):
        available_months = list(self.monthly_data.keys())
        if not available_months:
            QMessageBox.warning(self, "提示", "无实际数据可供模拟")
            return
        season_map = {}
        if self.province_name and self.province_name != "无":
            season_map = self.config_manager.get_season_map(self.province_name)
        if not self.available_years:
            QMessageBox.warning(self, "警告", "无法从现有数据中提取年份,无法模拟.")
            return
        dlg = SimulationConfigDialog(
            self, self.available_years, self.monthly_data,
            season_map, self.config_manager, self
        )
        if dlg.exec() != QDialog.Accepted or not dlg.result_configs:
            return
        self._execute_simulation(dlg.result_configs)

    def _execute_simulation(self, configs):
        self.simulated_monthly_data = {}
        for key, data in self.monthly_data.items():
            self.simulated_monthly_data[key] = data
        for year, month_cfg in configs.items():
            existing_months = [int(k.split('-')[1]) for k in self.monthly_data if k.startswith(str(year))]
            src_data_map = {}
            for m_int in existing_months:
                src_key = f"{year}-{m_int:02d}"
                if src_key in self.monthly_data:
                    src_data_map[m_int] = self.monthly_data[src_key]
            for month_int, cfg in month_cfg.items():
                target_key = f"{year}-{month_int:02d}"
                src_name = cfg["src"].replace("月", "")
                src_month_int = int(src_name)
                src_data = src_data_map.get(src_month_int)
                if src_data is None:
                    continue
                src_load = np.array(src_data['load_array'])
                n_points = src_load.shape[1]
                target_days = calendar.monthrange(year, month_int)[1]
                if cfg["strategy"] == "平均曲线":
                    avg_curve = np.nanmean(src_load, axis=0)
                    sim_load = np.tile(avg_curve, (target_days, 1))
                elif cfg["strategy"] == "最大需量日保留":
                    # 计算源数据每日滑动窗口需量,取最大的 target_days 天
                    n_src_days = src_load.shape[0]
                    demands = np.zeros(n_src_days)
                    for d in range(n_src_days):
                        dm, _ = _calc_sliding_window_demand(
                            src_load[d:d+1], src_data['time_labels'])
                        demands[d] = dm
                    top_idx = np.argsort(demands)[::-1][:target_days]
                    sim_load = np.zeros((target_days, n_points))
                    for i, idx in enumerate(top_idx):
                        sim_load[i] = src_load[idx]
                else:  # 循环复制
                    n_src_days = src_load.shape[0]
                    sim_load = np.zeros((target_days, n_points))
                    for d in range(target_days):
                        sim_load[d] = src_load[d % n_src_days]
                date_labels = [f"{year}-{month_int:02d}-{d+1:02d}" for d in range(target_days)]
                self.simulated_monthly_data[target_key] = {
                    'load_array': sim_load,
                    'time_labels': src_data['time_labels'],
                    'date_labels': date_labels,
                    'month_str': target_key,
                    'table_no': src_data.get('table_no', '未命名'),
                    'asset': src_data.get('asset', '未命名'),
                    'sheet': src_data.get('sheet', ''),
                    'simulated': True
                }
        self._use_simulation = True
        self._save_scenario(f"模拟_{datetime.now().strftime('%m%d_%H%M')}")  # v2.25: 自动保存场景
        # v2.25: 调度联动校验
        try:
            if hasattr(self, '_run_dispatch_simulation'):
                self._validate_dispatch()
        except Exception: log.warning("调度校验失败", exc_info=True)
        self.available_days = sum(
            d['load_array'].shape[0] for d in self.simulated_monthly_data.values()
            if 'load_array' in d and d['load_array'].ndim == 2
        )
        self._recalc_spaces()
        self._update_mode_options()
        self._populate_space_table()
        self._populate_daily_month_combo()
        if self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self.available_days_label.setText(f"模拟后数据天数: {self.available_days} 天")
        self._update_effective_days_label()
        self._update_system_scale()
        QMessageBox.information(self, "完成", '负荷模拟完成,数据已更新.可点击"恢复原始数据"撤销.')

    def _restore_original(self):
        self.simulated_monthly_data.clear()
        self._use_simulation = False
        self._active_scenario = None  # v2.25
        self.available_days = sum(
            d['load_array'].shape[0] for d in self.monthly_data.values()
            if 'load_array' in d and d['load_array'].ndim == 2
        )
        self._recalc_spaces()
        self._update_mode_options()
        self._populate_space_table()

    def _save_scenario(self, name):
        """v2.25: 保存当前模拟结果到场景栈"""
        if self._use_simulation and self.simulated_monthly_data:
            self._scenarios[name] = {
                'data': dict(self.simulated_monthly_data),
                'ts': datetime.now().isoformat()
            }
            self._active_scenario = name
            if self._scenario_combo and self._scenario_combo.findText(name) < 0:
                self._scenario_combo.addItem(name)
                self._scenario_combo.setCurrentText(name)

    def _switch_scenario(self, name):
        """v2.25: 切换场景--原始/已保存场景"""
        if not name or name == '原始数据':
            self._restore_original()
            msg = "已恢复为原始数据."
        elif name in self._scenarios:
            self._active_scenario = name
            self._use_simulation = True
            self.simulated_monthly_data = dict(self._scenarios[name]['data'])
            self._recalc_spaces()
            self._populate_space_table()
            msg = f"已切换到场景「{name}」."
        else:
            return
        self._populate_daily_month_combo()
        if self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self.available_days_label.setText(f"实际数据天数: {self.available_days} 天")
        self._update_effective_days_label()
        self._update_system_scale()
        QMessageBox.information(self, "场景切换", msg)

    def _restore_saved_settings(self):
        """v2.29: 恢复上次关闭时保存的参数。"""
        if not self.config_manager:
            return
        saved_power = self.config_manager.app_set('pw_rated_power', None)
        if saved_power is not None and hasattr(self, 'rated_power_spin'):
            self.rated_power_spin.setValue(int(saved_power))
            self.rated_power = int(saved_power)
        saved_dod = self.config_manager.app_set('pw_dod', int(BESS_DOD_DEFAULT * 100))
        if hasattr(self, 'dod_spin') and saved_dod >= 50:
            self.dod_spin.setValue(int(saved_dod))
        saved_cap = self.config_manager.app_set('pw_capacity_mode', 'two_two')
        self.capacity_mode = saved_cap
        saved_charge = self.config_manager.app_set('pw_charge_option', '')
        if saved_charge and hasattr(self, 'charge_option_combo'):
            idx = self.charge_option_combo.findText(saved_charge)
            if idx >= 0:
                self.charge_option_combo.setCurrentIndex(idx)
                self.charge_option = saved_charge
        saved_discharge = self.config_manager.app_set('pw_discharge_option', '')
        if saved_discharge and hasattr(self, 'discharge_option_combo'):
            idx = self.discharge_option_combo.findText(saved_discharge)
            if idx >= 0:
                self.discharge_option_combo.setCurrentIndex(idx)
                self.discharge_option = saved_discharge
        saved_pv = self.config_manager.app_set('pw_pv_algo', 0)
        if hasattr(self, 'pv_algo_combo') and saved_pv < self.pv_algo_combo.count():
            self.pv_algo_combo.setCurrentIndex(saved_pv)
        saved_need = self.config_manager.app_set('pw_need_capacity', False)
        if hasattr(self, 'need_cap_cb'):
            self.need_cap_cb.setChecked(saved_need)
        saved_ign = self.config_manager.app_set('pw_ignore_negative', False)
        if hasattr(self, 'ignore_neg_cb'):
            self.ignore_neg_cb.setChecked(saved_ign)

    def closeEvent(self, event):
        """v2.29: 关闭时保存参数,停止定时器,下次打开自动恢复。"""
        # 停止所有定时器,防止回调访问已销毁widget
        for timer_attr in ('_cap_sync_timer', '_param_debounce_timer', '_econ_debounce_timer'):
            t = getattr(self, timer_attr, None)
            if t is not None and t.isActive():
                t.stop()
        if self.config_manager:
            self.config_manager.set_app('pw_rated_power', self.rated_power_spin.value() if hasattr(self, 'rated_power_spin') else 500)
            self.config_manager.set_app('pw_dod', self.dod_spin.value() if hasattr(self, 'dod_spin') else int(BESS_DOD_DEFAULT * 100))
            self.config_manager.set_app('pw_capacity_mode', getattr(self, 'capacity_mode', 'two_two'))
            self.config_manager.set_app('pw_charge_option', self.charge_option_combo.currentText() if hasattr(self, 'charge_option_combo') else '')
            self.config_manager.set_app('pw_discharge_option', self.discharge_option_combo.currentText() if hasattr(self, 'discharge_option_combo') else '')
            self.config_manager.set_app('pw_pv_algo', self.pv_algo_combo.currentIndex() if hasattr(self, 'pv_algo_combo') else 0)
            self.config_manager.set_app('pw_ignore_negative', self.ignore_neg_cb.isChecked() if hasattr(self, 'ignore_neg_cb') else False)
            # v3.2: 保存窗口几何
            self.config_manager.set_window_geometry("ProfessionalWindow", self.saveGeometry())
        super().closeEvent(event)

    def _on_param_changed(self, checked=None):
        """v3.2fix: 200ms防抖——快速连击只执行最后一次重算."""
        if not hasattr(self, '_param_debounce_timer'):
            self._param_debounce_timer = QTimer(self)
            self._param_debounce_timer.setSingleShot(True)
            self._param_debounce_timer.setInterval(100)  # v3.2fix: 100ms够防连击且跟手
            self._param_debounce_timer.timeout.connect(self._do_param_changed)
        self._param_debounce_timer.start()

    def _do_param_changed(self):
        if self.mode in ('B', 'C'):
            self.rated_power = self.rated_power_spin.value()
        self.need_capacity = self.need_cap_cb.isChecked() if self.mode == 'C' else False
        self.ignore_negative = self.ignore_neg_cb.isChecked() if hasattr(self, 'ignore_neg_cb') else self.ignore_negative
        self._recalc_spaces()
        self._update_mode_options()
        self._populate_space_table()
        self._populate_assessment_tab()
        if hasattr(self, 'daily_month_combo') and self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self._update_system_scale()
        self.update_economic_label()
        # v3.2: 每次参数变更→记忆到文件指纹
        self._remember_current_settings()

    def _remember_current_settings(self):
        """v3.2: 保存当前设置到文件记忆."""
        try:
            if not self.summaries:
                return
            # 获取第一个文件的来源路径
            first = self.summaries[0]
            src = getattr(first, 'source_file', None)
            if not src or not os.path.exists(src):
                return
            settings = {'province': self.province_name, 'mode': self.mode}
            idx = self._summary_idx_map.get((first.asset_value, first.month_str))
            if idx is not None and hasattr(self, 'settings_model'):
                bill = self.settings_model.effective_billing(idx)
                if bill:
                    settings['billing'] = bill
            FileMemory().set(src, settings=settings)
        except Exception:
            log.debug("ProfessionalWindow error suppressed", exc_info=True)

    def _on_net_demand_toggled(self, checked):
        """v3.0: 净需量法开关."""
        self._use_net_demand = bool(checked)
        self._recalc_spaces()
        self._populate_assessment_tab()
        self._update_mode_options()
        self._populate_space_table()
        if self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self._update_system_scale()
        self._update_dashboard_params()
        self.update_economic_label()  # v2.9

    def _get_space_explanation(self):
        """v2.29: 充放电空间计算说明——通俗概念+具体步骤。"""
        return '''
        <div style="color:#444;font-size:10pt;line-height:1.7;">
        <b>💡 一句话理解：</b><br>
        充电空间 = 电费便宜时，变压器还能"吃进"多少电存到电池；<br>
        放电空间 = 电费贵时，电池放出的电，设备能"消化"多少。<br><br>

        <b>📐 程序的具体算法（以15分钟间隔为例）：</b><br>
        <b>1.</b> 获取你配置的电价时段策略（谷段充电、峰段放电、平段按策略分配）<br>
        <b>2.</b> 跨午夜的时段（如22:00→次日6:00）自动拆成两段：[22:00, 24:00) 和 [0:00, 6:00)<br>
        <b>3.</b> 连续同类型的时段自动合并（如谷0-8 + 平8-11 + 谷11-14 合并为一个大充电段）<br>
        <b>4.</b> 对每个15分钟切片，计算这一时刻的可用空间：<br>
        <span style="margin-left:16px;"><b>模式A 需量管理：</b>充电空间 = 容量线 - 当前负荷（负荷低于容量线时才有空间）；</span><br>
        <span style="margin-left:32px;">放电空间 = 当前负荷（负荷越高放电空间越大，但不能超过容量线）</span><br>
        <span style="margin-left:16px;"><b>模式B 纯光伏：</b>充电空间 = 光伏返送功率（发电大于用电时，多余部分存电池）；</span><br>
        <span style="margin-left:32px;">放电空间 = 当前负荷（用多少放多少，受电池功率限制）</span><br>
        <span style="margin-left:16px;"><b>模式C 光伏+峰谷：</b>充电空间 = 光伏返送 + 谷电时段可购买的电量；</span><br>
        <span style="margin-left:32px;">放电空间 = 峰电时段负荷消耗的电量</span><br>
        <b>5.</b> 把每个时段内所有15分钟切片的可用空间累加起来，就是该时段的充/放电总量（kWh）<br>
        <b>6.</b> 时间切片的宽度用"中点法"计算，首尾两个切片包含边界补偿，确保不遗漏边缘时段<br><br>

        <b>⚡ 功率上限：</b>充放电空间不会超过你设定的储能额定功率——
        即使变压器容量再大、光伏再多，电池的充放电速度是有上限的。<br><br>

        <b>📊 表格里的数值含义：</b>每个月份、每个充/放电时段的"最小可充/放功率"
        是该月所有天中最紧张那一天的数值——如果那一天能满足，其他天都够用。
        </div>
        '''

    def _update_dashboard_params(self):
        bill_val = 0.0
        if self.mode == 'A':
            bill = self.settings_model.effective_billing(
                self._summary_idx_map.get((self.summaries[0].asset_value, self.summaries[0].month_str), 0))
            bill_val = bill['value'] if bill else 0.0
        elif self.mode in ('B', 'C'):
            pass
        self.param_label.setText(f"额定功率: {self.rated_power if self.rated_power else '--'} kW | 容量: {bill_val:.2f}")

    def update_fit_settings(self, new_plot_options):
        """v2.8: 从预览窗口接收拟合算法变更,仅重新计算空间而不重载数据."""
        if isinstance(new_plot_options, dict):
            new_po = PlotOptions.from_dict(new_plot_options)
        elif isinstance(new_plot_options, PlotOptions):
            new_po = new_plot_options
        else:
            return
        self.plot_options.fit_algorithm = new_po.fit_algorithm
        self.plot_options.enable_fit_overlay = new_po.enable_fit_overlay
        self.plot_options.replace_with_fit = new_po.replace_with_fit
        self.plot_options.show_fit_clusters = new_po.show_fit_clusters
        self.plot_options.fit_percentile = new_po.fit_percentile
        self.plot_options.fit_n_clusters = new_po.fit_n_clusters
        self.plot_options.fit_n_components = new_po.fit_n_components
        self._recalc_spaces()
        self._update_mode_options()
        self._populate_space_table()
        if self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self._update_system_scale()

    def set_cleaned_data(self, cleaned_data):
        """v2.10: 接收从预览窗口传来的清洗后数据,更新 monthly_data"""
        self._cleaned_data = cleaned_data
        if cleaned_data:
            # 将清洗后数据同步到 monthly_data 的对应 key 中
            for key, _data in self.monthly_data.items():
                # key 格式: "asset|month_str"
                month_str = key.split('|')[-1] if '|' in key else key
                if month_str in cleaned_data:
                    cd = cleaned_data[month_str]
                    if 'load_array' in cd:
                        self.monthly_data[key]['load_array'] = cd['load_array']
                        if 'date_labels' in cd:
                            self.monthly_data[key]['date_labels'] = cd['date_labels']

    def set_global_multiplier(self, mult):
        """v2.10: 接收倍率变更"""
        self.global_multiplier = mult

    def update_asset_summaries(self, new_summaries, new_province_name, new_plot_options, new_global_multiplier):
        self.summaries = new_summaries
        self.province_name = new_province_name
        if isinstance(new_plot_options, dict):
            self.plot_options = PlotOptions.from_dict(new_plot_options)
        elif isinstance(new_plot_options, PlotOptions):
            self.plot_options = new_plot_options
        else:
            self.plot_options = PlotOptions()
        self.global_multiplier = new_global_multiplier
        self._build_idx_map()
        self._load_all_data()
        self._extract_years()
        self._unify_time_resolution()
        self.simulated_monthly_data.clear()
        self._use_simulation = False
        self._recalc_spaces()
        self._update_mode_options()
        self._populate_space_table()
        self._populate_daily_month_combo()
        if self.daily_month_combo.count() > 0:
            self._fill_daily_table(self.daily_month_combo.currentText())
        self.available_days_label.setText(f"实际数据天数: {self.available_days} 天")
        self._update_effective_days_label()
        self._update_system_scale()
        asset = self.summaries[0].asset_value if self.summaries else "未知"
        self.asset_info_label.setText(f"<b>🏷 资产:{asset}</b>  模式:{self.mode}")
        self._update_dashboard_params()

    # ═══════════ v3.2: 报告/诊断/工具 ═══════════
    def _on_cost_scenario_changed(self, idx):
        """v3.1: NREL成本场景切换——读取NRELCostData并更新经济标签."""
        # v3.2fix: 原为模块自导入(打包/改名后 ImportError), 本模块已有 NRELCostData 定义
        if idx == 0:
            bat = NRELCostData.battery_pack_cost["moderate"]
            bos = NRELCostData.bos_cost["moderate"]
        elif idx == 1:
            bat = NRELCostData.battery_pack_cost["conservative"]
            bos = NRELCostData.bos_cost["conservative"]
        else:
            bat = NRELCostData.battery_pack_cost["advanced"]
            bos = NRELCostData.bos_cost["advanced"]
        # v3.2fix: 将成本数据写入实例属性,供经济标签使用
        self._cost_battery = bat
        self._cost_bos = bos
        self._do_update_economic_label()



    def _on_import_pv(self):
        """v3.2: 导入外部光伏数据→月份匹配→集成。"""
        fp, _ = QFileDialog.getOpenFileName(self, "选择光伏数据文件", "", "表格 (*.xlsx *.xls *.csv)")
        if not fp: return
        try:
            import pandas as pd
            ext = os.path.splitext(fp)[1].lower()
            df = pd.read_csv(fp) if ext == '.csv' else pd.read_excel(fp)
            # 提取月份
            date_col = df.columns[0]
            dates = df[date_col].astype(str)
            pv_months = sorted(set(d[:7] if len(d) >= 7 else d[:5] for d in dates))
            load_months = sorted(set(s.month_str for s in self.summaries))
            # 打开匹配对话框
            dlg = PVMonthMatchDialog(self, load_months, pv_months)
            if dlg.exec() != QDialog.Accepted:
                return
            # 根据匹配结果加载数据
            match_map = getattr(dlg, '_match_map', {})
            if match_map:
                # v3.2fix: 实际加载匹配的PV数据
                nums = df.select_dtypes(include=[np.number])
                if not nums.empty:
                    pv_arr = nums.values
                    # 按月份匹配存入pv_monthly_data
                    if not hasattr(self, 'pv_monthly_data'):
                        self.pv_monthly_data = {}
                    for load_m, pv_m in match_map.items():
                        if pv_m in pv_months:
                            pv_rows = [i for i, d in enumerate(dates) if d[:7] == pv_m or d[:5] == pv_m]
                            if pv_rows:
                                self.pv_monthly_data[load_m] = {
                                    'load_array': pv_arr[pv_rows],
                                    'time_labels': [f'{h:02d}:00' for h in range(min(24, pv_arr.shape[1]))],
                                    'date_labels': [dates[i] for i in pv_rows]
                                }
                    self.pv_info_label.setText(f"已导入光伏: {len(match_map)}个月匹配")
                    self._recalc_spaces()
                    self._refresh_all_displays()
                else:
                    self.pv_info_label.setText("光伏导入: 无数值列")
            else:
                self.pv_info_label.setText("光伏导入: 无匹配月份")
        except Exception as e:
            QMessageBox.warning(self, "导入失败", str(e))



    def _auto_diagnose(self):
        """v2.32: 后台静默诊断→缓存结果→UI自动刷新."""
        try:
            work = self._get_work_data()
            if not work: return
            all_arr = []; all_dates = []; times = []
            for _, d in work.items():
                if d and 'load_array' in d:
                    all_arr.append(np.asarray(d['load_array']))
                    all_dates.extend(d.get('date_labels',[]))
                    if not times: times = d.get('time_labels',[])
            if not all_arr: return
            full = np.concatenate(all_arr, axis=0)
            report = EnergyStorageEngineer.diagnose(full, times, all_dates, province=self.province_name)
            self._diagnose_cache = report; self._diagnose_time = datetime.now()
            self._do_update_economic_label()
            self._diagnose_pending = False
        except Exception as e:
            log.warning(f"自动诊断失败: {e}")



    def _generate_proposal(self):
        """v2.30: 生成方案建议书——可选章节+多格式导出。"""
        # 先弹章节选择
        chk_dlg = QDialog(self)
        chk_dlg.setWindowTitle("选择报告章节")
        chk_layout = QVBoxLayout(chk_dlg)
        chk_layout.addWidget(QLabel("请勾选需要包含的章节:"))
        self._proposal_chapters = {
            'overview': QCheckBox("项目概况"),
            'load': QCheckBox("负荷特征"),
            'space': QCheckBox("充放电空间"),
            'config': QCheckBox("推荐配置"),
            'econ': QCheckBox("经济指标"),
            'advice': QCheckBox("建议"),
        }
        for cb in self._proposal_chapters.values():
            cb.setChecked(True)
            chk_layout.addWidget(cb)
        chk_btns = QHBoxLayout()
        chk_btns.addStretch()
        ok = QPushButton("生成报告"); ok.clicked.connect(chk_dlg.accept)
        cancel = QPushButton("取消"); cancel.clicked.connect(chk_dlg.reject)
        chk_btns.addWidget(cancel); chk_btns.addWidget(ok)
        chk_layout.addLayout(chk_btns)
        if chk_dlg.exec() != QDialog.Accepted:
            return

        lines = []
        lines.append("=" * 50)
        lines.append("          储能配置方案建议书")
        lines.append("=" * 50)
        lines.append("")
        asset = self.summaries[0].asset_value if self.summaries else '未命名'
        n_months = len(set(s.month_str for s in self.summaries))

        if self._proposal_chapters['overview'].isChecked():
            lines.append("【项目概况】")
            lines.append(f"资产/表号: {asset}")
            lines.append(f"分析模式: {'需量管理' if self.mode=='A' else ('纯光伏' if self.mode=='B' else '光伏+峰谷')}")
            lines.append(f"数据跨度: {n_months}个月")
            lines.append("")

        data = self.monthly_data
        if data and self._proposal_chapters['load'].isChecked():
            all_loads = []
            for _, d in data.items():
                if d and 'load_array' in d:
                    all_loads.append(np.asarray(d['load_array']).flatten())
            if all_loads:
                flat = np.concatenate(all_loads); flat = flat[~np.isnan(flat)]
                lines.append("【负荷特征】")
                lines.append(f"峰值: {np.max(flat):.0f}kW | 均值: {np.mean(flat):.0f}kW")
                lines.append(f"日负荷率: {np.mean(flat)/max(np.max(flat),1):.2f} | 峰谷差率: {(np.max(flat)-np.min(flat))/max(np.max(flat),1):.2f}")
                lines.append("")

        if hasattr(self, 'charge_segments_dict') and self._proposal_chapters['space'].isChecked():
            tc = sum(np.sum(np.nan_to_num(s,0)) for segs in self.charge_segments_dict.values() for s in segs)
            td = sum(np.sum(np.nan_to_num(s,0)) for segs in self.discharge_segments_dict.values() for s in segs)
            lines.append("【充放电空间】")
            lines.append(f"充电: {tc:,.0f}kWh | 放电: {td:,.0f}kWh")
            lines.append(f"日均充电: {tc/max(n_months*30,1):.0f}kWh | 日均放电: {td/max(n_months*30,1):.0f}kWh")
            lines.append("")

        if self._proposal_chapters['config'].isChecked():
            # v3.2fix: 原为 500kW/1000kWh 硬编码占位(与界面实际配置无关), 改为读取当前真实配置
            rated = float(getattr(self, 'rated_power', 0) or 0)
            cap = float(self.config_cap_spin.value()) if hasattr(self, 'config_cap_spin') else 0.0
            if rated <= 0:
                rated = cap / 2.0 if cap > 0 else 0.0
            if cap <= 0:
                cap = rated * 2.0
            lines.append("【推荐配置】")
            if rated > 0 and cap > 0:
                lines.append(f"额定功率: {rated:.0f}kW | 容量: {cap:.0f}kWh ({cap/max(rated,1e-9):.1f}h)")
            else:
                lines.append("额定功率/容量: 尚未设置(请先在左侧面板设定额定功率与容量)")
            lines.append("")

        if self._proposal_chapters['econ'].isChecked():
            # v3.2fix: 原用不存在的属性 + 硬编码 1000元/kWh 拼出"简单IRR"(实为首年收益率), 改为走真实经济模型
            lines.append("【经济指标】")
            try:
                _econ = self.calc_economic_summary()
            except Exception:
                log.debug("建议书经济指标计算失败", exc_info=True)
                _econ = {}
            if _econ:
                _pb = _econ.get('payback_years')
                _pb_txt = '无法计算' if (_pb is None or _pb == float('inf')) else f"{_pb:.1f}年"
                lines.append(f"年收益: ¥{_econ.get('annual_benefit', 0):,.0f} | 总投资: ¥{_econ.get('system_cost', 0):,.0f}")
                _risk = "(IRR未收敛或为负值,仅供参考)" if _econ.get('irr_risk') else ""
                lines.append(f"NPV: ¥{_econ.get('npv', 0):,.0f} | IRR: {_econ.get('irr', 0):.2f}%{_risk}")
                lines.append(f"回收期: {_pb_txt} | 年循环: {_econ.get('annual_cycles', 0):.0f}次"
                             f" | 电池寿命: {_econ.get('battery_life_years', '-')}年")
            else:
                lines.append("经济指标: 数据不足,未能计算")
            lines.append("")

        if self._proposal_chapters['advice'].isChecked():
            lines.append("【建议】")
            if n_months < 12:
                lines.append(f"当前仅{n_months}个月数据,建议补充全年数据后做最终决策。")
            lines.append(f"本建议书由 Ultra v{ULTRA_VERSION} 自动生成。")
            lines.append("=" * 50)

        text = '\n'.join(lines)
        dlg = QDialog(self)
        dlg.setWindowTitle("方案建议书")
        dlg.setMinimumSize(520, 550)
        layout = QVBoxLayout(dlg)
        edit = QPlainTextEdit()
        edit.setPlainText(text)
        edit.setReadOnly(True)
        edit.setFont(QFont("Microsoft YaHei", 11))
        layout.addWidget(edit)
        btn = QHBoxLayout()
        cb = QPushButton("📋 复制")
        cb.clicked.connect(lambda: (QApplication.clipboard().setText(text), ToastManager.show(dlg,"已复制",'success',1500)))
        btn.addWidget(cb)
        btn.addStretch()
        pdf_btn = QPushButton("📄 导出HTML")
        pdf_btn.clicked.connect(lambda: self._export_proposal_html(text))
        btn.addWidget(pdf_btn)
        ok_btn = QPushButton("关闭")
        ok_btn.clicked.connect(dlg.accept)
        btn.addWidget(ok_btn)
        layout.addLayout(btn)
        dlg.exec()
        self._report_generated = True
        self._update_step_indicators()  # v3.2



    def _export_proposal_html(self, text):
        """v3.2fix: 原名为导出PDF, 实际只写临时 HTML 后让用户自己去浏览器打印。
        现改为真正落盘到输出目录的 .html 并告知路径(行为与名称一致)。"""
        import html as _html_mod
        body = _html_mod.escape(text)
        html_doc = ("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>储能方案建议书</title>"
                    "<style>body{font-family:'Microsoft YaHei',sans-serif;font-size:13px;line-height:1.8;"
                    "max-width:720px;margin:40px auto;color:#333}pre{white-space:pre-wrap;font-family:inherit}"
                    "</style></head><body><pre>" + body + "</pre></body></html>")
        out_dir = self.config_manager.app_set('last_output_dir', os.path.expanduser('~')) if self.config_manager else os.path.expanduser('~')
        try:
            os.makedirs(out_dir, exist_ok=True)
            fp = os.path.join(out_dir, f'储能方案建议书_{datetime.now().strftime("%Y%m%d_%H%M%S")}.html')
            with open(fp, 'w', encoding='utf-8') as f:
                f.write(html_doc)
            QMessageBox.information(self, "已导出", f"建议书已保存:\n{fp}\n\n用浏览器打开后可打印为 PDF。")
        except Exception as e:
            QMessageBox.warning(self, "导出失败", f"{e}\n\n报告文本已复制到剪贴板。")
            QApplication.clipboard().setText(text)

    def _export_proposal_pdf(self, text):
        """兼容保留: 旧名转发到 _export_proposal_html."""
        return self._export_proposal_html(text)




    def _generate_html_report(self):
        """v2.32: 生成专业HTML方案报告(封面+负荷+储能+经济+风险)。"""
        if not self.monthly_data:
            QMessageBox.warning(self, "提示", "无可用数据"); return
        try:
            # v3.2: 使用诊断引擎数据(如有)
            if hasattr(self, "_diagnose_cache") and self._diagnose_cache:
                econ = self._diagnose_cache.get("economics", {})
            else:
                econ = self.calc_economic_summary()
        except Exception:
            log.debug("ProfessionalWindow fallback", exc_info=True)
            econ = {}
        # v3.2fix: 原只取第一个月, 多月份项目报告的 peak/avg 只反映单月; 改为全年聚合(分辨率不一致时插值对齐)
        diag = {}
        if self.monthly_data:
            _arrays = []
            for _d in self.monthly_data.values():
                _a = _d.get('load_array') if isinstance(_d, dict) else None
                if isinstance(_a, np.ndarray) and _a.ndim == 2 and _a.size > 0:
                    _arrays.append(_a)
            if _arrays:
                _max_pts = max(a.shape[1] for a in _arrays)
                _rows = []
                for _a in _arrays:
                    if _a.shape[1] == _max_pts:
                        _rows.append(_a)
                    else:
                        _x_old = np.linspace(0.0, 1.0, _a.shape[1])
                        _x_new = np.linspace(0.0, 1.0, _max_pts)
                        _rows.append(np.vstack([np.interp(_x_new, _x_old, r) for r in _a]))
                _stack = np.vstack(_rows)
                diag = {'peak': float(np.nanmax(_stack)), 'avg': float(np.nanmean(_stack)),
                        'days': int(_stack.shape[0]), 'points': int(_stack.shape[1])}
        out = self.config_manager.app_set('last_output_dir','.') if self.config_manager else '.'
        fp = os.path.join(out, f'方案报告_{datetime.now().strftime("%Y%m%d_%H%M%S")}.html')
        try:
            generate_html_report(self.monthly_data, econ, diag, fp,
                project_name=self.summaries[0].asset_value if self.summaries else '')
            QMessageBox.information(self, "报告已生成", f"已保存至:\n{fp}")
        except Exception as e:
            QMessageBox.critical(self, "生成失败", str(e))



    def _show_cycle_btn(self):
        """v3.2: 调用_show_cycle_analysis展示电池循环分析。"""
        _show_cycle_analysis(self)



    def _show_algo_compare(self):
        """v3.2: 调用_show_algorithm_comparison展示算法对比。"""
        _show_algorithm_comparison(self)



    def _on_device_compare(self):
        """v3.2fix: StorageOptimizer.compare_devices 设备比选。"""
        work = self._get_work_data()
        if not work: return
        arr = np.concatenate([np.asarray(d['load_array']) for d in work.values()], axis=0)
        times = list(work.values())[0].get('time_labels',[])
        dates = list(work.values())[0].get('date_labels',[])
        devices = [{'label': v['name'], 'cost': v['cost_per_kwh']} for v in BESS_CATALOG.values()]
        opt = StorageOptimizer(arr, times, dates)
        results = opt.compare_devices(devices)
        lines = ['设备比选结果(按IRR排序):']
        for name, r in sorted(results.items(), key=lambda x: x[1].get('irr',0), reverse=True):
            lines.append(f'{name}: IRR={r.get("irr",0):.1f}% NPV=¥{r.get("npv",0):,.0f} 回收期={r.get("payback",0):.1f}年')
        QMessageBox.information(self, "设备比选", chr(10).join(lines))



    def _run_settlement(self):
        """v3.2.1fix(N1): 本方法自加入起 100% 失败, 已重写。

        原实现两处硬错, 被 try/except 掩盖成「结算失败」弹窗, 从未出过一次结果:
          1) calc_monthly_settlement 需 8 个位置参数, 实传 1 个, 且 energy_price /
             peak_reduction_kw 根本不在形参表里 -> TypeError;
          2) 该函数返回 SettlementPeriod(dataclass), 原代码当 dict 用 .get() -> AttributeError。

        现改为复用 calc_economic_summary 的统一经济口径, 不再维护第四套结算实现
        (程序内已有 precise/daily/LP/MILP 四套口径, 再加一套只会继续分叉)。
        """
        try:
            work = self._get_work_data()
            if not work:
                QMessageBox.warning(self, "提示", "无数据"); return
            econ = self.calc_economic_summary()
            if not econ:
                QMessageBox.warning(self, "结算", "经济模型无结果, 请先完成空间计算"); return

            lines = ['月度负荷结算(统一经济口径):']
            total_kwh = 0.0
            total_peak = 0.0
            for m in sorted(work.keys()):
                data = work[m]
                arr = np.asarray(data.get('load_array', []))
                if arr.size == 0:
                    continue
                per_day = np.sum(np.maximum(arr, 0), axis=1) * 24.0 / max(arr.shape[1], 1)
                month_kwh = float(np.sum(per_day))
                month_peak = float(np.nanmax(arr))
                total_kwh += month_kwh
                total_peak = max(total_peak, month_peak)
                avg_day = month_kwh / max(len(per_day), 1)
                lines.append(f'{m}: 用电 {month_kwh:,.0f} kWh | 峰 {month_peak:,.0f} kW | 日均 {avg_day:,.0f} kWh')

            lines.append('')
            lines.append(f'全年用电 {total_kwh:,.0f} kWh | 最大需量 {total_peak:,.0f} kW')
            lines.append(f'储能年充电 {econ.get("annual_charge_kwh", 0):,.0f} kWh | 年放电 {econ.get("annual_discharge_kwh", 0):,.0f} kWh')
            lines.append(f'套利收益 ¥{econ.get("annual_arbitrage", 0):,.0f} | 需量节省 ¥{econ.get("demand_saving", 0):,.0f}')
            lines.append(f'年收益合计 ¥{econ.get("annual_benefit", 0):,.0f}')
            lines.append(f'投资 ¥{econ.get("system_cost", 0):,.0f} | NPV ¥{econ.get("npv", 0):,.0f} | '
                         f'IRR {econ.get("irr", 0)}% | 回收期 {econ.get("payback_years", 0)} 年')
            QMessageBox.information(self, '结算明细', chr(10).join(lines))
        except Exception as e:
            log.debug("结算明细失败", exc_info=True)
            QMessageBox.warning(self, '结算失败', str(e))

    # ── v3.2fix(特性同步): 从参考程序补回 ProfessionalWindow._run_full_diagnose ──
    def _run_full_diagnose(self):
            """v2.32: 调用EnergyStorageEngineer.diagnose运行13步诊断,并缓存结果供UI复用。"""
            work = self._get_work_data()
            if not work:
                QMessageBox.warning(self, "提示", "无可用数据"); return
            all_arr = []; all_dates = []; times = []
            for m, d in work.items():
                if d and 'load_array' in d:
                    all_arr.append(np.asarray(d['load_array']))
                    all_dates.extend(d.get('date_labels', []))
                    if not times: times = d.get('time_labels', [])
            if not all_arr: return
            full = np.concatenate(all_arr, axis=0)
            report = EnergyStorageEngineer.diagnose(
                full, times, all_dates,
                province=self.province_name,
                billing=self.settings_model.effective_billing(0) if hasattr(self,'settings_model') else None)
            # v2.32: 缓存报告,后续UI方法优先从报告取数,消除重复计算
            self._diagnose_cache = report
            self._diagnose_time = datetime.now()
            # 刷新UI——各方法检测到缓存后自动从报告取数
            self._do_update_economic_label()
            self._populate_space_table()
            self._populate_assessment_tab()
            summary = EnergyStorageEngineer._generate_summary(report) if hasattr(EnergyStorageEngineer, '_generate_summary') else str(report.get('summary', report))
            diag_text = summary if isinstance(summary, str) else json.dumps(report.get('summary', {}), ensure_ascii=False, indent=2)
            dlg = QDialog(self)
            dlg.setWindowTitle("🔬 综合诊断报告"); dlg.setMinimumSize(550, 500)
            layout = QVBoxLayout(dlg)
            edit = QPlainTextEdit(); edit.setPlainText(diag_text); edit.setReadOnly(True)
            edit.setFont(QFont("Microsoft YaHei", 11)); layout.addWidget(edit)
            btn = QHBoxLayout(); btn.addStretch()
            close = QPushButton("关闭"); close.clicked.connect(dlg.accept); btn.addWidget(close)
            layout.addLayout(btn); dlg.exec()

    # ── v3.2fix(特性同步): 从参考程序补回 ProfessionalWindow._run_optimization ──
    def _run_optimization(self):
            """v2.31: 四目标优化扫参+对比。"""
            work = self._get_work_data()
            if not work: QMessageBox.warning(self,"提示","无可用数据"); return
            first = list(work.values())[0]
            arr = np.asarray(first.get('load_array',[]))
            times = first.get('time_labels',[]); dates = first.get('date_labels',[])
            if arr.size == 0: return
            pv_arr = None
            if self.mode in ('B','C') and hasattr(self,'pv_monthly_data'):
                pd0 = list(self.pv_monthly_data.values())[0] if self.pv_monthly_data else None
                if pd0 and 'load_array' in pd0: pv_arr = np.asarray(pd0['load_array'])
            opt = StorageOptimizer(arr, times, dates, pv_array=pv_arr)
            result = opt.optimize()
            show_optimize_dialog(self, result)

