def resample_load_data(load_array, time_labels, target_minutes, method='auto'):
    """负荷数据精度转换:将任意精度数据转换为目标精度.

    Args:
        load_array: (n_days, n_points) 日负荷矩阵
        time_labels: 时间标签列表 ['00:00','00:15',...]
        target_minutes: 目标精度(分钟), 支持 5/15/30/60
        method: 转换方法
            - 'auto': 升采样用线性插值,降采样用均值聚合
            - 'mean': 降采样取均值
            - 'max': 降采样取最大值(需量保守估计)
            - 'min': 降采样取最小值
            - 'first': 降采样取首点
            - 'linear': 升采样线性插值
            - 'cubic': 升采样三次样条
            - 'forward': 升采样前向填充(阶梯保持)

    Returns:
        (new_load_array, new_time_labels) 或原数据(精度已匹配)
    """
    arr = np.asarray(load_array, dtype=np.float64)
    n_days, n_points = arr.shape
    if n_points < 2:
        return arr, time_labels

    # 推断当前精度
    hours = np.array([_parse_min(t) / 60.0 for t in time_labels])
    diffs = np.diff(hours)
    current_minutes = float(np.median(diffs[diffs > 0]) * 60.0) if np.any(diffs > 0) else 60.0
    # 四舍五入到标准精度
    standard_resolutions = [5, 15, 30, 60]
    current_minutes = min(standard_resolutions, key=lambda r: abs(r - current_minutes))

    if abs(current_minutes - target_minutes) < 0.5:
        return arr, time_labels  # 精度已匹配

    # 生成目标时间标签
    n_target = int(24 * 60 / target_minutes)
    new_hours = np.linspace(0, 24, n_target, endpoint=False)
    new_labels = [f"{int(h):02d}:{int((h-int(h))*60):02d}" for h in new_hours]

    if target_minutes > current_minutes:
        # ── 降采样:高精度→低精度 ──
        ratio = int(target_minutes / current_minutes + 0.5)
        if method in ('auto', 'mean'):
            # 均值聚合:保留总能量
            new_arr = np.zeros((n_days, n_target))
            for i in range(n_target):
                start = i * ratio
                end = min((i + 1) * ratio, n_points)
                if end > start:
                    new_arr[:, i] = np.nanmean(arr[:, start:end], axis=1)
                elif start < n_points:
                    new_arr[:, i] = arr[:, start]
            return new_arr, new_labels
        if method == 'max':
            new_arr = np.zeros((n_days, n_target))
            for i in range(n_target):
                start = i * ratio
                end = min((i + 1) * ratio, n_points)
                if end > start:
                    new_arr[:, i] = np.nanmax(arr[:, start:end], axis=1)
                elif start < n_points:
                    new_arr[:, i] = arr[:, start]
            return new_arr, new_labels
        if method == 'min':
            new_arr = np.zeros((n_days, n_target))
            for i in range(n_target):
                start = i * ratio
                end = min((i + 1) * ratio, n_points)
                if end > start:
                    new_arr[:, i] = np.nanmin(arr[:, start:end], axis=1)
                elif start < n_points:
                    new_arr[:, i] = arr[:, start]
            return new_arr, new_labels
        if method == 'first':
            indices = np.arange(0, n_points, ratio)[:n_target]
            return arr[:, indices], new_labels[:len(indices)]
    else:
        # ── 升采样:低精度→高精度 ──
        old_hours = np.array([_parse_min(t) / 60.0 for t in time_labels])
        if method in ('auto', 'linear'):
            new_arr = np.zeros((n_days, n_target))
            for d in range(n_days):
                new_arr[d, :] = np.interp(new_hours, old_hours, arr[d, :],
                                          left=arr[d, 0], right=arr[d, -1])
            return new_arr, new_labels
        if method == 'cubic':
            try:
                from scipy.interpolate import CubicSpline
                new_arr = np.zeros((n_days, n_target))
                for d in range(n_days):
                    valid = ~np.isnan(arr[d, :])
                    if valid.sum() >= 4:
                        cs = CubicSpline(old_hours[valid], arr[d, valid],
                                        bc_type='natural', extrapolate=True)
                        new_arr[d, :] = cs(new_hours)
                    else:
                        new_arr[d, :] = np.interp(new_hours, old_hours, arr[d, :],
                                                  left=arr[d, 0], right=arr[d, -1])
                return np.clip(new_arr, 0, None), new_labels
            except ImportError:
                pass  # 回退到线性
        elif method == 'forward':
            new_arr = np.zeros((n_days, n_target))
            for d in range(n_days):
                for i, h in enumerate(new_hours):
                    idx = np.searchsorted(old_hours, h, side='right') - 1
                    idx = max(0, min(idx, n_points - 1))
                    new_arr[d, i] = arr[d, idx]
            return new_arr, new_labels

    return arr, time_labels


def _date_has_year(sample: str) -> bool:
    """v2.29: 检测日期字符串是否含年份信息。"""
    import re
    # 匹配 2025-06-29, 2025/06/29, 20250629, 06/29/2025 等含4位年份的格式
    year_patterns = [
        r'\b(20\d{2})\b',          # 2025
        r'\b(19\d{2})\b',          # 1999
    ]
    for pat in year_patterns:
        if re.search(pat, str(sample)):
            return True
    return False

def _extract_year(sample: str) -> int:
    """v2.29: 从日期字符串提取4位年份,失败返回0。"""
    import re
    m = re.search(r'\b(20\d{2})\b', str(sample))
    return int(m.group(1)) if m else 0

def _patch_date_year(labels: list, year: int) -> list:
    """v2.29: 给无年份的日期标签补年份。
    支持: '06-29'→'2025-06-29', '06/29'→'2025/06/29', '6月29日'→'2025-6月29日'"""
    import re
    patched = []
    for label in labels:
        s = str(label).strip()
        if _date_has_year(s):
            patched.append(s)
        else:
            # 检测常见无年份格式: MM-DD, MM/DD, M月D日
            m = re.match(r'(\d{1,2})[-/](\d{1,2})', s)
            if m:
                patched.append(f"{year}-{m.group(1).zfill(2)}-{m.group(2).zfill(2)}")
            else:
                m2 = re.match(r'(\d{1,2})月(\d{1,2})日?', s)
                if m2:
                    patched.append(f"{year}-{m2.group(1).zfill(2)}-{m2.group(2).zfill(2)}")
                else:
                    patched.append(s)  # 无法识别,保持原样
    return patched

def _infer_data_resolution(time_labels):
    """推断数据精度(分钟)."""
    if len(time_labels) < 2:
        return 60
    hours = np.array([_parse_min(t) / 60.0 for t in time_labels])
    diffs = np.diff(hours)
    if not np.any(diffs > 0):
        return 60
    minutes = float(np.median(diffs[diffs > 0]) * 60.0)
    standard = [5, 15, 30, 60]
    return min(standard, key=lambda r: abs(r - minutes))


