# v2.25: 曲线融合引擎
# ═══════════════════════════════════════════════════════════

def _load_raw_for_fusion(fp, sheet, mapping, is_csv, enc, time_points, month_hint):
    """v2.29: 为曲线融合直接加载源B全量数据,不依赖GroupSummary/month_str匹配。
    自动检测宽表/长表格式,返回统一(load_array, time_labels, date_labels)结构。"""
    import pandas as pd
    delimiter = mapping.get('delimiter', ',')
    hrow = mapping.get('header_row', 0)
    if is_csv:
        df = pd.read_csv(fp, header=hrow, encoding=enc or 'utf-8',
                         delimiter=delimiter if delimiter != 'auto' else None,
                         keep_default_na=False)
    else:
        df = pd.read_excel(fp, sheet_name=sheet, header=hrow)

    date_col = str(mapping.get('date_col', ''))
    time_col = mapping.get('time_col')
    asset_col = mapping.get('asset_col')
    load_col_raw = mapping.get('load_col', '')
    fmt = mapping.get('format_type', 'long')

    # 解析load_col: 可能是逗号分隔的列名/列索引字符串,也可能是单列名
    if isinstance(load_col_raw, list):
        load_cols = [str(c) for c in load_col_raw if str(c) not in ('', 'nan')]
    elif isinstance(load_col_raw, str):
        parts = [c.strip() for c in load_col_raw.split(',') if c.strip()]
        # 如果是纯数字列表,尝试匹配列名;否则直接用
        if parts and all(p.isdigit() for p in parts):
            # 按索引取列
            idxs = [int(p) for p in parts if 0 <= int(p) < len(df.columns)]
            load_cols = [df.columns[i] for i in idxs] if idxs else []
        else:
            load_cols = [c for c in parts if c in df.columns]
    else:
        load_cols = []

    if not load_cols:
        # 回退:取所有数值列(排除日期/时间/资产列)
        num_cols = df.select_dtypes(include=np.number).columns.tolist()
        skip = {str(date_col), str(time_col) if time_col else '', str(asset_col) if asset_col else ''}
        load_cols = [c for c in num_cols if str(c) not in skip]
        if time_points and len(load_cols) > time_points:
            load_cols = load_cols[:time_points]

    if not load_cols:
        return None, "未找到有效负荷数据列"

    if fmt in ('wide', 'wide_transposed', 'accumulated'):
        arr = df[load_cols].apply(pd.to_numeric, errors='coerce').values.astype(np.float64)
        if date_col and date_col in df.columns:
            date_labels = df[date_col].astype(str).tolist()
        else:
            date_labels = [str(i) for i in range(len(arr))]
        n_pts = arr.shape[1]
        time_labels = [f"{i*24*60//n_pts//60:02d}:{i*24*60//n_pts%60:02d}" for i in range(n_pts)]
        return {'load_array': arr, 'time_labels': time_labels, 'date_labels': date_labels}, None
    else:
        arr = df[load_cols].apply(pd.to_numeric, errors='coerce').values.astype(np.float64)
        if arr.ndim == 1:
            arr = arr.reshape(-1, 1)
        if date_col and date_col in df.columns:
            date_series = df[date_col].astype(str)
            # v2.29: 智能拆分日期+时间列——检测是否含时间部分
            import re
            sample = str(date_series.iloc[0]) if len(date_series) > 0 else ''
            has_time = bool(re.search(r'\d{1,2}:\d{2}', sample))
            if has_time:
                # 拆分:取空格前的日期部分作为分组键
                date_keys = date_series.str.replace(r'\s+\d{1,2}:\d{2}.*$', '', regex=True)
            else:
                date_keys = date_series
            groups = date_keys.groupby(date_keys)
            all_dates = list(groups.groups.keys())
            max_pts = max(len(groups.get_group(d).index) for d in all_dates)
            result = np.full((len(all_dates), max_pts), np.nan)
            for i, d in enumerate(all_dates):
                idx = groups.groups[d]
                vals = arr[idx, 0][:max_pts]
                result[i, :len(vals)] = vals
            time_labels = [f"{i*24*60//max_pts//60:02d}:{i*24*60//max_pts%60:02d}" for i in range(max_pts)]
            return {'load_array': result, 'time_labels': time_labels, 'date_labels': all_dates}, None
        else:
            return None, f"未找到日期列 '{date_col}'"

def _slice_to_month(data, month_str, is_raw_b=False):
    """v2.29: 从融合数据中切片出指定月份的行。
    month_str: '2025-07'格式(源A)或'07'格式(源B raw)
    is_raw_b: True表示源B原始数据(MM-DD格式,无年份)"""
    if data is None or 'date_labels' not in data:
        return data
    date_labels = data.get('date_labels', [])
    load_array = np.asarray(data.get('load_array', []))
    if len(date_labels) == 0 or load_array.size == 0:
        return data
    # 确定目标月份
    if is_raw_b:
        target_mm = month_str[-2:] if len(month_str) >= 2 else month_str
        mask = [d[:2] == target_mm for d in date_labels]  # '07-01'[:2]=='07'
    else:
        mask = [str(d).startswith(month_str[:7]) for d in date_labels]  # '2025-07-01'.startswith('2025-07')
    indices = [i for i, m in enumerate(mask) if m]
    if not indices:
        return data  # 找不到匹配,返回原数据
    result = dict(data)
    result['load_array'] = load_array[indices]
    result['date_labels'] = [date_labels[i] for i in indices]
    return result

def fuse_load_curves(curve_a, labels_a, curve_b, labels_b, mode='add', weight=0.5):
    """融合两组负荷曲线.

    Args:
        curve_a, curve_b: (n_days, n_points) 负荷矩阵
        labels_a, labels_b: 时间标签列表
        mode: 'add'(叠加), 'subtract'(相减A-B), 'weighted'(加权混合)
        weight: 加权模式下的A权重(0~1)

    Returns:
        (fused_array, fused_labels, metadata)
    """
    a_arr = np.asarray(curve_a, dtype=np.float64)
    b_arr = np.asarray(curve_b, dtype=np.float64)

    # 检查精度是否一致,不一致则自动重采样到更高精度
    res_a = _infer_data_resolution(labels_a)
    res_b = _infer_data_resolution(labels_b)
    if res_a != res_b:
        target = min(res_a, res_b)
        a_arr, labels_a = resample_load_data(a_arr, labels_a, target)
        b_arr, labels_b = resample_load_data(b_arr, labels_b, target)

    # 对齐时间点
    n_pts = min(a_arr.shape[1], b_arr.shape[1])
    n_days = min(a_arr.shape[0], b_arr.shape[0])
    a = a_arr[:n_days, :n_pts]
    b = b_arr[:n_days, :n_pts]
    labels = labels_a[:n_pts] if len(labels_a) >= n_pts else labels_a

    if mode == 'add':
        result = a + b
        label = '叠加'
    elif mode == 'subtract':
        result = a - b
        label = '相减'
    elif mode == 'weighted':
        w = max(0.0, min(1.0, weight))
        result = a * w + b * (1.0 - w)
        label = f'加权({w:.0%}/{1-w:.0%})'
    else:
        return None, None, {'error': f'未知融合模式: {mode}'}

    # v2.29fix: 移除强制裁剪——负荷数据自有其物理含义,不应一刀切归零
    if mode == 'subtract' and np.allclose(result, 0):
        label = '相减(全零—A=B)'
    meta = {'mode': mode, 'label': label, 'n_days': n_days, 'n_points': n_pts,
            'resolution': res_a, 'source_days_a': a_arr.shape[0], 'source_days_b': b_arr.shape[0]}
    return result, labels, meta


