class _ExportVectorWorker(QObject):
    """后台工作器:矢量图导出,避免阻塞 GUI(使用线程池执行)"""
    finished = Signal(bool, str)

    def __init__(self, path, fmt, date_labels, load, time_labels, title, opts, bill, periods):
        super().__init__()
        self._path = path
        self._fmt = fmt
        self._date_labels = date_labels
        self._load = load
        self._time_labels = time_labels
        self._title = title
        self._opts = opts
        self._bill = bill
        self._periods = periods

    def run(self):
        try:
            _init_matplotlib()
            import matplotlib.pyplot as _plt_local
            fig, ax = _plt_local.subplots(figsize=EXPORT_FIGSIZE)
            if self._opts.get('dark_theme', False):
                fig.patch.set_facecolor('#1e1e1e')
                ax.set_facecolor('#2e2e2e')
            enable_holiday = self._opts.get('highlight_mode', 'none') in ('holiday', 'grouped')
            precomputed_day_types = [_get_day_type(d, enable_holiday=enable_holiday) for d in self._date_labels]
            _draw_curves_core(ax, self._date_labels, self._load, self._time_labels, self._title,
                              self._opts, self._bill if self._bill and self._bill.get('value') else None,
                              self._periods, precomputed_day_types=precomputed_day_types)
            fig.tight_layout()
            fig.savefig(self._path, format=self._fmt, dpi=EXPORT_DPI, bbox_inches='tight')
            _plt_local.close(fig)
            self.finished.emit(True, self._path)
        except Exception as e:
            self.finished.emit(False, str(e))


class PreviewDialog(AnimatedDialog):
    """负荷曲线预览与设置对话框.

    职责:数据导航、曲线渲染、策略配置、输出导出.
    内部模块划分(v2.15):
      - __init__ / _init_ui: 初始化与UI构建
      - Navigation: _navigate_to / _prev_group / _next_group
      - Data Panel: _filter_tree / _on_sort_changed / _select_by_asset
      - Curve Panel: _schedule_render / _on_fit_algorithm_changed / _on_fit_param_changed
      - Strategy Panel: _update_multiplier_ui / _on_settings_changed / _on_province_changed
      - Output: _export_vector / _export_chart_data / _refresh_template_list
      - Rendering: _start_silent_render / _connect_render_signals / _on_render_complete
    """
    def __init__(self, parent, all_summaries, config_manager, initial_multiplier=1.0,
                 initial_show_max_demand=False, initial_output_dir="", data_provider=None):
        super().__init__(parent)
        self.setWindowFlags(self.windowFlags() | Qt.WindowMinMaxButtonsHint)
        self.all_summaries = all_summaries
        self.config_manager = config_manager
        self.current_index = 0
        self._first_render_done = False
        self._last_province_text = ""
        self._zoom_level = 1.0
        self._show_max_demand = initial_show_max_demand if initial_show_max_demand is not None else False
        self._selected_province = None

        self.provider = data_provider if data_provider else DataProvider(
            self.config_manager.app_set('last_csv_encoding', 'auto'))

        self.setWindowTitle("📊 负荷曲线预览与设置")
        self.setMinimumSize(1000, 650)
        # v2.29fix: 始终最大化——跳过历史geometry恢复
        self._should_maximize = True

        bsize = int(base_size())
        self.tree_controller = None
        self._global_multiplier = initial_multiplier
        self._global_billing_dict = {}

        self.settings_model = _PerGroupSettings(
            self.all_summaries,
            self._global_multiplier,
            billing_dict=self._global_billing_dict
        )
        # v2.28fix: 构造期间屏蔽设置变更重渲染,避免 _init_ui 信号风暴
        self._batch_init = True
        self.settings_model.settingsChanged.connect(self._on_settings_changed)

        self.render_scheduler = None

        self._highlight_mode = self.config_manager.app_set('highlight_mode', 'none')
        self._weekday_color = self.config_manager.app_set('weekday_color', DEFAULT_WEEKDAY_COLOR)
        self._weekend_color = self.config_manager.app_set('weekend_color', DEFAULT_WEEKEND_COLOR)
        self._holiday_color = self.config_manager.app_set('holiday_color', DEFAULT_HOLIDAY_COLOR)
        self._weekend_line_width = self.config_manager.app_set('weekend_line_width', DEFAULT_WEEKEND_LINE_WIDTH)
        self._holiday_line_width = self.config_manager.app_set('holiday_line_width', DEFAULT_HOLIDAY_LINE_WIDTH)
        self._show_weekend_bg = self.config_manager.app_set('show_weekend_bg', False)
        self._legend_position = self.config_manager.app_set('legend_position', 'right')
        self._mark_anomalies = self.config_manager.app_set('mark_anomalies', False)
        self._dark_theme = False

        self._preload_timer = None
        self._is_closing = False
        # v3.2fix(P-26): 删除死字段 self._reusable（仅赋值、全文无读取）
        # v2.26: 融合状态
        self._fuse_data_a = None
        self._fuse_data_b = None
        self._fuse_data_result = None
        self._fuse_active = False
        self._current_view = 'result'
        self._install_process = None
        # v3.2fix(P-26): 删除死字段 self._install_retry_count（仅赋值、全文无读取）

        self._professional_window = None

        self._init_ui(initial_multiplier, initial_output_dir, bsize)

        plot_opts = PlotOptions(
            show_daily=self.config_manager.app_set('show_daily', True),
            show_avg=self.config_manager.app_set('show_avg', True),
            show_max_demand=self._show_max_demand,
            highlight_mode=self._highlight_mode,
            weekday_color=self._weekday_color,
            weekend_color=self._weekend_color,
            holiday_color=self._holiday_color,
            weekend_line_width=self._weekend_line_width,
            holiday_line_width=self._holiday_line_width,
            show_weekend_bg=self._show_weekend_bg,
            legend_position=self._legend_position,
            mark_anomalies=self._mark_anomalies,
            dark_theme=self._dark_theme,
        )
        self.render_scheduler = _PreviewRenderScheduler(
            self.provider,
            self.all_summaries,
            self.settings_model,
            strategy_getter=self._periods_for_idx,
            title_tpl_getter=self.title_edit.text
        )
        self.render_scheduler.set_plot_options(plot_opts)
        self._connect_render_signals()
        self._apply_global_display_options()

        self.tree_controller.load(self.all_summaries, set())
        self.tree_controller.itemClicked.connect(self._navigate_to)
        self.tree_controller.selectionChanged.connect(self._on_tree_selection_changed)
        self.tree_controller.set_all_check(True)

        self.province_combo.currentTextChanged.connect(self._on_province_changed)
        self._last_province_text = self.province_combo.currentText()
        self._init_periods_fingerprints()

        self._preload_timer = QTimer(self)
        self._preload_timer.timeout.connect(self._preload_step)
        self._preload_timer.setInterval(300)

        # v2.28fix: 延迟启动渲染——避免窗口未完全初始化时触发渲染竞态
        self._act_btn_data.setChecked(True)  # 默认激活数据面板
        QTimer.singleShot(200, self._on_first_show)  # 200ms延迟(原0ms)

    def _on_activity_btn_clicked(self, btn):
        """活动栏按钮切换面板"""
        if btn == self._act_btn_data:
            self.sidebar_stack.setCurrentIndex(0)
        elif btn == self._act_btn_curve:
            self.sidebar_stack.setCurrentIndex(1)
        elif btn == self._act_btn_strategy:
            self.sidebar_stack.setCurrentIndex(2)
        elif btn == self._act_btn_output:
            self.sidebar_stack.setCurrentIndex(3)

    def _init_output_dir_history(self):
        recent = self.config_manager.get_recent_output_dirs()
        if recent:
            menu = QMenu(self)
            for d in recent:
                act = menu.addAction(d)
                act.triggered.connect(lambda checked, path=d: self.output_dir_edit.setText(path))
            self.browse_btn_for_dir.setMenu(menu)
            self.browse_btn_for_dir.setStyleSheet("QPushButton::menu-indicator { image: none; }")

    def _start_silent_render(self):
        priority = set()
        cur = self.current_index
        total = len(self.all_summaries)
        for offset in range(-2, 3):
            idx = (cur + offset) % total
            if idx not in self.tree_controller.no_data_indices:
                priority.add(idx)
        self.render_scheduler.schedule_batch(priority)

    def _on_first_show(self):
        if self._is_closing or not self.all_summaries:
            return
        # v2.28fix: 批量初始化期间屏蔽设置变更的重渲染
        self._batch_init = True
        try:
            self._navigate_to(0)
            self._start_silent_render()
            self._restart_preload_timer()
            self._init_output_dir_history()
        except Exception as e:
            log.exception(f"预览窗口初始化渲染失败: {e}")
            QMessageBox.warning(self, "预览渲染失败",
                f"无法渲染第1组数据的预览图,可能是数据格式异常.\n\n错误: {e}\n\n"
                "您可以继续调整设置,但预览图可能无法显示.")
        finally:
            self._batch_init = False
        # v2.28fix: 初始化完成后补调 UI 同步(被 batch_init 跳过的部分)
        self._update_multiplier_ui()
        self._update_billing_ui()
        self._refresh_info_label()
        self._update_title_preview()
        self._update_precision_label(0)
        self.tree_controller.set_current_index(0)

    def _connect_render_signals(self):
        self.render_scheduler.renderReady.connect(self._on_render_ready)
        self.render_scheduler.renderError.connect(self._on_render_error)
        self.render_scheduler.cacheProgress.connect(self.cache_progress_label.setText)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, 'view') and self.view and self.scene:
            self.view.fitInView(self.scene.itemsBoundingRect(), Qt.KeepAspectRatio)

    def _restart_preload_timer(self):
        if self._preload_timer is not None:
            self._preload_timer.stop()
            self._preload_timer.start()

    def _preload_step(self):
        remaining = [i for i in range(len(self.all_summaries))
                     if not self.render_scheduler.has_pixmap(i)
                     and not self.render_scheduler.is_rendering(i)
                     and i not in self.tree_controller.no_data_indices]
        if not remaining:
            self._preload_timer.stop()
            return
        # v2.28: 按距离当前页排序—优先预加载附近页,提升翻页命中率
        cur = self.current_index
        remaining.sort(key=lambda i: abs(i - cur))
        batch = remaining[:5]  # 扩大预加载批次:3→5
        for idx in batch:
            self.render_scheduler.schedule_render(idx)

