        self.mult_apply_selected_btn.setMinimumHeight(bsize)
        self.mult_apply_selected_btn.clicked.connect(self._apply_mult_to_selected)
        mult_btn_layout.addWidget(self.mult_apply_selected_btn)
        self.mult_apply_all_btn = QPushButton("🌐 应用至全部")
        self.mult_apply_all_btn.setMinimumHeight(bsize)
        self.mult_apply_all_btn.clicked.connect(self._apply_mult_to_all)
        mult_btn_layout.addWidget(self.mult_apply_all_btn)
        self.mult_apply_same_asset_btn = QPushButton("🏷 应用至同一表号")
        self.mult_apply_same_asset_btn.setMinimumHeight(bsize)
        self.mult_apply_same_asset_btn.clicked.connect(self._apply_mult_to_same_asset)
        mult_btn_layout.addWidget(self.mult_apply_same_asset_btn)
