# v3.2fix: 25行业参数库——从参考程序注入


def _generate_load_profile(industry, daily_kwh, peak_kw, n_days, n_points,
                           shift_start_h=8, shift_end_h=17,
                           lunch_start_h=12, lunch_end_h=13,
                           weekend_atten=0.40, cv=0.12,
                           equipment=None, seed=None,
                           province=None, use_season=True):
    """v3.0: 三层叠加负荷模拟引擎（从备份程序 v2.29+ 回填，修复 v3.2 的特性丢失）。

    Args:
        industry: 行业名称(INDUSTRY_PARAMS 的 key)
        daily_kwh: 日均用电量(kWh)
        peak_kw: 峰值功率估算(kW)
        n_days: 模拟天数
        n_points: 每日时间点数(96=15min, 48=30min, 24=1h)
        shift_start_h: 上班起始小时
        shift_end_h: 下班小时
        lunch_start_h: 午休起始
        lunch_end_h: 午休结束
        weekend_atten: 周末衰减系数(0~1, 0=完全不工作)
        cv: 日间变异系数
        equipment: 设备列表 [{'power':kW, 'count':n, 'simul':0.8, 'run_prob':0.85}, ...]
        seed: 随机种子(可复现)
        province: 省份(使用该省典型基线曲线, None=纯班制)
        use_season: 是否启用季节修正

    Returns:
        (load_array, date_labels, time_labels)
    """
    rng = np.random.RandomState(seed) if seed is not None else np.random
    params = INDUSTRY_PARAMS.get(industry, INDUSTRY_PARAMS['机械加工'])

    # ===== 第一层: 省份基线 + 班制叠加(24h → n_points 插值) =====
    hours_24 = np.arange(0.5, 24.0, 1.0)
    target_hours = np.linspace(0, 24, n_points, endpoint=False)

    if province and province in PROVINCE_BASELINES:
        province_base = np.array(PROVINCE_BASELINES[province], dtype=np.float64)
    else:
        province_base = np.ones(24, dtype=np.float64)

    shift_24 = np.array(SHIFT_PROFILES_24H.get(params['shift'], SHIFT_PROFILES_24H['两班倒']), dtype=np.float64)
    for h in range(24):
        if lunch_start_h <= h < lunch_end_h:
            shift_24[h] *= 0.30
    for h in range(24):
        if h < shift_start_h or h >= shift_end_h:
            shift_24[h] = shift_24[h] * 0.08 + params['base_load'] * 0.08 * 24

    base_24 = province_base * shift_24
    base_24 = base_24 / max(np.mean(base_24), 1e-9)
    base_profile = np.interp(target_hours, hours_24, base_24, left=base_24[0], right=base_24[-1])
    base_profile = base_profile / max(np.mean(base_profile), 1e-9)

    # ===== 第二层: 设备 Markov 叠加 =====
    equipment_profile = np.zeros(n_points)
    if equipment:
        for eq in equipment:
            eq_power = eq.get('power', 0) * eq.get('count', 0)
            if eq_power <= 0:
                continue
            state = 2
            p_fault = 1.0 - eq.get('run_prob', 0.85)
            p_restart = 0.3
            p_off = 0.05
            for t in range(n_points):
                hour = t / n_points * 24
                in_shift = (shift_start_h <= hour < shift_end_h)
                if in_shift:
                    r = rng.random()
                    if state == 2:
                        equipment_profile[t] += eq_power * eq.get('simul', 0.8)
                        if r < p_fault:
                            state = 1
                    elif state == 1:
                        equipment_profile[t] += eq_power * 0.15
                        if r < p_restart:
                            state = 2
                        elif r < p_off:
                            state = 0
                    else:
                        if r < p_restart * 0.5:
                            state = 1
                else:
                    equipment_profile[t] += eq_power * 0.03

    # ===== 第三层: 日间随机噪声(Gaussian平滑) =====
    daily_noise = rng.normal(1.0, cv, size=n_days)
    daily_noise = np.clip(daily_noise, 0.5, 1.5)
    try:
        from scipy.ndimage import gaussian_filter1d
        smoothed = gaussian_filter1d(daily_noise, sigma=2.0)
    except ImportError:
        from collections import deque
        smoothed = np.zeros(n_days)
        window = deque(maxlen=5)
        for i in range(n_days):
            window.append(daily_noise[i])
            smoothed[i] = np.mean(window)

    # ===== 合成 =====
    load_array = np.zeros((n_days, n_points))
    dt_hours = 24.0 / n_points
    start_date = datetime(2025, 1, 1)
    date_labels = []

    for d in range(n_days):
        current_date = start_date + timedelta(days=d)
        date_labels.append(current_date.strftime('%Y-%m-%d'))
        wd = current_date.weekday()
        is_weekend = (wd >= 5)
        atten = weekend_atten if is_weekend else 1.0
        if use_season:
            month = current_date.month
            if month in (6, 7, 8):
                season_factor = SEASON_FACTORS['summer']
            elif month in (12, 1, 2):
                season_factor = SEASON_FACTORS['winter']
            elif month in (9, 10, 11):
                season_factor = SEASON_FACTORS['autumn']
            else:
                season_factor = SEASON_FACTORS['spring']
        else:
            season_factor = 1.0
        profile = base_profile * smoothed[d] * atten * season_factor + equipment_profile / max(peak_kw, 1)
        actual_daily = np.sum(np.maximum(profile, 0)) * dt_hours
        scale = daily_kwh / max(actual_daily, 1e-9)
        load_array[d] = profile * scale

    time_labels = [f"{int(h):02d}:{int((h%1)*60):02d}" for h in target_hours]
    return load_array, date_labels, time_labels


def simulate_to_csv(output_path, industry, daily_kwh, peak_kw, n_days=365,
                    n_points=96, shift_start_h=8, shift_end_h=17,
                    lunch_start_h=12, lunch_end_h=13,
                    weekend_atten=0.40, cv=0.12,
                    equipment=None, seed=None, province=None, use_season=True):
    """v3.0: 执行模拟并导出为标准宽表CSV（从备份程序回填）。"""
    arr, dates, times = _generate_load_profile(
        industry, daily_kwh, peak_kw, n_days, n_points,
        shift_start_h, shift_end_h, lunch_start_h, lunch_end_h,
        weekend_atten, cv, equipment, seed, province, use_season
    )
    import csv as _csv
    with open(output_path, 'w', encoding='utf-8-sig', newline='') as f:
        w = _csv.writer(f)
        w.writerow(['日期'] + times)
        for i, d in enumerate(dates):
            w.writerow([d] + [f'{v:.2f}' for v in arr[i]])
    return output_path


def generate_load_profile(config=None):
    """v2.29: 参数化生成全年15分钟精度人工负荷曲线。

    Args:
        config: dict或None。None时使用电解铝默认模板。
            关键字段:
            - industry: 行业模板名(默认'电子制造'),覆盖以下参数
            - avg_power_kw: 平均功率(kW),默认500
            - daily_load_factor: 日负荷率(0~1)
            - peak_valley_ratio: 峰谷差率(0~1)
            - weekend_factor: 周末系数(0~1)
            - schedule: 'one_shift'/'two_shift'/'three_shift'/'commercial'
            - month_factors: [12个]月系数
            - morning_peak: (时, 增幅) 早高峰位置和强度
            - evening_peak: (时, 增幅) 晚高峰位置和强度
            - noon_valley: (时, 降幅) 午间谷深
            - noise_std: 随机噪声标准差比例,默认0.05
            - pv_kw: 叠加光伏容量(kW),默认0(不叠加)
            - n_days: 天数,默认365
            - n_points: 每日点数,默认96(15min)

    Returns:
        dict: {'load_array': (n_days,n_points), 'time_labels': [...], 'date_labels': [...], 'config': config}
    """
    import numpy as np
    from datetime import datetime

    # ── 默认配置 ──
    if config is None:
        config = {}
    industry = config.get('industry', '电子制造')
    template = INDUSTRY_TEMPLATES.get(industry, INDUSTRY_TEMPLATES['电子制造'])

    # 合并配置:用户配置覆盖模板默认值
    avg_power = config.get('avg_power_kw', 500.0)
    daily_load_factor = config.get('daily_load_factor', template['daily_load_factor'])
    peak_valley_ratio = config.get('peak_valley_ratio', template['peak_valley_ratio'])
    weekend_factor = config.get('weekend_factor', template['weekend_factor'])
    schedule = config.get('schedule', template['schedule'])
    month_factors = config.get('month_factors', template['month_factors'])
    morning_peak = config.get('morning_peak', template['morning_peak'])
    evening_peak = config.get('evening_peak', template['evening_peak'])
    noon_valley = config.get('noon_valley', template['noon_valley'])
    noise_std = config.get('noise_std', 0.05)
    pv_kw = config.get('pv_kw', 0.0)
    n_days = config.get('n_days', 365)
    n_points = config.get('n_points', 96)

    # ── 计算基准值 ──
    # 日负荷率 = 平均/最大 → 最大 = 平均/日负荷率
    peak_power = avg_power / max(daily_load_factor, 0.01)
    # 峰谷差率 = (峰值-谷值)/峰值 → 谷值 = 峰值*(1-峰谷差率)
    valley_power = peak_power * (1.0 - peak_valley_ratio)
    base_power = valley_power  # 基荷=谷值

    # ── 生成日典型曲线(0~1归一化) ──
    t = np.linspace(0, 24, n_points, endpoint=False)
    day_profile = np.ones(n_points)  # 基荷=1

    # 早高峰(高斯峰)
    mp_h, mp_amp = morning_peak
    morning_gauss = mp_amp * np.exp(-0.5 * ((t - mp_h) / 1.5) ** 2)
    day_profile += morning_gauss

    # 晚高峰(高斯峰)
    ep_h, ep_amp = evening_peak
    evening_gauss = ep_amp * np.exp(-0.5 * ((t - ep_h) / 1.5) ** 2)
    day_profile += evening_gauss

    # 午间低谷(下凹)
    nv_h, nv_depth = noon_valley
    noon_dip = nv_depth * np.exp(-0.5 * ((t - nv_h) / 2.0) ** 2)
    day_profile -= noon_dip

    # 班制修正
    if schedule == 'one_shift':
        # 单班:8-17点外大幅衰减
        mask = (t < 7) | (t > 18)
        day_profile[mask] *= 0.3
        mask2 = (t >= 7) & (t < 8)
        day_profile[mask2] *= 0.6
        mask2 = (t > 17) & (t <= 18)
        day_profile[mask2] *= 0.6
    elif schedule == 'two_shift':
        # 双班:6-22点,凌晨衰减
        mask = (t < 5) | (t > 23)
        day_profile[mask] *= 0.4
    elif schedule == 'commercial':
        # 商业:6-22点
        mask = (t < 6) | (t > 22)
        day_profile[mask] *= 0.35

    day_profile = np.maximum(day_profile, 0.05)  # 最低5%保底

    # ── 缩放至目标峰谷范围 ──
    day_profile = day_profile / day_profile.max()  # 归一化到0~1
    day_profile = valley_power + (peak_power - valley_power) * day_profile

    # ── 生成全年数据 ──
    result = np.zeros((n_days, n_points))
    date_labels = []

    for day_idx in range(n_days):
        # 日期
        d = datetime(2025, 1, 1) + timedelta(days=day_idx)
        date_labels.append(d.strftime('%Y-%m-%d'))

        # 月系数
        mf = month_factors[d.month - 1]

        # 日类型
        weekday = d.weekday()
        if weekday >= 5:  # 周六日
            day_factor = weekend_factor
        else:
            day_factor = 1.0

        # 日曲线 = 月系数 × 日类型 × 典型曲线
        daily = day_profile * mf * day_factor

        # 随机噪声
        if noise_std > 0:
            noise = np.random.normal(0, noise_std * avg_power, n_points)
            daily += noise

        daily = np.maximum(daily, 0.0)
        result[day_idx] = daily

    # ── 光伏叠加(可选) ──
    if pv_kw > 0:
        result = _add_pv_to_load(result, date_labels, pv_kw, n_points)

    time_labels = [f'{i*24*60//n_points//60:02d}:{i*24*60//n_points%60:02d}' for i in range(n_points)]

    return {
        'load_array': result,
        'time_labels': time_labels,
        'date_labels': date_labels,
        'config': config,
        'month_str': '2025-01',  # 全年数据
    }



def _add_pv_to_load(load_array, date_labels, pv_kw, n_points):
    """v2.29: 叠加简化光伏出力到负荷曲线上。"""
    import numpy as np
    load_array = load_array.copy()  # v3.2: 防御性拷贝
    t_day = np.linspace(0, 24, n_points, endpoint=False)
    # 简化的日光伏曲线:高斯形,峰值在12:30,宽度约6小时
    pv_profile = np.exp(-0.5 * ((t_day - 12.5) / 2.5) ** 2)
    pv_profile = pv_profile / pv_profile.max() * pv_kw
    # 日出/日落外归零
    pv_profile[(t_day < 5) | (t_day > 20)] = 0.0

    # 月调幅:夏季长冬季短
    month_pv_factor = [0.55,0.65,0.80,0.90,0.95,1.00,0.98,0.92,0.82,0.72,0.60,0.52]

    labels = date_labels
    for i in range(len(load_array)):
        m = int(labels[i][5:7]) if len(labels[i]) >= 7 else 1
        result = load_array[i] - pv_profile * month_pv_factor[m-1]
        # v3.1fix: 已通过传入.copy()避免副作用,调用方负责拷贝
        load_array[i] = result
    return load_array



def extract_load_features(load_array, date_labels):
    """v2.29: 从已有负荷数据提取特征参数(用于填充模拟配置)。"""
    import numpy as np
    arr = np.asarray(load_array, dtype=np.float64)
    if arr.ndim != 2 or arr.size == 0:
        return None
    daily_peak = np.max(arr, axis=1)
    daily_avg = np.mean(arr, axis=1)
    daily_min = np.min(arr, axis=1)

    avg_power = float(np.mean(daily_avg))
    peak_power = float(np.max(daily_peak))
    valley_power = float(np.min(daily_min))
    daily_load_factor = float(np.mean(daily_avg) / max(np.mean(daily_peak), 1.0))
    peak_valley_ratio = float((peak_power - valley_power) / max(peak_power, 1.0))

    # 月系数
    month_factors = [1.0] * 12
    try:
        for m in range(1, 13):
            idx = [i for i, d in enumerate(date_labels) if len(str(d)) >= 7 and int(str(d)[5:7]) == m]
            if idx:
                month_factors[m-1] = float(np.mean(daily_peak[idx]) / max(peak_power, 1.0))
    except Exception:
        pass

    # 工作日/周末比
    weekdays_avg = float(np.mean(daily_avg[:5]))
    weekends_avg = float(np.mean(daily_avg[5:7])) if len(daily_avg) >= 7 else weekdays_avg
    weekend_factor = weekends_avg / max(weekdays_avg, 1.0)

    return {
        'avg_power_kw': round(avg_power, 1),
        'daily_load_factor': round(daily_load_factor, 3),
        'peak_valley_ratio': round(peak_valley_ratio, 3),
        'weekend_factor': round(weekend_factor, 3),
        'month_factors': [round(f, 3) for f in month_factors],
    }

# 第四部分结束
