    def _update_loadsim_rainbow(self):
        """v3.2: RGB炫彩灯条——HslAnimator驱动splitter竖线."""
        p = HslAnimator().phase()
        c1 = HslAnimator.hsl_color(p, 0.85, 0.55).name()
        c2 = HslAnimator.hsl_color(p + 0.15, 0.85, 0.58).name()
        c3 = HslAnimator.hsl_color(p + 0.30, 0.80, 0.55).name()
        c4 = HslAnimator.hsl_color(p + 0.50, 0.85, 0.58).name()
        c5 = HslAnimator.hsl_color(p + 0.65, 0.80, 0.55).name()
        self._loadsim_splitter.setStyleSheet(
            f'QSplitter::handle {{'
            f'  background: qlineargradient(x1:0, y1:0, x2:0, y2:1,'
            f'    stop:0 {c1}, stop:0.25 {c3}, stop:0.5 {c5},'
            f'    stop:0.75 {c2}, stop:1 {c4});'
            f'  width: 4px; border-radius: 2px;'
            f'}}'
        )

    def _schedule_preview(self):
        """v3.0: 参数变化 → 重置防抖, 300ms内无新变化才执行."""
        if not self._preview_pending:
            self.preview_label.setText("⏳ 计算中...")
            self.preview_label.setStyleSheet("color:#999;font-size:13px;border:none;background:transparent;")
            self._preview_pending = True
        self._preview_timer.start()

    def _do_preview(self):
        """v3.0: 执行实时预览渲染."""
        self._preview_pending = False
        try:
            arr, dates, times = self._do_simulate()
            self._simulated_arr = arr
            self._simulated_dates = dates
            self._simulated_times = times
            self._render_preview(arr, dates, times)
            self._update_stats(arr)
        except Exception as e:
            self.preview_label.setText(f"预览失败: {e}")
            self.preview_label.setStyleSheet("color:#E53935; font-size:12px; border:1px solid #E0E4EC; border-radius:8px; background:#FFF5F5;")

    def _update_stats(self, arr):
        """v3.0: 更新统计条."""
        import numpy as np
        daily = np.sum(np.maximum(arr, 0), axis=1) * 24.0 / arr.shape[1]
        peak = np.max(arr)
        avg = np.mean(arr)
        par = peak / max(avg, 1e-9)
        lf = avg / max(peak, 1e-9)
        cv = np.std(daily) / max(np.mean(daily), 1e-9) * 100
        vals = {'peak': f'峰值 {peak:.0f}kW', 'avg': f'均值 {avg:.0f}kW',
                'par': f'峰谷比 {par:.1f}', 'lf': f'负荷率 {lf:.0%}',
                'cv': f'日CV {cv:.1f}%'}
        for k, lbl in self._stat_labels.items():
            lbl.setText(vals.get(k, ''))

    def _render_preview(self, arr, dates, times):
        """v3.2: 高清预览——30天全曲线叠加, 与主预览窗口风格一致."""
        import numpy as np
        from datetime import datetime
        _init_matplotlib()
        n_show = min(30, len(arr))
        fig, ax = _get_plt().subplots(1, 1, figsize=(10, 4.2))
        fig.patch.set_facecolor('#FAFBFC')
        # 工作日蓝 / 周末灰 分色叠加
        date_objs = [datetime.strptime(d, '%Y-%m-%d') for d in dates[:n_show]]
        weekday_color = '#5B9BD5'
        weekend_color = '#B0B0B0'
        for i in range(n_show):
            is_weekday = date_objs[i].weekday() < 5
            color = weekday_color if is_weekday else weekend_color
            lw = 0.6 if is_weekday else 0.4
            ax.plot(arr[i], color=color, lw=lw, alpha=0.55)
        # 均值线
        avg = np.nanmean(arr[:n_show], axis=0)
        ax.plot(avg, '#E53935', lw=1.8, label=f'均值({n_show}天)', zorder=10, alpha=0.85)
        # 时间轴
        n_pts = arr.shape[1]
        tick_step = max(1, n_pts // 8)
        tick_pos = range(0, n_pts, tick_step)
        tick_labels = [f'{i*24//n_pts:02d}:00' for i in tick_pos]
        ax.set_xticks(tick_pos)
        ax.set_xticklabels(tick_labels, fontsize=8)
        ax.set_ylabel('功率 (kW)', fontsize=10)
        ax.set_title(f'{self.ind_combo.currentText()} | 日均 {self.kwh_spin.value():.0f}kWh | {len(arr)}天',
                      fontsize=11, fontweight='bold')
        ax.legend(fontsize=8, loc='upper right', framealpha=0.8)
        ax.grid(True, alpha=0.15, ls=':')
        ax.tick_params(labelsize=8)
        ax.set_xlim(0, n_pts - 1)
        fig.tight_layout(pad=2.0)
        buf = io.BytesIO()
        fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor=fig.get_facecolor())
        _get_plt().close(fig)
        buf.seek(0)
        pix = QPixmap()
        pix.loadFromData(buf.read())
        pw = self.preview_label.width()
        ph = self.preview_label.height()
        if pw > 100 and ph > 100:
            scaled = pix.scaled(pw, ph, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        else:
            scaled = pix.scaled(700, 350, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        self.preview_label.setPixmap(scaled)
        self.preview_label.setStyleSheet("border:1px solid #E0E4EC; border-radius:8px;")

    def _add_equipment(self):
        """v3.0: 添加一行设备."""
        row = self.eq_table.rowCount()
