    def _on_engine_mode_changed(self, idx):
        """v2.16: 引擎模式切换回调 - 无感切换,实时生效"""
        mode = self.engine_mode_combo.currentData()
        if mode == ANALYSIS_ENGINE_MODE:
            return
        set_engine_mode(mode)
        meta = ENGINE_MODE_META[mode]
        self._log(f"引擎模式已切换: {meta['label']}", "info")

        # 无感切换:如果专业分析窗口已打开,直接通知它切换
        if hasattr(self, '_professional_window') and self._professional_window and self._professional_window.isVisible():
            try:
                self._professional_window.switch_engine_mode(mode)
                self._log(f"专业分析窗口已同步切换为 {meta['label']}", "info")
            except Exception as e:
                log.warning(f"专业分析窗口无感切换失败: {e}")
        else:
            # v2.19: Toast替代模态框 - 不打断用户操作
            ToastManager.show(self, f"已切换至 {meta['label']}", kind='success', duration=3000)

    def _update_accent_style(self):
        """v3.0: HSL色相环驱动渐变分隔线."""
        tokens = DesignTokens.current_tokens()
        c1 = HslAnimator.hsl_color(0.0, 0.6, 0.55).name()
        c2 = HslAnimator.hsl_color(0.15, 0.7, 0.60).name()
        c3 = HslAnimator.hsl_color(0.30, 0.6, 0.55).name()
        self._accent_line.setStyleSheet(
            f'background: qlineargradient(x1:0, y1:0, x2:1, y2:0, '
            f'stop:0 {tokens["ACCENT"].name()}, stop:0.3 {c1}, '
            f'stop:0.5 {c2}, stop:0.7 {c3}, stop:1 {tokens["ACCENT"].name()});'
            f'border: none; border-radius: 1px;'
        )

    def _update_splitter_rainbow(self):
        """v3.1: RGB炫彩灯条——HslAnimator驱动splitter竖线滚动彩虹."""
        p = HslAnimator().phase()
        # 五段彩虹色, 每段跟随phase偏移
        c1 = HslAnimator.hsl_color(p, 0.85, 0.55).name()
        c2 = HslAnimator.hsl_color(p + 0.12, 0.85, 0.58).name()
        c3 = HslAnimator.hsl_color(p + 0.25, 0.80, 0.55).name()
        c4 = HslAnimator.hsl_color(p + 0.40, 0.85, 0.58).name()
        c5 = HslAnimator.hsl_color(p + 0.55, 0.80, 0.55).name()
        self._main_splitter.setStyleSheet(
            f'QSplitter::handle {{'
            f'  background: qlineargradient(x1:0, y1:0, x2:0, y2:1,'
            f'    stop:0 {c1}, stop:0.2 {c2}, stop:0.4 {c3}, stop:0.6 {c4},'
            f'    stop:0.8 {c5}, stop:1 {c1});'
            f'  width: 4px; border-radius: 2px;'
            f'}}'
        )

    def _animate_accent(self):
        """v3.0: 已迁移至HslAnimator.phase_changed,保留空壳兼容."""
        pass

    def _update_status_breath(self):
        """v3.0: 就绪态HSL呼吸——冰蓝→青→冰蓝慢循环."""
        if not hasattr(self, '_header_status'):
            return
        text = self._header_status.text()
        if not text.startswith('●'):
            return  # 非就绪状态不呼吸
        c = HslAnimator.hsl_color(0.0, 0.35, 0.60)
        self._header_status.setStyleSheet(f"color: {c.name()}; background: transparent;")

