    def _scan_health_scores(self):
        """v2.15: 异步扫描文件列表中的负荷数据,计算并显示健康评分. v2.28fix: 分批提交防止队列溢出."""
        if self.file_list.count() == 0:
            QMessageBox.information(self, "提示", "文件列表为空,请先添加文件")
            return
        self._health_score_pending = 0  # v2.29fix: 先初始化再使用
        total_files = self.file_list.count()
        self.status_label.setText(f"正在扫描数据健康评分... (共{total_files}个文件,约需{max(1,total_files//3)}秒)")
        QApplication.processEvents()
        self._health_score_results = {}
        batch_size = min(20, QThreadPool.globalInstance().maxThreadCount() * 2)
        for i in range(self.file_list.count()):
            item = self.file_list.item(i)
            if not item:
                continue
            fp = item.data(Qt.UserRole)
            if not fp or not os.path.isfile(fp):
                continue
            self._health_score_pending += 1
            task = HealthScoreTask(fp)
            task.score_ready.connect(self._on_health_score_ready)
            QThreadPool.globalInstance().start(task)
        if self._health_score_pending == 0:
            self.status_label.setText("无有效文件可评分")

    def _on_health_score_ready(self, fp, score_info):
        """异步健康评分回调"""
        self.file_list.set_health_score(fp, score_info)
        self._health_score_pending -= 1
        if self._health_score_pending <= 0:
            self.status_label.setText('健康评分完成')
            ToastManager.show(self, "✅ 数据健康评分完成", 'success', 3000)
            QTimer.singleShot(4000, lambda: self.status_label.setText(""))

