# v3.2: 预测模型注册 (prophet/xgboost——ForecastEngine 启动时自动加载)
# ═══════════════════════════════════════════════════════════
def _add_prophet_model(engine):
    try:
        from prophet import Prophet
        engine.register_model('prophet', Prophet); return True
    except ImportError:
        return False

def _add_xgboost_model(engine):
    try:
        from xgboost import XGBRegressor
        engine.register_model('xgboost', XGBRegressor); return True
    except ImportError:
        return False


