# v2.17: 光伏发电模拟引擎
# ═══════════════════════════════════════════════════════════

def simulate_pv_profile(load_array, time_labels, capacity_kwp, city='杭州',
                         system_efficiency=0.80, use_online=False,
                         latitude=None, longitude=None,
                         tilt_angle=None, temperature_coeff=-0.0035):  # v2.27fix: 补充缺失参数
    """v2.19: DEPRECATED - 请使用 calc_pv_hourly_output() 替代.保留向后兼容.

    基于正弦曲线模型(离线)或 PVGIS API(在线)生成与负荷数据
    时间分辨率一致的光伏发电曲线.

    Args:
        load_array: shape (n_days, n_points) 的负荷数据(仅用于获取形状和时间分辨率)
        time_labels: 时间标签列表 ['00:00', '00:15', ...]
        capacity_kwp: 光伏装机容量 (kWp)
        city: 城市名(离线模式用,查找峰值日照小时数)
        system_efficiency: 系统综合效率(默认 0.80)
        use_online: 是否使用 PVGIS 在线数据
        latitude, longitude: 在线模式的经纬度

    Returns:
        pv_profile: shape (n_days, n_points),每行是当天的光伏发电曲线 (kW)
        metadata: {'annual_kwh': 年发电量估算, 'peak_hours': 峰值日照小时数, ...}
    """
    n_days, n_points = load_array.shape
    hours = np.array([_parse_min(_normalize_time_column_name(t)) / 60.0 for t in time_labels])
    pv_profile = np.zeros((n_days, n_points))

    if use_online and latitude is not None and longitude is not None:
        return _simulate_pv_pvgis(load_array, time_labels, capacity_kwp, latitude, longitude,
                                   system_efficiency)
    # ── 离线简化模型:正弦曲线 ──
    peak_hours = CITY_SUNSHINE_HOURS.get(city, 4.0)
    # v2.17: 倾角修正 - 根据纬度估算最佳倾角修正系数
    if tilt_angle is None and latitude is not None:
        tilt_angle = latitude * 0.76 + 3.1  # 工程经验公式
    elif tilt_angle is None:
        tilt_angle = 25.0  # 默认25度
    lat_rad = math.radians(latitude if latitude else 30)
    tilt_rad = math.radians(tilt_angle)
    # 倾角修正系数:倾斜面/水平面辐照比,简化模型取 cos(纬度-倾角)/cos(纬度)
    tilt_correction = math.cos(lat_rad - tilt_rad) / max(math.cos(lat_rad), 0.1)
    tilt_correction = max(0.85, min(tilt_correction, 1.15))  # 约束在0.85-1.15
    peak_hours *= tilt_correction

    # v2.17: 温度衰减 - 简化等效温度修正(正午辐照最强时温度最高,效率下降)
    # 典型晶体硅温度系数 -0.35%/degC,正午温升约25degC -> 效率下降约8.75%
    temp_derate = 1.0 + temperature_coeff * 25  # ~= 0.9125
    effective_efficiency = system_efficiency * temp_derate
    # 日照时长 = 峰值日照小时 / 0.7(将辐照总量折算为有效日照时长)
    # 峰值日照小时 ~= 倾斜面日总辐照 kWh/m2/day
    # 有效日照窗口 ~= 峰值日照小时 / sin(pi/2处平均值) ~= peak_hours / 0.637
    daylight_hours = peak_hours / 0.637
    daylight_hours = max(6.0, min(daylight_hours, 16.0))  # 约束在6-16小时

    sunrise = 12.0 - daylight_hours / 2.0
    sunset = 12.0 + daylight_hours / 2.0

    # 生成一天的光伏曲线模板(正弦波,峰值在正午)
    daily_template = np.zeros(n_points)
    for t_idx, h in enumerate(hours):
        if sunrise <= h <= sunset:
            # 正弦曲线:日出=0, 正午=1, 日落=0
            frac = (h - sunrise) / (sunset - sunrise)
            daily_template[t_idx] = np.sin(np.pi * frac)

    # 缩放到装机容量:峰值功率 ~= capacity x 系统效率
    # 正弦曲线积分为 2/pi x peak x daylight,需归一化使日发电量 = capacity x peak_hours x efficiency
    template_integral = np.trapz(daily_template, hours) if n_points > 1 else np.sum(daily_template) * 24/n_points
    scale = capacity_kwp * peak_hours * effective_efficiency / template_integral if template_integral > 0 else 0
    daily_template *= scale

    for d in range(n_days):
        pv_profile[d, :] = daily_template

    annual_kwh = capacity_kwp * peak_hours * effective_efficiency * 365
    metadata = {
        'city': city, 'capacity_kwp': capacity_kwp,
        'peak_sunshine_hours': round(peak_hours, 2),
        'system_efficiency': system_efficiency,
        'tilt_angle': round(tilt_angle, 1),
        'tilt_correction': round(tilt_correction, 3),
        'temp_derate': round(temp_derate, 4),
        'daylight_hours': round(daylight_hours, 1),
        'annual_kwh_est': round(annual_kwh, 0),
        'model': 'sine_simplified', 'online': False,
    }
    return pv_profile, metadata


def _simulate_pv_pvgis(load_array, time_labels, capacity_kwp, latitude, longitude,
                        system_efficiency=0.80):
    """v2.17: 通过 PVGIS API 获取真实逐时太阳辐射并计算光伏功率.
    使用欧盟 JRC PVGIS v5.2 API,免费无需密钥.首次调用约3-5秒.
    """
    n_days, n_points = load_array.shape
    try:
        url = (f"https://re.jrc.ec.europa.eu/api/v5_2/seriescalc?"
               f"lat={latitude}&lon={longitude}&peakpower={capacity_kwp}"
               f"&loss={round((1-system_efficiency)*100)}&outputformat=json"
               f"&startyear=2020&endyear=2020&pvtechchoice=crystSi"
               f"&mountingplace=free&trackingtype=0")
        req = urllib.request.Request(url, headers={'User-Agent': 'LoadCurveTool/2.17'})
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = json.loads(resp.read())
        hourly_power = np.array([h.get('P', 0) for h in data['outputs']['hourly']])
        # hourly_power 是8760个值,需要匹配 load_array 的时间分辨率
        if len(hourly_power) < n_days * 24:
            log.warning("PVGIS返回数据不足,回退到离线模型")
            return simulate_pv_profile(load_array, time_labels, capacity_kwp,
                                        system_efficiency=system_efficiency)

        # 取前 n_days 天,按小时间隔重采样到 n_points
        daily_hours = hourly_power[:n_days * 24].reshape(n_days, 24)
        if n_points == 24:
            pv_profile = daily_hours.astype(np.float64)
        else:
            hours_24 = np.arange(0.5, 24, 1.0)  # 24h 中心点
            target_hours = np.array([_parse_min(_normalize_time_column_name(t)) / 60.0 for t in time_labels])
            pv_profile = np.zeros((n_days, n_points))
            for d in range(n_days):
                pv_profile[d, :] = np.interp(target_hours, hours_24, daily_hours[d, :],
                                               left=0, right=0)
        annual_kwh = float(np.sum(hourly_power[:min(len(hourly_power), 8760)])) / 1000.0
        metadata = {
            'city': f'PVGIS({latitude:.2f},{longitude:.2f})',
            'capacity_kwp': capacity_kwp, 'system_efficiency': system_efficiency,
            'annual_kwh_est': round(annual_kwh, 0), 'model': 'PVGIS_v5.2', 'online': True,
        }
        return pv_profile, metadata
    except Exception as e:
        log.warning(f"PVGIS API调用失败({e}),回退到离线模型")
        return simulate_pv_profile(load_array, time_labels, capacity_kwp,
                                    system_efficiency=system_efficiency)


def compute_net_load(load_array, pv_profile):
    """v2.17: 计算净负荷 = 原始负荷 - 光伏发电.
    负值表示光伏返送电网,保留在数组中供 mode B/C 分析使用.
    """
    return load_array - pv_profile


