class SchemeComparisonDialog(QDialog):
    """v2.25: 多方案并排对比--两组储能配置的逐项PK."""
    def __init__(self, parent, load_array, time_labels, date_labels, province, month,
                 periods=None, billing=None, system_cost=None):
        super().__init__(parent)
        self.setWindowTitle("📊 方案对比")
        self.setMinimumSize(900, 600)
        self.load_array = load_array
        self.time_labels = time_labels
        self.date_labels = date_labels
        self.province = province
        self.month = month
        self.periods = periods
        self.billing = billing
        self.system_cost = system_cost
        self.result_a = None
        self.result_b = None
        bsize = int(base_size()) if 'base_size' in dir() else 32
        self._init_ui(bsize)

    def _init_ui(self, bsize):
        layout = QVBoxLayout(self)
        # 顶部:方案A/B参数输入
        top = QHBoxLayout()
        gb_a = QGroupBox("🔵 方案A")
        gl_a = QGridLayout(gb_a)
        gl_a.addWidget(QLabel("功率(kW):"), 0, 0)
        self.power_a = QSpinBox(); self.power_a.setRange(50, 2000); self.power_a.setValue(200)
        gl_a.addWidget(self.power_a, 0, 1)
        gl_a.addWidget(QLabel("容量(kWh):"), 1, 0)
        self.cap_a = QSpinBox(); self.cap_a.setRange(50, 10000); self.cap_a.setValue(400)
        gl_a.addWidget(self.cap_a, 1, 1)
        top.addWidget(gb_a)

        vs_label = QLabel("⚡\nVS"); vs_label.setAlignment(Qt.AlignCenter)
        vs_label.setStyleSheet("font-size:20px;font-weight:bold;color:#E67E22;")
        top.addWidget(vs_label)

        gb_b = QGroupBox("🟠 方案B")
        gl_b = QGridLayout(gb_b)
        gl_b.addWidget(QLabel("功率(kW):"), 0, 0)
        self.power_b = QSpinBox(); self.power_b.setRange(50, 2000); self.power_b.setValue(300)
        gl_b.addWidget(self.power_b, 0, 1)
        gl_b.addWidget(QLabel("容量(kWh):"), 1, 0)
        self.cap_b = QSpinBox(); self.cap_b.setRange(50, 10000); self.cap_b.setValue(600)
        gl_b.addWidget(self.cap_b, 1, 1)
        top.addWidget(gb_b)

        run_btn = QPushButton("▶ 开始对比"); run_btn.setObjectName("primary")
        run_btn.setMinimumHeight(bsize); run_btn.clicked.connect(self._run_comparison)
        top.addWidget(run_btn, alignment=Qt.AlignBottom)
        layout.addLayout(top)

        # 结果表格
        self.table = QTableWidget(0, 4)
        self.table.setHorizontalHeaderLabels(["指标", "方案A", "方案B", "优势"])
        self.table.horizontalHeader().setStretchLastSection(True)
        self.table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        layout.addWidget(self.table)

    def _run_comparison(self):
        pa, ca = self.power_a.value(), self.cap_a.value()
        pb, cb = self.power_b.value(), self.cap_b.value()

        # v2.27fix: 为每个方案构造独立的billing(容量线=容量÷2.0h估算)
        billing_a = {'value': ca / 2.0} if ca > 0 else self.billing
        billing_b = {'value': cb / 2.0} if cb > 0 else self.billing

        # v2.29fix: 传入force参数确保对比的是用户输入值而非自动推荐值
        ra = EnergyStorageEngineer.diagnose(
            self.load_array, self.time_labels, self.date_labels,
            province=self.province, month=self.month,
            periods=self.periods, billing=billing_a,
            system_cost_per_kwh=self.system_cost,
            force_power_kw=pa, force_capacity_kwh=ca
        )
        rb = EnergyStorageEngineer.diagnose(
            self.load_array, self.time_labels, self.date_labels,
            province=self.province, month=self.month,
            periods=self.periods, billing=billing_b,
            system_cost_per_kwh=self.system_cost,
            force_power_kw=pb, force_capacity_kwh=cb
        )
        self._populate_table(ra, rb, pa, ca, pb, cb)

    def _populate_table(self, ra, rb, pa, ca, pb, cb):
        ea = ra.get('economics', {})
        eb = rb.get('economics', {})
        rows = [
            ("配置", f"{pa}kW/{ca}kWh", f"{pb}kW/{cb}kWh", ""),
            ("峰谷价差", f"{ea.get('spread',0):.2f}元", f"{eb.get('spread',0):.2f}元", "相同"),
            ("年收益", f"¥{ea.get('annual_revenue',0):,.0f}", f"¥{eb.get('annual_revenue',0):,.0f}",
             "A优" if ea.get('annual_revenue',0) > eb.get('annual_revenue',0) else "B优"),
            ("回收期", f"{ea.get('payback_years',0):.1f}年", f"{eb.get('payback_years',0):.1f}年",
             "A优" if ea.get('payback_years',0) < eb.get('payback_years',0) else "B优"),
            ("ROI", f"{ea.get('roi_est',0):.1f}%", f"{eb.get('roi_est',0):.1f}%",
             "A优" if ea.get('roi_est',0) > eb.get('roi_est',0) else "B优"),
            ("投资成本", f"¥{ea.get('est_cost',0):,.0f}", f"¥{eb.get('est_cost',0):,.0f}",
             "A低" if ea.get('est_cost',0) < eb.get('est_cost',0) else "B低"),
        ]
        rec_a = ra.get('recommendation', {})
        rec_b = rb.get('recommendation', {})
        rows.append(("推荐功率", f"{rec_a.get('power_kw','?')}kW", f"{rec_b.get('power_kw','?')}kW", ""))
        rows.append(("推荐容量", f"{rec_a.get('capacity_kwh','?')}kWh", f"{rec_b.get('capacity_kwh','?')}kWh", ""))

        self.table.setRowCount(len(rows))
        for i, (label, va, vb, winner) in enumerate(rows):
            self.table.setItem(i, 0, QTableWidgetItem(label))
            self.table.setItem(i, 1, QTableWidgetItem(va))
            self.table.setItem(i, 2, QTableWidgetItem(vb))
            w = QTableWidgetItem(winner)
            if "A优" in winner or "A低" in winner:
                w.setForeground(QColor("#1E88E5"))
            elif "B优" in winner or "B低" in winner:
                w.setForeground(QColor("#E67E22"))
            self.table.setItem(i, 3, w)
        self.table.resizeColumnsToContents()


class ScenarioComparisonDialog(QDialog):
    """场景对比对话框:并行评估 2~3 组储能配置方案,自动推荐最优."""
    def __init__(self, parent, econ_calc_fn, base_config=None):
        super().__init__(parent)
        self.econ_calc_fn = econ_calc_fn  # 接受 (power, capacity, dod, eff) -> 经济指标 dict
        self.setWindowTitle("📊 场景对比分析")
        self.setMinimumSize(750, 520)
        self.resize(800, 550)
        self.setModal(True)
        bsize = int(base_size())
        DesignTokens.current_tokens()

        layout = QVBoxLayout(self)
        header = QLabel("<b>配置 2~3 组储能参数,对比经济指标.自动推荐最优方案.</b>")
        header.setFont(get_default_font(12, bold=False))
        layout.addWidget(header)

        self.scenario_widgets = []
        scenarios_layout = QVBoxLayout()

        # v2.15: 全局经济参数(所有场景共享)
        econ_group = QGroupBox("💰 经济参数(所有场景共用)")
        econ_group.setFont(get_default_font(12, bold=True))
        econ_gl = QGridLayout(econ_group)
        self._global_sc = QDoubleSpinBox(); self._global_sc.setRange(500, 5000); self._global_sc.setValue(1500)
        self._global_sc.setSuffix(' 元/kWh'); self._global_sc.setMinimumHeight(bsize)
        self._global_dc = QDoubleSpinBox(); self._global_dc.setRange(10, 60); self._global_dc.setValue(30)
        self._global_dc.setSuffix(' 元/kVA·月'); self._global_dc.setMinimumHeight(bsize)
        self._global_py = QSpinBox(); self._global_py.setRange(5, 25); self._global_py.setValue(10)
        self._global_py.setSuffix(' 年'); self._global_py.setMinimumHeight(bsize)
        econ_gl.addWidget(QLabel('系统单价:'), 0, 0); econ_gl.addWidget(self._global_sc, 0, 1)
        econ_gl.addWidget(QLabel('需量电费:'), 0, 2); econ_gl.addWidget(self._global_dc, 0, 3)
        econ_gl.addWidget(QLabel('项目年限:'), 0, 4); econ_gl.addWidget(self._global_py, 0, 5)
        scenarios_layout.addWidget(econ_group)

        defaults = [
            ('场景 A', 200, 400, 90, 90),
            ('场景 B', 300, 600, 90, 90),
            ('场景 C', 250, 500, 85, 88),
        ]
        if base_config:
            p = base_config.get('power_kW', 200)
            c = base_config.get('capacity_kWh', 400)
            d = base_config.get('dod', 90)
            e = base_config.get('efficiency', 90)
            defaults[0] = ('当前配置', p, c, d, e)

        for i, (label, pk, ck, dd, ef) in enumerate(defaults):
            gw = QGroupBox(label)
            gw.setCheckable(i > 0)  # 场景A 必选
            if i == 0:
                gw.setChecked(True)
            gw.setChecked(True)
            gl = QGridLayout(gw)
            ps = QDoubleSpinBox(); ps.setRange(0, 10000); ps.setValue(pk); ps.setSuffix(' kW')
            cs = QDoubleSpinBox(); cs.setRange(0, 100000); cs.setValue(ck); cs.setSuffix(' kWh')
            ds = QDoubleSpinBox(); ds.setRange(50, 100); ds.setValue(dd); ds.setSuffix(' %')
            es = QDoubleSpinBox(); es.setRange(70, 99); es.setValue(ef); es.setSuffix(' %')
            for w in [ps, cs, ds, es]:
                w.setMinimumHeight(bsize)
            gl.addWidget(QLabel('功率:'), 0, 0); gl.addWidget(ps, 0, 1)
            gl.addWidget(QLabel('容量:'), 0, 2); gl.addWidget(cs, 0, 3)
            gl.addWidget(QLabel('DOD:'), 1, 0); gl.addWidget(ds, 1, 1)
            gl.addWidget(QLabel('效率:'), 1, 2); gl.addWidget(es, 1, 3)
            res_label = QLabel('点击"运行对比"计算')
            res_label.setStyleSheet('color:#64748b;font-size:12px;padding:4px 0')
            gl.addWidget(res_label, 2, 0, 1, 4)
            scenarios_layout.addWidget(gw)
            self.scenario_widgets.append((gw, ps, cs, ds, es, res_label))
        layout.addLayout(scenarios_layout)

        btn_layout = QHBoxLayout()
        run_btn = QPushButton('🚀 运行对比')
        run_btn.setMinimumHeight(bsize)
        run_btn.setFont(get_default_font(12, bold=True))
        run_btn.clicked.connect(self._run_comparison)
        btn_layout.addWidget(run_btn)
        apply_best_btn = QPushButton('✅ 应用最优方案')
        apply_best_btn.setMinimumHeight(bsize + 4)
        apply_best_btn.clicked.connect(self._apply_best)
        btn_layout.addWidget(apply_best_btn)
        close_btn = QPushButton('关闭')
        close_btn.setMinimumHeight(bsize + 4)
        close_btn.clicked.connect(self.reject)
        btn_layout.addWidget(close_btn)
        layout.addLayout(btn_layout)

        self._best_index = 0
        self._best_irr = 0
        self._results = []

    def _run_comparison(self):
        self._results = []
        best_irr = -999
        best_idx = 0
        for i, (gw, ps, cs, ds, es, res_label) in enumerate(self.scenario_widgets):
            if not gw.isChecked():
                self._results.append(None)
                continue
            try:
                econ = self.econ_calc_fn(ps.value(), cs.value(), ds.value(), es.value(),
                                          self._global_sc.value(), self._global_dc.value(), self._global_py.value())
                self._results.append(econ)
                irr = econ.get('irr', 0)
                npv = econ.get('npv', 0)
                pb = econ.get('payback_years', 0)
                text = f'IRR: {irr}% | NPV: ¥{npv:,.0f} | 回收: {pb}年'
                if irr > best_irr:
                    best_irr = irr
                    best_idx = i
                if irr > 8:
                    color = '#059669'
                elif irr > 4:
                    color = '#d97706'
                else:
                    color = '#dc2626'
                res_label.setStyleSheet(f'color:{color};font-weight:bold;font-size:13px;padding:4px 0')
                res_label.setText(text)
            except Exception as e:
                self._results.append(None)
                res_label.setStyleSheet('color:#dc2626;font-size:12px')
                res_label.setText(f'计算失败: {e}')
        self._best_index = best_idx
        self._best_irr = best_irr
        # 高亮最优
        for i, (gw, _, _, _, _, _) in enumerate(self.scenario_widgets):
            if i == best_idx:
                gw.setStyleSheet('QGroupBox{border:2px solid #059669;border-radius:6px;padding:8px;margin:4px}')
            else:
                gw.setStyleSheet('')

    def _apply_best(self):
        if not self._results or self._best_index >= len(self._results):
            return
        best = self._results[self._best_index]
        if best:
            self.result = best
            self.accept()


class SensitivitySliderPanel(QWidget):
    """敏感性分析滑块面板:拖动滑块实时更新 IRR 等经济指标.

    参数: peak_price(0.6~1.4), system_cost(1.0~1.8), efficiency(85~95), degradation(0.5~3.0)
    """
    param_changed = Signal(dict)  # 参数变更时发出 {param: value}

    def __init__(self, parent=None):
        super().__init__(parent)
        layout = QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8)
        self._sliders = {}
        self._value_labels = {}
        self._result_labels = {}
        tokens = DesignTokens.current_tokens()

        params = [
            ('peak_price', '峰时电价', 0.6, 1.4, 1.0, 0.01, '元/kWh'),
            ('valley_price', '谷时电价', 0.2, 0.6, 0.35, 0.01, '元/kWh'),
            ('system_cost', '系统单价', 1.0, 2.0, 1.4, 0.01, '元/Wh'),
            ('efficiency', '充放电效率', 85, 96, 90, 1, '%'),
            ('degradation', '年衰减率', 0.5, 3.0, 1.5, 0.1, '%/年'),
        ]
        for key, label, lo, hi, default, step, unit in params:
            row = QHBoxLayout()
            lbl = QLabel(f'{label}:')
            lbl.setMinimumWidth(90)
            lbl.setFont(get_default_font(11, bold=False))
            row.addWidget(lbl)
            slider = QSlider(Qt.Horizontal)
            slider.setRange(int(lo / step), int(hi / step))
            slider.setValue(int(default / step))
            slider.valueChanged.connect(lambda v, k=key, s=step: self._on_slider_change(k, v * s))
            row.addWidget(slider, 1)
            val_label = QLabel(f'{default} {unit}')
            val_label.setMinimumWidth(80)
            val_label.setFont(get_default_font(11, bold=True))
            val_label.setStyleSheet(f"color: {tokens['TEXT_PRIMARY'].name()};")
            row.addWidget(val_label)
            res_label = QLabel('')
            res_label.setFont(get_default_font(10, bold=False))
            res_label.setStyleSheet(f"color: {tokens['TEXT_SECONDARY'].name()};")
            res_label.setMinimumWidth(160)
            row.addWidget(res_label)
            layout.addLayout(row)
            self._sliders[key] = slider
            self._value_labels[key] = val_label
            self._result_labels[key] = res_label

        self._unit_map = {p[0]: p[6] for p in params}
        self._step_map = {p[0]: p[5] for p in params}
        # v2.15: 防抖定时器,避免拖动滑块时高频刷新
        self._debounce_timer = QTimer(self)
        self._debounce_timer.setSingleShot(True)
        self._debounce_timer.setInterval(150)
        self._debounce_timer.timeout.connect(self._emit_params)  # 用于值还原

    def _on_slider_change(self, key, value):
        unit = self._unit_map.get(key, '')
        self._step_map.get(key, 0.01)
        actual_value = value  # value 已经是 * step 的结果
        if key in ('efficiency', 'degradation'):
            self._value_labels[key].setText(f'{actual_value:.1f} {unit}')
        else:
            self._value_labels[key].setText(f'{actual_value:.2f} {unit}')
        # 防抖:延迟 150ms 再发射,避免拖动时高频重算
        self._debounce_timer.start()

    def _emit_params(self):
        self.param_changed.emit(self.get_params_normalized())

    def update_results(self, key, irr, npv_val):
        """更新某个参数变更后的 IRR / NPV 显示"""
        if key in self._result_labels:
            self._result_labels[key].setText(f'-> IRR:{irr}% NPV:¥{npv_val:,.0f}')

    def get_params(self):
        """返回原始单位参数值"""
        result = {}
        for k, slider in self._sliders.items():
            step = self._step_map.get(k, 0.01)
            result[k] = slider.value() * step
        return result

    def get_params_normalized(self):
        """返回归一化参数值(价格/成本保持原值,效率/衰减转为小数)"""
        p = self.get_params()
        for k in ('efficiency', 'degradation'):
            if k in p:
                p[k] = p[k] / 100.0
        return p


# region 数据源健康评分 (v2.15)
def _compute_data_health_score(data_dict):
    """计算单个负荷数据源的健康评分(0~100 -> A~F),含行业基准参照.

    评估维度(参照 Q/GDW 11266 储能配置数据要求):
    - 完整度 (40%): 数据天数 vs 理论最大天数
    - 分辨率 (20%): >=96点(15min)满分; >=48点(30min)及格; <24点不建议
    - 异常率 (25%): IQR筛查异常点比例
    - 采样稳定性 (15%): 每日点数一致性

    行业基准:
    - A级 (>=90): 适合精确储能配置测算
    - B级 (>=75): 可用于初步方案,建议补充数据
    - C级 (>=60): 仅适宜估算量级,误差 +/-20%
    - D级 (>=40): 数据存在严重缺口或低分辨率
    - F级 (<40): 不建议用于任何配置决策
    """
    if data_dict is None or 'load_array' not in data_dict:
        return {'score': 0, 'grade': 'F', 'warnings': ['无有效负荷数据']}
    arr = np.asarray(data_dict['load_array'], dtype=np.float64)
    if arr.ndim != 2 or arr.size == 0:
        return {'score': 0, 'grade': 'F', 'warnings': ['数据维度异常']}
    n_days, n_points = arr.shape
    warnings = []

    # v2.29fix: 智能识别数据分辨率——用行数/天数而不是列数(列可能是通道不是时间点)
    date_labels = data_dict.get('date_labels', [])
    points_per_day_est = n_points  # v3.2fix: 评分用的"每日点数"估计值, 与数组列数 n_points 解耦
    if date_labels:
        unique_dates = len(set(d[:10] for d in date_labels))
        if unique_dates > 0:
            pts_per_day = n_days / unique_dates
            if pts_per_day > n_points:
                # 原实现直接改写 n_points, 随后 arr[:, j] 越界崩溃(多资产长表是常态输入)
                points_per_day_est = int(round(pts_per_day))
    arr_std = np.nanstd(arr)
    if arr_std < 1e-9 or np.allclose(arr, arr[0,0], atol=1e-6):
        return {'score': 0, 'grade': 'F', 'warnings': ['数据方差为零(所有值相同或全为零),无法进行负荷分析.请检查数据源.']}

    # 1. 完整度评分
    date_labels = data_dict.get('date_labels', [])
    if date_labels:
        unique_dates = sorted(set(d.rsplit('/', 2)[0] if '/' in d else d[:10] for d in date_labels))
        if len(unique_dates) >= 2:
            try:
                d0 = datetime.strptime(unique_dates[0].replace('-', '/'), '%Y/%m/%d')
                d1 = datetime.strptime(unique_dates[-1].replace('-', '/'), '%Y/%m/%d')
                span_days = max((d1 - d0).days + 1, len(unique_dates))
            except Exception:
                span_days = max(len(unique_dates), n_days)
        else:
            span_days = n_days
    else:
        span_days = n_days
    completeness = min(n_days / max(span_days, 1), 1.0)
    completeness_score = completeness * 40
    if completeness < 0.7:
        warnings.append(f'数据覆盖仅 {completeness*100:.0f}%,可能缺少典型季节数据')

    # 2. 分辨率评分
    if points_per_day_est >= 96:
        res_score = 20
    elif points_per_day_est >= 48:
        res_score = 15
        warnings.append(f'分辨率 {points_per_day_est}点/日(建议 >=96点)')
    elif points_per_day_est >= 24:
        res_score = 10
        warnings.append(f'低分辨率 {points_per_day_est}点/日,容量计算精度下降')
    else:
        res_score = 5
        warnings.append(f'极低分辨率 {points_per_day_est}点/日,不建议用于精确测算')

    # 3. 异常率评分
    anomaly_rate = 0
    for j in range(n_points):
        col = arr[:, j]
        valid = ~np.isnan(col)
        if valid.sum() < 3:
            continue
        q1, q3 = np.percentile(col[valid], 25), np.percentile(col[valid], 75)
        iqr = q3 - q1
        if iqr > 0:
            outlier_mask = (col < q1 - 3 * iqr) | (col > q3 + 3 * iqr)
            anomaly_rate += outlier_mask.sum()
    anomaly_pct = anomaly_rate / max(n_days * n_points, 1)
    anomaly_score = max(0, 25 - anomaly_pct * 250)
    if anomaly_pct > 0.05:
        warnings.append(f'检测到 {anomaly_pct*100:.1f}% 异常数据点')

    # 4. 采样稳定性
    daily_points = np.sum(~np.isnan(arr), axis=1)
    if len(daily_points) > 1 and np.std(daily_points) < 1:
        stability_score = 15
    elif len(daily_points) > 1 and np.std(daily_points) / max(np.mean(daily_points), 1) < 0.1:
        stability_score = 10
    else:
        stability_score = 5
        if len(daily_points) > 1 and np.std(daily_points) > 0:
            warnings.append('每日采样点数不一致,可能存在数据缺口')

    total = completeness_score + res_score + anomaly_score + stability_score
    total = max(0, min(100, total))
    if total >= 90:
        grade = 'A'
    elif total >= 75:
        grade = 'B'
    elif total >= 60:
        grade = 'C'
    elif total >= 40:
        grade = 'D'
    else:
        grade = 'F'

    return {'score': round(total), 'grade': grade, 'warnings': warnings,
            'details': {'completeness': round(completeness*100), 'resolution': n_points,
                        'anomaly_pct': round(anomaly_pct*100, 1), 'n_days': n_days}}

# v2.16: 智能显示参数推荐(基于负荷特征自动建议最优显示设置)
def _recommend_display_params(load_array, time_labels=None):
    """根据负荷数据特征推荐最优显示参数.
    返回: {y_max, suggest_highlight, suggest_fit, summary}
    """
    if load_array is None or load_array.size == 0:
        return {'summary': '无有效数据'}

    arr = np.asarray(load_array, dtype=np.float64)
    if arr.ndim != 2:
        return {'summary': '数据格式不支持'}

    n_days, n_points = arr.shape

    # Y轴范围:95分位数 + 10%余量
    p95 = float(np.nanpercentile(arr, 95))
    y_max = round(p95 * 1.1, -1)  # 取整到十位

    # 建议高亮模式:数据覆盖>=7天且包含周末 -> 建议开启周末突出
    suggest_highlight = 'none'
    if n_days >= 7:
        suggest_highlight = 'weekend'

    # 建议拟合算法:日间方差大 -> 建议用聚类拟合发现典型模式
    daily_means = np.nanmean(arr, axis=1)
    cv = float(np.std(daily_means) / max(np.nanmean(daily_means), 1))
    suggest_fit = 'none'
    fit_reason = ''
    if cv > 0.3 and n_days > 10:
        suggest_fit = 'kmedoids'
        fit_reason = f'日负荷变异系数{cv:.1%},建议聚类拟合识别典型模式'
    elif cv > 0.15 and n_days > 5:
        suggest_fit = 'percentile_envelope'
        fit_reason = f'日负荷波动适中(cv={cv:.1%}),建议分位数包络'

    parts = []
    if y_max > 0:
        parts.append(f'建议Y轴上限: {int(y_max)}')
    if suggest_highlight != 'none':
        parts.append('建议开启周末高亮')
    if suggest_fit != 'none':
        parts.append(fit_reason)

    return {
        'y_max': y_max,
        'suggest_highlight': suggest_highlight,
        'suggest_fit': suggest_fit,
        'cv': round(cv, 3),
        'summary': ' | '.join(parts) if parts else '数据正常,使用默认设置即可'
    }
# endregion

