import types as _types
import sys as _sys

_names = {
    "adapter": ["load_array_to_series", "load_dict_to_series",
                  "periods_to_price_series", "DemandReport",
                  "ScheduleReport", "CapacityReport", "_parse_time_min"],
    "demand": ["calc_demand", "calc_sliding_window", "calc_fixed_window",
                "calc_demand_charge", "analyze_from_series", "compare_windows",
                "DemandConfig", "DemandResult"],
    "scheduler": ["solve_user_side_bess", "solve_bess_arbitrage",
                   "DispatchInput", "DispatchResult", "BESSParams"],
    "capacity": ["scan_capacity", "scan_capacity_multi_scenario",
                  "calc_investment", "calc_irr", "calc_npv", "calc_lcos",
                  "calc_simple_payback", "sensitivity_analysis",
                  "InvestmentParams", "CapacityPlan", "CostScenario",
                  "NRELCostData", "ITCConfig", "get_nrel_costs",
                  "get_nrel_cost_summary", "resolve_investment_params"],
    "compare": ["compare_demand", "format_demand_comparison",
                 "analyze_battery_cycles", "format_cycle_report",
                 "greedy_dispatch_annual", "DemandCompareResult", "CycleReport"],
    "settlement": ["calc_demand_saving", "calc_energy_saving",
                    "calc_monthly_settlement", "calc_payback_timeline",
                    "SettlementPeriod", "AnnualSettlement"],
}

for mod, names in _names.items():
    m = _types.ModuleType(f"powercurve_ext.{mod}")
    for n in names:
        if n in dir():  # globals
            setattr(m, n, globals()[n])
    _sys.modules[f"powercurve_ext.{mod}"] = m

# parent package
m = _types.ModuleType("powercurve_ext")
_sys.modules["powercurve_ext"] = m
del _types, _sys, _names, m, mod, names, n

# ═══════════════════════════════════════════════════════════════

class EnergyStorageEngineer:
    """顶级储能工程师:从负荷数据到储能方案的全自动推理流水线.

    输入:load_array + 元数据(省份、月份、电价策略)
    输出:EngineerReport(用户画像 + 分析结论 + 储能推荐 + 经济预估 + 风险提示)

    推理链:
      数据质量 -> 用户分型 -> 需量分析 -> 极端日 -> 趋势分解
      -> 电价匹配 -> 空间计算 -> 容量推荐 -> 经济性预估 -> 风险研判
    """

    # v2.23: 引用全局BESS常量,消除类内重复定义
    DEFAULT_SYSTEM_COST_PER_KWH = ECON_SYSTEM_COST_PER_KWH
    DEFAULT_DOD = BESS_DOD_DEFAULT
    TRANSFORMER_PF = XFMR_POWER_FACTOR
    REC_PEAK_VALLEY_RATIO = CAP_PEAK_VALLEY_RATIO
    REC_POWER_MIN_KW = CAP_MIN_POWER_KW
    REC_POWER_MAX_KW = CAP_MAX_POWER_KW
    EFF_CHARGE = BESS_EFF_CHARGE
    EFF_DISCHARGE = BESS_EFF_DISCHARGE
    BESS_COST_PER_KWH_LOW = 600
    BESS_COST_PER_KWH_HIGH = 850

    @staticmethod
    def diagnose(load_array, time_labels=None, date_labels=None,
                 province=None, month=None, periods=None,
                 billing=None, transformer_capacity=None,
                 system_cost_per_kwh=None,
                 force_power_kw=None, force_capacity_kwh=None) -> dict:
        """执行完整储能诊断流水线(13步推理链),返回结构化工程师报告.

        推理链: 数据质量门禁->用户分型->需量特征->极端日分析->趋势分解
                ->电价匹配->充放电空间->容量推荐->经济性预估->风险研判
                ->摘要生成->扩展模块->HTML报告

        Args:
            load_array: np.ndarray, shape (n_days, n_timepoints), 负荷数据(kW)
            time_labels: 时间标签列表 ['00:00','00:15',...]
            date_labels: 日期标签列表 ['2024-01-01',...]
            province: 省份名(用于电价匹配)
            month: 月份(1-12)
            periods: 手动充放电时段(优先级高于电价DB)
            billing: 容量线配置 {'value': float}
            transformer_capacity: 变压器容量(kVA),用于约束储能充电功率
            system_cost_per_kwh: 系统单价(元/kWh),默认800元/kWh

        Returns:
            dict with keys: data_profile, consumer, demand, load_quality,
                recommendation{powr_kw,capacity_kwh,reasoning},
                economics{spread,daily_revenue,annual_revenue,payback_years,irr_est},
                tariff, spaces, extreme_days, trend, risks, summary, extensions

        Raises:
            不抛异常--所有错误以 {'error': str} 返回

        References:
            - BESO (2024): Battery Energy Storage Optimization methodology
            - NREL SAM: System Advisor Model financial assumptions
            - 发改价格〔2026〕114号: 容量电价机制
        """
        if load_array is None or (hasattr(load_array, 'size') and load_array.size == 0):
            return {'error': '无有效负荷数据'}

        arr = np.asarray(load_array, dtype=np.float64)
        if arr.ndim != 2:
            return {'error': '数据维度异常,需要2D数组(天x时间点)'}

        n_days, n_points = arr.shape
        if n_points < 2:
            return {'error': f'时间分辨率不足(n_points={n_points}),至少需要2个时间点'}
        report = {
            'data_profile': {'n_days': n_days, 'n_points': n_points,
                             'resolution': f'{1440/n_points:.0f}分钟' if n_points > 0 else '未知'},
            'consumer': {},
            'demand': {},
            'load_quality': {},
            'recommendation': {},
            'economics': {},
            'risks': [],
        }

        # 1. 数据质量
        monthly_data = {'_all': {'load_array': arr, 'date_labels': date_labels or []}}
        health = _compute_data_health_score(monthly_data.get('_all'))
        report['load_quality'] = {
            'grade': health['grade'], 'score': health['score'],
            'warnings': health.get('warnings', [])
        }

        # v2.16: 数据质量门禁 - 健康分低于阈值时中止后续计算,避免垃圾进垃圾出
        if health['score'] < DQ_HEALTH_ABORT_THRESHOLD:
            report['quality_abort'] = True
            report['quality_abort_reason'] = (
                f"数据健康分 {health['score']:.0f}/100 ({health['grade']}级),低于安全阈值 {DQ_HEALTH_ABORT_THRESHOLD} 分."
                f"后续储能方案可能严重失准.建议:{';'.join(health.get('warnings', ['补充更多日期数据', '提高采样分辨率至>=96点/日']))}"
            )
            report['recommendation'] = {'power_kw': 0, 'capacity_kwh': 0, 'note': '数据质量不足,未生成推荐'}
            report['economics'] = {'note': '数据质量不足,未计算经济指标'}
            report['risks'] = [f'🔴 数据质量{health["grade"]}级({health["score"]:.0f}分),不建议基于当前数据做投资决策']
            report['summary'] = f"⚠ 数据质量不足({health['grade']}级,{health['score']:.0f}分),已中止自动分析.请补充数据后重试."
            return report

        # 2. 用户画像
        consumer = _classify_consumer_type(monthly_data)
        report['consumer'] = consumer

        # 3. 需量特征
        demand = _analyze_demand_characteristics(monthly_data, transformer_capacity)
        report['demand'] = demand
        report['data_profile']['max_demand'] = demand.get('max_demand', 0)
        report['data_profile']['p95_demand'] = demand.get('p95_demand', 0)

        # 4. 极端日
        extreme = _extreme_day_analysis(monthly_data)
        report['extreme_days'] = extreme

        # 5. 趋势
        trend = _decompose_load_trend(monthly_data)
        report['trend'] = trend

        # 6. 显示参数推荐
        display_rec = _recommend_display_params(arr, time_labels)
        report['display_recommendation'] = display_rec

        # 7. 电价匹配
        if province:
            strategy = tariff_to_strategy(province, month)
            tariff_info = PROVINCE_TARIFF_DB.get(province, {})
            report['tariff'] = {
                'province': province, 'month': month,
                'strategy': strategy,
                'peak_price': tariff_info.get('peak', 0),
                'valley_price': tariff_info.get('valley', 0),
                'flat_price': tariff_info.get('flat', 0),
                'mode': tariff_info.get('mode', '未知'),
                'note': tariff_info.get('note', ''),
            }
            # v2.24: 电价DB时效检查 - 软警告(>90天) + 硬门禁(>180天)
            stale, hard_stale, stale_msg = check_tariff_db_freshness()
            if stale:
                report['tariff']['stale_warning'] = stale_msg
                if hard_stale:
                    report['risks'].insert(0, f'🔴 电价数据库已严重过期: {stale_msg[:80]}')
                    report['economics'] = {'note': '电价数据过期(>{TARIFF_DB_STALE_DAYS}天),未计算经济指标'}
                else:
                    report['risks'].append(f'⚠ 电价数据库可能过期: {stale_msg[:60]}...')
        else:
            report['tariff'] = {'province': '未指定', 'note': '请选择省份以获取电价策略'}

        # 8. 充放电空间(如果有periods)
        if periods and time_labels:
            strategy_periods = tariff_to_strategy(province, month) if province else periods
            if strategy_periods and isinstance(strategy_periods[0], tuple):
                strategy_segments = []
                for s, e, t in strategy_periods:
                    if t == 'charge':
                        seg_type, seg_label = PeriodType.CHARGE, '充电'
                    elif t == 'discharge':
                        seg_type, seg_label = PeriodType.DISCHARGE, '放电'
                    else:
                        seg_type, seg_label = t, str(t)
                    strategy_segments.append({'start': s, 'end': e, 'type': seg_type, 'label': seg_label})
            else:
                strategy_segments = strategy_periods
            try:
                spaces = compute_segmented_spaces(arr, time_labels, strategy_segments, billing, 'A')
                report['spaces'] = {
                    'charge_kwh': round(float(np.sum(spaces[0] if isinstance(spaces, tuple) else spaces.get('charge_daily', [0]))), 1),
                    'discharge_kwh': round(float(np.sum(spaces[1] if isinstance(spaces, tuple) else spaces.get('discharge_daily', [0]))), 1),
                }
            except (ValueError, TypeError, IndexError) as e:
                log.warning(f"充放电空间计算失败: {e}")
                report['spaces'] = {'error': f'空间计算失败: {e}'}

        # 9. 容量推荐(v2.16: 含变压器约束 + DOD修正 + 一充一放模式修正)
        p95 = demand.get('p95_demand', 100)
        # 储能功率建议:覆盖峰谷差的60-80%
        peak_valley_gap = demand.get('reducible', p95 * 0.3)
        rec_power = round(peak_valley_gap * EnergyStorageEngineer.REC_PEAK_VALLEY_RATIO, -1)
        rec_power = max(EnergyStorageEngineer.REC_POWER_MIN_KW, min(rec_power, EnergyStorageEngineer.REC_POWER_MAX_KW))
        # v2.16: 变压器容量约束 - 充电功率不超过变压器容量 x 功率因数
        if transformer_capacity and transformer_capacity > 0:
            max_allowed_power = transformer_capacity * EnergyStorageEngineer.TRANSFORMER_PF
            if rec_power > max_allowed_power:
                rec_power = round(max_allowed_power, -1)
                report['transformer_constraint'] = {
                    'capacity_kva': transformer_capacity,
                    'max_charge_power_kw': round(max_allowed_power, 1),
                    'note': f'充电功率已按变压器容量{transformer_capacity}kVAx功率因数{EnergyStorageEngineer.TRANSFORMER_PF}限制'
                }
        # 储能容量建议:两充两放->2h,一充一放->根据实际可用窗口推算
        tariff_mode = report['tariff'].get('mode', CHARGE_MODE_TWO_CYCLES)
        if CHARGE_MODE_TWO_CYCLES in tariff_mode:
            duration_h = 2.0
        elif CHARGE_MODE_ONE_CYCLE in tariff_mode:
            # 一充一放模式:取低谷时段实际可用时长(至少4h,典型6-8h)
            info = PROVINCE_TARIFF_DB.get(province, {})
            raw_periods = info.get('periods', [])
            if raw_periods:
                # 取第一个可用时段列表
                sample_periods = raw_periods[0] if isinstance(raw_periods[0], tuple) else None
                if sample_periods and isinstance(sample_periods, tuple):
                    sample_periods = sample_periods[1]
                if not sample_periods:
                    sample_periods = raw_periods
                valley_hours = sum(e - s for s, e, t in (sample_periods if not isinstance(sample_periods[0], tuple) else sample_periods) if t in ('valley', 'deep_valley'))
                duration_h = max(4.0, valley_hours)
            else:
                duration_h = 4.0
        else:
            duration_h = 2.0
        rec_capacity = round(rec_power * duration_h, -1)

        # v2.16: DOD 修正使用统一常量
        DOD = EnergyStorageEngineer.DEFAULT_DOD
        rec_capacity_dod = round(rec_capacity / DOD, -1)
        # v2.28fix: 允许外部强制指定功率/容量,覆盖自动推荐(用于 sweep_capacity)
        if force_power_kw is not None and force_power_kw > 0:
            rec_power = float(force_power_kw)
            duration_h = force_capacity_kwh / rec_power if force_capacity_kwh else 2.0
            rec_capacity_dod = int(force_capacity_kwh) if force_capacity_kwh else rec_capacity_dod
        report['recommendation'] = {
            'power_kw': int(rec_power),
            'capacity_kwh': int(rec_capacity_dod),
            'duration_h': duration_h,
            'charge_mode': tariff_mode,
            'dod': DOD,
            'reasoning': f'基于{report["consumer"]["type"]}类型,p95需量{p95:.0f}kW,峰谷可削减{peak_valley_gap:.0f}kW'
        }
        if transformer_capacity and transformer_capacity > 0 and rec_power >= max_allowed_power * 0.95:
            report['recommendation']['reasoning'] += f'(受变压器{transformer_capacity}kVA约束)'

        # 10. 经济性预估(v2.24: 系统单价可配置 + 效率修正 + VAT)
        cost_per_kwh = system_cost_per_kwh if system_cost_per_kwh is not None else EnergyStorageEngineer.DEFAULT_SYSTEM_COST_PER_KWH
        if province and tariff_info:
            peak_price = tariff_info.get('peak', 0)
            valley_price = tariff_info.get('valley', 0)
            spread = peak_price - valley_price
            # v2.17: 使用类常量替换硬编码效率值
            EFF_C = EnergyStorageEngineer.EFF_CHARGE
            EFF_D = EnergyStorageEngineer.EFF_DISCHARGE
            VAT_RATE = ECON_VAT_RATE  # v2.24: 电力行业综合增值税率 6.5%
            if spread > 0 and rec_capacity_dod > 0:
                daily_cycles = 2 if CHARGE_MODE_TWO_CYCLES in tariff_mode else 1
                # 电网侧实际日收益 = 放电量xeff_dx峰价 - 充电量/eff_cx谷价, 扣除VAT
                cycle_charge_kwh = rec_capacity_dod * DOD / EFF_C      # 单次循环充电量(kWh)
                cycle_discharge_kwh = rec_capacity_dod * DOD * EFF_D   # 单次循环放电量(kWh)
                daily_revenue = cycle_discharge_kwh * peak_price - cycle_charge_kwh * valley_price
                daily_revenue *= daily_cycles
                annual_revenue = daily_revenue * _get_operating_days() * (1.0 - VAT_RATE)  # v2.24: VAT修正
                est_cost = rec_capacity_dod * cost_per_kwh
                payback = est_cost / max(annual_revenue, 1)
                roi_est = round((annual_revenue / est_cost) * 100, 1)  # v2.23: 简单ROI,非IRR
                report['economics'] = {
                    'system_cost_per_kwh': cost_per_kwh,
                    'spread': round(spread, 2),
                    'daily_revenue': round(daily_revenue, 0),
                    'annual_revenue': round(annual_revenue, 0),
                    'est_cost': round(est_cost, 0),
                    'payback_years': round(payback, 1),
                    'roi_est': roi_est,  # v2.23: 重命名为ROI(投资回报率),原字段名irr_est误导
                    'efficiency_note': f'已含充电效率{EFF_C}x放电效率{EFF_D}~=往返{round(EFF_C*EFF_D*100)}%修正'
                }

        # 11. 风险研判 (v2.16: 新增变压器约束风险)
        risks = []
        if health['grade'] in ('D', 'F'):
            risks.append(f"数据质量{health['grade']}级,建议补充数据后再决策")
        if province and tariff_mode == CHARGE_MODE_MARKET:
            risks.append(f"{province}已取消固定分时电价,实际收益受现货市场影响,本工具基于历史时段估算仅供参考")
            # v2.23: 现货省份强制降级提示--建议用户导入市场化电价曲线
            if not report.get('tariff', {}).get('market_prices_imported'):
                risks.append(f"⚠ {province}为现货市场省份,建议导入市场化电价曲线(CSV)以获得准确收益估算")
        if consumer.get('load_factor', 0) < 0.35:
            risks.append('负荷率低(<0.35),储能利用小时数可能不足,建议核实')
        if demand.get('max_demand', 0) > 5000:
            risks.append('最大需量超5000kW,建议考虑分步部署或高压侧接入')
        # v2.16: 变压器容量约束风险
        if transformer_capacity and transformer_capacity > 0 and rec_power > transformer_capacity * EnergyStorageEngineer.TRANSFORMER_PF * 1.05:
            risks.append(f'推荐功率({rec_power}kW)超过变压器容量({transformer_capacity}kVA)x功率因数的安全充电上限,建议确认变压器扩容可行性')
        if rec_capacity_dod > 2000:
            risks.append(f'单站容量{rec_capacity_dod}kWh较大,建议评估消防验收和并网审批周期')
        report['risks'] = risks

        # 11.5. v2.26: 需求响应收益叠加
        if province and rec_power > 0:
            dr = estimate_dr_revenue(rec_power, duration_h, province=province)
            if 'annual_revenue' not in report.get('economics', {}):
                report['economics'] = report.get('economics', {})
                report['economics']['annual_revenue'] = 0  # v2.28fix: 初始化
            report['economics']['dr_revenue'] = dr['annual_dr_revenue']
            report['economics']['dr_price'] = dr['dr_price']
            report['economics']['dr_note'] = dr['note']
            report['economics']['annual_revenue'] += dr['annual_dr_revenue']
            report['economics']['total_note'] = f"含DR补贴¥{dr['annual_dr_revenue']:,.0f}"
            # 重算回收期
            if report['economics'].get('est_cost', 0) > 0:
                total_rev = report['economics']['annual_revenue']
                report['economics']['payback_years'] = round(report['economics']['est_cost'] / max(total_rev, 1), 1)

        # 12. 生成自然语言摘要
        report['summary'] = EnergyStorageEngineer._generate_summary(report)

        # 13. 扩展模块 (v3.0: 联合优化 + 峰值预测 + 退化预估)
        try:
            _ext_raw = {
                'load_array': arr, 'time_labels': time_labels,
                'date_labels': date_labels, 'periods': periods,
                'province': province, 'month': month,
                'tariff_mode': tariff_mode, 'tariff_info': tariff_info,
                'recommendation': report.get('recommendation', {}),
                'economics': report.get('economics', {}),
                'spaces': report.get('spaces', {}),
                'billing': billing,
            }
            report['extensions'] = _run_extensions(_ext_raw, report)
        except Exception as _ext_err:
            log.debug(f'扩展模块运行跳过: {_ext_err}')

        return report

    @staticmethod
    def _generate_summary(report: dict) -> str:
        """生成人类可读的分析摘要."""
        c = report.get('consumer', {})
        d = report.get('demand', {})
        q = report.get('load_quality', {})
        r = report.get('recommendation', {})
        e = report.get('economics', {})
        t = report.get('tariff', {})

        parts = []

        # 用户画像
        if c.get('type'):
            lf = c.get('load_factor')
            lf_str = f"{lf*100:.1f}%" if isinstance(lf, (int, float)) else '?'
            md = d.get('max_demand')
            md_str = f"{md:.0f}" if isinstance(md, (int, float)) else '?'
            parts.append(f"该用户为{c['type']}(负荷率{lf_str}),"
                        f"年最大需量{md_str}kW,数据质量{q.get('grade', '?')}级")

        # 电价
        if t.get('province') and t.get('province') != '未指定':
            sp = e.get('spread')
            sp_str = f"{sp:.2f}" if isinstance(sp, (int, float)) else '?'
            parts.append(f"{t['province']}{t.get('month', '')}月采用{t.get('mode', '')}模式,"
                        f"峰谷价差{sp_str}元/kWh")

        # 推荐
        if r.get('power_kw'):
            parts.append(f"建议配置{r['power_kw']}kW/{r['capacity_kwh']}kWh储能系统")

        # 经济性
        if e.get('annual_revenue'):
            parts.append(f"预计年收益{e['annual_revenue']:.0f}元,回收期{e.get('payback_years', '?')}年")

        # 风险
        risks = report.get('risks', [])
        if risks:
            parts.append(f"⚠ {len(risks)}项风险:{';'.join(risks[:2])}")

        return '.'.join(parts) + '.' if parts else '分析完成.'

    @staticmethod
    def sweep_capacity(load_array, time_labels=None, province=None, month=None,
                       power_range=None, duration_range=None,
                       system_cost_per_kwh=None, periods=None, billing=None):
        """v2.25: 边际收益曲线 - 枚举所有容量组合计算收益.

        Args:
            power_range: 功率范围(kW), 默认 [50,100,150,200,300,400,500]
            duration_range: 时长范围(h), 默认 [1,1.5,2,2.5,3,4]

        Returns:
            {'power_kw': [...], 'duration_h': [...],
             'revenue_matrix': (n_power, n_duration),
             'payback_matrix': (n_power, n_duration),
             'irr_matrix': (n_power, n_duration),
             'best_power': int, 'best_capacity': int}
        """
        if power_range is None:
            power_range = [50, 100, 150, 200, 250, 300, 400, 500]
        if duration_range is None:
            duration_range = [1.0, 1.5, 2.0, 2.5, 3.0, 4.0]

        n_p, n_d = len(power_range), len(duration_range)
        revenue_mat = np.zeros((n_p, n_d))
        payback_mat = np.zeros((n_p, n_d))

        for i, power in enumerate(power_range):
            for j, duration in enumerate(duration_range):
                cap_kwh = power * duration  # v2.28fix: 枚举容量组合,传入diagnose强制覆盖自动推荐
                result = EnergyStorageEngineer.diagnose(
                    load_array, time_labels=time_labels,
                    province=province, month=month,
                    periods=periods, billing=billing,
                    system_cost_per_kwh=system_cost_per_kwh,
                    force_power_kw=power, force_capacity_kwh=cap_kwh
                )
                econ = result.get('economics', {})
                revenue_mat[i, j] = econ.get('annual_revenue', 0)
                payback_mat[i, j] = econ.get('payback_years', 99)

        # 找最优(最短回收期)
        best_idx = np.unravel_index(np.argmin(payback_mat), payback_mat.shape)
        best_power = power_range[best_idx[0]]
        best_capacity = int(best_power * duration_range[best_idx[1]])

        return {
            'power_kw': power_range, 'duration_h': duration_range,
            'revenue_matrix': revenue_mat, 'payback_matrix': payback_mat,
            'best_power': best_power, 'best_capacity': best_capacity,
            'best_payback': float(payback_mat[best_idx]),
            'best_revenue': float(revenue_mat[best_idx]),
        }


# endregion
