# ======== v3.0 merge: Ultra独家类(注入自负荷曲线批量生成Ultra.py) ========

class DataBus(QObject):
    """单一事件总线。任何模块产生/修改数据后发布事件,订阅者自动响应。"""
    _instance = None
    data_changed = Signal(str, object)  # (event_type, payload)
    # event_type: 'simulated','fused','desensitized','processed','analyzed'

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            QObject.__init__(cls._instance)
        return cls._instance

    @classmethod
    def publish(cls, event_type, payload=None):
        """发布事件。payload: {'data':arr,'summary':GroupSummary,'source':str,...}"""
        bus = cls()
        bus.data_changed.emit(event_type, payload or {})

    @classmethod
    def subscribe(cls, handler):
        """订阅事件。handler(event_type, payload)"""
        bus = cls()
        bus.data_changed.connect(handler)

