# v2.31: ReportEngine —— 统一报告生成,替代三套分散的报告系统
# ═══════════════════════════════════════════════════════


class FinanceEngine:
    """统一财务引擎。所有模块通过此类计算NPV/IRR/回收期,确保一致。"""

    @staticmethod
    def npv(investment, annual_cashflow, project_life=10, discount_rate=0.06,
            degradation=0.0, salvage_rate=0.1):
        """净现值。支持逐年衰减和残值。"""
        import math
        if math.isnan(annual_cashflow) or math.isinf(annual_cashflow) or math.isnan(investment):
            return float('-inf')
        npv_val = -investment
        for y in range(1, project_life + 1):
            cf = annual_cashflow * max(0, (1 - degradation) ** (y - 1))
            npv_val += cf / ((1 + discount_rate) ** y)
        npv_val += investment * salvage_rate / ((1 + discount_rate) ** project_life)
        return round(npv_val, 0)

    @staticmethod
    def irr(investment, annual_cashflow, project_life=10, degradation=0.0, guess=0.1):
        """Newton-Raphson法IRR。"""
        import math
        if math.isnan(investment) or math.isinf(investment): return 0.0
        if math.isnan(annual_cashflow) or annual_cashflow <= 0: return 0.0
        try:
            rate = guess
            for _ in range(200):
                npv_val = 0.0; dnpv = 0.0
                npv_val = -investment
                for y in range(1, project_life + 1):
                    cf = annual_cashflow * max(0, (1 - degradation) ** (y - 1))
                    npv_val += cf / ((1 + rate) ** y)
                    dnpv += -y * cf / ((1 + rate) ** (y + 1))
                if abs(dnpv) < 1e-12 or np.isnan(dnpv): break
                new_rate = rate - npv_val / dnpv
                if np.isnan(new_rate) or abs(new_rate - rate) < 1e-6:
                    rate = new_rate; break
                rate = new_rate
            rate = max(-0.99, min(0.99, rate))
            return round(rate * 100, 1)
        except Exception:
            return 0.0

    @staticmethod
    def payback(investment, annual_cashflow, degradation=0.0):
        """简单回收期(年)。"""
        if annual_cashflow <= 0: return 99.0
        cum = 0.0
        for y in range(1, 50):
            cum += annual_cashflow * max(0, (1 - degradation) ** (y - 1))
            if cum >= investment:
                return round(y - 1 + (investment - (cum - annual_cashflow * max(0, (1-degradation)**(y-2)))) / max(annual_cashflow * max(0, (1-degradation)**(y-1)), 1), 1) if y > 1 else round(investment / annual_cashflow, 1)
        return 99.0

    @staticmethod
    def discounted_payback(investment, annual_cashflow, discount_rate=0.06, degradation=0.0):
        """折现回收期——累计折现现金流转正年份。"""
        if annual_cashflow <= 0: return 99.0
        cum = -investment
        for y in range(1, 31):
            cf = annual_cashflow * max(0, (1 - degradation) ** (y - 1))
            cum += cf / ((1 + discount_rate) ** y)
            if cum >= 0:
                prev_cf = annual_cashflow * max(0, (1 - degradation) ** (y - 2)) if y > 1 else 0
                prev_cum = cum - cf / ((1 + discount_rate) ** y)
                return round(y - 1 + (-prev_cum) / (cf / ((1 + discount_rate) ** y)), 1)
        return 99.0


def calc_npv(annual_cashflow: float, investment: float,
             project_life: int = 15, discount_rate: float = 0.07,
             degradation: float = 0.02) -> float:
    """净现值(考虑容量衰减). v2.27fix: NaN/Inf 输入防护."""
    if math.isnan(annual_cashflow) or math.isinf(annual_cashflow):
        return float('-inf')
    if math.isnan(investment) or math.isinf(investment):
        return float('-inf')
    npv = -investment
    for year in range(1, project_life + 1):
        cf = annual_cashflow * ((1 - degradation) ** (year - 1))
        npv += cf / ((1 + discount_rate) ** year)
    return npv


def calc_irr(investment: float, annual_cashflow: float,
             project_life: int = 15, degradation: float = 0.02,
             guess: float = 0.1, tolerance: float = 1e-6) -> float:
    """Newton-Raphson 法计算 IRR(%).
    v2.29fix: 修复Newton更新误置于for-else分支的退化bug,恢复为每次迭代更新.
    v2.29fix: 增加 NaN/Inf 输入防护,对齐 calc_npv/calc_lcos."""
    if math.isnan(investment) or math.isinf(investment):
        return None
    if math.isnan(annual_cashflow) or math.isinf(annual_cashflow):
        return None
    if annual_cashflow <= 0:
        return None
    try:
        rate = guess
        for _ in range(200):
            npv = -investment
            dnpv = 0.0
            for y in range(1, project_life + 1):
                cf = annual_cashflow * ((1 - degradation) ** (y - 1))
                d = (1 + rate) ** y
                npv += cf / d
                dnpv += -y * cf / ((1 + rate) ** (y + 1))
            if abs(dnpv) < 1e-12:
                break
            new_rate = rate - npv / dnpv
            if abs(new_rate - rate) < tolerance:
                return new_rate * 100
            rate = new_rate
        else:
            log.warning(f"calc_irr: Newton法未在200次迭代内收敛 (investment={investment}, cashflow={annual_cashflow})")
    except (ZeroDivisionError, OverflowError):
        pass
    # v2.15: 不收敛时返回 None 而非 nan,避免下游排序/比较出现不可预测行为
    return None


def calc_lcos(investment: float, annual_throughput_kwh: float,
              project_life: int = 15, discount_rate: float = 0.07,
              fixed_om_rate: float = 0.02, variable_om: float = 0.05) -> float:
    """平准化储能成本 LCOS (元/kWh).

    方法: PNNL-33283 (Mongird et al. 2022)
    LCOS = (CAPEX + NPV of O&M) / NPV of energy throughput
    v2.27fix: NaN/Inf 输入防护.
    """
    if math.isnan(investment) or math.isinf(investment) or investment < 0:
        return float('inf')
    if math.isnan(annual_throughput_kwh) or math.isinf(annual_throughput_kwh) or annual_throughput_kwh <= 0:
        return float('inf')
    npv_throughput = 0.0
    npv_om = 0.0
    for year in range(1, project_life + 1):
        discount = (1 + discount_rate) ** year
        npv_throughput += annual_throughput_kwh / discount
        annual_om = investment * fixed_om_rate + annual_throughput_kwh * variable_om
        npv_om += annual_om / discount
    return (investment + npv_om) / npv_throughput if npv_throughput > 0 else float('inf')


# ═══════════════════════════════════════════════════════════════
# 容量扫描
# ═══════════════════════════════════════════════════════════════

def scan_capacity(load_profile: list[float], price_spread: float,
                  discharge_hours_range: tuple[float, float] = (0.5, 6.0),
                  step: float = 0.5,
                  demand_charge_rate: float = 40.0,
                  invest_params: InvestmentParams | None = None,
                  power_factor: float = 0.30) -> list[CapacityPlan]:
    """容量扫描:遍历放电时长,评估经济性.

    Args:
        load_profile: 典型日负荷 (kW)
        price_spread: 峰谷价差 (元/kWh)
        discharge_hours_range: 放电时长范围
        step: 扫描步长
        demand_charge_rate: 需量电价 (元/kW/月)
        invest_params: 投资参数
        power_factor: 储能功率占峰值负荷的比例 (默认 0.30)

    Returns:
        按 IRR 降序排列的方案列表
    """
    if invest_params is None:
        invest_params = InvestmentParams()

    capex_kwh, capex_kw, fixed_om, var_om = resolve_investment_params(invest_params)
    peak_load = max(load_profile) if load_profile else 1.0
    results = []

    duration = discharge_hours_range[0]
    while duration <= discharge_hours_range[1]:
        power_kw = peak_load * power_factor  # v2.15: 功率因子从硬编码改为参数化
        capacity_kwh = power_kw * duration
        daily_arbitrage = capacity_kwh * 0.8 * price_spread
        daily_demand_saving = power_kw * demand_charge_rate / 30
        annual_savings = (daily_arbitrage + daily_demand_saving) * 365
        investment = calc_investment(power_kw, capacity_kwh, invest_params)
        payback = calc_simple_payback(investment, annual_savings)
        irr = calc_irr(investment, annual_savings, invest_params.project_life)
        # v2.15: IRR 可能为 None(不收敛),排序时用 -999 沉底
        irr_val = irr if irr is not None else float('-inf')
        npv = calc_npv(annual_savings, investment, invest_params.project_life,
                       invest_params.discount_rate)
        annual_throughput = capacity_kwh * 0.8 * 365
        lcos = calc_lcos(investment, annual_throughput, invest_params.project_life,
                         invest_params.discount_rate, fixed_om, var_om)

        scenario_label = invest_params.cost_scenario.value
        results.append(CapacityPlan(
            optimal_power_kw=power_kw, optimal_capacity_kwh=capacity_kwh,
            duration_hours=duration, irr_percent=irr_val, npv=npv,
            payback_years=payback, annual_savings=annual_savings,
            annual_revenue=annual_savings, total_investment=investment,
            lcos=lcos, cost_scenario=scenario_label,
            capex_per_kwh=capex_kwh, capex_per_kw=capex_kw,
        ))
        duration += step

    # v2.15: 处理 IRR 可能为 None/-inf 的排序
    # v2.29fix: 用 float('-inf') 替代 -999 魔数,避免与真实IRR混淆
    def _sort_key(x):
        v = x.irr_percent
        if v is None or (isinstance(v, float) and (math.isnan(v) or v == float('-inf'))):
            return float('-inf')
        return float(v)
    results.sort(key=_sort_key, reverse=True)
    # v3.2.5fix(K1): 零负荷/负负荷时年省为 0，IRR 退化为 -inf，原逻辑照样入列，
    # 界面上会直接显示“-inf%”——既无意义又像程序坏了。过滤无收益方案；
    # 全被滤掉时返回空列表（调用方已有“未找到可行方案”分支）。
    results = [r for r in results
               if getattr(r, 'annual_savings', 0) > 0
               and isinstance(r.irr_percent, (int, float))
               and math.isfinite(float(r.irr_percent))]
    return results


def scan_capacity_multi_scenario(load_profile: list[float], price_spread: float,
                                 demand_charge_rate: float = 40.0,
                                 exchange_rate: float = 7.2) -> dict[str, list[CapacityPlan]]:
    """多场景容量扫描(保守/中等/先进 x 手动)."""
    results = {}
    for scenario in [CostScenario.CONSERVATIVE, CostScenario.MODERATE, CostScenario.ADVANCED]:
        params = InvestmentParams(cost_scenario=scenario, exchange_rate=exchange_rate)
        results[scenario.value] = scan_capacity(
            load_profile, price_spread,
            demand_charge_rate=demand_charge_rate,
            invest_params=params
        )
    return results


def sensitivity_analysis(base_investment: float, base_annual_savings: float,
                         param_name: str, values: list[float],
                         project_life: int = 15) -> list[dict]:
    """单参数敏感性分析."""
    results = []
    for val in values:
        if param_name == "capex":
            investment = base_investment * val
            savings = base_annual_savings
        elif param_name == "savings":
            investment = base_investment
            savings = base_annual_savings * val
        else:
            continue
        irr = calc_irr(investment, savings, project_life)
        payback = calc_simple_payback(investment, savings)
        results.append({
            "value": val, "irr_percent": irr, "payback_years": payback,
            "npv": calc_npv(savings, investment, project_life),
        })
    return results


