@dataclass


class ReportEngine:
    """统一报告引擎。输入ctx字典 → 输出格式化的文本/HTML/Markdown报告。"""

    @staticmethod
    def generate(ctx, fmt='text'):
        """ctx: {overview:{}, load:{}, space:{}, config:{}, econ:{}, advice:[]}"""
        if fmt == 'html':
            return ReportEngine._html(ctx)
        elif fmt == 'markdown':
            return ReportEngine._md(ctx)
        return ReportEngine._text(ctx)

    @staticmethod
    def _text(ctx):
        lines = ["=" * 50, "          储能配置方案建议书", "=" * 50, ""]
        if ctx.get('overview'):
            lines.append("【项目概况】")
            for k, v in ctx['overview'].items():
                lines.append(f"{k}: {v}")
            lines.append("")
        for section in ['load', 'space', 'config', 'econ']:
            if ctx.get(section):
                title = {'load':'负荷特征','space':'充放电空间','config':'推荐配置','econ':'经济指标'}[section]
                lines.append(f"【{title}】")
                for k, v in ctx[section].items():
                    lines.append(f"{k}: {v}")
                lines.append("")
        if ctx.get('advice'):
            lines.append("【建议】")
            for a in ctx['advice']:
                lines.append(f"• {a}")
            lines.append("")
        lines.append(f"由Ultra v2.31自动生成 | {datetime.now().strftime('%Y-%m-%d %H:%M')}")
        lines.append("=" * 50)
        return '\n'.join(lines)

    @staticmethod
    def _html(ctx):
        text = ReportEngine._text(ctx).replace('\n', '<br>')
        return f"""<!DOCTYPE html><html><head><meta charset="utf-8">
        <style>body{{font-family:'Microsoft YaHei',sans-serif;font-size:13px;line-height:1.8;
        max-width:700px;margin:40px auto;color:#333}}h2{{border-bottom:2px solid #2563EB}}
        .highlight{{color:#2563EB;font-weight:bold}}</style></head><body>{text}</body></html>"""

    @staticmethod
    def _md(ctx):
        text = ReportEngine._text(ctx)
        text = text.replace('【', '## ').replace('】', '')
        return text

# ═══════════════════════════════════════════════════════
# v2.31: WorkflowOrchestrator —— 三引擎总调度器
# 监听DataBus事件,自动编排模块间的数据流动
# ═══════════════════════════════════════════════════════


class StorageOptimizer:
    """扫参网格+MILP/贪心调度 → 四目标最优对比。"""
    def __init__(self, load_array, time_labels, date_labels, peak_price=1.0, valley_price=0.3,
                 flat_price=0.6, demand_charge=30.0, system_cost_per_kwh=750.0, pv_array=None,
                 peak_start=8, peak_end=22, consume_first=False,
                 cost_scenarios=None):  # v3.2: 多设备比选
        self.load = np.asarray(load_array, dtype=np.float64)
        self.times = time_labels; self.dates = date_labels
        self.peak_p = peak_price; self.valley_p = valley_price; self.flat_p = flat_price
        self.demand_c = demand_charge; self.cost_kwh = system_cost_per_kwh
        self.pv = np.asarray(pv_array) if pv_array is not None else None; self._cache = {}
        self.peak_start = peak_start; self.peak_end = peak_end
        self.consume_first = consume_first
        self.cost_scenarios = cost_scenarios or []  # [(label, cost_per_kwh), ...]

    def optimize(self, power_range=None, duration_range=None):
        if power_range is None:
            pmax = min(int(np.max(self.load) * 0.8), 2000)
            power_range = np.linspace(100, max(pmax, 200), 8).astype(int)
        if duration_range is None:
            duration_range = [1.0, 1.5, 2.0, 2.5, 3.0, 4.0]
        # v3.2: 多设备比选——对不同成本运行
        all_results = {}
        scenarios = self.cost_scenarios if self.cost_scenarios else [('默认', self.cost_kwh)]
        for _, cost in scenarios:
            self.cost_kwh = cost
            self._cache.clear()
            best = {'max_npv': None, 'min_payback': None, 'max_profit': None, 'max_pv_util': None}
        for p in power_range:
            for d in duration_range:
                c = int(p * d)
                key = (p, c)
                m = self._cache.get(key) or self._evaluate(p, c)
                self._cache[key] = m
                for target, score_key, cmp in [
                    ('max_npv', 'npv', lambda a,b: a>b),
                    ('min_payback', 'payback', lambda a,b: a>0 and (b is None or a<b)),
                    ('max_profit', 'total_profit', lambda a,b: a>b),
                    ('max_pv_util', 'pv_utilization', lambda a,b: a>b)]:
                    if best[target] is None or cmp(m[score_key], best[target][score_key]):
                        best[target] = {'power': p, 'capacity': c, **m}
        return {'best_npv': best['max_npv'], 'best_payback': best['min_payback'],
                'best_profit': best['max_profit'], 'best_pv': best['max_pv_util']}

    def compare_devices(self, devices, power_range=None, duration_range=None):
        """v3.2: 多设备比选——对不同单价分别优化,返回对比结果。
        devices: [{'label':'品牌A','cost':750}, {'label':'品牌B','cost':900}, ...]"""
        results = {}
        orig_cost = self.cost_kwh
        for dev in devices:
            self.cost_kwh = dev['cost']
            self._cache.clear()
            result = self.optimize(power_range, duration_range)
            results[dev['label']] = result
        self.cost_kwh = orig_cost
        return results

    def _evaluate(self, p_kw, c_kwh):
        dc, dd, dpv = self._dispatch(p_kw, c_kwh)
        dc = min(dc, c_kwh * 0.9)
        dd = min(dd, c_kwh * 0.9)
        ac = dc * 365; ad = dd * 365; apv = dpv * 365
        # v3.2: 自用优先——光伏充电免费用
        if self.consume_first:
            grid_ch = max(0, ac - apv)  # 扣掉光伏后才是电网购电
            rev = sum(ad * self.peak_p * 1.02**y - grid_ch * self.valley_p * 1.02**y for y in range(10)) / 10
        else:
            rev = sum(ad * self.peak_p * 1.02**y - ac * self.valley_p * 1.02**y for y in range(10)) / 10
        peaks = np.max(self.load, axis=1) if self.load.shape[1] > 0 else np.zeros(self.load.shape[0])
        months = {}
        for i, d in enumerate(self.dates):
            m = str(d)[5:7] if len(str(d)) >= 7 else '01'
            months[m] = max(months.get(m, 0), peaks[i])
        ds = sum(min(peak, p_kw) * self.demand_c / 12 for peak in months.values())
        inv = c_kwh * self.cost_kwh; om = inv * 0.015
        net = rev + ds - om  # v3.1fix: 允许负收益,NPV自然反映项目亏损
        # v3.1: 折现回收期——找到累计折现现金流转正的年份
        discount = 0.06
        cumulative = -inv
        dpb = 99.0
        for y in range(1, 21):
            cumulative += net / (1+discount)**y
            if cumulative >= 0 and dpb == 99.0:
                dpb = y - 1 + (cumulative - net/discount**y) / (net/discount**y) if net > 0 else 99
        # v3.2: 使用统一FinanceEngine
        npv = FinanceEngine.npv(inv, net)
        pb = FinanceEngine.discounted_payback(inv, net) if dpb >= 99 else dpb
        pf = net * 10 - inv
        pt = float(np.sum(np.maximum(self.pv, 0))) if self.pv is not None else 0
        pu = apv / max(pt, 1) * 100 if pt > 0 else 0
        return {'npv': round(npv), 'irr': round(net/max(inv,1)*100,1), 'payback': round(pb,1),
                'total_profit': round(pf), 'pv_utilization': round(pu,1), 'annual_net': round(net),
                'annual_revenue': round(rev), 'demand_saving': round(ds), 'investment': round(inv)}

    def _dispatch(self, p_kw, c_kwh):
        """v2.31: MILP优先,降级贪心。"""
        try:
            return self._dispatch_milp(p_kw, c_kwh)
        except Exception:
            return self._dispatch_greedy(p_kw, c_kwh)

    def _dispatch_milp(self, p_kw, c_kwh):
        """v3.2: MILP多日采样——每月取一天,12天平均。"""
        n_pts = self.load.shape[1]
        if n_pts < 2:
            return 0, 0, 0

        # 收集每月一个代表日
        n_days = self.load.shape[0]
        sample_days = []
        for m in range(1, 13):
            indices = [i for i, d in enumerate(self.dates) if len(str(d)) >= 7 and int(str(d)[5:7]) == m]
            if indices:
                sample_days.append(indices[len(indices) // 2])
        if not sample_days:
            sample_days = list(range(0, n_days, max(1, n_days // 12)))[:12]

        # 对每个采样日独立求解 MILP
        dc_total, dd_total, dpv_total = 0.0, 0.0, 0.0
        valid_count = 0
        for day_idx in sample_days[:12]:
            dch, ddh, dpvh = self._solve_milp_one_day(day_idx, p_kw, c_kwh, n_pts)
            if dch >= 0:
                dc_total += dch
                dd_total += ddh
                dpv_total += dpvh
                valid_count += 1

        if valid_count == 0:
            return self._dispatch_greedy(p_kw, c_kwh)
        return dc_total / valid_count, dd_total / valid_count, dpv_total / valid_count

    def _solve_milp_one_day(self, day_idx, p_kw, c_kwh, n_pts):
        """对单个代表日求解MILP,返回(充电kWh,放电kWh,光伏充电kWh)。"""
        from ortools.linear_solver import pywraplp
        row = self.load[min(day_idx, self.load.shape[0] - 1)]
        pv_row = self.pv[min(day_idx, self.pv.shape[0] - 1)] if self.pv is not None and self.pv.shape[0] > 0 else np.zeros(n_pts)
        t = np.linspace(0, 24, n_pts, endpoint=False)
        is_valley = ~((t >= self.peak_start) & (t <= self.peak_end))
        is_peak = (t >= self.peak_start) & (t <= self.peak_end)

        solver = pywraplp.Solver.CreateSolver('SCIP')
        if not solver:
            return -1, -1, -1
        solver.SuppressOutput()

        Y_CH = [solver.NumVar(0, p_kw, f'yc_{day_idx}_{i}') for i in range(n_pts)]
        Y_DIS = [solver.NumVar(0, p_kw, f'yd_{day_idx}_{i}') for i in range(n_pts)]
        Y_PVCH = [solver.NumVar(0, p_kw, f'ypv_{day_idx}_{i}') for i in range(n_pts)]
        SOC = [solver.NumVar(0, c_kwh, f's_{day_idx}_{i}') for i in range(n_pts)]

        solver.Add(SOC[0] == c_kwh * 0.1)
        for i in range(n_pts):
            demand = row[i] if not np.isnan(row[i]) else 0
            pv = pv_row[i] if i < len(pv_row) else 0
            solver.Add(Y_DIS[i] <= max(0, demand))
            solver.Add(Y_PVCH[i] <= max(0, pv))
            # v3.2: 变压器约束
            if hasattr(self, 'transformer_capacity') and self.transformer_capacity:
                solver.Add(Y_CH[i] + Y_PVCH[i] <= self.transformer_capacity * 0.9 - max(0, demand - pv))
            if i > 0:
                solver.Add(SOC[i] == SOC[i-1] + (Y_CH[i] + Y_PVCH[i]) * BESS_EFF_RT - Y_DIS[i] / BESS_EFF_RT)
            if is_valley[i]:
                solver.Add(Y_DIS[i] == 0)
            if is_peak[i]:
                solver.Add(Y_CH[i] == 0)

        revenue = solver.Sum(Y_DIS[i] * self.peak_p - Y_CH[i] * self.valley_p for i in range(n_pts))
        solver.Maximize(revenue)
        status = solver.Solve()
        if status != pywraplp.Solver.OPTIMAL:
            return -1, -1, -1
        # v3.2fix: 时间步长按实际分辨率推算。原实现硬编码 0.25h(仅 96 点成立),
        # 24 点数据会把电量算成真实值的 1/4, 与贪心路径(dt=24/n_pts)口径冲突。
        _dt_hours = 24.0 / max(n_pts, 1)
        dc = sum((Y_CH[i].solution_value() + Y_PVCH[i].solution_value()) for i in range(n_pts)) * _dt_hours
        dd = sum(Y_DIS[i].solution_value() for i in range(n_pts)) * _dt_hours
        dpv = sum(Y_PVCH[i].solution_value() for i in range(n_pts)) * _dt_hours
        return dc, dd, dpv

    def _dispatch_greedy(self, p_kw, c_kwh):
        """v3.2: 贪心调度——完善边界验证和SOC约束。"""
        n_pts = self.load.shape[1]
        if n_pts < 2: return 0, 0, 0
        # v3.2: 参数校验
        if p_kw <= 0 or c_kwh <= 0:
            return 0, 0, 0
        if self.peak_p <= 0 and self.valley_p <= 0:
            return 0, 0, 0
        dt = 24.0 / n_pts
        t = np.linspace(0, 24, n_pts, endpoint=False)
        is_peak = (t >= self.peak_start) & (t <= self.peak_end)
        dc = dd = dpv = 0.0
        n_days = self.load.shape[0]
        soc_min = c_kwh * 0.05  # v3.2: 最小SOC 5%
        soc_max = c_kwh * BESS_SOC_MAX  # v3.1: 最大SOC用常量
        for day in range(n_days):
            row = self.load[day]; soc = c_kwh * 0.1
            for pt in range(n_pts):
                demand = row[pt] if not np.isnan(row[pt]) else 0
                pv = self.pv[day,pt] if self.pv is not None and day<self.pv.shape[0] and pt<self.pv.shape[1] else 0
                if is_peak[pt]:
                    # v3.2: 放电不突破SOC下限
                    dis = min(p_kw * dt, max(0, soc - soc_min) * BESS_EFF_RT, max(0, demand) * dt)
                    soc -= dis / BESS_EFF_RT; dd += dis
                else:
                    # v3.2: 充电不突破SOC上限
                    ch = min(p_kw * dt, (soc_max - soc) / BESS_EFF_RT)
                    if pv > 0 and ch > 0: dpv += min(ch, pv * dt)
                    soc += ch * BESS_EFF_RT; dc += ch
        n_days = max(self.load.shape[0], 1)
        return dc / n_days, dd / n_days, 0.0



def show_optimize_dialog(parent, result):
    """v3.2: 四目标优化对比——支持单设备/多设备模式。"""
    dlg = QDialog(parent)
    dlg.setWindowTitle("🎯 储能配置优化"); dlg.setMinimumSize(720, 380)
    layout = QVBoxLayout(dlg)
    # v3.2: 检测多设备模式
    is_multi = isinstance(result, dict) and len(result) > 1 and all(
        isinstance(v, dict) and 'best_npv' in v for v in result.values())
    if is_multi:
        layout.addWidget(QLabel("<b>多设备对比</b> — 各品牌最优配置(NPV最大化)"))
        table = QTableWidget()
        headers = ['设备', '功率(kW)', '容量(kWh)', 'NPV(¥)', '回收期(年)', '年净收益(¥)']
        table.setColumnCount(6); table.setHorizontalHeaderLabels(headers)
        table.setRowCount(len(result)); table.setAlternatingRowColors(True)
        for row, (dev, r) in enumerate(result.items()):
            best = r.get('best_npv', {})
            if not best: continue
            vals = [dev, str(best.get('power','-')), str(best.get('capacity','-')),
                    f"{best.get('npv',0):,.0f}", f"{best.get('payback',0):.1f}",
                    f"{best.get('annual_net',0):,.0f}"]
            for col, val in enumerate(vals):
                item = QTableWidgetItem(val); item.setTextAlignment(Qt.AlignCenter)
                if col == 0: item.setFont(QFont("Microsoft YaHei", 11, QFont.Bold))
                table.setItem(row, col, item)
        table.resizeColumnsToContents(); layout.addWidget(table)
    else:
        layout.addWidget(QLabel("<b>四目标优化对比</b> — 每种目标推荐一个最优配置"))
        table = QTableWidget()
        headers = ['优化目标', '功率(kW)', '容量(kWh)', 'NPV(¥)', '回收期(年)', '年净收益(¥)', '光伏利用率']
        table.setColumnCount(7); table.setHorizontalHeaderLabels(headers); table.setRowCount(4)
        table.setAlternatingRowColors(True)
        objs = [('📈 最大NPV', 'best_npv'), ('⚡ 最快回本', 'best_payback'),
                ('💰 最大利润', 'best_profit'), ('☀ 最高光伏', 'best_pv')]
        for row, (label, key) in enumerate(objs):
            r = result.get(key, {})
            if not r: continue
            vals = [label, str(r.get('power','-')), str(r.get('capacity','-')),
                    f"{r.get('npv',0):,.0f}", f"{r.get('payback',0):.1f}",
                    f"{r.get('annual_net',0):,.0f}", f"{r.get('pv_utilization',0):.1f}%"]
            for col, val in enumerate(vals):
                item = QTableWidgetItem(val); item.setTextAlignment(Qt.AlignCenter)
                if col == 0: item.setFont(QFont("Microsoft YaHei", 11, QFont.Bold))
                table.setItem(row, col, item)
        table.resizeColumnsToContents(); layout.addWidget(table)
    hint = QLabel("💡 最大NPV→长期最优 | 最快回本→风险最低 | 最大利润→绝对收益 | 最高光伏→绿电合规")
    hint.setWordWrap(True); hint.setStyleSheet("color:#888;font-size:11px;"); layout.addWidget(hint)
    btn = QHBoxLayout(); btn.addStretch()
    close_btn = QPushButton("关闭"); close_btn.clicked.connect(dlg.accept); btn.addWidget(close_btn)
    layout.addLayout(btn); dlg.exec()

