        self.setMinimumSize(900, 550)
        self.result_config = None
        # v2.32: 指纹自动匹配
        self._fp_hint = fingerprint_hint
        bsize = 28

        # 水平分栏:左(控制)+右(预览)
        main_split = QHBoxLayout(self)

        # ── 左侧:控制面板 ──
        left_widget = QWidget()
