class ParkSimDialog(QDialog):
    """园区模拟——多个资产独立配置后加总生成总负荷。"""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("🏭 园区负荷模拟")
        self.setMinimumSize(600, 450)
        self.assets = []  # [{name, industry, power}]
        bsize = 28
        layout = QVBoxLayout(self)

        # ── 添加资产 ──
        add_layout = QHBoxLayout()
        add_layout.addWidget(QLabel("资产名:"))
        self.name_edit = QLineEdit("产线1")
        self.name_edit.setFixedWidth(100)
        add_layout.addWidget(self.name_edit)
        add_layout.addWidget(QLabel("行业:"))
        self.ind_combo = QComboBox()
        self.ind_combo.addItems(sorted(INDUSTRY_TEMPLATES.keys()))
        self.ind_combo.setCurrentText('电子制造')
        add_layout.addWidget(self.ind_combo)
        add_layout.addWidget(QLabel("功率(kW):"))
        self.power_spin = QSpinBox()
        self.power_spin.setRange(10, 10000)
        self.power_spin.setValue(300)
        add_layout.addWidget(self.power_spin)
        add_btn = QPushButton("＋ 添加")
        add_btn.clicked.connect(self._add_asset)
        add_layout.addWidget(add_btn)
        layout.addLayout(add_layout)

        # ── 资产列表 ──
        self.list_widget = QListWidget()
        self.list_widget.setAlternatingRowColors(True)
        layout.addWidget(self.list_widget)

        # ── 汇总信息 ──
        self.summary_lbl = QLabel("总计: 0个资产 | 0kW")
        layout.addWidget(self.summary_lbl)

        # ── 光伏 ──
        pv_layout = QHBoxLayout()
        self.pv_cb = QCheckBox("叠加光伏")
        pv_layout.addWidget(self.pv_cb)
        pv_layout.addWidget(QLabel("容量(kW):"))
        self.pv_spin = QSpinBox()
        self.pv_spin.setRange(0, 10000)
        self.pv_spin.setValue(0)
        pv_layout.addWidget(self.pv_spin)
        pv_layout.addStretch()
        layout.addLayout(pv_layout)

        # ── 按钮 ──
        btn_layout = QHBoxLayout()
        btn_layout.addStretch()
        del_btn = QPushButton("删除选中")
        del_btn.clicked.connect(self._del_asset)
        btn_layout.addWidget(del_btn)
        cancel_btn = QPushButton("取消")
        cancel_btn.clicked.connect(self.reject)
        btn_layout.addWidget(cancel_btn)
        gen_btn = QPushButton("✅ 生成园区负荷")
        gen_btn.setObjectName("primary")
        gen_btn.clicked.connect(self._on_gen_park)
        btn_layout.addWidget(gen_btn)
        layout.addLayout(btn_layout)

        self.result_data = None

    def _add_asset(self):
        name = self.name_edit.text().strip() or f'资产{len(self.assets)+1}'
        ind = self.ind_combo.currentText()
        power = self.power_spin.value()
        self.assets.append({'name': name, 'industry': ind, 'power': power})
        self.list_widget.addItem(f"{name} | {ind} | {power}kW")
        self._update_summary()

    def _del_asset(self):
        row = self.list_widget.currentRow()
        if row >= 0:
            self.list_widget.takeItem(row)
            del self.assets[row]
            self._update_summary()

    def _update_summary(self):
        total = sum(a['power'] for a in self.assets)
        self.summary_lbl.setText(f"总计: {len(self.assets)}个资产 | {total}kW")

    def _on_gen_park(self):
        if not self.assets:
            QMessageBox.warning(self, "提示", "请先添加至少一个资产")
            return
        total_load = None
        for asset in self.assets:
            cfg = {'industry': asset['industry'], 'avg_power_kw': asset['power'], 'noise_std': 0.03}
            data = generate_load_profile(cfg)
            if data:
                arr = data['load_array']
                if total_load is None:
                    total_load = arr.copy()
                    date_labels = data['date_labels']
                    time_labels = data['time_labels']
                else:
                    # 对齐形状
                    shp = min(total_load.shape[1], arr.shape[1])
                    total_load[:, :shp] += arr[:, :shp]
        if total_load is None:
            return
        self.result_data = {
            'load_array': total_load,
            'time_labels': time_labels,
            'date_labels': date_labels,
            'asset': '园区总负荷',
            'asset_count': len(self.assets),
            'total_power': sum(a['power'] for a in self.assets),
        }
        # 光伏叠加
        if self.pv_cb.isChecked() and self.pv_spin.value() > 0:
            self.result_data['load_array'] = _add_pv_to_load(
                self.result_data['load_array'].copy(), self.result_data['date_labels'],
                self.pv_spin.value(), self.result_data['load_array'].shape[1]
            )
        self.accept()




class WorkflowOrchestrator(QObject):
    """协调可视化/仿真/决策三引擎。订阅DataBus,自动触发响应动作。"""
    _instance = None
    analysis_requested = Signal(object)  # (summary, data) → ProfessionalWindow should load

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            QObject.__init__(cls._instance)
            DataBus.subscribe(cls._instance._on_data_event)
            cls._instance._recent_data = {}
        return cls._instance

    def _on_data_event(self, event_type, payload):
        """核心调度:根据事件类型决定响应动作。"""
        self._recent_data[event_type] = payload

    @classmethod
    def get_last(cls, event_type):
        """获取最近一次特定类型的数据。"""
        return cls()._recent_data.get(event_type)

    @classmethod
    def request_analysis(cls, summary, data):
        """请求打开ProfessionalWindow分析当前数据。v3.2fix: 已接入DoubleClick→请求分析。"""
        cls()._recent_data['analysis_requested'] = {'summary': summary, 'data': data}
        cls().analysis_requested.emit({'summary': summary, 'data': data})
        DataBus.publish('analysis_requested', {'summary': summary, 'data': data})

