# ── adapter.py ──
# -*- coding: utf-8 -*-
"""adapter - 数据格式桥接器

将负荷曲线工具的 numpy 数据结构转换为 ele-trading 的 pandas DatetimeIndex 格式.
确保两种数据流转: 用户工具 -> adapter -> 扩展计算 -> 结果 -> 用户工具.
"""


import numpy as np
import pandas as pd
from dataclasses import dataclass


# ── 输入转换:用户工具 -> 扩展 ────────────────────────────────────

def load_array_to_series(
    load_array: np.ndarray,
    time_labels: list[str],
    date_labels: list[str],
    power_unit: str = "kW",
) -> pd.Series:
    """将 numpy 二维负荷数组转换为 pandas DatetimeIndex Series.

    用户工具的典型数据:
      load_array: shape (n_days, n_points)  每行是一天的负荷
      time_labels: ["00:00", "00:15", ...]  每天的时间标签
      date_labels: ["2025-06-01", ...]      每天对应的日期

    Returns:
      pd.Series with DatetimeIndex, values in kW
    """
    records = []
    for day_idx, date_str in enumerate(date_labels):
        for time_idx, time_str in enumerate(time_labels):
            ts = pd.Timestamp(f"{date_str} {time_str}")
            val = float(load_array[day_idx, time_idx])
            if power_unit == "MW":
                val *= 1000.0
            records.append((ts, val))

    df = pd.DataFrame(records, columns=["timestamp", "power"])
    df = df.sort_values("timestamp")
    return df.set_index("timestamp")["power"]


def load_dict_to_series(
    monthly_data: dict[str, dict],
    power_unit: str = "kW",
) -> pd.Series:
    """将 monthly_data 字典转换为连续的 pandas Series.

    monthly_data 格式: {month_str: {'load_array': np.array, 'time_labels': [...], 'date_labels': [...]}}
    """
    all_series = []
    for month_str in sorted(monthly_data.keys()):
        data = monthly_data[month_str]
        arr = data.get("load_array")
        if arr is None or arr.size == 0:
            continue
        if arr.ndim == 1:
            # v2.24: 单日数据 reshape,校验时间标签长度
            n_labels = len(data.get("time_labels", []))
            if n_labels > 0 and len(arr) != n_labels:
                log.warning(f"load_dict_to_series: 单日数据长度({len(arr)})与时间标签数({n_labels})不一致,跳过 month={month_str}")
                continue
            arr = arr.reshape(1, -1)
        time_labels = data.get("time_labels", [])
        date_labels = data.get("date_labels", [])
        if not time_labels or not date_labels:
            continue
        s = load_array_to_series(arr, time_labels, date_labels, power_unit)
        all_series.append(s)

    if not all_series:
        return pd.Series(dtype=float)

    result = pd.concat(all_series)
    result = result[~result.index.duplicated()]  # 去重(跨月边界可能重叠)
    return result.sort_index()


def periods_to_price_series(
    time_labels: list[str],
    periods: dict[str, list[tuple[str, str]]],
    price_map: dict[str, float] | None = None,
    default_price: float = 0.0,
    date_str: str = "2025-01-01",
) -> tuple[pd.Series, pd.Series]:
    """将时段策略转换为价格序列.

    periods 格式: {"充电": [("08:00", "11:00"), ...], "放电": [("18:00", "21:00"), ...]}
    price_map: {"充电": 0.3, "放电": 1.2, "平时": 0.7}

    Returns:
        (buy_price: pd.Series, price_type: pd.Series)
    """
    if price_map is None:
        price_map = {"充电": 0.3, "平时": 0.7, "放电": 1.2}

    n_labels = len(time_labels)  # v2.28fix: 原为独立表达式,未赋值
    timestamps = [pd.Timestamp(f"{date_str} {t}") for t in time_labels]

    buy_price = pd.Series(default_price, index=timestamps, dtype=float)
    price_type = pd.Series("flat", index=timestamps)

    # 对每个时段的每个区间,设置价格
    for ptype, intervals in periods.items():
        p_price = price_map.get(ptype, default_price)
        for start_str, end_str in intervals:
            start_min = _parse_time_min(start_str)
            end_min = _parse_time_min(end_str)
            for i, t in enumerate(time_labels):
                cur_min = _parse_time_min(t)
                # 处理跨午夜时段
                if start_min <= end_min:
                    in_range = start_min <= cur_min < end_min
                else:
                    in_range = cur_min >= start_min or cur_min < end_min
                if in_range:
                    buy_price.iloc[i] = p_price
                    price_type.iloc[i] = ptype

    return buy_price, price_type


