# ── 工具函数 ──────────────────────────────────────────────────────

def _parse_time_min(t: str) -> int:
    """将时间字符串转为从 00:00 开始的分钟数."""
    parts = t.strip().split(":")
    return int(parts[0]) * 60 + int(parts[1])


# ── demand.py ──
# -*- coding: utf-8 -*-
"""demand - 需量分析模块

基于 ele-trading demand/calc.py 的滑动窗口算法,
提供: 最大需量计算、需量电费测算、固定/滑动窗口对比.
"""


import numpy as np
from dataclasses import dataclass


@dataclass
class DemandConfig:
    """需量计算配置."""
    window_minutes: int = 15
    window_type: str = "sliding"  # "fixed" or "sliding"
    demand_price: float = 0.0     # 需量电价 (元/kW/月)
    power_unit: str = "kW"        # 输入功率单位


@dataclass
class DemandResult:
    """需量计算结果."""
    max_demand: float             # 全局最大需量 (kW)
    peak_timestamp: pd.Timestamp  # 发生时刻
    monthly_max: pd.Series        # 每月最大需量
    daily_max: pd.Series          # 每日最大需量
    window_series: pd.Series      # 完整窗口序列
    config: DemandConfig


def calc_fixed_window(power: pd.Series, window_minutes: int) -> pd.Series:
    """固定不重叠窗口平均功率."""
    return power.resample(f"{window_minutes}min").mean().dropna()


def calc_sliding_window(power: pd.Series, window_minutes: int) -> pd.Series:
    """滑动窗口平均功率.

    窗口宽度 = window_minutes 分钟,逐点滑动取均值.
    返回与输入等长的序列.
    """
    if len(power) == 0:
        return power
    if len(power) < 2:
        log.warning("功率序列少于 2 个点,需量计算可能不准确")
        return power

    # 推断时间步长
    if not isinstance(power.index, pd.DatetimeIndex):
        raise TypeError("power series must have DatetimeIndex for demand calculation")

    dt = (power.index[1] - power.index[0]).total_seconds() / 60  # v2.27fix: 时间步长(分钟)
    window_steps = max(1, int(round(window_minutes / dt)))
    return power.rolling(window=window_steps, min_periods=1).mean()


def calc_demand(power: pd.Series, config: DemandConfig | None = None) -> DemandResult:
    """计算最大需量.

    根据窗口类型和时长,计算窗口平均功率序列,聚合出全局/月度/日度最大需量.

    Args:
        power: 功率时间序列 (index=DatetimeIndex)
        config: 计算配置,默认 15 分钟滑动窗口

    Returns:
        DemandResult 含完整计算结果
    """
    if config is None:
        config = DemandConfig()

    # 单位换算
    p = power.copy()
    if config.power_unit == "MW":
        p = p * 1000.0

    # 窗口计算
    if config.window_type == "fixed":
        ws = calc_fixed_window(p, config.window_minutes)
    else:
        ws = calc_sliding_window(p, config.window_minutes)

    # 空数据保护:避免 idxmax() 在空/全 NaN Series 上崩溃
    if len(ws) == 0 or ws.isna().all():
        log.warning("需量计算:窗口序列为空或全 NaN,返回零值")
        return DemandResult(
            max_demand=0.0,
            peak_timestamp=pd.NaT,
            monthly_max=pd.Series(dtype=float),
            daily_max=pd.Series(dtype=float),
            window_series=ws,
            config=config,
        )

    # 最大值提取
    peak_idx = ws.idxmax()
    max_demand = float(ws.loc[peak_idx])

    # 按月/日聚合
    monthly_max = ws.groupby(ws.index.to_period("M")).max()
    daily_max = ws.groupby(ws.index.date).max()
    daily_max.index = pd.to_datetime(daily_max.index)

    return DemandResult(
        max_demand=max_demand,
        peak_timestamp=pd.Timestamp(peak_idx),
        monthly_max=monthly_max,
        daily_max=daily_max,
        window_series=ws,
        config=config,
    )


def calc_demand_charge(result: DemandResult, demand_price: float | None = None) -> dict:
    """计算需量电费.

    Returns:
        {"max_demand_kw": ..., "demand_price": ..., "demand_charge": ...}
    """
    price = demand_price if demand_price is not None else result.config.demand_price
    return {
        "max_demand_kw": result.max_demand,
        "demand_price": price,
        "demand_charge": result.max_demand * price,
    }


def compare_windows(power: pd.Series, window_minutes: int = 15) -> dict:
    """对比固定窗口 vs 滑动窗口的最大需量.

    Returns:
        {"fixed_max": ..., "sliding_max": ..., "delta_kw": ..., "delta_pct": ...}
    """
    fixed = calc_demand(power, DemandConfig(window_minutes=window_minutes, window_type="fixed"))
    sliding = calc_demand(power, DemandConfig(window_minutes=window_minutes, window_type="sliding"))

    delta = sliding.max_demand - fixed.max_demand
    return {
        "fixed_max": fixed.max_demand,
        "sliding_max": sliding.max_demand,
        "delta_kw": delta,
        "delta_pct": (delta / fixed.max_demand * 100) if fixed.max_demand > 0 else 0,
    }


def analyze_from_series(power: pd.Series, window_minutes: int = 15,
                        demand_price: float = 40.0) -> dict:
    """一站式需量分析:从功率序列到完整报告.

    Returns:
        含 demand_result, charge, comparison, summary 的字典.
    """
    config = DemandConfig(window_minutes=window_minutes, window_type="sliding", demand_price=demand_price)
    result = calc_demand(power, config)
    charge = calc_demand_charge(result)
    comparison = compare_windows(power, window_minutes)

    return {
        "demand_result": result,
        "charge": charge,
        "comparison": comparison,
        "summary": (
            f"最大需量: {result.max_demand:.1f} kW\n"
            f"发生时刻: {result.peak_timestamp}\n"
            f"月基本电费: ¥{charge['demand_charge']:,.0f} (按 {demand_price} 元/kW/月)\n"
            f"滑动 vs 固定: +{comparison['delta_kw']:.1f} kW ({comparison['delta_pct']:.1f}%)"
        ),
    }


# ── scheduler.py ──
# -*- coding: utf-8 -*-
"""scheduler - 储能调度优化模块

基于 ele-trading optimization/ 的 PuLP 线性规划模型,
提供: 用户侧 BESS 最优调度、储能套利策略、充放电时序优化.
"""


from dataclasses import dataclass

try:
    from pulp import (
        LpBinary, LpMinimize, LpMaximize, LpProblem, LpVariable,
        PULP_CBC_CMD, lpSum, value, LpStatus,
    )
    _PULP_AVAILABLE = True
except ImportError:
    _PULP_AVAILABLE = False


@dataclass
class BESSParams:
    """储能系统参数."""
    capacity: float          # kWh
    soc_min: float           # kWh (最小 SOC)
    soc_max: float           # kWh (最大 SOC)
    p_ch_max: float          # kW (最大充电功率)
    p_dis_max: float         # kW (最大放电功率)
    eta_ch: float = 0.95     # 充电效率
    eta_dis: float = 0.95    # 放电效率


@dataclass
class DispatchInput:
    """调度优化输入."""
    timestamps: list[Any]
    load_forecast: list[float]     # kW, 每时段负荷预测
    buy_price: list[float]         # 元/kWh, 每时段购电价格
    bess: BESSParams
    initial_soc: float             # kWh, 初始 SOC
    demand_charge_rate: float      # 元/kW/月, 需量电价
    step_hours: float              # 每时段小时数 (如 15min = 0.25)
    terminal_soc_target: float | None = None
    cycle_cost_rate: float = 0.0   # 元/kWh, 循环退化成本


@dataclass
class DispatchResult:
    """调度优化输出."""
    charge_power: list[float]       # kW
    discharge_power: list[float]    # kW
    net_bess_power: list[float]     # kW (charge - discharge)
    soc: list[float]                # kWh
    grid_import: list[float]        # kW
    max_grid_import: float          # kW
    energy_cost: float              # 元
    demand_cost: float              # 元
    total_cost: float               # 元
    constraint_violations: dict[str, float]


def solve_user_side_bess(dispatch_input: DispatchInput) -> DispatchResult:
    """求解用户侧储能最优调度.

    目标: 最小化 电度电费 + 需量电费 + 循环退化成本.
    约束: SOC 动态、充放电互斥、功率上限、电网供需平衡.

    Args:
        dispatch_input: 调度输入参数

    Returns:
        DispatchResult 含最优充放电计划和成本

    Raises:
        RuntimeError: 若 PuLP 未安装
        ValueError: 若输入不合法
    """
    if not _PULP_AVAILABLE:
        raise RuntimeError("PuLP 未安装,无法运行调度优化.请 pip install pulp")

    _validate(dispatch_input)

    bess = dispatch_input.bess
    T = range(len(dispatch_input.timestamps))
    model = LpProblem("user_side_bess", LpMinimize)

    # 决策变量
    charge = {t: LpVariable(f"ch_{t}", lowBound=0, upBound=bess.p_ch_max) for t in T}
    discharge = {t: LpVariable(f"dis_{t}", lowBound=0, upBound=bess.p_dis_max) for t in T}
    soc = {t: LpVariable(f"soc_{t}", lowBound=bess.soc_min, upBound=bess.soc_max) for t in T}
    grid_import = {t: LpVariable(f"grid_{t}", lowBound=0) for t in T}
    is_ch = {t: LpVariable(f"ich_{t}", cat=LpBinary) for t in T}
    is_dis = {t: LpVariable(f"idis_{t}", cat=LpBinary) for t in T}
    max_grid = LpVariable("max_grid", lowBound=0)

    step = dispatch_input.step_hours

    for t in T:
        # 互斥
        model += is_ch[t] + is_dis[t] <= 1
        model += charge[t] <= bess.p_ch_max * is_ch[t]
        model += discharge[t] <= bess.p_dis_max * is_dis[t]
        model += discharge[t] <= dispatch_input.load_forecast[t]

        # 供需平衡
        model += grid_import[t] == dispatch_input.load_forecast[t] + charge[t] - discharge[t]
        model += max_grid >= grid_import[t]

        # SOC 递推
        prev_soc = dispatch_input.initial_soc if t == 0 else soc[t - 1]
        model += soc[t] == prev_soc + bess.eta_ch * charge[t] * step - discharge[t] * step / bess.eta_dis

    # 终端 SOC
    if dispatch_input.terminal_soc_target is not None:
        model += soc[len(T) - 1] == dispatch_input.terminal_soc_target

    # 目标
    energy_cost = lpSum(dispatch_input.buy_price[t] * grid_import[t] * step for t in T)
    cycle_cost = lpSum(dispatch_input.cycle_cost_rate * (charge[t] + discharge[t]) * step for t in T)
    demand_cost = dispatch_input.demand_charge_rate * max_grid
    model += energy_cost + demand_cost + cycle_cost

    model.solve(PULP_CBC_CMD(msg=False))

    # v2.29fix: 求解状态检查,防止不可行/无界时静默返回垃圾值
    if LpStatus[model.status] != 'Optimal':
        raise RuntimeError(f"用户侧BESS LP求解失败: {LpStatus[model.status]}")

    # 提取结果
    ch_vals = [value(charge[t]) for t in T]
    dis_vals = [value(discharge[t]) for t in T]
    soc_vals = [value(soc[t]) for t in T]
    grid_vals = [value(grid_import[t]) for t in T]
    mg = value(max_grid)

    # 从求解后变量重新计算实际成本(PuLP 表达式在 solve 后必须用 value 求值)
    energy_cost_val = sum(dispatch_input.buy_price[t] * grid_vals[t] * step for t in T)
    demand_cost_val = dispatch_input.demand_charge_rate * mg
    cycle_cost_val = sum(dispatch_input.cycle_cost_rate * (ch_vals[t] + dis_vals[t]) * step for t in T)
    total_cost_val = energy_cost_val + demand_cost_val + cycle_cost_val

    return DispatchResult(
        charge_power=ch_vals,
        discharge_power=dis_vals,
        net_bess_power=[ch_vals[t] - dis_vals[t] for t in T],
        soc=soc_vals,
        grid_import=grid_vals,
        max_grid_import=mg,
        energy_cost=energy_cost_val,
        demand_cost=demand_cost_val,
        total_cost=total_cost_val,
        constraint_violations={},
    )


def solve_bess_arbitrage(prices: list[float], capacity: float = 10.0,
                         p_max: float = 3.0, eta: float = 0.95,
                         initial_soc: float = 5.0, dt: float = 1.0,
                         enforce_terminal_soc: bool = False) -> dict:
    """求解单市场储能套利.

    目标: 最大化低买高卖收益 - 循环退化成本.

    Returns:
        {"objective": ..., "p_ch": [...], "p_dis": [...], "soc": [...]}
    """
    if not _PULP_AVAILABLE:
        raise RuntimeError("PuLP 未安装")

    T = range(len(prices))
    m = LpProblem('bess_arbitrage', LpMaximize)
    soc_min = capacity * 0.1
    soc_max = capacity

    p_ch = {t: LpVariable(f'pch_{t}', lowBound=0, upBound=p_max) for t in T}
    p_dis = {t: LpVariable(f'pdis_{t}', lowBound=0, upBound=p_max) for t in T}
    soc = {t: LpVariable(f'soc_{t}', lowBound=soc_min, upBound=soc_max) for t in T}
    u_ch = {t: LpVariable(f'uch_{t}', cat=LpBinary) for t in T}
    u_dis = {t: LpVariable(f'udis_{t}', cat=LpBinary) for t in T}

    for t in T:
        m += u_ch[t] + u_dis[t] <= 1
        m += p_ch[t] <= p_max * u_ch[t]
        m += p_dis[t] <= p_max * u_dis[t]
        prev = initial_soc if t == 0 else soc[t - 1]
        m += soc[t] == prev + eta * p_ch[t] * dt - p_dis[t] * dt / eta

    if enforce_terminal_soc:
        m += soc[len(T) - 1] == initial_soc

    m += lpSum(prices[t] * (p_dis[t] - p_ch[t]) * dt for t in T)
    m.solve(PULP_CBC_CMD(msg=False))

    # v2.29fix: 求解状态检查
    if LpStatus[m.status] != 'Optimal':
        raise RuntimeError(f"储能套利LP求解失败: {LpStatus[m.status]}")

    return {
        'objective': value(m.objective),
        'p_ch': [value(p_ch[t]) for t in T],
        'p_dis': [value(p_dis[t]) for t in T],
        'soc': [value(soc[t]) for t in T],
    }


def _validate(inp: DispatchInput) -> None:
    """输入校验.v2.15: 增加 NaN/Inf 检查,防止非法值传入 PuLP 求解器."""
    import math
    n = len(inp.timestamps)
    if n == 0:
        raise ValueError("时间序列为空")
    if not (len(inp.load_forecast) == len(inp.buy_price) == n):
        raise ValueError("load_forecast, buy_price 长度必须一致")
    if inp.step_hours <= 0:
        raise ValueError("step_hours 必须 > 0")
    # v2.15: NaN/Inf 检查
    if any(math.isnan(x) or math.isinf(x) for x in inp.load_forecast):
        raise ValueError("load_forecast 包含 NaN 或 Inf,请先清洗数据")
    if any(math.isnan(x) or math.isinf(x) for x in inp.buy_price):
        raise ValueError("buy_price 包含 NaN 或 Inf,请先清洗数据")
    if any(ld < 0 for ld in inp.load_forecast):
        raise ValueError("负荷不能为负")
    if any(p < 0 for p in inp.buy_price):
        raise ValueError("电价不能为负")

    b = inp.bess
    if b.capacity <= 0:
        raise ValueError("储能容量必须 > 0")
    if b.soc_min < 0 or b.soc_max > b.capacity:
        raise ValueError("SOC 边界超出容量")
    if b.p_ch_max < 0 or b.p_dis_max < 0:
        raise ValueError("功率边界不能为负")


# ── capacity.py ──
# -*- coding: utf-8 -*-
"""capacity - 容量规划与收益率测算模块(v2.6 双模式)

双模式投资模型:
  Mode A: NREL ATB 2024 权威数据(默认)
    - 三种场景: Conservative / Moderate / Advanced
    - 数据来源: Cole, Ramasamy & Turan 2025 NREL/TP-6A40-93281
    - LCOS: Mongird et al. 2022 PNNL-33283
    - ITC: IRA 2022 §48E
  Mode B: 手动输入(NREL 数据可覆盖)

融合: ele-trading capacity_planning + solar-bess-sizing-api 引用链 + 自研
"""


from dataclasses import dataclass, field
from enum import Enum


# ═══════════════════════════════════════════════════════════════
# NREL ATB 2024 权威成本数据
# 来源: Cole, Ramasamy & Turan (2025) NREL/TP-6A40-93281
#       Ramasamy et al. (2023) NREL/TP-7A40-87610
# ═══════════════════════════════════════════════════════════════

class CostScenario(Enum):
    CONSERVATIVE = "conservative"  # 保守估计(高成本)
    MODERATE = "moderate"          # 中等估计(基准)
    ADVANCED = "advanced"          # 先进估计(低成本)
    MANUAL = "manual"              # 手动输入


@dataclass
class NRELCostData:
    """NREL ATB 2024 储能成本数据(美元,需按汇率换算)."""

    # 电池包成本 ($/kWh)
    battery_pack_cost: dict[str, float] = field(default_factory=lambda: {
        "conservative": 283.0,   # Ramasamy et al. 2023
        "moderate": 241.0,       # Cole, Ramasamy & Turan 2025
        "advanced": 189.0,       # Cole et al. 2025 low trajectory
    })

    # BOS 成本 ($/kW, 含 PCS + 安装 + 并网)
    bos_cost: dict[str, float] = field(default_factory=lambda: {
        "conservative": 371.0,
        "moderate": 339.0,
        "advanced": 290.0,
    })

    # 固定运维费率 (% CAPEX/年)
    fixed_om_rate: float = 0.025

    # 可变运维成本 ($/kWh)
    variable_om: float = 0.0005

    # 典型寿命 (年)
    typical_life: int = 15

    # 典型退化率 (%/年)
    typical_degradation: float = 0.02

    # 典型 RTE (AC-AC)
    typical_rte: dict[str, float] = field(default_factory=lambda: {
        "LFP": 0.85,
        "NMC": 0.87,
        "LFP_LD": 0.84,  # 长时储能
    })

    # 汇率 (USD -> CNY)
    usd_to_cny: float = 7.2


# ═══════════════════════════════════════════════════════════════
# IRA 2022 §48E ITC 税收抵免
# ═══════════════════════════════════════════════════════════════

@dataclass
class ITCConfig:
    """IRA §48E 投资税收抵免配置."""
    base_rate: float = 0.30            # 基础 30%
    domestic_content: bool = False     # 本土内容 +10%
    energy_community: bool = False     # 能源社区 +10%
    # 注: 中国项目不适用 IRA ITC,此处保留供参考/对比

    @property
    def total_rate(self) -> float:
        r = self.base_rate
        if self.domestic_content:
            r += 0.10
        if self.energy_community:
            r += 0.10
        return min(r, 0.50)  # 上限 50%


# ═══════════════════════════════════════════════════════════════
# 核心数据类型
# ═══════════════════════════════════════════════════════════════

@dataclass
class CapacityPlan:
    """容量规划结果."""
    optimal_power_kw: float
    optimal_capacity_kwh: float
    duration_hours: float
    irr_percent: float
    npv: float
    payback_years: float
    annual_savings: float
    annual_revenue: float
    total_investment: float
    lcos: float
    cost_scenario: str = ""       # 使用的成本场景
    capex_per_kwh: float = 0.0    # 实际使用的单位投资
    capex_per_kw: float = 0.0     # 实际使用的 PCS 投资


@dataclass
class InvestmentParams:
    """投资参数(双模式).

    若 cost_scenario != MANUAL,则从 NREL 数据库自动取值;
    否则使用手动输入的 capex_per_kwh / capex_per_kw.
    """
    cost_scenario: CostScenario = CostScenario.MODERATE
    capex_per_kwh: float = 0.0     # 手动模式用
    capex_per_kw: float = 0.0      # 手动模式用
    fixed_om_rate: float = 0.02
    variable_om: float = 0.05
    discount_rate: float = 0.07
    project_life: int = 15
    degradation_rate: float = 0.02
    exchange_rate: float = 7.2     # USD->CNY. 注意: 需随汇率变动定期更新,当前值基于2026年6月市场汇率
    itc: ITCConfig | None = None   # 可选 ITC


# ═══════════════════════════════════════════════════════════════
# NREL 成本查询
# ═══════════════════════════════════════════════════════════════

_NREL_DATA = NRELCostData()


def get_nrel_costs(scenario: CostScenario, exchange_rate: float = 7.2) -> tuple:
    """获取 NREL ATB 2024 成本数据(人民币).

    Returns:
        (battery_pack_cny_per_kwh, bos_cny_per_kw)
    """
    key = scenario.value
    pack_usd = _NREL_DATA.battery_pack_cost.get(key, 241.0)
    bos_usd = _NREL_DATA.bos_cost.get(key, 290.0)
    return pack_usd * exchange_rate, bos_usd * exchange_rate


def resolve_investment_params(params: InvestmentParams) -> tuple:
    """解析投资参数,返回实际使用的 (capex_per_kwh, capex_per_kw, fixed_om, variable_om).

    若为 NREL 模式,自动从数据库取值;若为 MANUAL,使用用户输入.
    """
    if params.cost_scenario == CostScenario.MANUAL:
        return (params.capex_per_kwh, params.capex_per_kw,
                params.fixed_om_rate, params.variable_om)

    capex_kwh, capex_kw = get_nrel_costs(params.cost_scenario, params.exchange_rate)
    return capex_kwh, capex_kw, _NREL_DATA.fixed_om_rate, _NREL_DATA.variable_om


def get_nrel_cost_summary(exchange_rate: float = 7.2) -> str:
    """获取 NREL 成本数据摘要(供 UI 展示)."""
    lines = [
        "═══ NREL ATB 2024 BESS 成本 ═══",
        f"汇率: USD 1 = CNY {exchange_rate:.1f}",
        "",
    ]
    for scenario in ["conservative", "moderate", "advanced"]:
        pack, bos = get_nrel_costs(CostScenario(scenario), exchange_rate)
        labels = {"conservative": "保守", "moderate": "中等", "advanced": "先进"}
        label = labels.get(scenario, scenario)
        lines.append(
            f"  {label}: 电池 ¥{pack:,.0f}/kWh, BOS ¥{bos:,.0f}/kW, "
            f"4h系统 ¥{(pack*4+bos):,.0f}/kW"
        )
    lines.append("")
    lines.append("来源: Cole, Ramasamy & Turan 2025 NREL/TP-6A40-93281")
    lines.append("      Ramasamy et al. 2023 NREL/TP-7A40-87610")
    return "\n".join(lines)


# ═══════════════════════════════════════════════════════════════
# 投资计算
# ═══════════════════════════════════════════════════════════════

def calc_investment(power_kw: float, capacity_kwh: float,
                    params: InvestmentParams | None = None) -> float:
    """计算总投资(含可选 ITC 抵扣)."""
    if params is None:
        params = InvestmentParams()
    capex_kwh, capex_kw, _, _ = resolve_investment_params(params)
    gross = capacity_kwh * capex_kwh + power_kw * capex_kw
    if params.itc:
        gross *= (1.0 - params.itc.total_rate)
    return gross


def calc_simple_payback(investment: float, annual_savings: float) -> float:
    """简单回收期 (年)."""
    if annual_savings <= 0:
        return float('inf')
    return investment / annual_savings


class DemandCompareResult:
    """两套需量算法的对比结果."""
    # 原有算法(numpy 手动)
    original_max_kw: float
    original_method: str = "numpy manual"

    # ele-trading 算法(pandas rolling)
    ele_max_kw: float = 0.0
    ele_peak_time: str = ""
    ele_method: str = "pandas rolling (ele-trading)"

    # 对比
    delta_kw: float = 0.0       # ele - original
    delta_pct: float = 0.0      # %
    agreement: str = ""         # "一致" / "偏差<1%" / "偏差>=1%"

    # 额外: 结构化信息(ele-trading 独有)
    monthly_max: dict[str, float] | None = None
    daily_max: dict[str, float] | None = None


def compare_demand(
    load_array: np.ndarray,
    time_labels: list[str],
    date_labels: list[str],
    window_minutes: int = 15,
    demand_price: float = 40.0,
) -> DemandCompareResult:
    """对比原有算法和 ele-trading 算法的需量计算结果.

    Args:
        load_array: numpy 2D (n_days, n_points)
        time_labels: 时间标签
        date_labels: 日期标签
        window_minutes: 窗口分钟数
        demand_price: 需量电价

    Returns:
        DemandCompareResult
    """
    # ── 原有算法(模拟你现有的 _calc_sliding_window_demand 逻辑)──
    result = DemandCompareResult(original_max_kw=0.0)

    if load_array.size == 0:
        result.agreement = "无数据"
        return result

    # 原有: numpy 手动滑动窗口
    n_days, n_points = load_array.shape
    dt_minutes = _infer_dt_minutes(time_labels, n_points)
    window_steps = max(1, int(round(window_minutes / dt_minutes)))

    all_window_means = []
    for day in range(n_days):
        day_load = load_array[day, :]
        pad = np.pad(day_load, (window_steps//2, window_steps//2), mode='edge')
        for i in range(n_points):
            window = pad[i:i+window_steps]
            all_window_means.append(np.mean(window))

    result.original_max_kw = float(np.max(all_window_means)) if all_window_means else 0.0

    # ── ele-trading 算法 ──
    if _HAS_PANDAS:
        try:
            from powercurve_ext.adapter import load_array_to_series
            from powercurve_ext.demand import calc_demand, DemandConfig

            series = load_array_to_series(load_array, time_labels, date_labels)
            if not series.empty:
                config = DemandConfig(
                    window_minutes=window_minutes,
                    window_type="sliding",
                    demand_price=demand_price,
                )
                ele_result = calc_demand(series, config)

                result.ele_max_kw = ele_result.max_demand
                result.ele_peak_time = str(ele_result.peak_timestamp)

                # 聚合月度/日度
                result.monthly_max = {
                    str(p): float(v)
                    for p, v in ele_result.monthly_max.items()
                }
                result.daily_max = {
                    str(d.date()): float(v)
                    for d, v in ele_result.daily_max.items()
                }
        except Exception:
            pass

    # ── 对比 ──
    if result.original_max_kw > 0 and result.ele_max_kw > 0:
        result.delta_kw = result.ele_max_kw - result.original_max_kw
        result.delta_pct = result.delta_kw / result.original_max_kw * 100
        if abs(result.delta_pct) < 0.5:
            result.agreement = "✓ 一致"
        elif abs(result.delta_pct) < 1.0:
            result.agreement = "偏差 < 1%"
        else:
            result.agreement = f"偏差 {result.delta_pct:.1f}%"
    elif result.ele_max_kw > 0:
        result.agreement = "原有算法无结果"
    elif result.original_max_kw > 0:
        result.agreement = "ele-trading 算法无结果(需 pandas)"
    else:
        result.agreement = "无数据"

    return result


def format_demand_comparison(r: DemandCompareResult) -> str:
    """格式化需量对比报告."""
    lines = [
        "═══ 需量算法对比 ═══",
        "",
        f"原有算法 (numpy): {r.original_max_kw:.1f} kW",
        f"ele-trading (pandas): {r.ele_max_kw:.1f} kW",
        f"差值: {r.delta_kw:+.1f} kW ({r.delta_pct:+.1f}%)",
        f"结论: {r.agreement}",
    ]
    if r.ele_peak_time:
        lines.append(f"峰值时刻: {r.ele_peak_time}")
    if r.monthly_max and len(r.monthly_max) <= 6:
        lines.append("")
        lines.append("月度最大需量 (ele-trading):")
        for month, val in list(r.monthly_max.items())[:6]:
            lines.append(f"  {month}: {val:.1f} kW")
    return "\n".join(lines)


# ═══════════════════════════════════════════════════════════════
# 2. SOC 循环计数 (rainflow)
# ═══════════════════════════════════════════════════════════════

@dataclass
class CycleReport:
    """电池循环报告."""
    total_cycles: float           # 等效全循环次数
    cycle_depths: list[float]     # 各循环深度 (0-1)
    cycle_counts: list[float]     # 对应次数
    annual_cycles: float          # 年化等效循环
    estimated_life_years: float   # 预估日历寿命
    depth_distribution: dict[str, float]  # 深度分布: {"浅循环(<30%)": n, ...}


def analyze_battery_cycles(
    soc_series: list[float],
    capacity_kwh: float = 500.0,
    rated_cycles: float = 6000.0,
) -> CycleReport:
    """分析电池 SOC 曲线的循环特性.

    Args:
        soc_series: SOC 时间序列 (kWh)
        capacity_kwh: 电池容量
        rated_cycles: 额定循环寿命 (@100% DoD)

    Returns:
        CycleReport
    """
    if not _HAS_RAINFLOW or not soc_series:
        return CycleReport(
            total_cycles=0.0, cycle_depths=[], cycle_counts=[],
            annual_cycles=0.0, estimated_life_years=0.0,
            depth_distribution={"需要 rainflow 库": 0}
        )

    # 用 rainflow 提取循环
    cycles = list(rainflow.extract_cycles(np.array(soc_series)))

    if not cycles:
        return CycleReport(
            total_cycles=0.0, cycle_depths=[], cycle_counts=[],
            annual_cycles=0.0, estimated_life_years=0.0,
            depth_distribution={"无有效循环": 0}
        )

    # 每个循环的深度和计数
    depths = []
    counts = []
    total_damage = 0.0
    shallow = mid = deep = 0

    # rainflow returns: (count, range, mean, start_idx, end_idx) - 5-tuple
    for entry in cycles:
        if len(entry) >= 2:
            cycle_range = float(entry[1])  # range
            count = float(entry[0])         # count
        # cycle_range 是 SOC 范围 (kWh)
        depth = cycle_range / capacity_kwh if capacity_kwh > 0 else 0.0
        depths.append(min(depth, 1.0))
        counts.append(count)

        # Wöhler 曲线简化: 损伤 = count / (rated_cycles * depth^-k)
        # k ~= 1.1 for LFP, 2 for NMC
        k = 1.1
        if depth > 0.01:
            damage = count / (rated_cycles * (depth ** (-k)))
            total_damage += damage

        if depth < 0.3:
            shallow += count
        elif depth < 0.7:
            mid += count
        else:
            deep += count

    total_cycles = sum(c * d for c, d in zip(counts, depths, strict=False))  # 等效全循环

    # 年化(假设 SOC 序列代表一年)
    annual_cycles = total_cycles

    # 预估寿命
    estimated_life = rated_cycles / total_cycles if total_cycles > 0 else float('inf')

    return CycleReport(
        total_cycles=total_cycles,
        cycle_depths=depths,
        cycle_counts=counts,
        annual_cycles=annual_cycles,
        estimated_life_years=min(estimated_life, 25.0),
        depth_distribution={
            "浅循环 (<30% DoD)": shallow,
            "中度循环 (30-70% DoD)": mid,
            "深循环 (>70% DoD)": deep,
        },
    )


def format_cycle_report(r: CycleReport) -> str:
    """格式化循环报告."""
    if not _HAS_RAINFLOW:
        return "需要 pip install rainflow"
    lines = [
        "═══ 电池循环分析 ═══",
        f"等效年循环次数: {r.annual_cycles:.0f}",
        f"预估日历寿命: {r.estimated_life_years:.1f} 年",
        "",
        "循环深度分布:",
    ]
    for label, count in r.depth_distribution.items():
        lines.append(f"  {label}: {count:.0f} 次")
    return "\n".join(lines)


# ═══════════════════════════════════════════════════════════════
# 3. 贪心调度引擎 (Numba)
# ═══════════════════════════════════════════════════════════════

def greedy_dispatch_annual(
    load_kw: np.ndarray,
    pv_kw: np.ndarray | None = None,
    wind_kw: np.ndarray | None = None,
    batt_kwh: float = 500.0,
    c_rate: float = 0.5,
    eta_roundtrip: float = 0.90,
    soc_init_frac: float = 0.5,
    soc_min_frac: float = 0.1,
    soc_max_frac: float = 0.95,
    dt_hours: float = 0.25,
) -> dict:
    """v2.19 SSS: 纯Python贪心调度引擎 - 逐时遍历,新能源优先.

    调度逻辑(每时步按序执行):
        1) 新能源直供负荷(direct = min(renewable, load))
        2) 多余电优先充电(受SOC上限和Pmax约束)
        3) 缺额优先放电(受SOC下限和Pmax约束)
        4) 未消纳新能源计入弃电
        5) 剩余缺额从电网购电

    Args:
        load_kw: 逐时负荷(kW), shape (n_timesteps,)
        pv_kw: 逐时光伏出力(kW), shape (n_timesteps,), None->全零
        wind_kw: 逐时风电出力(kW), shape (n_timesteps,), None->全零
        batt_kwh: 电池容量(kWh)
        c_rate: 充放电倍率(C-rate), 0.5=2小时充满
        eta_roundtrip: 往返效率, 默认0.90
        soc_init_frac: 初始SOC比例
        soc_min_frac: SOC下限比例
        soc_max_frac: SOC上限比例
        dt_hours: 时间步长(h), 默认0.25=15分钟

    Returns:
        {soc, grid_import, bess_charge, bess_discharge, curtailment,
         direct_use, total_gen, total_load, total_import, total_curtail}

    Note:
        - 仅适配新能源消纳优先场景,峰谷套利请使用 optimal_dispatch_lp()
        - dt_hours=0时自动回退0.25h(v2.19安全修复)
        - SOC约束: 充放电后夹具 soc = max(soc_min, min(soc_max, soc))
    """
    # v2.29fix: dt_hours入口校验,防止SOC更新与功率限制使用不同步长
    if dt_hours <= 0:
        raise ValueError(f"dt_hours 必须 > 0, 当前值 {dt_hours}")
    n = len(load_kw)
    if pv_kw is None:
        pv_kw = np.zeros(n)
    if wind_kw is None:
        wind_kw = np.zeros(n)

    renewable = pv_kw + wind_kw
    E = batt_kwh
    Pmax = c_rate * E

    soc_min = soc_min_frac * E
    soc_max = soc_max_frac * E
    soc = soc_init_frac * E
    eta_c = eta_roundtrip ** 0.5
    eta_d = eta_roundtrip ** 0.5

    soc_arr = np.zeros(n)
    grid_import = np.zeros(n)
    bess_ch = np.zeros(n)
    bess_dis = np.zeros(n)
    curtail = np.zeros(n)

    total_gen = 0.0
    total_load = 0.0
    total_import = 0.0
    total_curtail = 0.0
    direct_use = 0.0

    for t in range(n):
        ld = load_kw[t]
        ren = renewable[t]
        total_load += ld * dt_hours
        total_gen += ren * dt_hours

        # 1) 新能源直供
        direct = min(ren, ld)
        direct_use += direct * dt_hours
        surplus = ren - direct
        deficit = ld - direct

        # 2) 多余电充电
        ch_power = 0.0
        if surplus > 0 and soc < soc_max:
            max_ch_energy = (soc_max - soc) / eta_c
            max_ch_power = min(Pmax, max_ch_energy / dt_hours)
            ch_power = min(surplus, max_ch_power)
            soc += ch_power * eta_c * dt_hours
            bess_ch[t] = ch_power
            if surplus > ch_power:
                curtail[t] = surplus - ch_power
                total_curtail += curtail[t] * dt_hours

        # 3) 缺额放电
        dis_power = 0.0
        if deficit > 0 and soc > soc_min:
            max_dis_energy = (soc - soc_min) * eta_d
            max_dis_power = min(Pmax, max_dis_energy / dt_hours)
            dis_power = min(deficit, max_dis_power)
            soc -= dis_power * dt_hours / eta_d
            bess_dis[t] = dis_power

        # 4) 剩余缺额从电网购电
        net_deficit = deficit - dis_power
        if net_deficit > 0:
            grid_import[t] = net_deficit
            total_import += net_deficit * dt_hours

        # 夹具
        soc = max(soc_min, min(soc_max, soc))
        soc_arr[t] = soc

    return {
        "soc": soc_arr,
        "grid_import": grid_import,
        "bess_charge": bess_ch,
        "bess_discharge": bess_dis,
        "curtailment": curtail,
        "direct_use": direct_use,
        "total_gen": total_gen,
        "total_load": total_load,
        "total_import": total_import,
        "total_curtail": total_curtail,
    }


# v2.19 SSS: MILP全局最优调度引擎 - 线性规划求解充放电策略
def optimal_dispatch_lp(load_kw, buy_price, sell_price, batt_kwh=500, Pmax=250,
                         eta_c=0.95, eta_d=0.95, soc_min=0.1, soc_max=0.95,
                         soc_init=0.5, dt=0.25, demand_limit=None, demand_rate=0):
    """v2.19 SSS: 线性规划全局最优储能调度.

    使用 scipy.optimize.linprog 求解考虑分时电价+需量约束的最优充放电策略.
    相比贪心算法,LP能保证全局最优解(在连续松弛下).

    决策变量 (3T+1个, T=时间步数):
        ch[t]: 充电功率(kW), dis[t]: 放电功率(kW), soc[t]: 电池SOC(kWh)
        peak: 周期内峰值需量(kW)

    目标: max sum((dis[t]*sell_price[t] - ch[t]*buy_price[t]) * dt) - peak * demand_rate

    约束:
        - 0 <= ch[t], dis[t] <= Pmax
        - soc[t+1] = soc[t] + ch[t]*eta_c*dt - dis[t]*eta_d_inv*dt
        - soc_min*batt_kwh <= soc[t] <= soc_max*batt_kwh
        - soc[0] = soc_init*batt_kwh
        - load[t] - dis[t] + ch[t] <= peak (需量约束, 可选)

    Args:
        load_kw: 逐时负荷(kW), shape (T,)
        buy_price: 购电价格(元/kWh), shape (T,)
        sell_price: 售电/节电价格(元/kWh), shape (T,)
        batt_kwh: 电池容量(kWh)
        Pmax: 最大充放电功率(kW)
        eta_c, eta_d: 充放电效率
        soc_min, soc_max: SOC比例限制
        soc_init: 初始SOC比例
        dt: 时间步长(h)
        demand_limit: 需量上限(kW), None=不约束
        demand_rate: 需量费率(元/kW/周期)

    Returns:
        {ch, dis, soc, revenue, peak_demand, feasible, message}
        若scipy不可用或无可行解,返回 feasible=False
    """
    try:
        from scipy.optimize import linprog
    except ImportError:
        return {'feasible': False, 'message': 'scipy未安装,无法使用MILP调度'}

    import numpy as np
    T = len(load_kw)
    E = batt_kwh

    # 变量: ch[0..T-1], dis[0..T-1], soc[1..T], peak(可选)
    n_demand = 1 if demand_limit is not None else 0
    n_vars = 2*T + T + n_demand  # ch + dis + soc(1..T) + peak

    # 目标系数 (linprog最小化 -> 取负最大化收益)
    # v3.2.1fix(N2): 原实现放电收益只按 sell_price 计算。sell_price=0（纯自用）时
    # LP 认为放电不产生收益，于是完全不碰电池（或只把初值 SOC 白送掉），
    # 同一场景下比正确口径低 5.7 倍。物理上放电是「替代购电」，省的是 buy_price。
    # 现按「自用优先」取较高者：放电能量要么自己用掉（省买价），要么卖电网（得卖价）。
    c = np.zeros(n_vars)
    for t in range(T):
        c[t] = buy_price[t] * dt        # ch成本
        benefit = max(float(buy_price[t]), float(sell_price[t]))
        c[T+t] = -benefit * dt          # dis收益(负=最大化)
    if n_demand:
        c[-1] = demand_rate  # 需量成本

    # 约束: A_ub @ x <= b_ub
    A_rows, b_rows = [], []

    # SOC递推: soc[t] 定义为"第t个时段结束后的电量"
    # v3.2fix: 原实现 for t in range(T-1) 只约束到 soc[T-2], 末时段 ch[T-1]/dis[T-1]
    # 未进入任何方程, 可在最后一步凭空满功率放电而不付 SOC 代价(收益虚增);
    # 且初值绑在 soc[0] 上造成变量语义错位。现改为覆盖全部 T 个时段。
    inv_eta_d = 1.0 / eta_d if eta_d > 0 else 1.0
    for t in range(T):
        row = np.zeros(n_vars)
        row[t] = -eta_c * dt
        row[T + t] = inv_eta_d * dt
        row[2 * T + t] = 1.0
        if t > 0:
            row[2 * T + t - 1] = -1.0
        base_b = E * soc_init if t == 0 else 0.0
        # 上界: soc[t] - soc[t-1] - eta_c*dt*ch[t] + inv_eta_d*dt*dis[t] <= base_b
        A_rows.append(row.copy()); b_rows.append(base_b)
        # 下界(取负): -soc[t] + soc[t-1] + eta_c*dt*ch[t] - inv_eta_d*dt*dis[t] <= -base_b
        A_rows.append(-row); b_rows.append(-base_b)

    # SOC上下限
    for t in range(T):
        idx = 2*T + t
        # soc <= soc_max * E
        row_ub = np.zeros(n_vars); row_ub[idx] = 1.0
        A_rows.append(row_ub); b_rows.append(soc_max * E)
        # -soc <= -soc_min * E -> soc >= soc_min * E
        row_lb = np.zeros(n_vars); row_lb[idx] = -1.0
        A_rows.append(row_lb); b_rows.append(-soc_min * E)

    # 需量约束: load[t] - dis[t] + ch[t] <= peak
    if n_demand:
        peak_idx = n_vars - 1
        # v2.19fix: 峰值变量上限约束 peak <= demand_limit
        row = np.zeros(n_vars); row[peak_idx] = 1.0
        A_rows.append(row); b_rows.append(demand_limit)
        for t in range(T):
            row = np.zeros(n_vars)
            row[t] = 1.0; row[T+t] = -1.0; row[peak_idx] = -1.0
            A_rows.append(row); b_rows.append(-load_kw[t])

    # 变量上下界
    bounds = [(0, Pmax)] * (2*T)  # ch, dis
    bounds += [(soc_min*E, soc_max*E)] * T  # soc
    if n_demand:
        # v2.19fix: peak上界使用demand_limit而非硬编码
        bounds += [(0, demand_limit)]  # peak

    A = np.array(A_rows) if A_rows else None
    b = np.array(b_rows) if b_rows else None

    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs',
                     options={'time_limit': 120})  # v2.22fix: 防止大问题挂死GUI

    if result.success:
        x = result.x
        ch = x[:T]; dis = x[T:2*T]; soc = x[2*T:2*T+T]
        revenue = float(-result.fun)
        peak = x[-1] if n_demand else max(load_kw)
        return {'ch': ch, 'dis': dis, 'soc': soc, 'revenue': round(revenue, 2),
                'peak_demand': round(peak, 1), 'feasible': True,
                'message': f'LP最优解 (收益: {revenue:.2f}元)'}
    return {'feasible': False, 'message': result.message}


# ═══════════════════════════════════════════════════════════════
# 工具函数
# ═══════════════════════════════════════════════════════════════

def _infer_dt_minutes(time_labels: list[str], n_points: int) -> float:
    """推断时间步长(分钟)."""
    if n_points < 2 or len(time_labels) < 2:
        return 15.0  # 默认 15 分钟
    try:
        t0 = _parse_min_stl(time_labels[0])
        t1 = _parse_min_stl(time_labels[1])
        dt = abs(t1 - t0)
        if dt == 0:
            return 15.0
        return float(dt)
    except Exception:
        return 15.0


def _parse_min_stl(t: str) -> int:
    """Settlement模块内部时间解析 - 仅支持HH:MM格式.
    主模块 _parse_min() 支持6条解析路径,此处为简化版.
    如需修改时间解析逻辑,请确保与 _parse_min() 行为一致."""
    try:
        parts = t.strip().split(":")
        if len(parts) != 2:
            raise ValueError(f"Invalid time format: {t!r}")
        return int(parts[0]) * 60 + int(parts[1])
    except (ValueError, IndexError) as e:
        log.warning(f"_parse_min_stl failed for {t!r}: {e}")
        return INVALID_MINUTES


