# -*- coding: utf-8 -*-
"""settlement - 结算与回测模块

基于 ele-trading evaluation/ 的方法论,
提供: 收益结算、需量节省核算、投资回收追踪.
"""


from dataclasses import dataclass


@dataclass
class SettlementPeriod:
    """单周期结算结果."""
    period: str                    # "2025-06" 或 "2025-06-01"
    energy_cost_without_bess: float
    energy_cost_with_bess: float
    demand_without_bess: float     # kW
    demand_with_bess: float        # kW
    demand_saving: float           # 元
    energy_saving: float           # 元
    total_saving: float            # 元
    bess_cycles: float             # 等效循环次数


@dataclass
# ═══════════════════════════════════════════════════════════
# v3.2: 🔮 智能负荷预测引擎
# 五模型竞赛 + Shapley归因 + 决策链路 + 在线学习
# ═══════════════════════════════════════════════════════════

@dataclass
class ForecastConfig:
    """预测配置."""
    horizon_hours: int = 168         # 预测时长(小时), 默认7天
    history_days: int = 60            # 用多少天历史数据训练
    confidence_levels: tuple = (0.80, 0.95)
    auto_model: bool = True           # 自动选最优模型
    freq_minutes: int = 15            # 数据频率(分钟)
    enable_decomposition: bool = True # Shapley归因
    enable_recommendations: bool = True


@dataclass
class ForecastResult:
    """预测结果——完整版."""
    point: np.ndarray = None
    lower_80: np.ndarray = None; upper_80: np.ndarray = None
    lower_95: np.ndarray = None; upper_95: np.ndarray = None
    history: np.ndarray = None
    model_name: str = ''
    mape: float = 0.0; rmse: float = 0.0
    decomposition: dict = None
    recommendations: list = None
    scenarios: dict = None  # {'optimistic': arr, 'baseline': arr, 'pessimistic': arr}
    solve_time_s: float = 0.0

    def to_csv(self, path: str, freq_minutes: int = 15, start_date: str = None):
        """导出为标准宽表CSV, 可直接加入文件列表."""
        import csv, datetime
        n_pts = int(24 * 60 / freq_minutes)
        horizon_pts = len(self.point)
        n_days = int(np.ceil(horizon_pts / n_pts))
        if start_date is None:
            start_date = datetime.date.today().isoformat()
        base = datetime.date.fromisoformat(start_date)
        with open(path, 'w', encoding='utf-8-sig', newline='') as f:
            w = csv.writer(f)
            times = [f'{i*freq_minutes//60:02d}:{i*freq_minutes%60:02d}' for i in range(n_pts)]
            w.writerow(['日期'] + times)
            for d in range(n_days):
                dt = (base + datetime.timedelta(days=d)).isoformat()
                vals = [f'{self.point[d*n_pts + i]:.2f}' if d*n_pts + i < horizon_pts else ''
                        for i in range(n_pts)]
                w.writerow([dt] + vals)
        return path

    def render_chart(self, width=10, height=4.5, dpi=130) -> 'QPixmap':
        """渲染预测图表: 历史+预测+置信区间+场景, 风格对齐主预览."""
        _init_matplotlib()
        fig, ax = _get_plt().subplots(1, 1, figsize=(width, height))
        fig.patch.set_facecolor('#FAFBFC')
        n_hist = len(self.history) if self.history is not None else 0
        n_pred = len(self.point)
        # 历史曲线
        if n_hist > 0:
            ax.plot(range(n_hist), self.history, color='#5B9BD5', lw=0.6, alpha=0.6, label='历史')
        # 预测曲线
        x_pred = range(n_hist, n_hist + n_pred)
        ax.plot(x_pred, self.point, color='#E53935', lw=2.0, label=f'预测({self.model_name})')
        # 置信区间
        ax.fill_between(x_pred, self.lower_80, self.upper_80, alpha=0.15, color='#E53935', label='80%置信')
        ax.fill_between(x_pred, self.lower_95, self.upper_95, alpha=0.08, color='#E53935', label='95%置信')
        # 场景
        if self.scenarios:
            for s, color in [('optimistic', '#4CAF50'), ('pessimistic', '#FF9800')]:
                if s in self.scenarios:
                    ax.plot(x_pred, self.scenarios[s], color=color, lw=0.6, ls='--', alpha=0.5, label=s)
        # 分界线
        if n_hist > 0:
            ax.axvline(x=n_hist-1, color='#999', ls=':', lw=1)
        # 标签
        ax.set_ylabel('功率 (kW)', fontsize=10)
        ax.set_title(f'🔮 负荷预测 | {self.model_name} | MAPE:{self.mape:.1f}% RMSE:{self.rmse:.0f}kW',
                     fontsize=11, fontweight='bold')
        ax.legend(fontsize=8, loc='upper left', framealpha=0.8, ncol=2)
        ax.grid(True, alpha=0.15, ls=':')
        ax.tick_params(labelsize=8)
        fig.tight_layout(pad=2.0)
        buf = io.BytesIO()
        fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor=fig.get_facecolor())
        _get_plt().close(fig)
        buf.seek(0)
        pix = QPixmap()
        pix.loadFromData(buf.read())
        return pix


class ForecastEngine:
    """多模型竞赛预测引擎: Holt-Winters / SARIMA / 朴素 / 分解 / 集成."""

    def __init__(self, config: ForecastConfig = None):
        self.config = config or ForecastConfig()
        self._best_model = None
        self._last_data = None
        self._metrics_history = []  # 在线学习: 记录每次预测误差

    def _build_features(self, series: np.ndarray, n_pts: int) -> np.ndarray:
        """特征工程: 滞后/滚动统计/时间编码."""
        n = len(series)
        feats = np.zeros((n, 9))
        # 滞后特征
        for i in range(n):
            feats[i, 0] = series[i-1] if i >= 1 else series[0]           # t-1
            feats[i, 1] = series[i-n_pts] if i >= n_pts else series[0]   # t-24h
            feats[i, 2] = series[i-n_pts*7] if i >= n_pts*7 else series[0]  # t-7d
        # 滚动统计
        for i in range(n):
            window = series[max(0, i-n_pts):i+1]
            feats[i, 3] = np.mean(window)                                # 24h均值
            feats[i, 4] = np.std(window) if len(window) > 1 else 0       # 24h标准差
            feats[i, 5] = np.max(window) - np.min(window)                 # 峰谷差
        # 时间编码(sin/cos循环)
        for i in range(n):
            h = (i % n_pts) / n_pts * 24
            feats[i, 6] = np.sin(2 * np.pi * h / 24)                     # sin时刻
            feats[i, 7] = np.cos(2 * np.pi * h / 24)                     # cos时刻
            feats[i, 8] = (i // n_pts) % 7 / 7.0                          # 星期几
        return feats

    def fit_predict(self, load_array: np.ndarray, date_labels: list = None,
                    time_labels: list = None, holidays: list = None) -> ForecastResult:
        """训练+预测: 输入(n_days, n_points)负荷矩阵, 输出预测结果."""
        import time; t0 = time.time()
        n_days, n_pts = load_array.shape
        cfg = self.config

        # ── 数据准备: 展平为1D序列 ──
        series = load_array.flatten()
        n_hist = min(cfg.history_days * n_pts, len(series))
        train = series[-n_hist:]
        horizon = int(cfg.horizon_hours * 60 / cfg.freq_minutes)

        # v3.2: 特征工程
        features = self._build_features(series, n_pts)
        train_feat = features[-n_hist:] if n_hist < len(features) else features

        # ── 模型竞赛 ──
        models = {}
        errors = {}

        # 1. 朴素持久模型(baseline)
        try:
            naive_pred = np.tile(train[-horizon:min(len(train), horizon*2)], 
                                 int(np.ceil(horizon/len(train[-horizon:]))))[:horizon]
            if len(train) > horizon:
                naive_err = np.mean(np.abs(train[-horizon:] - naive_pred[:len(train[-horizon:])]))
            else:
                naive_err = np.mean(np.abs(train))
            models['naive'] = naive_pred
            errors['naive'] = naive_err
        except Exception:
            errors['naive'] = 1e9

        # 2. Holt-Winters 三重指数平滑
        try:
            from statsmodels.tsa.holtwinters import ExponentialSmoothing
            period = n_pts  # 日周期
            if len(train) >= period * 3:
                hw = ExponentialSmoothing(train, seasonal_periods=period,
                                          trend='add', seasonal='add')
                hw_fit = hw.fit()
                hw_pred = hw_fit.forecast(horizon)
                models['holt_winters'] = hw_pred
                errors['holt_winters'] = np.mean(np.abs(hw_fit.fittedvalues[-horizon:] - train[-horizon:])) if len(train) > horizon else hw_fit.sse / len(train)
        except Exception:
            errors['holt_winters'] = 1e9

        # 3. SARIMA (如果数据足够)
        try:
            if len(train) >= n_pts * 7:
                from statsmodels.tsa.arima.model import ARIMA
                arima = ARIMA(train[-min(len(train), n_pts*14):], order=(2,1,2),
                              seasonal_order=(1,0,1, n_pts))
                arima_fit = arima.fit()
                arima_pred = arima_fit.forecast(horizon)
                models['sarima'] = arima_pred
                errors['sarima'] = np.mean(np.abs(arima_fit.resid[-horizon:])) if len(arima_fit.resid) > horizon else np.mean(np.abs(arima_fit.resid))
        except Exception:
            errors['sarima'] = 1e9

        # 4. STL分解 + 趋势外推
        try:
            if len(train) >= n_pts * 14:
                from statsmodels.tsa.seasonal import STL
                stl = STL(train, period=n_pts, seasonal=13)
                stl_res = stl.fit()
                # 趋势: 线性外推
                trend = stl_res.trend
                valid = ~np.isnan(trend)
                if np.sum(valid) > 10:
                    x = np.arange(len(trend))
                    coeffs = np.polyfit(x[valid], trend[valid], 1)
                    trend_pred = np.polyval(coeffs, np.arange(len(trend), len(trend)+horizon))
                    # 季节: 重复最后一周
                    seasonal = stl_res.seasonal
                    seas_last = seasonal[-n_pts:]
                    seas_pred = np.tile(seas_last, int(np.ceil(horizon/n_pts)))[:horizon]
                    stl_pred = trend_pred + seas_pred
                    models['stl'] = stl_pred
                    errors['stl'] = np.mean(np.abs(stl_res.resid[-min(horizon, len(stl_res.resid)):]))
        except Exception:
            errors['stl'] = 1e9

        # 5. 简单指数平滑(轻量fallback)
        try:
            from statsmodels.tsa.holtwinters import SimpleExpSmoothing
            ses = SimpleExpSmoothing(train).fit()
            ses_pred = ses.forecast(horizon)
            models['ses'] = ses_pred
            errors['ses'] = np.mean(np.abs(ses.fittedvalues[-horizon:] - train[-horizon:])) if len(train) > horizon else ses.sse / len(train)
        except Exception:
            errors['ses'] = 1e9

        # 6. XGBoost 梯度提升树(v3.2fix)
        try:
            from xgboost import XGBRegressor
            if len(train) >= n_pts * 3 and train_feat.shape[0] >= 30:
                # 用滞后+滚动+时间特征训练
                cutoff = max(1, len(train) - horizon)
                X_tr = train_feat[:cutoff][-min(2000, cutoff):]
                y_tr = train[:cutoff][-min(2000, cutoff):]
                xgb = XGBRegressor(n_estimators=100, max_depth=5, learning_rate=0.05,
                                   subsample=0.8, colsample_bytree=0.8, random_state=42, verbosity=0)
                xgb.fit(X_tr, y_tr)
                # 预测: 递归——每次预测一步, 更新特征
                xgb_pred = np.zeros(horizon)
                last_feat = train_feat[-1:].copy()
                for h in range(horizon):
                    pred = float(xgb.predict(last_feat)[0])
                    xgb_pred[h] = pred
                    # 简单滚动: 更新滞后特征(用预测值)
                    last_feat = np.roll(last_feat, -1, axis=1)
                    last_feat[0, -1] = pred
                models['xgboost'] = xgb_pred
                # 验证误差
                if cutoff > 1:
                    xgb_pred_valid = xgb.predict(X_tr[-min(horizon, len(X_tr)):])
                    errors['xgboost'] = np.mean(np.abs(xgb_pred_valid - y_tr[-min(horizon, len(y_tr)):]))
                else:
                    errors['xgboost'] = np.mean(np.abs(y_tr)) * 0.8
        except Exception:
            errors['xgboost'] = 1e9

        # 7. Prophet Meta时序模型(v3.2fix)
        try:
            from prophet import Prophet
            import pandas as _pd
            if len(train) >= n_pts * 7:  # 至少7天数据
                # 日聚合: 取每日均值
                n_days_train = len(train) // n_pts
                daily_vals = np.array([np.mean(train[i*n_pts:(i+1)*n_pts]) for i in range(n_days_train)])
                df_p = _pd.DataFrame({'ds': _pd.date_range('2026-01-01', periods=n_days_train, freq='D'), 'y': daily_vals})
                m = Prophet(daily_seasonality=True, weekly_seasonality=True, yearly_seasonality=False)
                m.fit(df_p)
                future = m.make_future_dataframe(periods=int(np.ceil(horizon/n_pts)))
                fc = m.predict(future)
                daily_pred = fc['yhat'].values[-int(np.ceil(horizon/n_pts)):]
                # 展开到原分辨率: 重复日值
                prophet_pred = np.repeat(daily_pred, n_pts)[:horizon]
                models['prophet'] = prophet_pred
                # 验证: 最后已知日的误差
                val_pred = fc['yhat'].values[n_days_train-1]
                errors['prophet'] = abs(val_pred - daily_vals[-1]) / max(abs(daily_vals[-1]), 1) * np.mean(np.abs(daily_vals))
        except Exception:
            errors['prophet'] = 1e9

        # ── 模型集成加权(基于误差倒数) ──
        valid_models = {k: v for k, v in models.items() if k in errors and errors[k] < 1e8}
        if len(valid_models) > 1 and cfg.auto_model:
            weights = {}
            total_weight = 0.0
            for name in valid_models:
                w = 1.0 / max(errors[name], 0.001)
                weights[name] = w
                total_weight += w
            ensemble_pred = np.zeros(horizon)
            for name, pred_arr in valid_models.items():
                ensemble_pred += weights[name] / total_weight * pred_arr[:horizon]
            point_forecast = ensemble_pred
            self._best_model = 'ensemble(' + '+'.join(valid_models.keys()) + ')'
        elif valid_models:
            self._best_model = min(errors, key=errors.get)
            point_forecast = valid_models.get(self._best_model.split('(')[0] if '(' in self._best_model else self._best_model,
                                              np.zeros(horizon))
        else:
            point_forecast = np.zeros(horizon)
            self._best_model = 'none'
        self._last_data = train

        # ── 三段式节假日调整 ──
        try:
            from chinese_calendar import is_workday, is_holiday
            import datetime as _dt
            holiday_adj = np.ones(horizon)
            today = _dt.date.today()
            for i in range(horizon):
                d = today + _dt.timedelta(hours=i * cfg.freq_minutes / 60)
                day = d  # v3.2fix: date+timedelta 已返回 date 对象
                tomorrow = day + _dt.timedelta(days=1)
                if is_holiday(day):
                    holiday_adj[i] = 0.45   # 节假日-55%
                elif is_holiday(tomorrow) and day.weekday() < 5:
                    holiday_adj[i] = 1.18   # 节前赶工+18%
                elif not is_workday(day):
                    holiday_adj[i] = 0.60   # 周末-40%
            point_forecast = point_forecast * holiday_adj
        except ImportError:
            pass

        # ── 行业模板冷启动(数据不足时用INDUSTRY_TEMPLATES先验) ──
        if n_days < 14 and load_array.size > 0:
            daily_pattern = np.mean(load_array, axis=0)
            daily_avg = np.mean(daily_pattern)
            daily_peak = np.max(daily_pattern)
            lf = daily_avg / max(daily_peak, 1)
            # 匹配最接近的行业模板
            best_match = None
            best_diff = 1e9
            for ind, tpl in INDUSTRY_TEMPLATES.items():
                diff = abs(lf - tpl.get('daily_load_factor', 0.5))
                if diff < best_diff:
                    best_diff = diff
                    best_match = ind
            if best_match and best_diff < 0.2:
                template = INDUSTRY_TEMPLATES[best_match]
                template_pattern = np.array(template.get('month_factors', [1.0]*12))
                month_idx = today.month - 1 if 'today' in dir() else 0
                month_factor = template_pattern[month_idx] if 0 <= month_idx < 12 else 1.0
                point_forecast = point_forecast * 0.6 + (daily_avg * month_factor) * 0.4
                self._best_model += f'+template({best_match})'

        # ── 置信区间(基于残差Bootstrap) ──
        resid = train[-min(horizon, len(train)):] - point_forecast[:min(horizon, len(train))]
        if len(resid) > 0:
            resid_std = np.std(resid)
            lower_80 = point_forecast - 1.28 * resid_std
            upper_80 = point_forecast + 1.28 * resid_std
            lower_95 = point_forecast - 1.96 * resid_std
            upper_95 = point_forecast + 1.96 * resid_std
        else:
            lower_80 = upper_80 = lower_95 = upper_95 = point_forecast

        # ── 精度指标 ──
        if len(train) > horizon:
            test = train[-horizon:]
            mape = np.mean(np.abs((test - point_forecast[:len(test)]) / np.maximum(test, 1))) * 100
            rmse = np.sqrt(np.mean((test - point_forecast[:len(test)])**2))
        else:
            mape = rmse = 0.0

        # ── Shapley分解 ──
        decomp = {}
        if cfg.enable_decomposition:
            # 节假日检测
            try:
                from chinese_calendar import is_workday
                import datetime as _dt
                holiday_effect = np.zeros(horizon)
                for i in range(min(horizon, len(date_labels) if date_labels else 0)):
                    try:
                        d = _dt.date.fromisoformat(str(date_labels[i])[:10])
                        if not is_workday(d):
                            holiday_effect[i] = -0.15 * point_forecast[i] if i < len(point_forecast) else 0
                    except Exception:
                        pass
                decomp['holiday'] = holiday_effect
            except ImportError:
                pass
            # 趋势+周期分解
            if self._best_model == 'stl':
                decomp['trend'] = trend_pred
                decomp['seasonal'] = seas_pred
            else:
                daily_avg = np.mean(train)
                daily_pattern = np.mean(load_array[-min(7, n_days):], axis=0) if n_days > 0 else np.ones(n_pts) * daily_avg
                decomp['base'] = np.full(horizon, daily_avg)
                decomp['daily_pattern'] = np.tile(daily_pattern, int(np.ceil(horizon/n_pts)))[:horizon]

        # ── 行动建议 ──
        recs = []
        if cfg.enable_recommendations:
            peak_pred = np.max(point_forecast)
            peak_hour = np.argmax(point_forecast) * cfg.freq_minutes / 60
            recs.append(f"预测峰值 {peak_pred:.0f}kW 出现在第 {peak_hour:.1f}h")
            if peak_pred > 500:
                recs.append("⚠️ 峰值较高, 建议储能提前充电削峰")
            daily_energy = np.sum(np.maximum(point_forecast, 0)) * cfg.freq_minutes / 60
            recs.append(f"预测日用电量 {daily_energy:.0f}kWh")

        # ── 场景推演(乐观/基准/悲观) ──
        scenarios = {}
        if len(resid) > 0:
            resid_std = np.std(resid)
            scenarios['baseline'] = point_forecast
            scenarios['optimistic'] = point_forecast * 0.92  # 乐观: -8%
            scenarios['pessimistic'] = point_forecast * 1.12  # 悲观: +12%
        else:
            scenarios = {'baseline': point_forecast, 'optimistic': point_forecast, 'pessimistic': point_forecast}

        # ── 行动建议(增强版: 含经济估算) ──
        recs = []
        if cfg.enable_recommendations:
            peak_pred = np.max(point_forecast)
            peak_hour = np.argmax(point_forecast) * cfg.freq_minutes / 60
            peak_day = int(peak_hour // 24) + 1
            peak_h = peak_hour % 24
            recs.append(f"⚡ 峰值 {peak_pred:.0f}kW @ 第{peak_day}天 {peak_h:.0f}:00")
            daily_kwh = np.sum(np.maximum(point_forecast, 0)) * cfg.freq_minutes / 60
            recs.append(f"🔋 预测总电量 {daily_kwh:.0f}kWh")
            # 经济估算
            if hasattr(self, '_capacity_line') and self._capacity_line:
                over_cap = max(0, peak_pred - self._capacity_line)
                if over_cap > 0:
                    recs.append(f"⚠️ 超容量线 {over_cap:.0f}kW, 预计多交需量费 ¥{over_cap*40:.0f}/月")
                    recs.append(f"💡 建议: 在峰值前2小时将储能充至85%, 可削峰{over_cap:.0f}kW")
            # 充放电建议
            peak_idx = np.argmax(point_forecast)
            valley_before = np.min(point_forecast[max(0,peak_idx-n_pts):peak_idx]) if peak_idx > n_pts else np.min(point_forecast[:peak_idx])
            if peak_pred > valley_before * 1.3:
                recs.append(f"💰 峰谷价差机会: 谷段充电 {valley_before:.0f}kW → 峰段放电 {peak_pred:.0f}kW")
            # 在线学习状态
            if self._metrics_history:
                last_err = self._metrics_history[-1]
                if isinstance(last_err, dict) and last_err.get('mape', 0) > 15:
                    recs.append("⚠️ 近期预测误差较大, 建议重新训练模型")

        return ForecastResult(
            point=point_forecast, lower_80=lower_80, upper_80=upper_80,
            lower_95=lower_95, upper_95=upper_95,
            history=train[-min(n_pts*7, len(train)):],
            model_name=self._best_model, mape=mape, rmse=rmse,
            decomposition=decomp, recommendations=recs,
            scenarios=scenarios, solve_time_s=time.time() - t0
        )

    def online_update(self, actual: np.ndarray, predicted: np.ndarray):
        """在线学习: 记录实际vs预测误差, 漂移检测."""
        err = np.abs(actual - predicted)
        mape = np.mean(err / np.maximum(np.abs(actual), 1)) * 100
        self._metrics_history.append({'mape': mape, 'rmse': np.sqrt(np.mean(err**2)),
                                       'time': __import__('datetime').datetime.now().isoformat()})
        if len(self._metrics_history) > 100:
            self._metrics_history = self._metrics_history[-100:]


# ═══════════════════════════════════════════════════════════
# v3.2: 🎯 MPC 模型预测控制器
# 预测→优化→执行→反馈 四步闭环
# ═══════════════════════════════════════════════════════════

@dataclass
class MPCConfig:
    """MPC 控制配置."""
    horizon_steps: int = 96        # 预测步数(24h×4=96@15min)
    control_interval_min: int = 15 # 控制间隔(分钟)
    battery_capacity_kwh: float = 500
    battery_power_kw: float = 250
    soc_min: float = 0.05
    soc_max: float = 0.95
    eta_ch: float = 0.95
    eta_dis: float = 0.95
    peak_price: float = 1.1
    valley_price: float = 0.3
    flat_price: float = 0.7
    demand_charge: float = 40   # 需量电价(元/kW/月)
    capacity_line: float = 0    # 变压器容量限制(kW), 0=不限


@dataclass
class MPCStep:
    """单步MPC决策."""
    action: str = 'idle'     # charge/discharge/idle
    power_kw: float = 0.0     # 充/放功率
    energy_kwh: float = 0.0   # 充/放电量
    soc_before: float = 0.0
    soc_after: float = 0.0
    cost_saving: float = 0.0  # 该步节省的电费
    predicted_load: float = 0.0
    actual_load: float = 0.0


@dataclass
class MPCResult:
    """MPC 优化结果."""
    steps: list = None              # MPCStep 列表
    total_saving: float = 0.0       # 总节省
    total_charge_kwh: float = 0.0
    total_discharge_kwh: float = 0.0
    peak_reduction_kw: float = 0.0  # 削峰量
    soc_trajectory: np.ndarray = None
    recommendations: list = None


class MPCController:
    """MPC 滚动优化控制器: 预测→贪心优化→执行→反馈."""

    def __init__(self, config: MPCConfig = None):
        self.config = config or MPCConfig()
        self._engine = ForecastEngine(ForecastConfig(horizon_hours=24))
        self._soc = 0.1  # 初始SOC
        self._history = []

    def optimize(self, load_array: np.ndarray, current_soc: float = None,
                 date_labels: list = None, time_labels: list = None,
                 pv_array: np.ndarray = None) -> MPCResult:
        """两阶段滚动优化: MILP全局→贪心微调+光伏联动."""
        cfg = self.config
        if current_soc is not None:
            self._soc = current_soc
        n_pts = load_array.shape[1]
        freq = int(24 * 60 / n_pts)
        cfg.control_interval_min = freq
        cfg.horizon_steps = int(24 * 60 / freq)

        # ① 预测(含光伏)
        self._engine.config.freq_minutes = freq
        forecast = self._engine.fit_predict(load_array, date_labels, time_labels)
        pred = forecast.point[:cfg.horizon_steps]
        # 光伏联动: 如果有光伏数据, 计算净负荷
        pv_pred = np.zeros(cfg.horizon_steps)
        if pv_array is not None and pv_array.size > 0:
            pv_flat = pv_array.flatten()
            pv_pred = pv_flat[-min(len(pv_flat), cfg.horizon_steps):]
            if len(pv_pred) < cfg.horizon_steps:
                pv_pred = np.pad(pv_pred, (0, cfg.horizon_steps - len(pv_pred)))
        net_load = pred - pv_pred  # 净负荷 = 负荷 - 光伏

        # ② 第一阶段: MILP全局(简化版——只在有ortools时)
        milp_plan = None
        try:
            from ortools.linear_solver import pywraplp
            solver = pywraplp.Solver.CreateSolver('SCIP')
            if solver:
                solver.SuppressOutput()
                N = min(cfg.horizon_steps, 96)
                ch = [solver.NumVar(0, cfg.battery_power_kw, f'ch_{i}') for i in range(N)]
                dis = [solver.NumVar(0, cfg.battery_power_kw, f'dis_{i}') for i in range(N)]
                soc_v = [solver.NumVar(0, cfg.battery_capacity_kwh, f's_{i}') for i in range(N+1)]
                solver.Add(soc_v[0] == cfg.battery_capacity_kwh * self._soc)
                revenue = solver.Sum(
                    dis[i] * (cfg.peak_price if 9 <= (i*freq/60)%24 < 21 else cfg.valley_price)
                    - ch[i] * (cfg.valley_price if 0 <= (i*freq/60)%24 < 8 else cfg.flat_price)
                    for i in range(N))
                for i in range(N):
                    solver.Add(ch[i] + net_load[i] >= 0)
                    solver.Add(dis[i] <= max(0, net_load[i]))
                    if i > 0:
                        dt = freq / 60.0
                        solver.Add(soc_v[i] == soc_v[i-1] + ch[i]*cfg.eta_ch*dt - dis[i]*dt/cfg.eta_dis)
                solver.Add(soc_v[N] >= soc_v[0] * 0.8)
                solver.Maximize(revenue)
                if solver.Solve() in (pywraplp.Solver.OPTIMAL, pywraplp.Solver.FEASIBLE):
                    milp_plan = [(ch[i].solution_value(), dis[i].solution_value()) for i in range(N)]
        except Exception:
            pass  # MILP不可用时降级为贪心

        # ③ 第二阶段: 贪心微调(基于MILP计划或纯贪心)
        steps = []
        soc = self._soc
        batt_kwh = cfg.battery_capacity_kwh
        batt_kw = cfg.battery_power_kw
        total_saving = total_ch = total_dis = 0.0
        soc_traj = np.zeros(cfg.horizon_steps + 1)
        soc_traj[0] = soc

        for t in range(cfg.horizon_steps):
            load = net_load[t]  # 使用净负荷(已扣除光伏)
            dt = freq / 60.0
            h = (t * freq / 60) % 24
            is_peak = (9 <= h < 12) or (14 <= h < 17) or (18 <= h < 21)
            is_valley = (0 <= h < 8)
            price = cfg.peak_price if is_peak else (cfg.valley_price if is_valley else cfg.flat_price)

            action = 'idle'
            power = 0.0
            # MILP引导: 如果有MILP计划, 优先采用然后微调
            milp_ch, milp_dis = milp_plan[t] if milp_plan and t < len(milp_plan) else (0, 0)

            if is_valley and soc < cfg.soc_max:
                max_ch = min(batt_kw, (cfg.soc_max - soc) * batt_kwh / max(cfg.eta_ch * dt, 0.01))
                pv_avail = pv_pred[t] if t < len(pv_pred) else 0
                ch_power = min(max_ch, pv_avail + milp_ch)  # 优先用光伏充电
                if ch_power > batt_kw * 0.03:
                    action = 'charge'
                    power = ch_power
                    energy = ch_power * dt
                    soc += energy * cfg.eta_ch / batt_kwh
                    total_ch += energy
                    total_saving -= energy * price * 0.3  # 充电成本
            elif is_peak and soc > cfg.soc_min:
                max_dis = min(batt_kw, (soc - cfg.soc_min) * batt_kwh * cfg.eta_dis / max(dt, 0.01))
                dis_power = min(load, max_dis, milp_dis + batt_kw * 0.3)
                if dis_power > batt_kw * 0.03:
                    action = 'discharge'
                    power = dis_power
                    energy = dis_power * dt
                    soc -= energy / max(cfg.eta_dis * batt_kwh, 0.01)
                    total_dis += energy
                    total_saving += energy * price

            soc = max(cfg.soc_min, min(cfg.soc_max, soc))
            soc_traj[t + 1] = soc
            steps.append(MPCStep(
                action=action, power_kw=power, energy_kwh=power * dt,
                soc_before=soc_traj[t], soc_after=soc,
                cost_saving=total_saving, predicted_load=load
            ))

        # ④ 建议
        recs = [
            f"充电: {total_ch:.0f}kWh | 放电: {total_dis:.0f}kWh",
            f"预估节省: ¥{total_saving:.0f}",
            f"终态SOC: {soc*100:.0f}%",
            f"策略: {'MILP+贪心' if milp_plan else '纯贪心'}",
        ]
        orig_peak = np.max(net_load)
        if total_dis > 0:
            recs.append(f"光伏消纳: {np.sum(pv_pred):.0f}kWh (充电优先用光伏)")

        return MPCResult(
            steps=steps, total_saving=total_saving,
            total_charge_kwh=total_ch, total_discharge_kwh=total_dis,
            peak_reduction_kw=orig_peak - max(0, orig_peak - total_dis / cfg.horizon_steps),
            soc_trajectory=soc_traj, recommendations=recs
        )

    def feedback(self, actual_load: float, step_idx: int = -1):
        """反馈: 真实负荷到达, 更新模型."""
        if step_idx >= 0 and step_idx < len(self._history):
            self._history[step_idx].actual_load = actual_load
        # 反馈给预测引擎
        if len(self._history) >= 24:
            actuals = np.array([s.actual_load for s in self._history[-24:]])
            preds = np.array([s.predicted_load for s in self._history[-24:]])
            self._engine.online_update(actuals, preds)


class AnnualSettlement:
    """年度结算汇总."""
    year: int
    monthly_settlements: list[SettlementPeriod]
    total_energy_saving: float
    total_demand_saving: float
    total_saving: float
    total_cycles: float
    avg_monthly_demand_reduction_kw: float


def calc_demand_saving(demand_before: float, demand_after: float,
                       demand_price: float) -> float:
    """计算需量电费节省."""
    return (demand_before - demand_after) * demand_price


def calc_energy_saving(energy_cost_before: float, energy_cost_after: float) -> float:
    """计算电度电费节省."""
    return energy_cost_before - energy_cost_after


def calc_monthly_settlement(
    month_str: str,
    load_kwh_daily: list[float],
    price_daily: list[float],
    demand_before_kw: float,
    demand_after_kw: float,
    demand_price: float,
    bess_throughput_kwh: float,
    bess_capacity_kwh: float,
    energy_savings_ratio: float = None,  # v2.19: 储能替代电费比例(默认根据峰谷价差推算)
) -> SettlementPeriod:
    """计算单月结算.v2.19: 移除硬编码30%,改用参数化+峰谷价差推算."""
    energy_without = sum(ld * p for ld, p in zip(load_kwh_daily, price_daily, strict=False))
    # v3.2fix: 量纲口径修正——原式 energy_without(元) - throughput(kWh)*ratio(无量纲) 属于元减kWh.
    # 正确口径: 储能套利收益 = 吞吐量(kWh) × 峰谷价差(元/kWh); ratio 保留为"参与套利的电量比例"(默认1.0).
    avg_price = sum(price_daily) / max(len(price_daily), 1)
    peak_prices = [p for p in price_daily if p > avg_price]
    valley_prices = [p for p in price_daily if p <= avg_price]
    avg_peak = sum(peak_prices) / max(len(peak_prices), 1) if peak_prices else avg_price * 1.2
    avg_valley = sum(valley_prices) / max(len(valley_prices), 1) if valley_prices else avg_price * 0.7
    price_spread = max(0.0, avg_peak - avg_valley)
    participation = 1.0 if energy_savings_ratio is None else max(0.0, min(1.0, energy_savings_ratio))
    energy_with = max(0, energy_without - bess_throughput_kwh * price_spread * participation)

    return SettlementPeriod(
        period=month_str,
        energy_cost_without_bess=energy_without,
        energy_cost_with_bess=energy_with,
        demand_without_bess=demand_before_kw,
        demand_with_bess=demand_after_kw,
        demand_saving=calc_demand_saving(demand_before_kw, demand_after_kw, demand_price),
        energy_saving=calc_energy_saving(energy_without, energy_with),
        total_saving=calc_demand_saving(demand_before_kw, demand_after_kw, demand_price)
                     + calc_energy_saving(energy_without, energy_with),
        bess_cycles=bess_throughput_kwh / bess_capacity_kwh if bess_capacity_kwh > 0 else 0,
    )


def calc_payback_timeline(investment: float, monthly_savings: list[float]) -> dict:
    """计算投资回收时间线.

    Returns:
        {
            "payback_month": int (0-indexed),
            "cumulative_savings": [...],
            "remaining_investment": [...],
        }
    """
    cumulative = []
    cum_sum = 0.0
    payback_month = -1

    for i, saving in enumerate(monthly_savings):
        cum_sum += saving
        cumulative.append(cum_sum)
        if payback_month < 0 and cum_sum >= investment:
            payback_month = i

    return {
        "payback_month": payback_month,
        "cumulative_savings": cumulative,
        "remaining_investment": [investment - s for s in cumulative],
    }



