_BESS_DEFAULTS = {
    "bess_demand_price": 40.0,       # 需量电价 元/kW/月
    "bess_peak_valley_spread": 0.7,  # 峰谷价差 元/kWh
    "bess_capacity_kwh": 500.0,      # 储能容量 kWh
    "bess_power_kw": 250.0,          # 储能功率 kW
    "bess_eta": 0.95,                # 充放电效率
    "bess_capex_per_kwh": 1000.0,    # 单位投资 元/kWh(2026年工商业储能EPC均价~900-950,取1000含余量)
    "bess_project_life": 15,         # 项目寿命 年
    "bess_discount_rate": 0.07,      # 折现率
    "bess_cost_mode": "moderate",   # NREL模式: conservative/moderate/advanced/manual
    "bess_exchange_rate": 7.2,       # USD->CNY 汇率
}


def _get_bess_setting(config_manager, key):
    return config_manager.app_set(key, _BESS_DEFAULTS.get(key, 0))


def _set_bess_setting(config_manager, key, value):
    config_manager.set_app(key, value)


def _extract_load_data(parent_window):
    """从 MainWindow/ProfessionalWindow 提取负荷数据."""
    try:
        from powercurve_ext.adapter import load_dict_to_series
        if hasattr(parent_window, 'monthly_data') and parent_window.monthly_data:
            data = parent_window.monthly_data
        elif hasattr(parent_window, '_get_work_data'):
            data = parent_window._get_work_data()
        elif hasattr(parent_window, '_last_data_provider') and hasattr(parent_window, '_last_summaries'):
            provider = parent_window._last_data_provider
            summaries = parent_window._last_summaries
            data = {}
            for s in (summaries or []):
                d = provider.get_group_data(s) if provider else None
                if d:
                    data[f"{s.asset_value}|{s.month_str}"] = d
        else:
            return None, False, 0
        if not data:
            return None, False, 0
        power_series = load_dict_to_series(data)
        if power_series.empty:
            return None, False, 0
        peak_kw = float(power_series.max())
        return power_series, True, peak_kw
    except Exception:
        return None, False, 0


def _run_demand_analysis(parent_window):
    """需量分析:从已加载数据计算最大需量+电费."""
    try:
        from powercurve_ext.demand import analyze_from_series
        power_series, ok, peak = _extract_load_data(parent_window)
        if not ok:
            QMessageBox.information(parent_window, "需量分析", "无可用负荷数据.\n请先加载文件并完成数据扫描.")
            return
        cm = parent_window.config_manager
        demand_price = _get_bess_setting(cm, "bess_demand_price")
        result = analyze_from_series(power_series, window_minutes=15, demand_price=demand_price)
        monthly_detail = "\n".join(
            f"  {str(p)}: {v:.1f} kW"
            for p, v in list(result['demand_result'].monthly_max.items())[:6]
        )
        msg = (
            f"═══ 需量分析 ═══\n\n"
            f"📊 全局最大需量: {result['demand_result'].max_demand:.1f} kW\n"
            f"🕐 发生时刻: {result['demand_result'].peak_timestamp}\n"
            f"💴 月基本电费: ¥{result['charge']['demand_charge']:,.0f}\n"
            f"   (按 {demand_price} 元/kW/月)\n\n"
            f"📅 月度最大需量:\n{monthly_detail}\n\n"
            f"📐 滑动 vs 固定窗口:\n"
            f"  滑动: {result['comparison']['sliding_max']:.1f} kW\n"
            f"  固定: {result['comparison']['fixed_max']:.1f} kW\n"
            f"  差值: +{result['comparison']['delta_kw']:.1f} kW"
        )
        QMessageBox.information(parent_window, "需量分析", msg)
        log.info(f"[需量] 最大需量={result['demand_result'].max_demand:.1f}kW")
    except Exception as e:
        log.exception("需量分析失败")
        QMessageBox.warning(parent_window, "需量分析", f"分析失败: {e}")


def _run_bess_scheduler(parent_window):
    """储能调度:PuLP 线性规划求解最优充放电."""
    try:
        from powercurve_ext.scheduler import solve_user_side_bess, DispatchInput, BESSParams
        from powercurve_ext.adapter import periods_to_price_series
        power_series, ok, peak = _extract_load_data(parent_window)
        if not ok:
            QMessageBox.information(parent_window, "储能调度", "无可用负荷数据.")
            return
        cm = parent_window.config_manager
        capacity = _get_bess_setting(cm, "bess_capacity_kwh")
        power_kw = _get_bess_setting(cm, "bess_power_kw")
        eta = _get_bess_setting(cm, "bess_eta")
        demand_price = _get_bess_setting(cm, "bess_demand_price")
        province = cm.app_set('last_province_name', None)
        periods = cm.get_periods_for_all_months(province) if province and province != "无" else {}
        sample = power_series.iloc[:96] if len(power_series) > 96 else power_series
        time_labels = [t.strftime("%H:%M") for t in sample.index]
        load = sample.values.tolist()
        if not periods:
            buy_price, _ = periods_to_price_series(time_labels, {"平时": [("00:00", "24:00")]}, {"平时": 0.7})
        else:
            buy_price, _ = periods_to_price_series(time_labels, periods, {"充电": 0.3, "平时": 0.7, "放电": 1.2})
        bess = BESSParams(capacity=capacity, soc_min=capacity*0.1, soc_max=capacity, p_ch_max=power_kw, p_dis_max=power_kw, eta_ch=eta, eta_dis=eta)
        inp = DispatchInput(timestamps=list(sample.index), load_forecast=load, buy_price=buy_price.values.tolist(), bess=bess, initial_soc=capacity*0.5, demand_charge_rate=demand_price, step_hours=0.25)
        result = solve_user_side_bess(inp)
        total_ch = sum(c for c in result.charge_power) * 0.25
        total_dis = sum(d for d in result.discharge_power) * 0.25
        msg = (f"═══ 储能调度优化 ═══\n\n🔋 配置: {power_kw:.0f}kW/{capacity:.0f}kWh\n📊 调度: {len(load)}x15min\n\n💰 电度电费: ¥{result.energy_cost:,.2f}\n⚡ 需量电费: ¥{result.demand_cost:,.2f}\n💵 总成本: ¥{result.total_cost:,.2f}\n📈 最大需量: {result.max_grid_import:.1f}kW\n\n🔄 充电: {total_ch:.1f}kWh\n🔌 放电: {total_dis:.1f}kWh\n📉 SOC: {min(result.soc):.1f}~{max(result.soc):.1f}kWh")
        QMessageBox.information(parent_window, "储能调度", msg)
        log.info(f"[储能调度] 总成本={result.total_cost:.2f}元")
    except Exception as e:
        log.exception("储能调度失败")
        QMessageBox.warning(parent_window, "储能调度", f"调度失败: {e}")


def _run_capacity_planner(parent_window):
    """容量规划:扫描+IRR+LCOS."""
    try:
        from powercurve_ext.capacity import scan_capacity, InvestmentParams
        power_series, ok, peak_kw = _extract_load_data(parent_window)
        if not ok:
            QMessageBox.information(parent_window, "容量规划", "无可用负荷数据.")
            return
        cm = parent_window.config_manager
        spread = _get_bess_setting(cm, "bess_peak_valley_spread")
        capex = _get_bess_setting(cm, "bess_capex_per_kwh")
        life = int(_get_bess_setting(cm, "bess_project_life"))
        rate = _get_bess_setting(cm, "bess_discount_rate")
        demand_price = _get_bess_setting(cm, "bess_demand_price")
        daily_load = power_series.groupby(power_series.index.time).mean().values.tolist()[:96] if len(power_series) >= 96 else power_series.values.tolist()
        params = InvestmentParams(capex_per_kwh=capex, project_life=life, discount_rate=rate)
        plans = scan_capacity(daily_load or [peak_kw]*24, price_spread=spread, discharge_hours_range=(0.5, 6.0), step=0.5, demand_charge_rate=demand_price, invest_params=params)
        if not plans:
            QMessageBox.information(parent_window, "容量规划", "未找到可行方案.")
            return
        best = plans[0]
        msg = (f"═══ 容量规划 ═══\n\n📊 峰值: {peak_kw:.0f}kW\n💹 价差: {spread:.2f}元/kWh\n💴 需量电价: {demand_price}元/kW/月\n\n━━ ★ 最优 ━━\n功率: {best.optimal_power_kw:.0f}kW\n容量: {best.optimal_capacity_kwh:.0f}kWh\n时长: {best.duration_hours:.1f}h\n投资: ¥{best.total_investment:,.0f}\n年收益: ¥{best.annual_savings:,.0f}\n回收期: {best.payback_years:.1f}年\nIRR: {best.irr_percent:.1f}%\nLCOS: {best.lcos:.3f}元/kWh\n\n━━ 方案对比 ━━\n")
        for i, p in enumerate(plans[1:6], 1):
            irr_str = f"{p.irr_percent:.1f}%" if str(p.irr_percent) != 'nan' else 'N/A'
            msg += f"{i}. {p.optimal_capacity_kwh:.0f}kWh/{p.duration_hours:.1f}h -> IRR {irr_str}, 回收 {p.payback_years:.1f}年\n"
        QMessageBox.information(parent_window, "容量规划", msg)
        log.info(f"[容量规划] 最优={best.optimal_capacity_kwh:.0f}kWh, IRR={best.irr_percent:.1f}%")
    except Exception as e:
        log.exception("容量规划失败")
        QMessageBox.warning(parent_window, "容量规划", f"规划失败: {e}")


def _show_algorithm_comparison(parent_window):
    """展示原有算法 vs ele-trading 需量计算对比."""
    if hasattr(parent_window, '_demand_summary') and parent_window._demand_summary:
        cmp_text = parent_window._demand_summary.get('comparison_text', '')
        if cmp_text:
            QMessageBox.information(parent_window, "算法对比", cmp_text)
            return
    QMessageBox.information(parent_window, "算法对比", "暂无对比数据.请先加载数据完成分析.")

def _show_cycle_analysis(parent_window):
    """展示电池循环寿命分析."""
    try:
        from powercurve_ext.compare import analyze_battery_cycles, format_cycle_report
        power_series, ok, peak = _extract_load_data(parent_window)
        if not ok:
            QMessageBox.information(parent_window, "循环分析", "无可用负荷数据.")
            return
        cm = parent_window.config_manager
        capacity = _get_bess_setting(cm, 'bess_capacity_kwh')
        # 用贪心调度生成 SOC 曲线
        from powercurve_ext.compare import greedy_dispatch_annual
        daily = power_series.groupby(power_series.index.time).mean().values[:96]
        load_kw = np.tile(daily, 30)  # 30天
        dispatch = greedy_dispatch_annual(load_kw, batt_kwh=capacity, c_rate=0.5)
        soc_series = list(dispatch['soc'])
        report = analyze_battery_cycles(soc_series, capacity_kwh=capacity)
        text = format_cycle_report(report)
        text += chr(10) + chr(10) + '贪心调度摘要:' + chr(10) + '  电网购电: ' + str(int(dispatch['total_import'])) + 'kWh' + chr(10) + '  新能源直供: ' + str(int(dispatch['direct_use'])) + 'kWh'
        QMessageBox.information(parent_window, "电池循环分析", text)
    except Exception as e:
        QMessageBox.warning(parent_window, "循环分析", f"分析失败: {e}")

