_original_main_init = MainWindow.__init__

def _patched_main_init(self):
    _original_main_init(self)
    if _EXT_AVAILABLE:
        ext_menu = self.menuBar().addMenu("🔋 储能分析")
        ext_menu.addAction("📊 需量分析", lambda: _run_demand_analysis(self))
        ext_menu.addAction("⚡ 储能调度", lambda: _run_bess_scheduler(self))
        ext_menu.addAction("📐 容量规划", lambda: _run_capacity_planner(self))
        # 工具栏按钮
        for btn in self.findChildren(QPushButton):
            if btn.text() == "⚙️ 设置":
                parent_tb = btn.parent()
                if isinstance(parent_tb, QToolBar):
                    bess_btn = QPushButton("🔋 储能")
                    bess_btn.setToolTip("储能分析")
                    bess_btn.setMinimumHeight(int(base_size()))
                    bess_menu = QMenu(bess_btn)
                    bess_menu.addAction("📊 需量分析", lambda: _run_demand_analysis(self))
                    bess_menu.addAction("⚡ 储能调度", lambda: _run_bess_scheduler(self))
                    bess_menu.addAction("📐 容量规划", lambda: _run_capacity_planner(self))
                    bess_btn.setMenu(bess_menu)
                    # v3.0fix: insertWidget 第一个参数必须是 QAction
                    btn_action = None
                    for action in parent_tb.actions():
                        if parent_tb.widgetForAction(action) is btn:
                            btn_action = action; break
                    if btn_action:
                        parent_tb.insertWidget(btn_action, bess_btn)
                    else:
                        parent_tb.addWidget(bess_btn)
                    break
    else:
        ext_menu = self.menuBar().addMenu("🔋 储能分析")
        ext_menu.addAction("📦 安装储能扩展...").triggered.connect(
            lambda: QMessageBox.information(self, "储能扩展",
                f"扩展模块加载失败.{_EXT_ERROR or ''}\n请检查 pulp 依赖是否已安装:pip install pulp"))

MainWindow.__init__ = _patched_main_init


