_original_open_settings = MainWindow._open_settings

def _patched_open_settings(self):
    _original_open_settings(self)
    if not _EXT_AVAILABLE:
        return
    app = QApplication.instance()
    for widget in app.topLevelWidgets():
        if isinstance(widget, QDialog) and widget.windowTitle() == "⚙️ 设置" and widget.isVisible():
            layout = widget.layout()
            if layout:
                count = layout.count()
                btn_box_idx = -1
                for i in range(count):
                    item = layout.itemAt(i)
                    if item and isinstance(item.widget(), QDialogButtonBox):
                        btn_box_idx = i
                        break
                if btn_box_idx >= 0:
                    bess_group = QGroupBox("🔋 储能测算参数")
                    bess_layout = QVBoxLayout(bess_group)
                    cm = self.config_manager
                    fields = [
                        ("需量电价 (元/kW/月)", "bess_demand_price", 0, 200, 1),
                        ("峰谷价差 (元/kWh)", "bess_peak_valley_spread", 0, 5, 2),
                        ("储能容量 (kWh)", "bess_capacity_kwh", 0, 100000, 0),
                        ("储能功率 (kW)", "bess_power_kw", 0, 100000, 0),
                        ("成本模式", "bess_cost_mode", 0, 0, 0),  # special: combo box
                        ("单位投资 (元/kWh)", "bess_capex_per_kwh", 0, 10000, 0),
                        ("汇率 (USD->CNY)", "bess_exchange_rate", 5, 10, 2),
                        ("项目寿命 (年)", "bess_project_life", 1, 30),
                    ]
                    spin_widgets = {}
                    for label, key, vmin, vmax, decimals in fields:
                        row = QHBoxLayout()
                        row.addWidget(QLabel(label))
                        sp = QDoubleSpinBox()
                        sp.setDecimals(max(decimals, 0))
                        sp.setRange(vmin, vmax)
                        sp.setValue(_get_bess_setting(cm, key))
                        sp.setMinimumHeight(int(base_size()))
                        row.addWidget(sp)
                        bess_layout.addLayout(row)
                        spin_widgets[key] = sp
                    layout.insertWidget(btn_box_idx, bess_group)
                    btn_box = layout.itemAt(btn_box_idx + 1).widget()
                    def save_bess_and_accept():
                        reverse_map = {0: "conservative", 1: "moderate", 2: "advanced", 3: "manual"}
                        for key, widget_ref in spin_widgets.items():
                            if key == "bess_cost_mode":
                                _set_bess_setting(cm, key, reverse_map.get(widget_ref.currentIndex(), "moderate"))
                            else:
                                _set_bess_setting(cm, key, widget_ref.value())
                        widget.accept()
                    with suppress(Exception):
                        btn_box.accepted.disconnect()
                    btn_box.accepted.connect(save_bess_and_accept)
            break

MainWindow._open_settings = _patched_open_settings


