# ── 扩展配置 ──────────────────────────────────────────────────

EXT_CONFIG = {
    'rainflow': {'enabled': True},
    'peak_predict': {'enabled': True, 'method': 'sarima', 'history_min_months': 3},
    'joint_optimize': {'enabled': True, 'solver': 'scipy',
                       'weight_energy': 1.0, 'weight_demand': 1.0},
    'degradation': {'enabled': True, 'chemistry': 'LFP', 'ambient_temp_c': 25},
}


# ── 扩展1: Rainflow 循环计数 ──────────────────────────────────

def _rainflow_cycle_count(soc_sequence, capacity_kwh=1000):
    """Rainflow 循环计数法 (ASTM E1049 四峰谷法简化实现).

    从 SOC 轨迹提取充放电半循环,按放电深度 (DoD) 分 bin,
    折算为等效全循环次数.

    Args:
        soc_sequence: SOC 序列 (0~1 或 0~100 均可,内部归一化)
        capacity_kwh: 系统额定容量 (kWh),仅用于输出吞吐量

    Returns:
        dict: {equivalent_full_cycles, half_cycles, dod_bins, total_throughput_kwh}
    """
    seq = np.asarray(soc_sequence, dtype=np.float64)
    if seq.max() > 1.5:
        seq = seq / 100.0  # 百分比转 0~1
    seq = np.clip(seq, 0.0, 1.0)

    # 提取转折点(峰谷交替)
    turning_points = []
    n = len(seq)
    if n < 3:
        return {'equivalent_full_cycles': 0, 'half_cycles': [], 'dod_bins': {},
                'total_throughput_kwh': 0.0, 'note': '序列太短,跳过Rainflow'}

    turning_points.append(0)
    for i in range(1, n - 1):
        if (seq[i] - seq[i-1]) * (seq[i+1] - seq[i]) < 0:
            turning_points.append(i)
    turning_points.append(n - 1)

    # 四峰谷法提取半循环
    half_cycles = []
    stack = []
    for idx in turning_points:
        stack.append((idx, seq[idx]))
        while len(stack) >= 4:
            a0, a1, a2, a3 = stack[-4], stack[-3], stack[-2], stack[-1]
            range_y = abs(a2[1] - a1[1])
            range_x = abs(a0[1] - a3[1])
            if range_y <= range_x:
                dod = abs(a2[1] - a1[1])
                if dod > 0.005:
                    half_cycles.append(float(dod))
                stack.pop(-2)
                stack.pop(-2)
            else:
                break
    # 残余堆栈
    for i in range(len(stack) - 1):
        dod = abs(stack[i+1][1] - stack[i][1])
        if dod > 0.005:
            half_cycles.append(float(dod))

    if not half_cycles:
        return {'equivalent_full_cycles': 0, 'half_cycles': [], 'dod_bins': {},
                'total_throughput_kwh': 0.0, 'note': '无有效循环'}

    # DoD 分 bin 并折算等效全循环
    bins = {
        '0-20%': 0, '20-40%': 0, '40-60%': 0,
        '60-80%': 0, '80-100%': 0
    }
    equivalent_full = 0.0
    for dod in half_cycles:
        if dod <= 0.20: bins['0-20%'] += 1
        elif dod <= 0.40: bins['20-40%'] += 1
        elif dod <= 0.60: bins['40-60%'] += 1
        elif dod <= 0.80: bins['60-80%'] += 1
        else: bins['80-100%'] += 1
        equivalent_full += dod / 2.0  # 每个半循环折算为 DoD/2 个全循环

    total_throughput = sum(d * capacity_kwh for d in half_cycles)

    return {
        'equivalent_full_cycles': round(equivalent_full, 2),
        'half_cycles': len(half_cycles),
        'dod_bins': bins,
        'total_throughput_kwh': round(total_throughput, 1),
        'note': f'共计{len(half_cycles)}个半循环,等效{equivalent_full:.1f}个全循环'
    }


# ── 扩展2: SARIMA 峰值预测 ────────────────────────────────────

def _peak_predict_sarima(daily_peaks, forecast_days=30, history_min=14):
    """基于 SARIMA 的每日峰值负荷预测.

    用历史每日峰值序列做 SARIMA(1,0,1)x(1,0,1,7) 拟合,
    预测未来 forecast_days 天的峰值负荷.

    Args:
        daily_peaks: 历史每日峰值负荷 list/array (kW)
        forecast_days: 预测未来天数
        history_min: 最少需要的历史天数

    Returns:
        dict: {forecast, conf_lower, conf_upper, peak_day_indices, method}
    """
    import warnings as _w
    result = {'method': 'sarima', 'status': 'skipped', 'forecast': [],
              'conf_lower': [], 'conf_upper': [], 'peak_day_indices': []}

    peaks = np.asarray(daily_peaks, dtype=np.float64)
    peaks = peaks[~np.isnan(peaks)]
    if len(peaks) < history_min:
        result['note'] = f'历史数据不足({len(peaks)}天 < {history_min}天),跳过SARIMA预测'
        return result

    try:
        from statsmodels.tsa.statespace.sarimax import SARIMAX
        with _w.catch_warnings():
            _w.simplefilter('ignore')
            model = SARIMAX(peaks, order=(1, 0, 1),
                            seasonal_order=(1, 0, 1, min(7, len(peaks)//2)),
                            enforce_stationarity=False,
                            enforce_invertibility=False)
            fitted = model.fit(disp=False, maxiter=50)
            forecast_result = fitted.get_forecast(steps=forecast_days)
            fc = forecast_result.predicted_mean
            ci = forecast_result.conf_int(alpha=0.20)

        result['status'] = 'ok'
        result['forecast'] = [round(float(v), 1) for v in fc]
        result['conf_lower'] = [round(float(v), 1) for v in ci[:, 0]]
        result['conf_upper'] = [round(float(v), 1) for v in ci[:, 1]]
        # 找预测期内峰值最高的3天
        top_indices = np.argsort(fc)[-3:][::-1]
        result['peak_day_indices'] = [int(i) for i in top_indices]
        # 计算预测峰值 vs 历史峰值的变化
        hist_max = float(np.max(peaks))
        fc_max = float(np.max(fc))
        result['predicted_max_kw'] = round(fc_max, 1)
        result['historical_max_kw'] = round(hist_max, 1)
        result['delta_pct'] = round((fc_max - hist_max) / hist_max * 100, 1) if hist_max > 0 else 0
        result['note'] = (f'SARIMA预测未来{forecast_days}天峰值{fc_max:.0f}kW'
                          f'(历史峰值{hist_max:.0f}kW, 变化{result["delta_pct"]:+.1f}%)')
    except Exception as e:
        result['status'] = 'error'
        result['note'] = f'SARIMA拟合失败: {e}'

    return result


# ── 扩展3: 联合优化线性规划 ───────────────────────────────────

def _joint_optimize_lp(load_array, time_labels, periods, tariff_info,
                        capacity_kwh, power_kw, config=None):
    """联合优化 LP (借鉴 DOPER 架构).

    将峰谷套利 + 需量削减合并为一个 LP,含完整 SOC 状态变量和递推约束.
    用 scipy.optimize.linprog 求解(零额外依赖).

    目标: min w1x能耗费 + w2x需量费
    约束: SOC 递推动态、功率上限、需量窗口、跨日 SOC 回位(软约束)

    变量布局 (3*n_total + 1):
      [0..n-1]          charge_power (kW)
      [n..2n-1]         discharge_power (kW)
      [2n..3n-1]        SOC (kWh, 状态变量)
      [3n]              max_grid_import (kW, 需量上限)

    Args:
        load_array: (n_days, n_points) 负荷数组
        time_labels: 时间标签
        periods: 充放电时段策略
        tariff_info: 电价信息 dict (peak_price, valley_price, flat_price)
        capacity_kwh: 储能容量
        power_kw: 储能功率
        config: 扩展配置

    Returns:
        dict: {optimal_schedule, ...}
    """
    config = config or {}
    w_e = config.get('weight_energy', 1.0)
    w_d = config.get('weight_demand', 1.0)

    result = {'status': 'skipped', 'note': ''}

    arr = np.asarray(load_array, dtype=np.float64)
    if arr.ndim != 2 or arr.shape[0] < 1 or arr.shape[1] < 2:
        result['note'] = '数据维度不满足联合优化要求'
        return result

    n_days, n_points = arr.shape
    n = n_days * n_points

    peak_price = tariff_info.get('peak', 1.0)
    valley_price = tariff_info.get('valley', 0.3)
    flat_price = tariff_info.get('flat', 0.6)

    # 构建逐时点电价向量
    price_vector = np.full(n, flat_price)
    expanded_periods = _expand_overnight(periods) if periods else []
    for d in range(n_days):
        for t_idx in range(n_points):
            hour = _parse_min(time_labels[t_idx]) / 60.0 if t_idx < len(time_labels) and isinstance(time_labels[t_idx], str) else t_idx / n_points * 24
            for p in expanded_periods:
                in_range = (p['start'] <= hour < p['end']) if p['start'] <= p['end'] else (hour >= p['start'] or hour < p['end'])
                if in_range:
                    if p['type'] in ('discharge', 'peak', PeriodType.DISCHARGE,
                                     PeriodType.DISCHARGE_LABEL, '放电'):
                        price_vector[d * n_points + t_idx] = peak_price
                    elif p['type'] in ('charge', 'valley', PeriodType.CHARGE,
                                       PeriodType.CHARGE_LABEL, '充电'):
                        price_vector[d * n_points + t_idx] = valley_price
                    break

    load_flat = arr.flatten()
    dt_h = 24.0 / max(n_points, 1)

    try:
        from scipy.optimize import linprog
    except ImportError:
        result['note'] = 'scipy 未安装,无法运行联合优化'
        return result

    # 系统参数
    eff_c = 0.95
    eff_d = 0.95
    # v3.2fix: SOC 区间与全局口径统一（原写死 10%~90%）
    soc_min = BESS_SOC_MIN * capacity_kwh
    soc_max = BESS_SOC_MAX * capacity_kwh
    init_soc = 0.20 * capacity_kwh

    # ── 变量布局 ──
    I_CH = 0
    I_DIS = n
    I_SOC = 2 * n
    I_MGRID = 3 * n
    n_vars = 3 * n + 1

    # ── 目标系数 ──
    c = np.zeros(n_vars)
    for i in range(n):
        c[I_CH + i] = w_e * price_vector[i] * dt_h
        c[I_DIS + i] = -w_e * price_vector[i] * dt_h
    c[I_MGRID] = w_d

    # ── 变量边界 ──
    bounds = ([(0, power_kw)] * n           # charge
            + [(0, power_kw)] * n           # discharge
            + [(soc_min, soc_max)] * n      # SOC
            + [(0, max(np.nanmax(arr) * 1.5, power_kw * 2))])  # max_grid

    # ── 约束 ──
    A_ub_rows, b_ub_vals = [], []
    A_eq_rows, b_eq_vals = [], []

    # 约束1: SOC 递推 - soc[t] = soc[t-1] + ηc·ch[t]·dt - dis[t]·dt/ηd
    # 重排为: soc[t] - soc[t-1] - ηc·dt·ch[t] + (dt/ηd)·dis[t] = 0
    for t in range(1, n):
        row = np.zeros(n_vars)
        row[I_SOC + t] = 1.0
        row[I_SOC + t - 1] = -1.0
        row[I_CH + t] = -eff_c * dt_h
        row[I_DIS + t] = dt_h / eff_d
        A_eq_rows.append(row)
        b_eq_vals.append(0.0)

    # 约束2: SOC 初值
    row = np.zeros(n_vars)
    row[I_SOC + 0] = 1.0
    A_eq_rows.append(row)
    b_eq_vals.append(init_soc)

    # 约束3: 需量上限 max_grid >= load[t] + ch[t] - dis[t]
    # -> -ch[t] + dis[t] - max_grid <= -load[t]
    for i in range(n):
        row = np.zeros(n_vars)
        row[I_CH + i] = -1.0
        row[I_DIS + i] = 1.0
        row[I_MGRID] = -1.0
        A_ub_rows.append(row)
        b_ub_vals.append(-load_flat[i])

    # 约束4: 每日 SOC 终值归位(软约束,允许 +/-20% 偏差)
    delta_tol = 0.20 * capacity_kwh
    for d in range(n_days):
        day_end = (d + 1) * n_points - 1
        # soc[day_end] - init_soc <= delta_tol
        row = np.zeros(n_vars)
        row[I_SOC + day_end] = 1.0
        A_ub_rows.append(row)
        b_ub_vals.append(init_soc + delta_tol)
        # -(soc[day_end] - init_soc) <= delta_tol -> -soc[day_end] + init_soc <= delta_tol
        row2 = np.zeros(n_vars)
        row2[I_SOC + day_end] = -1.0
        A_ub_rows.append(row2)
        b_ub_vals.append(-init_soc + delta_tol)

    # 约束5: 充放电互斥(LP 弱约束 - 仅限功率和不超过功率上限)
    # 对每个时间步:ch[t] + dis[t] <= power_kw(避免同时满功率充放)
    for i in range(n):
        row = np.zeros(n_vars)
        row[I_CH + i] = 1.0
        row[I_DIS + i] = 1.0
        A_ub_rows.append(row)
        b_ub_vals.append(power_kw)

    # ── 求解 ──
    try:
        A_ub = np.array(A_ub_rows, dtype=np.float64)
        b_ub = np.array(b_ub_vals, dtype=np.float64)
        A_eq = np.array(A_eq_rows, dtype=np.float64)
        b_eq = np.array(b_eq_vals, dtype=np.float64)

        res = linprog(c, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                      bounds=bounds, method='highs',
                      options={'time_limit': 120})  # v2.22fix: 防止大问题挂死GUI

        if res.success:
            ch = res.x[I_CH:I_CH + n].reshape(n_days, n_points)
            dis = res.x[I_DIS:I_DIS + n].reshape(n_days, n_points)
            soc = res.x[I_SOC:I_SOC + n].reshape(n_days, n_points)
            mg = res.x[I_MGRID]

            grid_import = load_flat + ch.flatten() - dis.flatten()
            ec_storage = np.sum(grid_import * price_vector * dt_h)
            ec_bare = np.sum(load_flat * price_vector * dt_h)
            daily_save = float(ec_bare - ec_storage) / max(n_days, 1)

            # 校验 SOC 递推(后验检查)
            soc_pred = np.zeros(n)
            soc_pred[0] = init_soc
            for t in range(1, n):
                soc_pred[t] = soc_pred[t-1] + eff_c * ch.flatten()[t] * dt_h - dis.flatten()[t] * dt_h / eff_d
            soc_err = float(np.max(np.abs(soc.flatten() - soc_pred)))

            result['status'] = 'ok'
            result['optimal_charge_kw'] = [round(float(v), 1) for v in ch.flatten()[:min(96, n)]]
            result['optimal_discharge_kw'] = [round(float(v), 1) for v in dis.flatten()[:min(96, n)]]
            result['optimal_soc_kwh'] = [round(float(v), 1) for v in soc.flatten()[:min(96, n)]]
            result['max_grid_import_kw'] = round(float(mg), 1)
            result['energy_cost_with_storage'] = round(float(ec_storage), 2)
            result['energy_cost_without_storage'] = round(float(ec_bare), 2)
            result['daily_savings'] = round(float(daily_save), 2)
            result['objective_value'] = round(float(res.fun), 2)
            result['soc_consistency_error_kwh'] = round(float(soc_err), 4)
            result['note'] = (f'联合优化收敛,日节省{daily_save:.0f}元(SOC递推误差{soc_err:.3f}kWh)'
                              f'(独立计算作为对比基准已包含在原报告中)')
        else:
            result['status'] = 'infeasible'
            result['note'] = f'联合优化无可行解: {res.message}'
    except ImportError:
        result['status'] = 'error'
        result['note'] = '联合优化不可用: scipy未安装'
    except Exception as e:
        result['status'] = 'error'
        result['note'] = f'联合优化求解异常: {e}'

    return result


# ── 扩展4: 电池退化预估 ──────────────────────────────────────

def _estimate_degradation(equiv_full_cycles_per_year, chemistry='LFP',
                           ambient_temp_c=25, project_life_years=15):
    """电池退化预估模型(日历老化 + 循环老化混合模型).

    模型: Q_loss = k_cal(T) x t + k_cyc(T) x N
    其中温度加速因子为 Arrhenius 形式: k(T) = k_25 x exp(Ea/R x (1/298.15 - 1/T))

    标定基准(25degC,365 循环/年):
      LFP: 第5年 SOH~=88%,第10年 SOH~=79%,第13年触发更换
      NMC: 第5年 SOH~=83%,第8年 SOH~=72%,第8年触发更换

    Args:
        equiv_full_cycles_per_year: 年均等效全循环次数
        chemistry: 'LFP' 或 'NMC'
        ambient_temp_c: 环境温度 (degC)
        project_life_years: 项目寿命 (年)

    Returns:
        dict: {yearly_soh_pct, replacement_year, note, ...}
    """
    # ── 输入验证 ──
    if equiv_full_cycles_per_year is None or equiv_full_cycles_per_year < 0:
        equiv_full_cycles_per_year = 0
    if chemistry not in ('LFP', 'NMC'):
        chemistry = 'LFP'
        log.warning("_estimate_degradation: 未知电池化学类型,回退为LFP")
    if ambient_temp_c < -50 or ambient_temp_c > 80:
        log.warning(f"_estimate_degradation: 环境温度{ambient_temp_c}degC超出合理范围,已钳位")
        ambient_temp_c = max(-50, min(80, ambient_temp_c))
    if project_life_years < 1 or project_life_years > 50:
        log.warning(f"_estimate_degradation: 项目寿命{project_life_years}年超出合理范围")
        project_life_years = max(1, min(50, project_life_years))

    # ── 25degC 基准衰减系数 ──
    if chemistry == 'LFP':
        k_cal_25 = 0.012     # 日历衰减系数 (1/年)
        k_cyc_25 = 0.000025  # 循环衰减系数 (1/次)
        Ea_cal = 24000       # 日历老化活化能 J/mol
        Ea_cyc = 15000       # 循环老化活化能 J/mol
        label = 'LFP (磷酸铁锂)'
    else:  # NMC
        k_cal_25 = 0.018
        k_cyc_25 = 0.000040
        Ea_cal = 24000
        Ea_cyc = 15000
        label = 'NMC (三元锂)'

    R = 8.314
    T_ref = 298.15          # 25degC 参考温度 (K)
    T_actual = ambient_temp_c + 273.15

    # 温度加速因子
    accel_cal = math.exp((Ea_cal / R) * (1.0 / T_ref - 1.0 / T_actual))
    accel_cyc = math.exp((Ea_cyc / R) * (1.0 / T_ref - 1.0 / T_actual))
    k_cal_T = k_cal_25 * accel_cal
    k_cyc_T = k_cyc_25 * accel_cyc

    yearly_soh = []
    cumulative_cycles = 0
    replacement_year = None

    for y in range(1, project_life_years + 1):
        cumulative_cycles += equiv_full_cycles_per_year
        q_loss_cal = k_cal_T * y
        q_loss_cyc = k_cyc_T * cumulative_cycles
        q_loss_total = q_loss_cal + q_loss_cyc
        soh = max(0.0, 1.0 - q_loss_total)
        yearly_soh.append(round(soh * 100, 1))
        if replacement_year is None and soh < 0.70:
            replacement_year = y

    return {
        'chemistry': chemistry,
        'chemistry_label': label,
        'ambient_temp_c': ambient_temp_c,
        'cycles_per_year': equiv_full_cycles_per_year,
        'yearly_soh_pct': yearly_soh,
        'year5_soh_pct': yearly_soh[4] if len(yearly_soh) >= 5 else yearly_soh[-1],
        'year10_soh_pct': yearly_soh[9] if len(yearly_soh) >= 10 else yearly_soh[-1],
        'replacement_year': replacement_year,
        'cal_loss_rate': round(k_cal_T * 100, 2),
        'cyc_loss_rate': round(k_cyc_T * 100, 5),
        'note': (f'{label},{ambient_temp_c}degC环境下(日历衰减{k_cal_T*100:.1f}%/年 + 循环衰减{k_cyc_T*100:.4f}%/次),'
                 f'第5年SOH~={yearly_soh[4] if len(yearly_soh)>=5 else yearly_soh[-1]}%,'
                 + (f'预计第{replacement_year}年需更换' if replacement_year
                    else f'{project_life_years}年内未触发更换阈值(SOH>{70}%)'))
    }


# ── 扩展5: 序贯调度规划器 ──────────────────────────────────────

def _sequential_plan(load_array, time_labels, periods, capacity_kwh, power_kw):
    """序贯调度规划器 (借鉴 FlexPower 三阶段结构).

    Phase1: 基于分时电价时段粗排充放电框架
    Phase2: 在框架内精细分配功率(优先需量峰值附近放电)
    Phase3: 剩余容量分配(光伏消纳 + 备用)

    Args:
        load_array: (n_days, n_points)
        time_labels: 时间标签
        periods: 充放电时段
        capacity_kwh: 储能容量
        power_kw: 储能功率

    Returns:
        dict: 三阶段规划结果
    """
    arr = np.asarray(load_array, dtype=np.float64)
    if arr.ndim != 2:
        return {'status': 'skipped', 'note': '数据维度不满足序贯规划要求'}

    n_days, n_points = arr.shape
    expanded = _expand_overnight(periods) if periods else []

    # Phase1: 粗排充放电时段
    charge_windows = []
    discharge_windows = []
    for p in expanded:
        ptype = p['type']
        if ptype in ('charge', 'valley', PeriodType.CHARGE, PeriodType.CHARGE_LABEL, '充电'):
            charge_windows.append({'start': p['start'], 'end': p['end']})
        elif ptype in ('discharge', 'peak', PeriodType.DISCHARGE,
                       PeriodType.DISCHARGE_LABEL, '放电'):
            discharge_windows.append({'start': p['start'], 'end': p['end']})

    # Phase2: 在每个放电窗口内找需量峰值位置
    peak_targets = []
    hours = np.array([_parse_min(t) / 60.0 if isinstance(t, str) else i / n_points * 24
                      for i, t in enumerate(time_labels)])
    for dw in discharge_windows:
        for d in range(n_days):
            window_mask = (hours >= dw['start']) & (hours < dw['end'])
            if not np.any(window_mask):
                continue
            window_loads = arr[d, window_mask]
            peak_t_idx = int(np.argmax(window_loads))
            peak_t_global = int(np.where(window_mask)[0][peak_t_idx])
            peak_targets.append({
                'day': d, 't_idx': peak_t_global,
                'load_kw': float(arr[d, peak_t_global])
            })

    # Phase3: 计算剩余容量可用于光伏消纳和备用
    daily_charge_cap = capacity_kwh * 0.80  # 可用充电空间
    daily_discharge_cap = capacity_kwh * 0.80  # 可用放电空间

    return {
        'status': 'ok',
        'phase1_charge_windows': len(charge_windows),
        'phase1_discharge_windows': len(discharge_windows),
        'phase2_peak_targets': len(peak_targets),
        'phase2_top3_peaks': sorted(peak_targets, key=lambda x: x['load_kw'], reverse=True)[:3],
        'phase3_daily_charge_headroom_kwh': round(daily_charge_cap, 1),
        'phase3_daily_discharge_headroom_kwh': round(daily_discharge_cap, 1),
        'note': (f'序贯规划: {len(charge_windows)}个充电窗口, '
                 f'{len(discharge_windows)}个放电窗口, '
                 f'{len(peak_targets)}个需量峰值目标')
    }


# ── 扩展6: HTML 报告注入 ───────────────────────────────────────

