# ── 统一扩展入口 ───────────────────────────────────────────────

def _run_extensions(raw_data, report):
    """运行所有已启用的扩展模块,返回扩展结果字典.

    Args:
        raw_data: {'load_array', 'time_labels', 'date_labels', 'periods', ...}
        report: EnergyStorageEngineer.diagnose() 的当前报告 dict

    Returns:
        dict: 各扩展模块的结果
    """
    cfg = EXT_CONFIG
    results = {}

    arr = raw_data.get('load_array')
    if arr is None or arr.size == 0:
        return results

    time_labels = raw_data.get('time_labels', [])
    periods = raw_data.get('periods')
    # 格式归一化: tariff_to_strategy 返回 tuple 格式需转为 dict 格式 (含 PeriodType)
    if periods and len(periods) > 0:
        first = periods[0]
        if isinstance(first, (tuple, list)) and len(first) == 3 and not isinstance(first, dict):
            normalized = []
            for s, e, t in periods:
                seg_type = PeriodType.CHARGE if str(t) in ('charge', 'valley', '充电') else PeriodType.DISCHARGE
                normalized.append({'start': float(s), 'end': float(e), 'type': seg_type})
            periods = normalized
    rec = raw_data.get('recommendation', {})
    capacity_kwh = rec.get('capacity_kwh', 1000)
    power_kw = rec.get('power_kw', 500)
    tariff_info = raw_data.get('tariff_info', {})

    # 生成模拟 SOC 轨迹用于 Rainflow
    try:
        soc_seq = _simulate_soc_for_rainflow(arr, time_labels, periods,
                                              capacity_kwh, power_kw,
                                              efficiency=cfg.get('efficiency', 0.90))
    except Exception:
        soc_seq = np.linspace(0.2, 0.9, 96)  # fallback

    # 1. Rainflow 循环计数
    if cfg.get('rainflow', {}).get('enabled'):
        results['rainflow'] = _rainflow_cycle_count(soc_seq, capacity_kwh)

    # 2. SARIMA 峰值预测(需要跨日数据)
    if cfg.get('peak_predict', {}).get('enabled') and arr.ndim == 2:
        daily_peaks = np.nanmax(arr, axis=1)
        history_min = cfg['peak_predict'].get('history_min_months', 3) * 30  # v2.22fix: 月->天换算(x30)
        if arr.shape[0] < history_min:
            results['peak_predict'] = {'note': f'历史数据不足({arr.shape[0]}天 < {history_min}天),跳过SARIMA预测', 'status': 'skipped'}
        else:
            results['peak_predict'] = _peak_predict_sarima(
                daily_peaks,
                forecast_days=min(30, arr.shape[0]),
                history_min=history_min
            )

    # 3. 联合优化 LP
    if cfg.get('joint_optimize', {}).get('enabled') and periods:
        results['joint_optimize'] = _joint_optimize_lp(
            arr, time_labels, periods, tariff_info,
            capacity_kwh, power_kw, cfg['joint_optimize']
        )

    # 4. Arrhenius 退化预估(依赖 Rainflow 结果)
    if cfg.get('degradation', {}).get('enabled'):
        rf = results.get('rainflow', {})
        # v3.2fix: rainflow 的 SOC 轨迹只跑 min(n_days,30) 天(见 _simulate_soc_for_rainflow),
        # 原实现把这 30 天的等效循环直接当年值, 年循环最多低估 12 倍, replacement_year 系统性推后。
        _obs_days = max(1, min(int(arr.shape[0]), 30))
        _rf_cycles = float(rf.get('equivalent_full_cycles', 0) or 0)
        cycles_per_year = _rf_cycles * (365.0 / _obs_days) if _rf_cycles > 0 else 365.0
        chemistry = cfg['degradation'].get('chemistry', 'LFP')
        temp = cfg['degradation'].get('ambient_temp_c', 25)
        results['degradation'] = _estimate_degradation(
            cycles_per_year, chemistry, temp
        )

    # 5. 序贯调度规划
    if periods:
        results['sequential_plan'] = _sequential_plan(
            arr, time_labels, periods, capacity_kwh, power_kw
        )

    return results


def _simulate_soc_for_rainflow(load_array, time_labels, periods,
                                capacity_kwh, power_kw, efficiency=0.90):
    """快速生成 SOC 轨迹用于 Rainflow 分析.

    Args:
        efficiency: 充放电往返效率 (0~1),默认 0.90 与 simulate_daily_dispatch 一致
    """
    arr = np.asarray(load_array, dtype=np.float64)
    if arr.ndim != 2:
        return np.array([0.5])
    n_days, n_points = arr.shape
    expanded = _expand_overnight(periods) if periods else []
    hours = np.array([_parse_min(t) / 60.0 if isinstance(t, str) else i / n_points * 24
                      for i, t in enumerate(time_labels)])

    eff_one_way = math.sqrt(max(efficiency, 0.01))
    soc = 0.2 * capacity_kwh
    # v3.2fix: 与全局 SOC 口径统一（原写死 10%~90%，与 BESS_SOC_MIN/MAX 不一致）
    soc_min = BESS_SOC_MIN * capacity_kwh
    soc_max = BESS_SOC_MAX * capacity_kwh
    soc_seq = []

    for _d in range(min(n_days, 30)):
        for t in range(n_points):
            hour = hours[t] if t < len(hours) else 0
            seg_type = None
            for p in expanded:
                in_range = False
                if p['start'] <= p['end']:
                    in_range = p['start'] <= hour < p['end']
                else:
                    in_range = hour >= p['start'] or hour < p['end']
                if in_range:
                    seg_type = p['type']
                    break
            dt = 1.0 / n_points * 24
            if seg_type in ('charge', 'valley', PeriodType.CHARGE,
                            PeriodType.CHARGE_LABEL, '充电'):
                chg = min(power_kw, (soc_max - soc) / dt) if dt > 0 else 0
                soc += chg * dt * eff_one_way
            elif seg_type in ('discharge', 'peak', PeriodType.DISCHARGE,
                              PeriodType.DISCHARGE_LABEL, '放电'):
                dis = min(power_kw, (soc - soc_min) / dt) if dt > 0 else 0
                soc -= dis * dt / eff_one_way
            soc = max(soc_min, min(soc_max, soc))
            soc_seq.append(float(soc / capacity_kwh))

    return np.array(soc_seq)


# v2.28fix: 将内联扩展函数注入到 powercurve_ext.* shim 模块中
# 解决 _run_demand_analysis / _run_bess_scheduler 等入口的 ImportError
import sys as __sys
_G = globals()
_SHIMMED = {
    'powercurve_ext.adapter': ['load_array_to_series', 'load_dict_to_series', 'periods_to_price_series'],
    'powercurve_ext.demand': ['DemandConfig', 'DemandResult', 'calc_fixed_window', 'calc_sliding_window',
                               'calc_demand', 'calc_demand_charge', 'compare_windows', 'analyze_from_series',
                               '_parse_time_min'],
    'powercurve_ext.scheduler': ['BESSParams', 'DispatchInput', 'DispatchResult',
                                  'solve_user_side_bess', 'solve_bess_arbitrage'],
    'powercurve_ext.capacity': ['CostScenario', 'NRELCostData', 'ITCConfig', 'CapacityPlan', 'InvestmentParams',
                                 'get_nrel_costs', 'resolve_investment_params', 'get_nrel_cost_summary',
                                 'calc_investment', 'calc_simple_payback', 'calc_npv', 'calc_irr', 'calc_lcos',
                                 'scan_capacity', 'scan_capacity_multi_scenario', 'sensitivity_analysis'],
    'powercurve_ext.compare': ['DemandCompareResult', 'compare_demand', 'format_demand_comparison',
                                'CycleReport', 'analyze_battery_cycles', 'format_cycle_report'],
    'powercurve_ext.settlement': ['SettlementPeriod', 'AnnualSettlement',
                                   'calc_demand_saving', 'calc_energy_saving',
                                   'calc_monthly_settlement', 'calc_payback_timeline'],
}
for __mod_name, __names in _SHIMMED.items():
    __shim = __sys.modules.get(__mod_name)
    if __shim is not None:
        for __n in __names:
            if __n in _G:
                setattr(__shim, __n, _G[__n])
del __sys, _G, _SHIMMED, __mod_name, __names, __shim, __n


